pub(crate) fn rebuild_native_amx_participant_receipt_latest_indexes_on_startup(
    &self,
) -> Result<usize> {
    let _prune_guard = self.prune_lock.lock();
    self.ensure_prune_recovery_not_required()?;
    self.durable_mutation_authorized()?;
    let _canonical_chain_guard = self.canonical_chain_lock.lock();
    let _geometry_guard = self.lane_geometry_lock.lock();
    let entries = self.retained_lane_storage_entries_under_geometry_guard()?;
    let _sidecar_guard = self.sidecar_lock.lock();
    let exact_durable_tip = u64::try_from(self.exact_durable_blocks_count()?)?;
    let mut accounting_mutation = self
        .begin_total_disk_usage_mutation()
        .with_resource_children(entries.len());
    let mut rebuilt = 0_usize;
    for entry in entries {
        let evidence_directory = Self::lane_artifact_dir(&entry.blocks_dir(&self.store_root));
        match std::fs::symlink_metadata(&evidence_directory) {
            Ok(_) => {}
            Err(error) if error.kind() == ErrorKind::NotFound => {
                accounting_mutation.resource_batch(0).finish();
                continue;
            }
            Err(error) => return Err(Error::IO(error, evidence_directory)),
        }
        let mut lane_resources = accounting_mutation.resource_batch(3);
        let namespace = self.native_amx_evidence_namespace_for_entry(&entry)?;
        let latest_index_path =
            Self::native_amx_participant_receipt_latest_index_path_for_entry(
                &entry,
                &self.store_root,
            );
        if latest_index_path.parent() != Some(evidence_directory.as_path())
            || !Self::progress_mutation_namespace_unchanged(&namespace)
        {
            return Err(Self::invalid_lane_artifact_error(
                evidence_directory,
                "Native AMX startup evidence does not share one descriptor-bound directory",
            ));
        }
        for directory_entry in std::fs::read_dir(&evidence_directory)
            .map_err(|error| Error::IO(error, evidence_directory.clone()))?
        {
            let directory_entry = directory_entry
                .map_err(|error| Error::IO(error, evidence_directory.clone()))?;
            if directory_entry
                .file_name()
                .to_string_lossy()
                .starts_with(".kura-sidecar-")
            {
                return Err(Self::invalid_lane_artifact_error(
                    directory_entry.path(),
                    "Native AMX startup reconstruction found an unresolved atomic temporary",
                ));
            }
        }
        let before_bytes = self.native_amx_evidence_tracked_bytes_locked(&namespace)?;
        let latest_temp_present = self
            .native_amx_latest_index_temp_bytes_locked(&namespace)?
            .is_some();
        if latest_temp_present {
            // Pointer staging follows complete pair publication and
            // precedes pruning. Do not consume another recovery journal
            // when these mutually exclusive crash shapes overlap.
            self.require_native_amx_latest_index_temp_recovery_unambiguous_locked(&namespace)?;
            lane_resources.guard().resource_batch(0).finish();
        } else {
            let mut recovery = lane_resources.guard().resource_batch(2);
            self.complete_native_amx_evidence_prune_intent_locked(
                recovery.guard(),
                &entry,
                &namespace,
            )?;
            self.recover_native_amx_evidence_publication_temp_locked(
                recovery.guard(),
                &entry,
                &namespace,
                NativeAmxEvidenceRecoveryPhase::Startup,
            )?;
            recovery.finish();
        }
        let inventory = self.inventory_native_amx_evidence_files_locked(&namespace, true)?;
        let receipt_payload_heights =
            inventory.receipts.keys().copied().collect::<BTreeSet<_>>();
        let manifest_payload_heights =
            inventory.manifests.keys().copied().collect::<BTreeSet<_>>();
        let latest_height = receipt_payload_heights.last().copied();
        let mut validated_manifests = BTreeMap::new();
        for manifest_height in &manifest_payload_heights {
            let file = inventory
                .manifests
                .get(manifest_height)
                .expect("inventoried Native AMX manifest height exists");
            let manifest =
                self.decode_native_amx_manifest_file_locked(&entry, &namespace, file)?;
            if !self
                .native_amx_participant_application_manifest_matches_available_finality_under_prune_and_canonical_guards(
                    &manifest,
                )
            {
                return Err(Self::invalid_lane_artifact_error(
                    file.path.clone(),
                    format!(
                        "Native AMX participant manifest at retained height {manifest_height} conflicts with authenticated finality"
                    ),
                ));
            }
            validated_manifests.insert(*manifest_height, manifest);
        }
        let mut validated_receipts = BTreeMap::new();
        let mut startup_evidence = BTreeMap::new();
        for receipt_height in &receipt_payload_heights {
            let file = inventory
                .receipts
                .get(receipt_height)
                .expect("inventoried Native AMX receipt height exists");
            let receipt =
                self.decode_native_amx_receipt_file_locked(&entry, &namespace, file)?;
            let evidence = self
                .classify_native_amx_latest_receipt_evidence_under_startup_guards(
                    &entry,
                    &receipt,
                    &namespace,
                    &manifest_payload_heights,
                    exact_durable_tip,
                )?;
            if evidence != NativeAmxParticipantReceiptStartupEvidence::DurablyApplied
                && Some(*receipt_height) != latest_height
            {
                return Err(Self::invalid_lane_artifact_error(
                    file.path.clone(),
                    format!(
                        "older Native AMX participant receipt at retained height {receipt_height} has an unrecoverable partial evidence join"
                    ),
                ));
            }
            validated_receipts.insert(*receipt_height, receipt);
            startup_evidence.insert(*receipt_height, evidence);
        }
        let receipt_without_manifest = receipt_payload_heights
            .difference(&manifest_payload_heights)
            .copied()
            .collect::<Vec<_>>();
        let manifest_without_receipt = manifest_payload_heights
            .difference(&receipt_payload_heights)
            .copied()
            .collect::<Vec<_>>();
        Self::validate_native_amx_retained_history_continuity(
            &validated_manifests,
            &validated_receipts,
            true,
        )
        .map_err(|message| {
            Self::invalid_lane_artifact_error(
                evidence_directory.clone(),
                format!("Native AMX startup retained history is invalid: {message}"),
            )
        })?;
        let expected_receipt = latest_height
            .and_then(|height| validated_receipts.get(&height))
            .cloned();
        let expected_startup_evidence =
            latest_height.and_then(|height| startup_evidence.get(&height).copied());
        let expected_can_publish = !matches!(
            expected_startup_evidence,
            Some(NativeAmxParticipantReceiptStartupEvidence::PendingManifestRepair)
        );
        let expected = expected_receipt
            .as_ref()
            .map(NativeAmxParticipantReceiptLatestIndexV2::from_receipt);
        let mut authenticated_complete = BTreeMap::new();
        for (height, receipt) in &validated_receipts {
            let Some(manifest) = validated_manifests.get(height) else {
                continue;
            };
            let identity = NativeAmxParticipantReceiptLatestIndexV2::from_receipt(receipt);
            if !identity.matches_manifest(manifest) {
                return Err(Self::invalid_lane_artifact_error(
                    evidence_directory.clone(),
                    format!(
                        "Native AMX complete startup pair at height {height} has conflicting latest-index projections"
                    ),
                ));
            }
            authenticated_complete.insert(*height, identity);
        }
        let latest_child = lane_resources.guard().resource_child(vec![
            latest_index_path.clone(),
            evidence_directory.join(NATIVE_AMX_PARTICIPANT_RECEIPTS_LATEST_INDEX_TEMP_FILE),
        ]);
        if self.reconcile_native_amx_latest_index_temp_locked(
            &entry,
            &namespace,
            &latest_index_path,
            &authenticated_complete,
            expected,
            expected_can_publish,
        )? == NativeAmxLatestIndexTempReconciliation::Promoted
        {
            rebuilt = rebuilt.saturating_add(1);
        }
        let current = self.decode_bound_native_amx_participant_receipt_latest_index_locked(
            &entry,
            &latest_index_path,
            &namespace,
        )?;
        let current_manifest_backed = if let Some(current) = current {
            let canonical_height = usize::try_from(current.application_block_height)
                .ok()
                .and_then(NonZeroUsize::new);
            if self
                .require_active_lane_incarnation(
                    &entry,
                    current.lane_incarnation,
                    current.application_block_height,
                )
                .is_err()
                || canonical_height.and_then(|height| self.get_durable_block_hash(height))
                    != Some(current.application_block_hash)
            {
                return Err(Self::invalid_lane_artifact_error(
                    latest_index_path,
                    "Native AMX participant latest index targets a stale incarnation or non-canonical application block",
                ));
            }
            let current_receipt_backed = validated_receipts
                .get(&current.lane_block_height)
                .is_some_and(|receipt| current.matches_receipt(receipt));
            let current_manifest_backed = validated_manifests
                .get(&current.lane_block_height)
                .is_some_and(|manifest| current.matches_manifest(manifest));
            if !current_receipt_backed && !current_manifest_backed {
                return Err(Self::invalid_lane_artifact_error(
                    latest_index_path.clone(),
                    "Native AMX participant latest index is not backed by its exact receipt or QC-authenticated manifest",
                ));
            }
            current_manifest_backed
        } else {
            false
        };
        match (expected, current) {
            (Some(expected), Some(current)) if current != expected => {
                if current.lane_block_height > expected.lane_block_height
                    && current_manifest_backed
                    && manifest_without_receipt.contains(&current.lane_block_height)
                {
                    iroha_logger::warn!(
                        lane = %entry.lane_id.as_u32(),
                        dataspace = entry.dataspace_id.as_u64(),
                        lane_block_height = current.lane_block_height,
                        "Native AMX derived latest pointer is awaiting authoritative receipt repair"
                    );
                } else if current.lane_block_height < expected.lane_block_height {
                    if expected_can_publish {
                        let receipt = expected_receipt.as_ref().ok_or_else(|| {
                            Self::invalid_lane_artifact_error(
                                evidence_directory.clone(),
                                "Native AMX participant highest receipt disappeared during startup reconstruction",
                            )
                        })?;
                        self.persist_native_amx_participant_receipt_latest_index_from_reconstructed_inventory_locked(
                            &entry,
                            receipt,
                            &latest_index_path,
                            &namespace,
                        )?;
                        rebuilt = rebuilt.saturating_add(1);
                    } else {
                        iroha_logger::warn!(
                            lane = %entry.lane_id.as_u32(),
                            dataspace = entry.dataspace_id.as_u64(),
                            lane_block_height = expected.lane_block_height,
                            "newest Native AMX receipt is awaiting manifest repair before latest-pointer advancement"
                        );
                    }
                } else {
                    return Err(Self::invalid_lane_artifact_error(
                        latest_index_path,
                        "Native AMX participant latest index conflicts with exact durable application evidence",
                    ));
                }
            }
            (Some(expected), None) if expected_can_publish => {
                let receipt = expected_receipt.as_ref().ok_or_else(|| {
                    Self::invalid_lane_artifact_error(
                        evidence_directory.clone(),
                        "Native AMX participant highest receipt disappeared during startup reconstruction",
                    )
                })?;
                debug_assert!(expected.matches_receipt(receipt));
                self.persist_native_amx_participant_receipt_latest_index_from_reconstructed_inventory_locked(
                    &entry,
                    receipt,
                    &latest_index_path,
                    &namespace,
                )?;
                rebuilt = rebuilt.saturating_add(1);
            }
            (Some(_), None) => {
                iroha_logger::warn!(
                    lane = %entry.lane_id.as_u32(),
                    dataspace = entry.dataspace_id.as_u64(),
                    "Native AMX receipt is awaiting manifest repair before latest-pointer publication"
                );
            }
            (Some(_), Some(_)) | (None, None) => {}
            (None, Some(current)) => {
                iroha_logger::warn!(
                    lane = %entry.lane_id.as_u32(),
                    dataspace = entry.dataspace_id.as_u64(),
                    lane_block_height = current.lane_block_height,
                    "Native AMX derived latest pointer is awaiting authoritative receipt repair"
                );
            }
        }
        if !Self::progress_mutation_namespace_unchanged(&namespace) {
            return Err(Self::invalid_lane_artifact_error(
                evidence_directory.clone(),
                "Native AMX startup evidence namespace changed during reconstruction",
            ));
        }
        latest_child.finish();
        if expected_can_publish
            && let Some(receipt) = expected_receipt.as_ref()
            && let Some(manifest) = validated_manifests
                .get(&receipt.participant_proposal.descriptor.lane_block_height)
        {
            // Durable physical publication consumes its original allocation
            // even while post-WSV authority and retention cleanup are pending.
            self.consume_native_amx_startup_stable_components_locked(
                &entry, &namespace, manifest, receipt,
            )?;
        }
        // A prepublished tip intentionally has no post-WSV metadata yet.
        // Keep the previous complete pair until State replay commits that
        // tip and the normal repair path authenticates the full join.
        if native_amx_startup_retention_cleanup_authorized(
            expected_startup_evidence,
            !receipt_without_manifest.is_empty() || !manifest_without_receipt.is_empty(),
        ) {
            self.prune_native_amx_evidence_pairs_locked(
                lane_resources.guard(),
                &entry,
                &namespace,
            )?;
        } else {
            self.inventory_native_amx_evidence_files_locked(&namespace, true)?;
            lane_resources.guard().resource_batch(0).finish();
        }
        let after_bytes = self.native_amx_evidence_tracked_bytes_locked(&namespace)?;
        self.update_disk_usage_delta(before_bytes, after_bytes);
        if native_amx_startup_retention_cleanup_authorized(
            expected_startup_evidence,
            !receipt_without_manifest.is_empty() || !manifest_without_receipt.is_empty(),
        ) && let Some(receipt) = expected_receipt.as_ref()
        {
            let height = receipt.participant_proposal.descriptor.lane_block_height;
            let manifest = validated_manifests.get(&height).ok_or_else(|| {
                Error::PruneIntentConflict(
                    "Native startup completion lost its authenticated manifest".to_owned(),
                )
            })?;
            self.validate_native_amx_startup_completed_pair_locked(
                &entry, &namespace, &inventory, manifest, receipt,
            )?;
            self.complete_native_amx_publication_route_capacity_locked(
                &entry, &namespace, receipt,
            )?;
        }
        lane_resources.finish();
    }
    accounting_mutation.finish();
    if !self.disk_usage_initialized.load(Ordering::Relaxed)
        || !self.disk_usage_total_initialized.load(Ordering::Relaxed)
    {
        // A prior failed recovery attempt deliberately invalidates both
        // caches. The successful retry has now released its mutation
        // guard, so rebuild the complete enforced/total snapshot instead
        // of publishing a delta against stale cached totals.
        self.refresh_disk_usage_bytes()?;
    }
    Ok(rebuilt)
}

if !self.lane_route_active(
            body.coordinator_lane_id,
            body.coordinator_dataspace_id,
            body.coordinator_lane_incarnation,
