fn wrap<'state>(
        &'state self,
        guard: parking_lot::MutexGuard<'state, T>,
    ) -> PublicationGuard<'state, T> {
        // Advance while the actual physical mutex is held, before any caller
        // can create/rename/unlink or unwind. Saturation permanently disables
        // observation reuse instead of allowing an ABA wraparound.
        if let Some(epoch) = &self.mutation_epoch {
            let _ = epoch.fetch_update(
                std::sync::atomic::Ordering::Relaxed,
                std::sync::atomic::Ordering::Relaxed,
                |epoch| epoch.checked_add(1),
            );
        }
        self.wrap_read_only(guard)
    }

fn wrap_read_only<'state>(
        &'state self,
        guard: parking_lot::MutexGuard<'state, T>,
    ) -> PublicationGuard<'state, T> {
        let epoch = self.mutation_epoch.as_ref().and_then(|epoch| {
            let epoch = epoch.load(std::sync::atomic::Ordering::Relaxed);
            (epoch != u64::MAX).then_some(epoch)
        });
        PublicationGuard {
            mutation_epoch: epoch,
            inner: self.released.guard(PhysicalPublicationGuard {
                guard: Some(guard),
                fair: false,
            }),
        }
    }

fn try_publication_lease(
        &self,
    ) -> Result<KuraPublicationLease<'_>, KuraPublicationPreparationError> {
        fn acquire<'kura>(
            field: &'static str,
            lock: &'kura PublicationMutex,
        ) -> Result<PublicationGuard<'kura>, KuraPublicationPreparationError> {
            lock.try_lock_or_wait()
                .map_err(|wait| KuraPublicationPreparationError::Busy { field, wait })
        }
        // Canonical poisoning is permanent for this Kura. It cannot become a
        // lock-release dependency, even when another physical owner is busy.
        self.ensure_canonical_storage_not_poisoned()
            .map_err(KuraPublicationPreparationError::Storage)?;
        let mut fences = AcquiredKuraPublicationFences::new(self);
        fences.prune = Some(acquire("prune_lock", &self.prune_lock)?);
        // Active pruning also sets this flag while it owns prune_lock. Only
        // classify it as restart-required after acquiring that actual owner.
        self.ensure_prune_recovery_not_required()
            .map_err(KuraPublicationPreparationError::Storage)?;
        fences.canonical = Some(acquire("canonical_chain_lock", &self.canonical_chain_lock)?);
        let pending_canonical_bytes = self
            .try_pending_canonical_capacity_bytes_under_prune_and_canonical_guards(&mut fences)?;
        fences.geometry = Some(acquire("lane_geometry_lock", &self.lane_geometry_lock)?);
        fences.sidecar = Some(acquire("sidecar_lock", &self.sidecar_lock)?);
        self.ensure_prune_recovery_not_required()
            .map_err(KuraPublicationPreparationError::Storage)?;
        self.ensure_canonical_storage_not_poisoned()
            .map_err(KuraPublicationPreparationError::Storage)?;
        Ok(KuraPublicationLease {
            kura: self,
            pending_canonical_bytes,
            fences,
        })
    }

fn try_pending_canonical_capacity_bytes_under_prune_and_canonical_guards<'kura>(
        &'kura self,
        fences: &mut AcquiredKuraPublicationFences<'kura>,
    ) -> Result<u64, KuraPublicationPreparationError> {
        if self.max_disk_usage_bytes == 0 || self.store_root.as_os_str().is_empty() {
            return Ok(0);
        }
        let (persisted_count, unindexed_bytes) = self.persisted_count_and_unindexed_bytes()?;
        self.pending_block_bytes_with_merge_resolver(persisted_count, unindexed_bytes, |hash| {
            fences.sidecar = Some(self.sidecar_lock.try_lock_or_wait().map_err(|wait| {
                KuraPublicationPreparationError::Busy {
                    field: "sidecar_lock",
                    wait,
                }
            })?);
            let pending = self.pending_merge_entry_by_hash_under_sidecar_guard(hash)?;
            fences.release_cold_sidecar()?;
            self.merge_entry_by_hash_after_sidecar(hash, pending)
                .map_err(KuraPublicationPreparationError::Storage)
        })
    }

fn try_new(
        target: &State,
        geometry: &PreparedCarrierGeometry,
        header: BlockHeader,
        source: &crate::sumeragi::v2_apply::carrier_queue_retirement::OriginalCarrierQueue<'queue>,
        cut: QueueLaneRetirementCut<'queue>,
    ) -> Result<Self, (CarrierQueueRetirementError, QueueRetirementCleanup)> {
        let checked = (|| {
            if !source.belongs_to(target) || !geometry.matches_publication_target(target, header) {
                return Err(CarrierQueueRetirementError::ForeignState);
            }
            if !source.owns_cut(&cut) {
                return Err(CarrierQueueRetirementError::ForeignQueue);
            }
            let mut routes = Vec::new();
            geometry
                .for_each_retirement_route(|lane, dataspace, incarnation| {
                    routes.push((lane, dataspace, incarnation));
                    Ok(())
                })
                .map_err(CarrierQueueRetirementError::Geometry)?;
            for &(lane, dataspace, incarnation) in &routes {
                match cut.lane_pending_work_release(lane, dataspace, incarnation) {
                    Ok(None) => {}
                    Ok(Some(wait)) => {
                        return Err(CarrierQueueRetirementError::Pending {
                            lane,
                            dataspace,
                            incarnation,
                            wait,
                        });
                    }
                    Err(error) => return Err(CarrierQueueRetirementError::Unavailable(error)),
                }
            }
            let state_owner = target
                .native_lane_state_owner()
                .ok_or(CarrierQueueRetirementError::ForeignState)?;
            Ok((state_owner, routes))
        })();
        match checked {
            Ok((state_owner, routes)) => Ok(Self {
                state_owner,
                header,
                routes,
                _cut: cut,
            }),
            Err(error) => Err((
                error,
                QueueRetirementCleanup {
                    released: cut.release_deferred().map(Some),
                },
            )),
        }
    }

