fn try_next_block(
        &self,
        replacement: bool,
    ) -> Result<BlockHashesBlock<'_>, BlockHashAdmissionError> {
        self.budget.with_deferred_refund_notifications(|_| {
            let map = self.map().ok_or(BlockHashAdmissionError::ReadOnly)?;
            let wait = map.observe_reader_release();
            let view = self.try_view().map_err(|error| match error {
                concread::bptree::OwnedWriteError::Busy => {
                    BlockHashAdmissionError::Busy(wait.clone())
                }
                concread::bptree::OwnedWriteError::Poisoned => BlockHashAdmissionError::Poisoned,
                concread::bptree::OwnedWriteError::Changed => {
                    BlockHashAdmissionError::Changed(wait.clone())
                }
            })?;
            let prefix = if replacement {
                view.len().saturating_sub(1)
            } else {
                view.len()
            };
            let predecessor = match &view.inner {
                BlockHashesViewInner::Owned(view) => view.predecessor().retain(),
                BlockHashesViewInner::Mapped(_) => unreachable!("mutable map checked above"),
            };
            drop(view);
            let wait = self.released.observe();
            let acquired = map
                .try_acquire_writer()
                .ok_or_else(|| BlockHashAdmissionError::Busy(wait.clone()))?;
            let writer = match self
                .released
                .poisoning_guard(acquired)
                .try_map_preserving_release(|acquired| {
                    acquired
                        .try_insert_admitted_with_footprint(
                            prefix,
                            HashOf::from_untyped_unchecked(Hash::prehashed([0; 32])),
                            |existing, additional| self.admit_successor(existing, additional),
                        )
                        .map_err(|(acquired, input, error)| (acquired, (input, error)))
                }) {
                Ok(writer) => writer,
                Err((acquired, (_, error))) => {
                    drop(acquired);
                    return Err(self.admission_error(error, wait));
                }
            };
            let (work, _) = writer.release_with(|(writer, previous)| (writer.detach(), previous));
            if !predecessor.matches(&work.predecessor()) {
                return Err(BlockHashAdmissionError::Changed(wait));
            }
            Ok(BlockHashesBlock {
                inner: self,
                work,
                visible_len: prefix,
                reserved_tip: Some(prefix),
                fixture_edits: false,
                mode: if replacement {
                    mv::BlockMode::Replace
                } else {
                    mv::BlockMode::Ordinary
                },
            })
        })
    }

pub(super) fn acquire_canonical_runtime_block(
    &self,
    replacement: bool,
) -> Result<AcquiredRuntimeBlock<'_>, StateAdmissionError> {
    loop {
        let generation = self.state_view_generation();
        if generation % 2 != 0 {
            std::thread::yield_now();
            continue;
        }
        // Capture immutable index inputs before acquiring any native writer.
        // Their release callbacks may retry those writers synchronously. The
        // final generation check joins the manifest baseline to the acquired
        // World; SCCP still validates that World's exact current/undo wire.
        let baseline = self.lane_manifests.read().clone();
        let mut registry_cache = self.sccp_registry_cache.lock().clone();
        // All constructors use the same order. Every guard is dropped before
        // retry; a World-only generation check cannot bind the predecessor.
        // Hash construction detaches its private tree before waiting for World.
        let block_hashes = self.block_hashes.try_next_block(replacement)?;
        let membership = self.transactions.prepare_next_block(replacement)?;
        // Projection payloads outlive joint physical retirement on refusal
        // and unwind. Every Cell slot remains in this caller while initializing.
        let projection_result;
        let mut projection;
        let mut sccp_registry;
        let mut pending =
            acquisition::RuntimeBlockAcquisition::new(self, block_hashes, membership);
        if let Err(error) = pending.initialize(replacement) {
            // The same original prepared generation returns to its sole
            // preparation slot only after every physical sibling releases.
            pending.retain_refused_membership();
            return Err(error.into());
        }
        projection_result = self.project_canonical_runtime_with_manifests(
            pending.canonical_runtime().get(),
            pending.world(),
            &baseline,
        );
        sccp_registry = Some(Self::sccp_registry_snapshot_from_cache(
            pending.world().sccp_registry.get(),
            &mut registry_cache,
        ));
        if !is_stable_state_view_generation(generation, self.state_view_generation()) {
            // One owner unlocks all physical siblings before any native wake,
            // payload cleanup, or original hash-budget refund can run.
            drop(pending);
            drop(sccp_registry);
            drop(projection_result);
            std::thread::yield_now();
            continue;
        }
        projection = Some(
            projection_result.expect("persisted canonical runtime projection must be valid"),
        );
        pending.world_mut().dataspace_catalog = projection
            .as_ref()
            .expect("original prepared runtime projection")
            .nexus
            .dataspace_catalog
            .clone();
        return Ok(pending.finish(&mut projection, &mut sccp_registry));
    }
}

