        _preflight_release: preflight_release,
    }
}

fn detach_retaining(self) -> (DetachedTransactionsBlock, MembershipRelease) {
    self.assert_unpublished();
    let Self {
        block,
        publication,
        next_identity,
        retired_tip: _,
        publication_started: _,
        published: _,
    } = self;
    let mut block = block;
    let history = block
        ._guard
        .history
        .as_mut()
        .expect("original history")
        .recover_detached();
    let detached = DetachedTransactionsBlock {
        history,
        predecessor_identity: block._guard.identity().clone(),
        predecessor: block.latest_block_ref.load_full(),
        current: block
            .current_block
            .as_ref()
            .expect("admitted membership")
            .clone(),
        revert: block.revert,
        publication,
        next_identity,
    };
    let TransactionsBlock {
        _guard,
        current_block,
        ..
    } = block;
    let release = _guard.into_release();
    // The detached journal owns the original staged allocation.
    drop(current_block);
    (detached, release)
}

fn abort(self) -> DetachedCarrierComponents {
    // Reverse local drop order also keeps fences behind all components if
    // abort bookkeeping unwinds before the explicit release below.
    let mut effect_cleanup;
    let fences;
    let Self {
        world,
        runtime,
        transactions,
        block_hashes,
        effect_locks: original_effect_locks,
        _fences: original_fences,
    } = self;
    fences = original_fences;
    effect_cleanup = original_effect_locks;
    let mut effect_locks = effect_cleanup.physical_scope();
    let (world, world_retirement) = world.abort();
    let (runtime, runtime_retirement) = runtime.abort();
    let (transactions, transactions_retirement) = transactions.abort();
    let (block_hashes, block_hashes_retirement) = block_hashes.abort();
    effect_locks.release_writers();
    drop(fences.release_for_completion());
    drop((
        world_retirement,
        runtime_retirement,
        transactions_retirement,
        block_hashes_retirement,
    ));
    DetachedCarrierComponents {
        world,
        runtime,
        transactions,
        block_hashes,
    }
}

pub(in crate::state) fn try_prepare_publication<'target, Installation, E>(
    self,
    target: &'target World,
    scope: Option<&'target AllocationScope<'target>>,
    admit: impl FnOnce(&Self, &World) -> Result<Installation, E>,
) -> Result<
    PreparedWorld<'target, Admission, Installation>,
    (
        Self,
        WorldPublicationError<E>,
        AbortedWorld<'target, Installation>,
    ),
> {
    let mut slot = self.publication_slot(target, scope);
    match slot.try_prepare(admit) {
        Ok(()) => Ok(slot.into_prepared()),
        Err(error) => {
            let original = slot.recover_original();
            Err((original, error, slot.into_cleanup()))
        }
    }
}

