fn new(kura: &'kura Kura) -> Self {
        Self {
            sidecar: None,
            geometry: None,
            canonical: None,
            prune: None,
            cold_sidecar: Some(kura.sidecar_lock.deferred_releases()),
        }
    }

fn release_cold_sidecar(&mut self) -> Result<(), KuraPublicationPreparationError> {
        let sidecar = self.sidecar.take().expect("original cold sidecar guard");
        match sidecar.try_release_into(
            self.cold_sidecar
                .as_mut()
                .expect("original sidecar release batch"),
        ) {
            Ok(()) => Ok(()),
            Err(sidecar) => {
                // Preserve even an invalid source substitution for joint cleanup.
                // Nothing was unlocked or notified by the refused transfer.
                self.sidecar = Some(sidecar);
                Err(KuraPublicationPreparationError::Storage(
                    Error::PruneIntentConflict(
                        "publication sidecar release belongs to a foreign physical owner"
                            .to_owned(),
                    ),
                ))
            }
        }
    }

fn take_cleanup(&mut self) -> KuraPublicationCleanup {
        KuraPublicationCleanup {
            _fences: [
                self.sidecar.take().map(PublicationGuard::release_deferred),
                self.geometry.take().map(PublicationGuard::release_deferred),
                self.canonical
                    .take()
                    .map(PublicationGuard::release_deferred),
                self.prune.take().map(PublicationGuard::release_deferred),
            ],
            _cold_sidecar: self.cold_sidecar.take(),
        }
    }

fn drop(&mut self) {
        // The fixed cleanup owner is built only after all four physical unlocks.
        // Empty slots and an unused cold batch cannot signal an unacquired lock.
        drop(self.take_cleanup());
    }

fn authenticate_archive_capture(
        &self,
        network_id: NetworkId,
        height: u64,
        block_hash: [u8; 32],
        finalized_at_unix_ms: u64,
        receipt: &super::KuraV2CommitReceipt,
    ) -> Result<(), KuraArchiveCaptureAuthenticationError> {
        let mut fences = AcquiredKuraPublicationFences::new(self);
        fences.prune = Some(self.prune_lock.lock());
        fences.canonical = Some(self.canonical_chain_lock.lock());
        fences.sidecar = Some(self.sidecar_lock.lock());
        self.authenticate_archive_capture_under_publication_guards(
            network_id,
            height,
            block_hash,
            finalized_at_unix_ms,
            receipt,
        )
    }

struct DeferredReleaseBatch {
    notification: ReleaseNotification,
    released: bool,
    poisoned: bool,
}

fn deferred_batch(&self) -> DeferredReleaseBatch {
        DeferredReleaseBatch {
            notification: ReleaseNotification {
                state: Arc::clone(&self.state),
            },
            released: false,
            poisoned: false,
        }
    }

pub fn try_release_into<R>(
    mut self,
    batch: &mut DeferredReleaseBatch,
    release: impl FnOnce(T) -> R,
) -> Result<R, Self> {
    if !Arc::ptr_eq(&self.notification.state, &batch.notification.state) {
        return Err(self);
    }
    struct Record<'a> {
        batch: &'a mut DeferredReleaseBatch,
        poison: PoisonPolicy<'a>,
    }
    impl Drop for Record<'_> {
        fn drop(&mut self) {
            self.batch.released = true;
            self.batch.poisoned |= self.poison.observe();
        }
    }
    // On callback unwind the original physical owner drops before this
    // record. The batch remains in its caller's aggregate throughout.
    let record = Record {
        batch,
        poison: self.poison,
    };
    let inner = self.inner.take().expect("owned release guard");
    let _transferred = std::mem::ManuallyDrop::new(self);
    let result = release(inner);
    drop(record);
    Ok(result)
}

fn try_release_into(
        self,
        batch: &mut concread::release::DeferredReleaseBatch,
    ) -> Result<(), Self> {
        let mutation_epoch = self.mutation_epoch;
        self.inner
            .try_release_into(batch, drop)
            .map_err(|inner| Self {
                inner,
                mutation_epoch,
            })
    }

fn merge_entry_by_hash_with_sidecar_guard(
        &self,
        hash: HashOf<MergeLedgerEntry>,
        sidecar: PublicationGuard<'_>,
    ) -> Result<Option<MergeLedgerEntry>> {
        let pending = self.pending_merge_entry_by_hash_under_sidecar_guard(hash)?;
        drop(sidecar);
        self.merge_entry_by_hash_after_sidecar(hash, pending)
    }

fn merge_entry_by_hash_after_sidecar(
        &self,
        hash: HashOf<MergeLedgerEntry>,
        pending: Option<MergeLedgerEntry>,
    ) -> Result<Option<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        if pending.is_some() {
            return Ok(pending);
        }
        let mut merge_log = self.merge_log.lock();
        self.ensure_prune_recovery_not_required()?;
        let entry = merge_log.entry_by_hash(hash)?;
        self.ensure_prune_recovery_not_required()?;
        Ok(entry)
    }

struct LinCowCellOwnedAcquisition<'a, T, R, U, Charge = Untracked> {
    guard: MutexGuard<'a, WriteState<T, R, Charge>>,
    owned: LinCowCellOwned<T, R, U, Charge>,
    caller: &'a LinCowCell<T, R, U, Charge>,
    poisoned: bool,
}

fn validate(
        self,
    ) -> Result<LinCowCellWriteTxn<'a, T, R, U, Charge>, (Self, OwnedWriteError)> {
        if self.poisoned {
            return Err((self, OwnedWriteError::Poisoned));
        }
        if !Shared::ptr_eq(&self.guard.current, &self.owned.base) {
            return Err((self, OwnedWriteError::Changed));
        }
        let Self {
            guard,
            owned,
            caller,
            ..
        } = self;
        let LinCowCellOwned {
            work,
            next,
            base,
            root,
        } = owned;
        // The same root remains borrowed through caller throughout this handoff.
        drop(root);
        Ok(LinCowCellWriteTxn {
            caller,
            guard,
            work,
            next,
            base,
        })
    }

fn abort(self) -> LinCowCellOwned<T, R, U, Charge> {
        let Self { guard, owned, .. } = self;
        drop(guard);
        owned
    }

pub fn try_acquire_owned(
    &self,
    owned: LinCowCellOwned<T, R, U, Charge>,
) -> Result<
    LinCowCellOwnedAcquisition<'_, T, R, U, Charge>,
    (LinCowCellOwned<T, R, U, Charge>, OwnedWriteError),
> {
    self.acquire_owned(owned, false)
}

fn try_write_owned(
        &self,
        owned: LinCowCellOwned<T, R, U, Charge>,
    ) -> Result<
        LinCowCellWriteTxn<'_, T, R, U, Charge>,
        (LinCowCellOwned<T, R, U, Charge>, OwnedWriteError),
    > {
        self.try_acquire_owned(owned)?
            .validate()
            .map_err(|(acquired, error)| (acquired.abort(), error))
    }

fn validate(self) -> Result<BptreeMapWriteTxn<'a, K, V, M>, (Self, OwnedWriteError)> {
        self.inner
            .validate()
            .map(|inner| BptreeMapWriteTxn { inner })
            .map_err(|(inner, error)| (Self { inner }, error))
    }

fn abort(self) -> BptreeMapOwned<K, V, M> {
        BptreeMapOwned {
            inner: self.inner.abort(),
        }
    }

fn try_acquire_owned(
        &self,
        owned: BptreeMapOwned<K, V, M>,
    ) -> Result<BptreeMapOwnedAcquisition<'_, K, V, M>, (BptreeMapOwned<K, V, M>, OwnedWriteError)>
    {
        owned.inner.as_ref().assert_operable();
        self.inner
            .try_acquire_owned(owned.inner)
            .map(|inner| BptreeMapOwnedAcquisition { inner })
            .map_err(|(inner, error)| (BptreeMapOwned { inner }, error))
    }

fn try_write_owned(
        &self,
        owned: BptreeMapOwned<K, V, M>,
    ) -> Result<BptreeMapWriteTxn<'_, K, V, M>, (BptreeMapOwned<K, V, M>, OwnedWriteError)> {
        self.try_acquire_owned(owned)?
            .validate()
            .map_err(|(acquired, error)| (acquired.abort(), error))
    }

fn acquire_owned_writer<'a, K: Key, V: Value, M: MapMode + NodeCloning<K, V>>(
    map: &'a BptreeMap<K, V, M>,
    released: &'a ReleaseNotification,
    owned: BptreeMapOwned<K, V, M>,
) -> Result<
    ReleaseGuard<'a, BptreeMapWriteTxn<'a, K, V, M>>,
    (
        BptreeMapOwned<K, V, M>,
        OwnedWriteError,
        Option<DeferredRelease>,
    ),
> {
    let acquired = map
        .try_acquire_owned(owned)
        .map_err(|(owned, error)| (owned, error, None))?;
    released
        .poisoning_guard(acquired)
        .try_map_preserving_release(|acquired| acquired.validate())
        .map_err(|(acquired, error)| {
            let (owned, notification) = acquired.release_deferred(|acquired| acquired.abort());
            (owned, error, Some(notification))
        })
}

struct LinCowCellWriterAcquisition<'a, T, R, U, Charge = Untracked> {
    guard: MutexGuard<'a, WriteState<T, R, Charge>>,
    caller: &'a LinCowCell<T, R, U, Charge>,
    poisoned: bool,
}

enum WriterAdmissionError<E> {
    /// An earlier unwind poisoned the acquired writer; admission was not called.
    Poisoned,
    /// Planning or admission refused before successor construction.
    Refused(E),
}

fn try_write_charged<E>(
        self,
        admit: impl FnOnce(&T, WriterLayouts) -> Result<WriterAdmission<Charge, T::WriterInput>, E>,
    ) -> Result<LinCowCellWriteTxn<'a, T, R, U, Charge>, (Self, WriterAdmissionError<E>)> {
        if self.poisoned {
            return Err((self, WriterAdmissionError::Poisoned));
        }
        let admission = match admit(
            &self.guard.data,
            LinCowCell::<T, R, U, Charge>::writer_allocation_layouts(),
        ) {
            Ok(admission) => admission,
            Err(error) => return Err((self, WriterAdmissionError::Refused(error))),
        };
        let Self { guard, caller, .. } = self;
        Ok(caller.create_writer(guard, admission))
    }

fn try_write_charged<E>(
        &self,
        admit: impl FnOnce(&T, WriterLayouts) -> Result<WriterAdmission<Charge, T::WriterInput>, E>,
    ) -> Result<Option<LinCowCellWriteTxn<'_, T, R, U, Charge>>, E> {
        let Some(acquired) = self.try_acquire_writer() else {
            return Ok(None);
        };
        match acquired.try_write_charged(admit) {
            Ok(writer) => Ok(Some(writer)),
            Err((acquired, error)) => {
                drop(acquired);
                match error {
                    WriterAdmissionError::Poisoned => Ok(None),
                    WriterAdmissionError::Refused(error) => Err(error),
                }
            }
        }
    }

fn try_acquire_writer(&self) -> Option<LinCowCellWriterAcquisition<'_, T, R, U, Charge>> {
        let (guard, poisoned) = match self.write.try_lock() {
            Ok(guard) => (guard, false),
            Err(TryLockError::WouldBlock) => return None,
            Err(TryLockError::Poisoned(error)) => (error.into_inner(), true),
        };
        Some(LinCowCellWriterAcquisition {
            guard,
            caller: self,
            poisoned,
        })
    }

fn try_acquire_writer(&self) -> Option<BptreeMapWriterAcquisition<'_, K, V, M>> {
        self.inner
            .try_acquire_writer()
            .map(|inner| BptreeMapWriterAcquisition { inner })
    }

fn insert_with_source<E>(
        &self,
        key: K,
        value: V,
        admit: impl FnOnce(
            &SuperBlock<K, V, Prepaid<P>>,
            AllocationDemand,
        ) -> Result<P, MapAdmissionError<E>>,
    ) -> Result<(BptreeMapOwned<K, V, Prepaid<P>>, Option<V>), ((K, V), MapAdmissionError<E>)> {
        let Some(acquired) = self.try_acquire_writer() else {
            return Err(((key, value), MapAdmissionError::Busy));
        };
        match acquired.insert_with_source(key, value, admit) {
            Ok((writer, previous)) => Ok((writer.detach(), previous)),
            Err((acquired, input, error)) => {
                drop(acquired);
                Err((input, error))
            }
        }
    }

fn insert_with_source<E>(
        self,
        key: K,
        value: V,
        admit: impl FnOnce(
            &SuperBlock<K, V, Prepaid<P>>,
            AllocationDemand,
        ) -> Result<P, MapAdmissionError<E>>,
    ) -> Result<
        (BptreeMapWriteTxn<'a, K, V, Prepaid<P>>, Option<V>),
        (Self, (K, V), MapAdmissionError<E>),
    > {
        let mut input = Some((key, value));
        let acquired = self.inner.try_write_charged(|source, shells| {
            let plan =
                plan_insert::<K, V, P>(source, &input.as_ref().expect("original input").0, shells)
                    .map_err(MapAdmissionError::Planning)?;
            let mut provider = Prepaid(Some(admit(source, plan.demand)?));
            let first_charge = provider.take_node_charge(plan.first_layout);
            let first = FixedTrackingBuffer::try_new(plan.first, first_charge)
                .unwrap_or_else(|_| unreachable!("planned first buffer layout"));
            let last_charge = provider.take_node_charge(plan.last_layout);
            let last = FixedTrackingBuffer::try_new(plan.last, last_charge)
                .unwrap_or_else(|_| unreachable!("planned retirement buffer layout"));
            let charges = WriterCharges {
                cursor: provider.take_node_charge(shells.cursor),
                reader: provider.take_node_charge(shells.reader),
            };
            Ok(WriterAdmission {
                charges,
                input: (provider, first, last),
            })
        });
        let mut writer = match acquired {
            Ok(writer) => writer,
            Err((inner, error)) => {
                let error = match error {
                    WriterAdmissionError::Poisoned => MapAdmissionError::Poisoned,
                    WriterAdmissionError::Refused(error) => error,
                };
                return Err((
                    Self { inner },
                    input.take().expect("original refused input"),
                    error,
                ));
            }
        };
        let (key, value) = input.take().expect("original admitted input");
        writer.as_mut().begin_admitted_edit();
        let previous = writer.as_mut().try_insert(key, value).unwrap_or_else(|_| {
            unreachable!("complete fixed tracking bound planned under original writer")
        });
        // A further closed edit requires its own complete admission. Release the
        // unused remainder now, before potentially long handoff waits;
        // actual allocation charges remain attached to their original owners.
        writer.as_mut().finish_admitted_funding();
        Ok((BptreeMapWriteTxn { inner: writer }, previous))
    }

fn try_insert_admitted_with_footprint<E>(
        &self,
        key: K,
        value: V,
        admit: impl FnOnce(AllocationDemand, AllocationDemand) -> Result<P, E>,
    ) -> Result<(BptreeMapOwned<K, V, Prepaid<P>>, Option<V>), ((K, V), MapAdmissionError<E>)> {
        self.insert_with_source(key, value, |source, additional| {
            let existing =
                current_footprint::<K, V, P>(source).map_err(MapAdmissionError::Planning)?;
            admit(existing, additional).map_err(MapAdmissionError::Refused)
        })
    }

fn try_insert_admitted_with_footprint<E>(
        self,
        key: K,
        value: V,
        admit: impl FnOnce(AllocationDemand, AllocationDemand) -> Result<P, E>,
    ) -> Result<
        (BptreeMapWriteTxn<'a, K, V, Prepaid<P>>, Option<V>),
        (Self, (K, V), MapAdmissionError<E>),
    > {
        self.insert_with_source(key, value, |source, additional| {
            let existing =
                current_footprint::<K, V, P>(source).map_err(MapAdmissionError::Planning)?;
            admit(existing, additional).map_err(MapAdmissionError::Refused)
        })
    }

fn current_footprint<K, V, P>(
    source: &SuperBlock<K, V, Prepaid<P>>,
) -> Result<AllocationDemand, PlanningError>
where
    K: Copy + Ord + Debug + Send + Sync + 'static,
    V: Copy + Send + Sync + 'static,
    P: ClonePlanning<K, V>,
{
    let mut existing = AllocationDemand::new();
    existing.add_layout(MapCell::<K, V, Prepaid<P>>::initial_allocation_layouts().root)?;
    existing.add_layout(MapCell::<K, V, Prepaid<P>>::reader_allocation_layout())?;
    let (leaves, branches) = source.node_counts();
    let mut leaf = AllocationDemand::new();
    leaf.add_layout(Layout::new::<CachePadded<Leaf<K, V, P::Charge>>>())?;
    let mut branch = AllocationDemand::new();
    branch.add_layout(Layout::new::<CachePadded<Branch<K, V, P::Charge>>>())?;
    existing.add(leaf, leaves)?;
    existing.add(branch, branches)?;
    Ok(existing)
}

pub fn acquire_writer(&self) -> LinCowCellWriterAcquisition<'_, T, R, U, Charge> {
        let (guard, poisoned) = match self.write.lock() {
            Ok(guard) => (guard, false),
            Err(error) => (error.into_inner(), true),
        };
        LinCowCellWriterAcquisition {
            guard,
            caller: self,
            poisoned,
        }
    }

pub fn write_with(
        self,
        input: impl FnOnce(&T) -> T::WriterInput,
    ) -> LinCowCellWriteTxn<'a, T, R, U> {
        match self.try_write_charged(|data, _| {
            Ok::<_, std::convert::Infallible>(WriterAdmission {
                charges: WriterCharges {
                    cursor: Untracked,
                    reader: Untracked,
                },
                input: input(data),
            })
        }) {
            Ok(writer) => writer,
            Err((_acquired, WriterAdmissionError::Poisoned)) => {
                panic!("original writer is poisoned")
            }
            Err((_, WriterAdmissionError::Refused(never))) => match never {},
        }
    }

pub fn write_with(
        &self,
        input: impl FnOnce(&T) -> T::WriterInput,
    ) -> LinCowCellWriteTxn<'_, T, R, U> {
        self.acquire_writer().write_with(input)
    }

pub fn acquire_writer(&self) -> BptreeMapWriterAcquisition<'_, K, V, M> {
        BptreeMapWriterAcquisition {
            inner: self.inner.acquire_writer(),
        }
    }

pub fn write(self) -> BptreeMapWriteTxn<'a, K, V> {
        BptreeMapWriteTxn {
            inner: self.inner.write_with(|_| ()),
        }
    }

pub fn write(&self) -> BptreeMapWriteTxn<'_, K, V> {
        self.acquire_writer().write()
    }

pub fn try_write_admitted<E>(
        &self,
        admit: impl FnOnce(AllocationDemand) -> Result<P, E>,
    ) -> Result<BptreeMapWriteTxn<'_, K, V, Prepaid<P>>, MapAdmissionError<E>> {
        let Some(acquired) = self.try_acquire_writer() else {
            return Err(MapAdmissionError::Busy);
        };
        match acquired.try_write_admitted(admit) {
            Ok(writer) => Ok(writer),
            Err((acquired, error)) => {
                drop(acquired);
                Err(error)
            }
        }
    }

pub fn try_clear_admitted<E>(
        &self,
        admit: impl FnOnce(AllocationDemand) -> Result<P, E>,
    ) -> Result<BptreeMapWriteTxn<'_, K, V, Prepaid<P>>, MapAdmissionError<E>> {
        let Some(acquired) = self.try_acquire_writer() else {
            return Err(MapAdmissionError::Busy);
        };
        match acquired.try_clear_admitted(admit) {
            Ok(writer) => Ok(writer),
            Err((acquired, error)) => {
                drop(acquired);
                Err(error)
            }
        }
    }

pub fn try_write_admitted<E>(
    self,
    admit: impl FnOnce(AllocationDemand) -> Result<P, E>,
) -> Result<BptreeMapWriteTxn<'a, K, V, Prepaid<P>>, (Self, MapAdmissionError<E>)> {
    self.write_with_source(|_, demand| admit(demand).map_err(MapAdmissionError::Refused))
}

pub fn try_clear_admitted<E>(
        self,
        admit: impl FnOnce(AllocationDemand) -> Result<P, E>,
    ) -> Result<BptreeMapWriteTxn<'a, K, V, Prepaid<P>>, (Self, MapAdmissionError<E>)> {
        let acquired = self.inner.try_write_charged(|source, shells| {
            checked_next_generation(source.txid)
                .ok_or(MapAdmissionError::Planning(PlanningError::Overflow))?;
            // SAFETY: this exact source is retained under the original writer.
            let mut plan = unsafe { plan_tree_clear::<K, V, P>(source.root, [(0, 0); 2]) }
                .map_err(MapAdmissionError::Planning)?;
            for layout in [shells.cursor, shells.reader] {
                plan.demand
                    .add_layout(layout)
                    .map_err(MapAdmissionError::Planning)?;
            }
            let mut provider = admit(plan.demand).map_err(MapAdmissionError::Refused)?;
            let first = allocate_tracking::<K, V, P>(plan.first, &mut provider)
                .expect("one empty leaf requires original first-seen storage");
            let last = allocate_tracking::<K, V, P>(plan.last, &mut provider)
                .expect("every tree has an original root to retire");
            let charges = WriterCharges {
                cursor: provider.take_node_charge(shells.cursor),
                reader: provider.take_node_charge(shells.reader),
            };
            Ok(WriterAdmission {
                charges,
                input: (Prepaid(Some(provider)), first, last),
            })
        });
        let mut inner = match acquired {
            Ok(writer) => writer,
            Err((inner, error)) => {
                let error = match error {
                    WriterAdmissionError::Poisoned => MapAdmissionError::Poisoned,
                    WriterAdmissionError::Refused(error) => error,
                };
                return Err((Self { inner }, error));
            }
        };
        inner.as_mut().begin_admitted_edit();
        inner
            .as_mut()
            .try_clear()
            .expect("complete original clear plan");
        inner.as_mut().finish_admitted_funding();
        Ok(BptreeMapWriteTxn { inner })
    }

pub fn try_map_pair_preserving_release<'other, S, A, B, E>(
    mut self,
    mut other: ReleaseGuard<'other, S>,
    consume: impl FnOnce(T, S) -> Result<(A, B), E>,
    observe_poison: impl Fn() -> (bool, bool),
) -> Result<(ReleaseGuard<'owner, A>, ReleaseGuard<'other, B>), E> {
    struct Signal<'a> {
        notification: &'a ReleaseNotification,
        poisoned: bool,
    }
    impl Drop for Signal<'_> {
        fn drop(&mut self) {
            self.notification.released(self.poisoned);
        }
    }
    struct PairSignals<'a, 'b, F: Fn() -> (bool, bool)> {
        first: &'a ReleaseNotification,
        second: &'b ReleaseNotification,
        observe_poison: F,
        armed: bool,
    }
    impl<F: Fn() -> (bool, bool)> Drop for PairSignals<'_, '_, F> {
        fn drop(&mut self) {
            if !self.armed {
                return;
            }
            let (first, second) = (self.observe_poison)();
            let first = Signal {
                notification: self.first,
                poisoned: first,
            };
            let second = Signal {
                notification: self.second,
                poisoned: second,
            };
            // Both verdicts are frozen before the first callback. Unwind
            // must still deliver the other original release with its own
            // physical verdict, not the callback's panic state.
            drop(first);
            drop(second);
        }
    }
    let mut signals = PairSignals {
        first: self.notification,
        second: other.notification,
        observe_poison,
        armed: true,
    };
    let first = self.inner.take().expect("owned first release guard");
    let second = other.inner.take().expect("owned second release guard");
    // Only empty wrappers remain; the pair owns both original signals.
    let _first = std::mem::ManuallyDrop::new(self);
    let _second = std::mem::ManuallyDrop::new(other);
    match consume(first, second) {
        Ok((first, second)) => {
            signals.armed = false;
            Ok((
                ReleaseGuard {
                    inner: Some(first),
                    notification: _first.notification,
                    poison: _first.poison,
                },
                ReleaseGuard {
                    inner: Some(second),
                    notification: _second.notification,
                    poison: _second.poison,
                },
            ))
        }
        Err(error) => {
            drop(signals);
            Err(error)
        }
    }
}

pub fn release_pair_with<S, R>(
        self,
        other: ReleaseGuard<'_, S>,
        consume: impl FnOnce(T, S) -> R,
        observe_poison: impl Fn() -> (bool, bool),
    ) -> R {
        match self.try_map_pair_preserving_release::<_, (), (), R>(
            other,
            |first, second| Err(consume(first, second)),
            observe_poison,
        ) {
            Err(result) => result,
            Ok(_) => unreachable!("release never transfers physical owners"),
        }
    }

fn initialize(&mut self, mode: BlockMode) {
    assert!(!self.started, "original storage acquisition is one-shot");
    self.started = true;
    let target = self.target;
    let AcquisitionPhase::Pending { undo, current } = &mut self.phase else {
        panic!("original pending acquisition");
    };
    *undo = WriterPhase::Raw(
        target
            .revert_released
            .poisoning_guard(target.revert.acquire_writer()),
    );
    assert!(!undo.is_poisoned(), "original undo writer is poisoned");
    *current = WriterPhase::Raw(
        target
            .blocks_released
            .poisoning_guard(target.blocks.acquire_writer()),
    );
    assert!(
        !current.is_poisoned(),
        "original storage writer is poisoned"
    );
    let raw = undo.take_raw();
    *undo = WriterPhase::Writer(
        match raw
            .try_map_preserving_release_into(
                &mut self.undo_release,
                |undo| Ok::<_, (_, std::convert::Infallible)>(undo.write()),
                || target.revert.is_poisoned(),
            )
            .unwrap_or_else(|_| unreachable!("original undo release source"))
        {
            Ok(writer) => writer,
            Err((_, never)) => match never {},
        },
    );
    let raw = current.take_raw();
    *current = WriterPhase::Writer(
        match raw
            .try_map_preserving_release_into(
                &mut self.current_release,
                |current| Ok::<_, (_, std::convert::Infallible)>(current.write()),
                || target.blocks.is_poisoned(),
            )
            .unwrap_or_else(|_| unreachable!("original current release source"))
        {
            Ok(writer) => writer,
            Err((_, never)) => match never {},
        },
    );
    // The caller slot owns completed writers before identity lookup and all
    // reset/replacement operations that may invoke arbitrary payload code.
    let predecessor = target.publication.capture();
    let writers = StorageWriters::new(target, undo.take_writer(), current.take_writer());
    self.phase = AcquisitionPhase::Block(Block::new(
        writers,
        mode == BlockMode::Replace,
        predecessor,
        mode,
    ));
    let AcquisitionPhase::Block(block) = &mut self.phase else {
        unreachable!("original storage block");
    };
    block.failed = true;
    let OriginalWriters { revert, blocks } = block.writers.as_mut();
    if mode == BlockMode::Replace {
        for (key, value) in revert.iter() {
            match value {
                None => blocks.remove(key),
                Some(value) => blocks.insert(key.clone(), value.clone()),
            };
        }
    }
    revert.clear();
    block.failed = false;
    self.complete = true;
}

pub fn block(&self) -> Block<'_, K, V> {
    let mut slot = self.block_acquisition();
    crate::BlockAcquisition::initialize(&mut slot, BlockMode::Ordinary);
    crate::BlockAcquisition::into_block(slot)
}

pub fn block_and_revert(&self) -> Block<'_, K, V> {
    let mut slot = self.block_acquisition();
    crate::BlockAcquisition::initialize(&mut slot, BlockMode::Replace);
    crate::BlockAcquisition::into_block(slot)
}

fn open_admitted_writers(&self) -> Result<AdmittedWriters<'_, K, V, P>, AdmittedStorageError> {
        let budget = self
            .allocation
            .as_ref()
            .expect("admitted Storage original pool");
        let current = BptreeMap::<K, V, Prepaid<P>>::writer_start_allocation_demand()
            .map_err(AdmittedStorageError::Planning)?;
        let undo = BptreeMap::<K, Option<V>, Prepaid<P>>::writer_start_allocation_demand()
            .map_err(AdmittedStorageError::Planning)?;
        let identity =
            NextPublication::allocation_demand().map_err(AdmittedStorageError::Planning)?;
        let (current, undo, identity) = reserve_owners(budget, current, undo, identity)?;
        let undo_wait = self.revert_released.observe();
        let revert = self.revert.try_acquire_writer().ok_or_else(|| {
            writer_error(
                MapAdmissionError::Busy,
                StorageRole::Undo,
                undo_wait.clone(),
            )
        })?;
        let revert = self.revert_released.poisoning_guard(revert);
        if revert.is_poisoned() {
            revert.release_with_observed_poison(drop, || self.revert.is_poisoned());
            return Err(AdmittedStorageError::Poisoned {
                role: StorageRole::Undo,
            });
        }
        let current_wait = self.blocks_released.observe();
        let blocks = self.blocks.try_acquire_writer().ok_or_else(|| {
            writer_error(
                MapAdmissionError::Busy,
                StorageRole::Current,
                current_wait.clone(),
            )
        })?;
        let blocks = self.blocks_released.poisoning_guard(blocks);
        let (revert, blocks) = revert.try_map_pair_preserving_release(
            blocks,
            |revert, blocks| {
                // Both actual poison checks precede either cursor allocation.
                if blocks.is_poisoned() {
                    return Err(AdmittedStorageError::Poisoned {
                        role: StorageRole::Current,
                    });
                }
                let revert = revert
                    .try_write_admitted(|demand| policy::<P>(budget, undo, demand))
                    .map_err(|(acquired, error)| {
                        drop(acquired);
                        writer_error(error, StorageRole::Undo, undo_wait)
                    })?;
                let blocks = blocks
                    .try_write_admitted(|demand| policy::<P>(budget, current, demand))
                    .map_err(|(acquired, error)| {
                        drop(acquired);
                        writer_error(error, StorageRole::Current, current_wait)
                    })?;
                Ok((revert, blocks))
            },
            || (self.revert.is_poisoned(), self.blocks.is_poisoned()),
        )?;
        // Refused/poisoned acquisition must not allocate an unused identity.
        // Its original reservation already exists; both writers now belong to
        // this opening, before reset, replacement copying or user execution.
        let writers = StorageWriters::new(self, revert, blocks);
        let next = NextPublication::from_admission(identity);
        Ok(AdmittedWriters { writers, next })
    }

pub fn release_with_observed_poison<R>(
        mut self,
        consume: impl FnOnce(T) -> R,
        observe_poison: impl Fn() -> bool,
    ) -> R {
        struct Signal<'a, F: Fn() -> bool> {
            notification: &'a ReleaseNotification,
            observe_poison: F,
        }
        impl<F: Fn() -> bool> Drop for Signal<'_, F> {
            fn drop(&mut self) {
                self.notification.released((self.observe_poison)());
            }
        }
        let signal = Signal {
            notification: self.notification,
            observe_poison,
        };
        let inner = self.inner.take().expect("owned release guard");
        let _transferred = std::mem::ManuallyDrop::new(self);
        let result = consume(inner);
        drop(signal);
        result
    }

pub fn acquire_writer(&self) -> EbrCellWriterAcquisition<'_, T, Charge> {
    EbrCellWriterAcquisition {
        caller: self,
        guard: self
            .write
            .lock()
            .unwrap_or_else(|poison| poison.into_inner()),
    }
}

pub fn try_acquire_writer(&self) -> Option<EbrCellWriterAcquisition<'_, T, Charge>> {
    let guard = match self.write.try_lock() {
        Ok(guard) => guard,
        Err(TryLockError::Poisoned(poison)) => poison.into_inner(),
        Err(TryLockError::WouldBlock) => return None,
    };
    Some(EbrCellWriterAcquisition {
        caller: self,
        guard,
    })
}

pub fn try_clone_charged<E>(
    self,
    admit: impl FnOnce(&T, Layout) -> Result<Charge, E>,
) -> Result<(Self, EbrCellOwned<T, Charge>), (Self, EbrCellWriterAdmissionError<E>)> {
    if self.is_poisoned() {
        return Err((self, EbrCellWriterAdmissionError::Poisoned));
    }
    // SAFETY: this original writer excludes replacement, and its borrowed
    // cell excludes destruction. The active allocation therefore cannot be
    // unlinked while admission and cloning run; no collector pin is needed.
    let current = self
        .caller
        .active
        .load(Acquire, unsafe { epoch::unprotected() });
    let current = unsafe { current.deref() };
    let charge = match admit(&current.value, EbrCell::<T, Charge>::allocation_layout()) {
        Ok(charge) => ManuallyDrop::new(charge),
        Err(error) => return Err((self, EbrCellWriterAdmissionError::Refused(error))),
    };
    let allocation = Owned::new(Allocation {
        value: current.value.clone(),
        charge,
    });
    Ok((
        self,
        EbrCellOwned {
            data: Some(allocation),
        },
    ))
}

pub fn try_write_owned(
    self,
    owned: EbrCellOwned<T, Charge>,
) -> Result<EbrCellWriteTxn<'a, T, Charge>, (Self, EbrCellOwned<T, Charge>)> {
    if self.is_poisoned() {
        return Err((self, owned));
    }
    Ok(self.install_owned(owned))
}

fn install_owned(self, mut owned: EbrCellOwned<T, Charge>) -> EbrCellWriteTxn<'a, T, Charge> {
    EbrCellWriteTxn {
        data: owned.data.take(),
        caller: self.caller,
        _guard: Some(self.guard),
    }
}

pub struct EbrCellWriteTxn<
    'a,
    T: 'static + Clone + Send + Sync,
    Charge: Send + Sync + 'static = Untracked,
> {
    data: Option<Owned<Allocation<T, Charge>>>,
    // This way we know who to contact for updating our data ....
    caller: &'a EbrCell<T, Charge>,
    _guard: Option<MutexGuard<'a, ()>>,
}

fn drop(&mut self) {
    // No payload destructor or capacity refund may run under this writer.
    // Aggregates additionally retain the private allocation until every
    // sibling guard releases, using detach rather than sequential Drop.
    drop(self._guard.take());
    if let Some(allocation) = self.data.take() {
        reclaim(allocation);
    }
}

pub fn detach(mut self) -> EbrCellOwned<T, Charge> {
    EbrCellOwned {
        data: self.data.take(),
    }
}

fn write_from_guard<'a, E>(
    &'a self,
    mguard: MutexGuard<'a, ()>,
    admit: impl FnOnce(&T, Layout) -> Result<Charge, E>,
) -> Result<EbrCellWriteTxn<'a, T, Charge>, E> {
    let acquired = EbrCellWriterAcquisition {
        caller: self,
        guard: mguard,
    };
    match acquired.try_clone_charged(admit) {
        Ok((acquired, owned)) => Ok(acquired.install_owned(owned)),
        Err((_acquired, EbrCellWriterAdmissionError::Poisoned)) => {
            panic!("original writer is poisoned")
        }
        Err((_acquired, EbrCellWriterAdmissionError::Refused(error))) => Err(error),
    }
}

pub fn write_charged<E>(
    &self,
    admit: impl FnOnce(&T, Layout) -> Result<Charge, E>,
) -> Result<EbrCellWriteTxn<'_, T, Charge>, E> {
    self.write_from_guard(self.write.lock().unwrap(), admit)
}

pub fn try_write_charged<E>(
    &self,
    admit: impl FnOnce(&T, Layout) -> Result<Charge, E>,
) -> Result<Option<EbrCellWriteTxn<'_, T, Charge>>, E> {
    let Ok(mguard) = self.write.try_lock() else {
        return Ok(None);
    };
    self.write_from_guard(mguard, admit).map(Some)
}

pub fn try_write_owned(
    &self,
    owner: EbrCellOwned<T, Charge>,
) -> Result<EbrCellWriteTxn<'_, T, Charge>, EbrCellOwned<T, Charge>> {
    let Some(acquired) = self.try_acquire_writer() else {
        return Err(owner);
    };
    acquired
        .try_write_owned(owner)
        .map_err(|(acquired, owner)| {
            drop(acquired);
            owner
        })
}

pub struct BlockAcquisitionSlot<'a, V: Value, C: Send + Sync + 'static = Untracked> {
    target: &'a Cell<V, C>,
    phase: AcquisitionPhase<'a, V, C>,
    started: bool,
    complete: bool,
    // Last: original payload/charge cleanup precedes original notification.
    undo_release: DeferredReleaseBatch,
    current_release: DeferredReleaseBatch,
}

pub(super) struct OriginalCellWriters<'a, V: Value, C: Send + Sync + 'static> {
    pub(super) revert: CellWriter<'a, Option<V>, C>,
    pub(super) blocks: CellWriter<'a, V, C>,
}

pub(super) struct CellWriters<'a, V: Value, C: Send + Sync + 'static> {
    state: Option<CellWriterState<'a, V, C>>,
}

pub(super) fn acquire(target: &'a Cell<V, C>, charges: CellAllocationCharges<C>) -> Self {
    let mut slot = BlockAcquisitionSlot::new(target, charges);
    slot.initialize_writers();
    slot.take_writers()
}

pub(super) fn into_original(mut self) -> OriginalCellWriters<'a, V, C> {
    match self.state.take() {
        Some(CellWriterState::Attached(original)) => original,
        other => {
            self.state = other;
            panic!("original cell pair was released")
        }
    }
}

pub(super) fn detach_retaining(
    self,
) -> (
    EbrCellOwned<Option<V>, C>,
    EbrCellOwned<V, C>,
    crate::CaptureCleanup,
) {
    let OriginalCellWriters { revert, blocks } = self.into_original();
    // The capture slot checked attachment while still owning its Block.
    // Native detachment only moves these exact allocations and unlocks.
    let (revert, undo_release) = revert.release_deferred(|writer| writer.detach());
    let (blocks, current_release) = blocks.release_deferred(|writer| writer.detach());
    (
        revert,
        blocks,
        crate::CaptureCleanup::new(current_release, undo_release),
    )
}

fn acquire_charged_writers(
    &self,
    charges: CellAllocationCharges<Charge>,
) -> CellWriters<'_, V, Charge> {
    CellWriters::acquire(self, charges)
}

pub fn block_charged(&self, charges: CellAllocationCharges<Charge>) -> Block<'_, V, Charge> {
    let mut slot = self.block_acquisition_charged(charges);
    crate::BlockAcquisition::initialize(&mut slot, BlockMode::Ordinary);
    crate::BlockAcquisition::into_block(slot)
}

pub fn block_and_revert_charged(
    &self,
    charges: CellAllocationCharges<Charge>,
) -> Block<'_, V, Charge> {
    let mut slot = self.block_acquisition_charged(charges);
    crate::BlockAcquisition::initialize(&mut slot, BlockMode::Replace);
    crate::BlockAcquisition::into_block(slot)
}

pub fn current_replacement_charged(
    &self,
    charges: CellAllocationCharges<Charge>,
) -> CurrentReplacement<'_, V, Charge> {
    CurrentReplacement {
        writers: self.acquire_charged_writers(charges),
        publication: &self.publication,
    }
}

pub struct CurrentReplacement<'storage, V: Value, Charge: Send + Sync + 'static = Untracked> {
    writers: CellWriters<'storage, V, Charge>,
    publication: &'storage Publication,
}

pub fn publish(self, value: V) {
    let Self {
        mut writers,
        publication,
    } = self;
    *writers.as_mut().blocks.get_mut() = value;
    publish_pair(writers, publication, NextPublication::new(), true, false);
}

pub fn commit(mut self) {
    self.prepare_attached_publication();
    self.publish_attached_prepared();
}

pub fn try_detach<Admission, E>(
    self,
    admit: impl FnOnce(&Self) -> Result<Admission, E>,
) -> Result<Detached<V, Admission, Charge>, E> {
    let mut slot = self.capture_slot();
    crate::BlockCapture::try_capture(&mut slot, admit)?;
    let (journal, cleanup) = crate::BlockCapture::into_detached(slot);
    drop(cleanup);
    Ok(journal)
}

fn publish_pair<'a, V: Value, Charge: Send + Sync + 'static>(
    writers: CellWriters<'a, V, Charge>,
    publication: &Publication,
    next: NextPublication,
    publish_current: bool,
    publish_undo: bool,
) {
    let retirement = publication.publish_retaining(
        next,
        || {
            // Retain the complete joint owner until the fallible identity-lock
            // acquisition above succeeds. Native preparation and publication
            // below neither allocate nor execute payload or collector callbacks.
            let OriginalCellWriters { revert, blocks } = writers.into_original();
            let (blocks, unchanged_blocks) = if publish_current {
                (
                    Some(blocks.map_preserving_release(|writer| writer.prepare_commit())),
                    None,
                )
            } else {
                (None, Some(blocks))
            };
            let (revert, unchanged_revert) = if publish_undo {
                (
                    Some(revert.map_preserving_release(|writer| writer.prepare_commit())),
                    None,
                )
            } else {
                (None, Some(revert))
            };
            let blocks =
                blocks.map(|writer| writer.map_preserving_release(|prepared| prepared.publish()));
            let revert =
                revert.map(|writer| writer.map_preserving_release(|prepared| prepared.publish()));
            (blocks, revert, unchanged_blocks, unchanged_revert)
        },
        |(blocks, revert, unchanged_blocks, unchanged_revert)| {
            let blocks =
                blocks.map(|writer| writer.release_retaining(|published| published.release()));
            let revert =
                revert.map(|writer| writer.release_retaining(|published| published.release()));
            let unchanged_blocks =
                unchanged_blocks.map(|writer| writer.release_retaining(|writer| writer.detach()));
            let unchanged_revert =
                unchanged_revert.map(|writer| writer.release_retaining(|writer| writer.detach()));
            (blocks, revert, unchanged_blocks, unchanged_revert)
        },
    );
    drop(retirement);
}

pub(crate) fn publish_retaining<Published, Retirement>(
    &self,
    next: NextPublication,
    publish: impl FnOnce() -> Published,
    release: impl FnOnce(Published) -> Retirement,
) -> Retirement {
    // Declare retirement first so unwind also releases the visibility lock
    // before the old identity can refund its original allocation credits.
    let retired_version;
    let mut version = self.lock_version();
    let published = publish();
    retired_version = std::mem::replace(&mut **version, next.0);
    let retirement = release(published);
    drop(version);
    drop(retired_version);
    retirement
}

pub fn release(&mut self) {
    self.complete = false;
    self.started = true;
    match &mut self.phase {
        AcquisitionPhase::Empty => {}
        AcquisitionPhase::Block(block) => crate::BlockRetirement::release_writers(block),
        AcquisitionPhase::Pending { undo, current } => {
            current.release(&self.target.blocks, &mut self.current_release);
            undo.release(&self.target.revert, &mut self.undo_release);
        }
    }
}

fn release(&mut self, target: &BptreeMap<K, V, M>, releases: &mut DeferredReleaseBatch) {
    match std::mem::replace(self, Self::Empty) {
        Self::Empty => {}
        Self::Raw(raw) => {
            raw.try_release_into_observed(releases, drop, || target.is_poisoned())
                .unwrap_or_else(|_| unreachable!("original raw release source"));
        }
        Self::Writer(writer) => {
            let retirement = writer
                .try_release_into_observed(
                    releases,
                    |writer| writer.abort_retaining(),
                    || target.is_poisoned(),
                )
                .unwrap_or_else(|_| unreachable!("original converted release source"));
            *self = Self::Retired(retirement);
        }
        Self::Retired(retirement) => *self = Self::Retired(retirement),
    }
}

fn initialize_writers(&mut self) {
    assert!(!self.started, "original cell acquisition is one-shot");
    self.started = true;
    let target = self.target;
    let AcquisitionPhase::Pending(pending) = &mut self.phase else {
        panic!("original pending acquisition");
    };
    pending.revert = Some(
        target
            .revert_released
            .poisoning_guard(target.revert.acquire_writer()),
    );
    assert!(
        !pending
            .revert
            .as_ref()
            .expect("original undo")
            .is_poisoned(),
        "original undo writer is poisoned",
    );
    pending.blocks = Some(
        target
            .blocks_released
            .poisoning_guard(target.blocks.acquire_writer()),
    );
    assert!(
        !pending
            .blocks
            .as_ref()
            .expect("original current")
            .is_poisoned(),
        "original current writer is poisoned",
    );
    // The original slot owns both guards and both charges before either clone.
    let undo = pending.revert.take().expect("original undo");
    let undo_value = &mut pending.undo_value;
    let undo_charge = &mut pending.undo_charge;
    let result = undo
        .try_map_preserving_release_into(
            &mut self.undo_release,
            |undo| match undo.try_clone_charged(|_, _| {
                Ok::<_, std::convert::Infallible>(
                    undo_charge.take().expect("original undo charge"),
                )
            }) {
                Ok((undo, value)) => {
                    *undo_value = Some(value);
                    Ok(undo)
                }
                Err((undo, error)) => Err((undo, error)),
            },
            || target.revert.is_poisoned(),
        )
        .unwrap_or_else(|_| unreachable!("original undo release source"));
    match result {
        Ok(undo) => pending.revert = Some(undo),
        Err((undo, error)) => {
            pending.revert = Some(undo);
            match error {
                EbrCellWriterAdmissionError::Poisoned => {
                    panic!("original undo writer is poisoned")
                }
                EbrCellWriterAdmissionError::Refused(never) => match never {},
            }
        }
    }
    let current = pending.blocks.take().expect("original current");
    let current_value = &mut pending.current_value;
    let current_charge = &mut pending.current_charge;
    let result = current
        .try_map_preserving_release_into(
            &mut self.current_release,
            |current| match current.try_clone_charged(|_, _| {
                Ok::<_, std::convert::Infallible>(
                    current_charge.take().expect("original current charge"),
                )
            }) {
                Ok((current, value)) => {
                    *current_value = Some(value);
                    Ok(current)
                }
                Err((current, error)) => Err((current, error)),
            },
            || target.blocks.is_poisoned(),
        )
        .unwrap_or_else(|_| unreachable!("original current release source"));
    match result {
        Ok(current) => pending.blocks = Some(current),
        Err((current, error)) => {
            pending.blocks = Some(current);
            match error {
                EbrCellWriterAdmissionError::Poisoned => {
                    panic!("original current writer is poisoned")
                }
                EbrCellWriterAdmissionError::Refused(never) => match never {},
            }
        }
    }
    // No new lock or user operation occurs during either attachment. Keep the
    // original values in the caller slot if the native attachment refuses.
    let undo = pending.revert.take().expect("original undo");
    let undo_value = &mut pending.undo_value;
    let undo = match undo
        .try_map_preserving_release_into(
            &mut self.undo_release,
            |undo| match undo.try_write_owned(undo_value.take().expect("original undo value")) {
                Ok(writer) => Ok(writer),
                Err((undo, value)) => {
                    *undo_value = Some(value);
                    Err((undo, ()))
                }
            },
            || target.revert.is_poisoned(),
        )
        .unwrap_or_else(|_| unreachable!("original undo release source"))
    {
        Ok(writer) => writer,
        Err((undo, ())) => {
            pending.revert = Some(undo);
            panic!("original healthy undo stays acquired");
        }
    };
    // Attachment cannot panic or refuse after the same exclusive healthy
    // acquisitions above; no payload code runs between these two transfers.
    let current = pending.blocks.take().expect("original current");
    let current_value = pending
        .current_value
        .take()
        .expect("original current value");
    let current = current.map_preserving_release(|current| {
        match current.try_write_owned(current_value) {
            Ok(writer) => writer,
            Err(_) => unreachable!("original healthy current stays acquired"),
        }
    });
    self.phase = AcquisitionPhase::Writers(CellWriters::new(undo, current));
}

fn initialize(&mut self, mode: BlockMode) {
    self.initialize_writers();
    let predecessor = self.target.publication.capture();
    let writers = self.take_writers();
    self.phase = AcquisitionPhase::Block(Block::new(
        writers,
        mode == BlockMode::Replace,
        &self.target.publication,
        predecessor,
        mode,
    ));
    let AcquisitionPhase::Block(block) = &mut self.phase else {
        unreachable!("original block");
    };
    let OriginalCellWriters { revert, blocks } = block.writers.as_mut();
    match mode {
        BlockMode::Ordinary => *revert.get_mut() = None,
        BlockMode::Replace => {
            if let Some(value) = core::mem::take(revert.get_mut()) {
                *blocks.get_mut() = value;
            }
        }
    }
    self.complete = true;
}

fn release(&mut self) {
    self.complete = false;
    self.started = true;
    match &mut self.phase {
        AcquisitionPhase::Empty => {}
        AcquisitionPhase::Block(block) => crate::BlockRetirement::release_writers(block),
        AcquisitionPhase::Writers(writers) => writers.release(),
        AcquisitionPhase::Pending(pending) => {
            let target = self.target;
            if let Some(current) = pending.blocks.take() {
                current
                    .try_release_into_observed(&mut self.current_release, drop, || {
                        target.blocks.is_poisoned()
                    })
                    .unwrap_or_else(|_| unreachable!("original current release source"));
            }
            if let Some(undo) = pending.revert.take() {
                undo.try_release_into_observed(&mut self.undo_release, drop, || {
                    target.revert.is_poisoned()
                })
                .unwrap_or_else(|_| unreachable!("original undo release source"));
            }
        }
    }
}

pub(super) fn release(&mut self) {
    if let Some(CellWriterState::Preparing { writers, .. }) = self.state.as_mut() {
        writers.release();
        return;
    }
    let Some(CellWriterState::Attached(original)) = self.state.as_ref() else {
        return;
    };
    let _ = original;
    let Some(CellWriterState::Attached(OriginalCellWriters { revert, blocks })) =
        self.state.take()
    else {
        unreachable!()
    };
    let (undo, undo_release) = revert.release_deferred(|writer| writer.detach());
    let (current, current_release) = blocks.release_deferred(|writer| writer.detach());
    self.state = Some(CellWriterState::Released {
        _undo: undo,
        _current: current,
        _undo_release: undo_release,
        _current_release: current_release,
    });
}

pub fn release_deferred<R>(self, release: impl FnOnce(T) -> R) -> (R, DeferredRelease) {
    let policy = self.poison;
    let mut retirement = self.release_retaining(release);
    // Actual primitive poison is established when its guard is released.
    let poisoned = policy.observe();
    let notification = DeferredRelease {
        notification: ReleaseNotification {
            state: Arc::clone(&retirement.notification.state),
        },
        poisoned,
    };
    let retained = retirement.inner.take().expect("owned release retirement");
    let _transferred = std::mem::ManuallyDrop::new(retirement);
    (retained, notification)
}

enum AcquisitionPhase<'a, V: Value, C: Send + Sync + 'static> {
    Empty,
    Pending(PendingPair<'a, V, C>),
    Writers(CellWriters<'a, V, C>),
    Block(Block<'a, V, C>),
}

fn take_writers(&mut self) -> CellWriters<'a, V, C> {
    match std::mem::replace(&mut self.phase, AcquisitionPhase::Empty) {
        AcquisitionPhase::Writers(writers) => writers,
        other => {
            self.phase = other;
            panic!("original initialized pair")
        }
    }
}

enum AcquisitionPhase<'a, K: Key, V: Value, M: StorageMode<K, V>> {
    Empty,
    Pending {
        undo: WriterPhase<'a, K, Option<V>, M>,
        current: WriterPhase<'a, K, V, M>,
    },
    Block(Block<'a, K, V, M>),
}

enum WriterPhase<'a, K: Key, V: Value, M: MapMode + NodeCloning<K, V>> {
    Empty,
    Raw(ReleaseGuard<'a, BptreeMapWriterAcquisition<'a, K, V, M>>),
    Writer(ReleaseGuard<'a, BptreeMapWriteTxn<'a, K, V, M>>),
    Retired(BptreeMapAbandonment<K, V, M>),
}

fn is_poisoned(&self) -> bool {
    match self {
        Self::Raw(raw) => raw.is_poisoned(),
        _ => panic!("original raw writer"),
    }
}

fn take_raw(&mut self) -> ReleaseGuard<'a, BptreeMapWriterAcquisition<'a, K, V, M>> {
    match std::mem::replace(self, Self::Empty) {
        Self::Raw(raw) => raw,
        other => {
            *self = other;
            panic!("original raw writer")
        }
    }
}

fn take_writer(&mut self) -> ReleaseGuard<'a, BptreeMapWriteTxn<'a, K, V, M>> {
    match std::mem::replace(self, Self::Empty) {
        Self::Writer(writer) => writer,
        other => {
            *self = other;
            panic!("original converted writer")
        }
    }
}

pub fn try_map_preserving_release_into<R, E>(
    mut self,
    batch: &mut DeferredReleaseBatch,
    consume: impl FnOnce(T) -> Result<R, (T, E)>,
    observe_poison: impl Fn() -> bool,
) -> Result<Result<ReleaseGuard<'owner, R>, (Self, E)>, Self> {
    if !Arc::ptr_eq(&self.notification.state, &batch.notification.state) {
        return Err(self);
    }
    struct Record<'a, F: Fn() -> bool> {
        batch: &'a mut DeferredReleaseBatch,
        observe_poison: F,
        armed: bool,
    }
    impl<F: Fn() -> bool> Drop for Record<'_, F> {
        fn drop(&mut self) {
            if self.armed {
                self.batch.released = true;
                self.batch.poisoned |= (self.observe_poison)();
            }
        }
    }
    let mut record = Record {
        batch,
        observe_poison,
        armed: true,
    };
    let inner = self.inner.take().expect("original physical guard");
    let transferred = std::mem::ManuallyDrop::new(self);
    let result = consume(inner);
    record.armed = false;
    drop(record);
    Ok(match result {
        Ok(inner) => Ok(ReleaseGuard {
            inner: Some(inner),
            notification: transferred.notification,
            poison: transferred.poison,
        }),
        Err((inner, error)) => Err((
            Self {
                inner: Some(inner),
                notification: transferred.notification,
                poison: transferred.poison,
            },
            error,
        )),
    })
}

pub fn try_release_into_observed<R>(
    mut self,
    batch: &mut DeferredReleaseBatch,
    release: impl FnOnce(T) -> R,
    observe_poison: impl Fn() -> bool,
) -> Result<R, Self> {
    if !Arc::ptr_eq(&self.notification.state, &batch.notification.state) {
        return Err(self);
    }
    struct Record<'a, F: Fn() -> bool> {
        batch: &'a mut DeferredReleaseBatch,
        observe_poison: F,
    }
    impl<F: Fn() -> bool> Drop for Record<'_, F> {
        fn drop(&mut self) {
            self.batch.released = true;
            self.batch.poisoned |= (self.observe_poison)();
        }
    }
    let record = Record {
        batch,
        observe_poison,
    };
    let inner = self.inner.take().expect("original physical guard");
    let _transferred = std::mem::ManuallyDrop::new(self);
    let result = release(inner);
    drop(record);
    Ok(result)
}

pub fn abort_retaining(self) -> BptreeMapAbandonment<K, V, M> {
    BptreeMapAbandonment {
        _inner: self.inner.detach(),
    }
}

pub fn block_acquisition_charged(
    &self,
    charges: CellAllocationCharges<Charge>,
) -> BlockAcquisitionSlot<'_, V, Charge> {
    BlockAcquisitionSlot::new(self, charges)
}

pub(super) fn new(target: &'a Cell<V, C>, charges: CellAllocationCharges<C>) -> Self {
    let CellAllocationCharges { current, undo } = charges;
    Self {
        target,
        phase: AcquisitionPhase::Pending(PendingPair {
            revert: None,
            blocks: None,
            undo_value: None,
            current_value: None,
            undo_charge: Some(undo),
            current_charge: Some(current),
        }),
        started: false,
        complete: false,
        undo_release: target.revert_released.deferred_batch(),
        current_release: target.blocks_released.deferred_batch(),
    }
}

fn into_block(mut self) -> Self::Block {
    assert!(
        self.complete,
        "original cell initialization did not complete"
    );
    match std::mem::replace(&mut self.phase, AcquisitionPhase::Empty) {
        AcquisitionPhase::Block(block) => block,
        other => {
            self.phase = other;
            panic!("original completed cell block")
        }
    }
}

enum CellWriterState<'a, V: Value, C: Send + Sync + 'static> {
    Attached(OriginalCellWriters<'a, V, C>),
    Preparing {
        writers: PreparedCellWriters<'a, V, C>,
        next: NextPublication,
    },
    Published {
        _retirement: physical::PublishedPublication<V, (), (), C>,
    },
    Released {
        _undo: EbrCellOwned<Option<V>, C>,
        _current: EbrCellOwned<V, C>,
        _undo_release: DeferredRelease,
        _current_release: DeferredRelease,
    },
}

fn new(revert: CellWriter<'a, Option<V>, C>, blocks: CellWriter<'a, V, C>) -> Self {
    Self {
        state: Some(CellWriterState::Attached(OriginalCellWriters {
            revert,
            blocks,
        })),
    }
}

pub(super) fn as_ref(&self) -> &OriginalCellWriters<'a, V, C> {
    match self.state.as_ref() {
        Some(CellWriterState::Attached(original)) => original,
        _ => panic!("original cell pair was released"),
    }
}

pub(super) fn as_mut(&mut self) -> &mut OriginalCellWriters<'a, V, C> {
    match self.state.as_mut() {
        Some(CellWriterState::Attached(original)) => original,
        _ => panic!("original cell pair was released"),
    }
}

pub fn block_acquisition(&self) -> BlockAcquisitionSlot<'_, K, V> {
    BlockAcquisitionSlot::new(self)
}

pub struct BlockAcquisitionSlot<'a, K: Key, V: Value, M: StorageMode<K, V> = Untracked> {
    target: &'a Storage<K, V, M>,
    phase: AcquisitionPhase<'a, K, V, M>,
    started: bool,
    complete: bool,
    custody: M::AcquisitionCustody,
    // Last: recorded native notifications survive payload/charge destruction.
    undo_release: DeferredReleaseBatch,
    current_release: DeferredReleaseBatch,
}

pub(super) fn new(target: &'a Storage<K, V>) -> Self {
    Self {
        target,
        phase: AcquisitionPhase::Pending {
            undo: WriterPhase::Empty,
            current: WriterPhase::Empty,
        },
        started: false,
        complete: false,
        custody: (),
        undo_release: target.revert_released.deferred_batch(),
        current_release: target.blocks_released.deferred_batch(),
    }
}

pub fn into_block(mut self) -> Block<'a, K, V, M> {
    assert!(
        self.complete,
        "original storage initialization did not complete"
    );
    match std::mem::replace(&mut self.phase, AcquisitionPhase::Empty) {
        AcquisitionPhase::Block(block) => block,
        other => {
            self.phase = other;
            panic!("original completed storage block")
        }
    }
}

enum StorageWriterState<'a, K: Key, V: Value, M: StorageMode<K, V>> {
    Attached(OriginalWriters<'a, K, V, M>),
    Preparing(PreparedStorageWriters<'a, K, V, M>),
    Published {
        _retirement: PublicationRetirement<K, V, M>,
    },
    Released {
        _blocks: BptreeMapAbandonment<K, V, M>,
        _revert: BptreeMapAbandonment<K, Option<V>, M>,
        _blocks_release: concread::release::DeferredRelease,
        _revert_release: concread::release::DeferredRelease,
    },
}

struct StorageWriters<'target, K: Key, V: Value, M: StorageMode<K, V>> {
    state: Option<StorageWriterState<'target, K, V, M>>,
    target: &'target Storage<K, V, M>,
}

fn new(
    target: &'target Storage<K, V, M>,
    revert: ReleaseGuard<'target, BptreeMapWriteTxn<'target, K, Option<V>, M>>,
    blocks: ReleaseGuard<'target, BptreeMapWriteTxn<'target, K, V, M>>,
) -> Self {
    Self {
        state: Some(StorageWriterState::Attached(OriginalWriters {
            revert,
            blocks,
        })),
        target,
    }
}

fn as_ref(&self) -> &OriginalWriters<'target, K, V, M> {
    match self.state.as_ref() {
        Some(StorageWriterState::Attached(original)) => original,
        _ => panic!("original storage pair was released"),
    }
}

fn as_mut(&mut self) -> &mut OriginalWriters<'target, K, V, M> {
    match self.state.as_mut() {
        Some(StorageWriterState::Attached(original)) => original,
        _ => panic!("original storage pair was released"),
    }
}

fn into_original(mut self) -> OriginalWriters<'target, K, V, M> {
    match self.state.take() {
        Some(StorageWriterState::Attached(original)) => original,
        other => {
            self.state = other;
            panic!("original storage pair was released")
        }
    }
}

fn release(&mut self) {
    if let Some(StorageWriterState::Preparing(writers)) = self.state.as_mut() {
        writers.release();
        return;
    }
    if !matches!(&self.state, Some(StorageWriterState::Attached(_))) {
        return;
    }
    let Some(StorageWriterState::Attached(OriginalWriters { revert, blocks })) =
        self.state.take()
    else {
        unreachable!()
    };
    // Unlike detach, cleanup-only native retirement also accepts an edit-failed
    // private cursor. It grants no read or publication authority afterward.
    let (blocks, blocks_release) = blocks.release_deferred(|writer| writer.abort_retaining());
    let (revert, revert_release) = revert.release_deferred(|writer| writer.abort_retaining());
    self.state = Some(StorageWriterState::Released {
        _blocks: blocks,
        _revert: revert,
        _blocks_release: blocks_release,
        _revert_release: revert_release,
    });
}

macro_rules! declare_world_acquisition {
    (; [$($prefix:ident,)*] [$($privacy:ident,)*] [$($suffix:ident,)*]) => {
        // Generic parameter names deliberately follow the single field census.
        #[allow(non_camel_case_types)]
        pub(super) struct WorldAcquisition<
            $($prefix: BlockAcquisition,)*
            $($privacy: BlockAcquisition,)*
            $($suffix: BlockAcquisition,)*
        > {
            $(pub(super) $prefix: Option<$prefix>,)*
            $(pub(super) $privacy: Option<$privacy>,)*
            $(pub(super) $suffix: Option<$suffix>,)*
        }

        #[allow(non_camel_case_types)]
        impl<$($prefix: BlockAcquisition,)* $($privacy: BlockAcquisition,)* $($suffix: BlockAcquisition,)*>
            WorldAcquisition<$($prefix,)* $($privacy,)* $($suffix,)*>
        {
            pub(super) fn initialize(&mut self, mode: BlockMode) {
                $(self.$prefix.as_mut().expect("original field acquisition").initialize(mode);)*
                $(self.$privacy.as_mut().expect("original field acquisition").initialize(mode);)*
                $(self.$suffix.as_mut().expect("original field acquisition").initialize(mode);)*
            }
        }

        #[allow(non_camel_case_types)]
        impl<$($prefix: BlockAcquisition,)* $($privacy: BlockAcquisition,)* $($suffix: BlockAcquisition,)*>
            Drop for WorldAcquisition<$($prefix,)* $($privacy,)* $($suffix,)*>
        {
            fn drop(&mut self) {
                $(if let Some(field) = self.$prefix.as_mut() { field.release(); })*
                $(if let Some(field) = self.$privacy.as_mut() { field.release(); })*
                $(if let Some(field) = self.$suffix.as_mut() { field.release(); })*
                // Automatic field drop now reclaims payloads/charges and wakes
                // original waiters only after all acquired writers are free.
            }
        }

        impl WorldBlock<'_> {
            pub(super) fn prepare_publication(&mut self) {
                self.publication.begin_preparation();
                let fields = self.fields.as_mut().expect("original World block fields");
                $(fields.$prefix.prepare_publication();)*
                $(fields.$privacy.prepare_publication();)*
                $(fields.$suffix.prepare_publication();)*
                self.publication.finish_preparation();
            }
            pub(super) fn publish_prepared(&mut self) {
                self.publication.begin_publication();
                let fields = self.fields.as_mut().expect("original World block fields");
                $(fields.$prefix.publish_prepared();)*
                $(fields.$privacy.publish_prepared();)*
                $(fields.$suffix.publish_prepared();)*
                self.publication.finish_publication();
            }
        }

        impl BlockRetirement for WorldBlock<'_> {
            fn release_writers(&mut self) {
                self.publication.release();
                if let Some(fields) = self.fields.as_mut() {
                    $(fields.$prefix.release_writers();)*
                    $(fields.$privacy.release_writers();)*
                    $(fields.$suffix.release_writers();)*
                }
            }
        }
    };
}

macro_rules! build_world_block_from_fields {
    ($state:expr, $mode:expr;
        [$($prefix:ident,)*] [$($privacy:ident,)*] [$($suffix:ident,)*]) => {{
        use mv::BlockAcquisition as _;
        let mut pending = world_acquisition::WorldAcquisition {
            $($prefix: None,)*
            $($privacy: None,)*
            $($suffix: None,)*
        };
        // Fill the same caller-owned slots one at a time before acquiring any
        // writer, without retaining a full composite initializer temporary.
        world_acquisition::fill_world_acquisition(|| {
            $(pending.$prefix = Some($state.$prefix.block_acquisition());)*
            $(pending.$privacy = Some($state.$privacy.block_acquisition());)*
            $(pending.$suffix = Some($state.$suffix.block_acquisition());)*
        });
        pending.initialize($mode);
        world_acquisition::finish_world_acquisition(|| WorldBlock {
            publication: block_field::AggregatePublication::Executing,
            // TODO: include this one metadata allocation in complete retained
            // pre-execution admission before enabling that production path.
            fields: Some(Box::new(WorldBlockFields {
                dataspace_catalog: iroha_data_model::nexus::DataSpaceCatalog::default(),
                $($prefix: world_acquisition::retain_executing_field(pending.$prefix.take().expect("original field acquisition").into_block()),)*
                $($privacy: world_acquisition::retain_executing_field(pending.$privacy.take().expect("original field acquisition").into_block()),)*
                $($suffix: world_acquisition::retain_executing_field(pending.$suffix.take().expect("original field acquisition").into_block()),)*
                external_event_buf: Vec::new(),
            })),
        })
    }};
}

pub(super) fn into_fields(mut self) -> WorldBlockFields<'world> {
    self.publication.assert_executing();
    *self.fields.take().expect("original World block fields")
}

pub struct WorldBlock<'world> {
    publication: block_field::AggregatePublication,
    // Preserve one allocation through acquisition, execution and publication.
    // Moving State or a runtime result must not copy this complete inventory
    // through every caller's stack frame.
    fields: Option<Box<WorldBlockFields<'world>>>,
}

pub fn block(&self) -> WorldBlock<'_> {
    build_world_block!(self, mv::BlockMode::Ordinary)
}

pub fn block_and_revert(&self) -> WorldBlock<'_> {
    build_world_block!(self, mv::BlockMode::Replace)
}

macro_rules! trigger_acquisition {
    ($($field:ident: ($key:ty, $value:ty)),+ $(,)?) => {
        /// Inert original field slots retained across all fallible initialization.
        pub(crate) struct SetBlockAcquisition<'set> {
            $($field: Option<mv::storage::BlockAcquisitionSlot<'set, $key, $value>>,)+
        }

        impl<'set> SetBlockAcquisition<'set> {
            pub(super) fn new(target: &'set Set) -> Self {
                Self { $($field: Some(target.$field.block_acquisition()),)+ }
            }
        }

        impl<'set> BlockAcquisition for SetBlockAcquisition<'set> {
            type Block = SetBlock<'set>;

            fn initialize(&mut self, mode: BlockMode) {
                $(self.$field.as_mut().expect("original trigger slot").initialize(mode);)+
            }

            fn release(&mut self) {
                $(if let Some(field) = self.$field.as_mut() { field.release(); })+
            }

            fn into_block(mut self) -> Self::Block {
                SetBlock { publication: AggregatePublication::Executing, fields: Some(SetBlockFields {
                    $($field: BlockField::new(self.$field.take().expect("original trigger slot").into_block()),)+
                }) }
            }
        }

        impl Drop for SetBlockAcquisition<'_> {
            fn drop(&mut self) {
                self.release();
            }
        }

        impl SetBlock<'_> {
            pub(crate) fn prepare_publication(&mut self) {
                self.publication.begin_preparation();
                let fields = self.fields.as_mut().expect("original trigger block fields");
                $(fields.$field.prepare_publication();)+
                self.publication.finish_preparation();
            }
            pub(crate) fn publish_prepared(&mut self) {
                self.publication.begin_publication();
                let fields = self.fields.as_mut().expect("original trigger block fields");
                $(fields.$field.publish_prepared();)+
                self.publication.finish_publication();
            }
        }

        impl BlockRetirement for SetBlock<'_> {
            fn release_writers(&mut self) {
                self.publication.release();
                if let Some(fields) = self.fields.as_mut() {
                    $(fields.$field.release_writers();)+
                }
            }
        }
    };
}

pub(super) fn into_fields(mut self) -> SetBlockFields<'set> {
    self.publication.assert_executing();
    self.fields.take().expect("original trigger block fields")
}

