pub struct CaptureCleanup {
    current: Option<DeferredRelease>,
    undo: Option<DeferredRelease>,
}

pub(crate) fn new(current: DeferredRelease, undo: DeferredRelease) -> Self {
    Self {
        current: Some(current),
        undo: Some(undo),
    }
}

fn drop(&mut self) {
    // Taking each field keeps the remaining actual notification armed if
    // the first callback unwinds. No physical guard remains in this owner.
    drop(self.current.take());
    drop(self.undo.take());
}

pub struct BlockCaptureSlot<'a, V: Value, Admission, C: Send + Sync + 'static = Untracked> {
    phase: CapturePhase<'a, V, Admission, C>,
    started: bool,
    // Last: captured payloads and admission outlive all physical writers and
    // are destroyed before these original notifications on abandonment.
    cleanup: CaptureCleanup,
}

enum CapturePhase<'a, V: Value, Admission, C: Send + Sync + 'static> {
    Empty,
    Attached {
        block: Block<'a, V, C>,
        admission: Option<Admission>,
    },
    Captured(Detached<V, Admission, C>),
}

pub fn capture_slot<Admission>(self) -> BlockCaptureSlot<'a, V, Admission, C> {
    BlockCaptureSlot {
        phase: CapturePhase::Attached {
            block: self,
            admission: None,
        },
        started: false,
        cleanup: CaptureCleanup::default(),
    }
}

fn try_capture<E>(
    &mut self,
    admit: impl FnOnce(&Self::Block) -> Result<Admission, E>,
) -> Result<(), E> {
    assert!(!self.started, "original cell capture is one-shot");
    self.started = true;
    let CapturePhase::Attached {
        block,
        admission: retained,
    } = &mut self.phase
    else {
        panic!("original attached cell capture");
    };
    // Released cleanup-only blocks must never regain journal authority.
    block.writers.as_ref();
    *retained = Some(admit(block)?);
    let next = NextPublication::new();
    // From here only infallible original-owner moves/native unlocks occur.
    // Any future fallible/user operation belongs above this extraction.
    let CapturePhase::Attached {
        block,
        admission: Some(admission),
    } = std::mem::replace(&mut self.phase, CapturePhase::Empty)
    else {
        unreachable!("original checked cell block");
    };
    let Block {
        writers,
        dirty,
        predecessor,
        mode,
        publication: _,
    } = block;
    let (revert, blocks, cleanup) = writers.detach_retaining();
    self.phase = CapturePhase::Captured(Detached {
        revert,
        blocks,
        metadata: DetachedMetadata {
            predecessor,
            mode,
            dirty,
            next,
            admission,
        },
    });
    self.cleanup = cleanup;
    Ok(())
}

fn release(&mut self) {
    self.started = true;
    if let CapturePhase::Attached { block, .. } = &mut self.phase {
        block.release_writers();
    }
}

fn into_detached(mut self) -> (Self::Detached, CaptureCleanup) {
    match std::mem::replace(&mut self.phase, CapturePhase::Empty) {
        CapturePhase::Captured(journal) => (journal, std::mem::take(&mut self.cleanup)),
        original => {
            self.phase = original;
            panic!("original cell capture did not complete");
        }
    }
}

pub struct BlockCaptureSlot<'a, K: Key, V: Value, Admission, M: StorageMode<K, V> = Untracked> {
    phase: CapturePhase<'a, K, V, Admission, M>,
    started: bool,
    cleanup: CaptureCleanup,
}

enum CapturePhase<'a, K: Key, V: Value, Admission, M: StorageMode<K, V>> {
    Empty,
    Attached {
        block: Block<'a, K, V, M>,
        admission: Option<Admission>,
    },
    Captured(Detached<K, V, Admission, M>),
}

pub fn capture_slot<Admission>(self) -> BlockCaptureSlot<'a, K, V, Admission, M> {
    BlockCaptureSlot {
        phase: CapturePhase::Attached {
            block: self,
            admission: None,
        },
        started: false,
        cleanup: CaptureCleanup::default(),
    }
}

fn try_capture<E>(
    &mut self,
    admit: impl FnOnce(&Self::Block) -> Result<Admission, E>,
) -> Result<(), E> {
    assert!(!self.started, "original map capture is one-shot");
    self.started = true;
    let CapturePhase::Attached {
        block,
        admission: retained,
    } = &mut self.phase
    else {
        panic!("original attached map capture");
    };
    // Both logical cursor verdicts run before taking the original Block.
    // A caught panic leaves failed private roots owned here for abandonment.
    block.assert_operable();
    *retained = Some(admit(block)?);
    self.finish_capture();
    Ok(())
}

fn release(&mut self) {
    self.started = true;
    if let CapturePhase::Attached { block, .. } = &mut self.phase {
        block.release_writers();
    }
}

fn into_detached(mut self) -> (Self::Detached, CaptureCleanup) {
    match std::mem::replace(&mut self.phase, CapturePhase::Empty) {
        CapturePhase::Captured(journal) => (journal, std::mem::take(&mut self.cleanup)),
        original => {
            self.phase = original;
            panic!("original map capture did not complete");
        }
    }
}

pub(super) fn capture_admitted(&mut self, admission: Admission) {
    assert!(!self.started, "original map capture is one-shot");
    self.started = true;
    let CapturePhase::Attached {
        block,
        admission: retained,
    } = &mut self.phase
    else {
        panic!("original attached map capture");
    };
    *retained = Some(admission);
    block.assert_operable();
    self.finish_capture();
}

fn finish_capture(&mut self) {
    let CapturePhase::Attached {
        block,
        admission: Some(admission),
    } = std::mem::replace(&mut self.phase, CapturePhase::Empty)
    else {
        unreachable!("original checked map block");
    };
    let Block {
        writers,
        dirty,
        failed: _,
        predecessor,
        next,
        mode,
        _acquisition_custody: _,
    } = block;
    let OriginalWriters { revert, blocks } = writers.into_original();
    let (blocks, revert, cleanup) = detach_pair_retaining(blocks, revert);
    self.phase = CapturePhase::Captured(Detached {
        revert,
        blocks,
        metadata: DetachedMetadata {
            predecessor,
            mode,
            dirty,
            next: next.expect("attached block retained original successor identity"),
            admission,
        },
    });
    self.cleanup = cleanup;
}

fn detach_pair_retaining<K: Key, V: Value, M: StorageMode<K, V>>(
    blocks: ReleaseGuard<'_, BptreeMapWriteTxn<'_, K, V, M>>,
    revert: ReleaseGuard<'_, BptreeMapWriteTxn<'_, K, Option<V>, M>>,
) -> (
    BptreeMapOwned<K, V, M>,
    BptreeMapOwned<K, Option<V>, M>,
    crate::CaptureCleanup,
) {
    // Both cursor flags were checked while the caller still owned its Block.
    // Exclusive ownership prevents a new edit between that check and detach.
    let (blocks, current_release) = blocks.release_deferred(|writer| writer.detach());
    let (revert, undo_release) = revert.release_deferred(|writer| writer.detach());
    (
        blocks,
        revert,
        crate::CaptureCleanup::new(current_release, undo_release),
    )
}

pub(super) fn detach_owned<Admission>(
    self,
    admission: Admission,
) -> Detached<K, V, Admission, M> {
    let mut slot = self.capture_slot();
    slot.capture_admitted(admission);
    let (journal, cleanup) = crate::BlockCapture::into_detached(slot);
    drop(cleanup);
    journal
}

pub fn try_detach<Admission, E>(
    self,
    admit: impl FnOnce(&Self) -> Result<Admission, E>,
) -> Result<Detached<K, V, Admission>, E> {
    let mut slot = self.capture_slot();
    crate::BlockCapture::try_capture(&mut slot, admit)?;
    let (journal, cleanup) = crate::BlockCapture::into_detached(slot);
    drop(cleanup);
    Ok(journal)
}

