macro_rules! declare_world_capture {
    (; [$($prefix:ident,)*] [$($privacy:ident,)*] [$($suffix:ident,)*]) => {
        #[allow(non_camel_case_types)]
        struct WorldCapture<$($prefix: WorldCaptureSlot,)* $($privacy: WorldCaptureSlot,)* $($suffix: WorldCaptureSlot,)*> {
            $($prefix: Option<($prefix, fn(&World) -> &<$prefix as WorldCaptureSlot>::Target)>,)* $($privacy: Option<($privacy, fn(&World) -> &<$privacy as WorldCaptureSlot>::Target)>,)* $($suffix: Option<($suffix, fn(&World) -> &<$suffix as WorldCaptureSlot>::Target)>,)*
            extras: Option<(DataSpaceCatalog, Vec<EventBox>)>,
            mode: BlockMode,
            refusal: Option<CaptureError<Infallible>>,
            started: bool,
            complete: bool,
        }
        #[allow(non_camel_case_types)]
        impl<$($prefix: WorldCaptureSlot,)* $($privacy: WorldCaptureSlot,)* $($suffix: WorldCaptureSlot,)*>
            WorldJournalCapture for WorldCapture<$($prefix,)* $($privacy,)* $($suffix,)*>
        {
            fn capture(&mut self) -> Result<(), CaptureError<Infallible>> {
                assert!(!self.started, "original World capture is one-shot");
                self.started = true;
                if let Some(error) = self.refusal.take() {
                    return Err(error);
                }
                $(self.$prefix.as_mut().expect("original World capture slot").0.capture()?;)*
                $(self.$privacy.as_mut().expect("original World capture slot").0.capture()?;)*
                $(self.$suffix.as_mut().expect("original World capture slot").0.capture()?;)*
                self.complete = true;
                Ok(())
            }
            fn release(&mut self) {
                self.started = true;
                self.complete = false;
                $(if let Some((field, _)) = self.$prefix.as_mut() { field.release(); })*
                $(if let Some((field, _)) = self.$privacy.as_mut() { field.release(); })*
                $(if let Some((field, _)) = self.$suffix.as_mut() { field.release(); })*
            }
            fn into_journals<Admission>(self, admission: Admission) -> DetachedWorld<Admission> {
                // Original payloads/notifications retire before this reservation,
                // including a wake panic during wrapper materialization.
                let admission = admission;
                let mut pending = self;
                assert!(pending.complete, "original World capture did not complete");
                const FIELD_COUNT: usize = [
                    $(stringify!($prefix),)* $(stringify!($privacy),)* $(stringify!($suffix),)*
                ].len();
                let fields = finish_world_capture(|| {
                    let mut fields: Vec<Box<dyn RetainedWorldField>> = Vec::with_capacity(FIELD_COUNT);
                    $(retain_field!(fields, pending, $prefix);)*
                    $(retain_field!(fields, pending, $privacy);)*
                    $(retain_field!(fields, pending, $suffix);)*
                    fields
                });
                let (dataspace_catalog, external_event_buf) = pending.extras.take().expect("original World extras");
                DetachedWorld { mode: pending.mode, fields, dataspace_catalog, external_event_buf, admission }
            }
        }
        #[allow(non_camel_case_types)]
        impl<$($prefix: WorldCaptureSlot,)* $($privacy: WorldCaptureSlot,)* $($suffix: WorldCaptureSlot,)*>
            Drop for WorldCapture<$($prefix,)* $($privacy,)* $($suffix,)*>
        {
            fn drop(&mut self) {
                self.release();
            }
        }
    };
}

macro_rules! capture_world_fields {
    ($original:ident;
        [$($prefix:ident,)*] [$($privacy:ident,)*] [$($suffix:ident,)*]) => {{
        // These concrete metadata reads neither allocate nor run payload code.
        // Keep any inconsistent-mode verdict in the returned caller-owned slot.
        let mode = $original.parameters.mode();
        let refusal = $original.capture_mode().err();
        let mut pending = WorldCapture {
            $($prefix: None,)* $($privacy: None,)* $($suffix: None,)*
            extras: None, mode, refusal, started: false, complete: false,
        };
        fill_world_capture(|| {
            let WorldBlockFields {
                dataspace_catalog,
                $($prefix,)* $($privacy,)* $($suffix,)*
                external_event_buf,
            } = *$original.fields.take().expect("original World block fields");
            $(pending.$prefix = Some(($prefix.into_capture(), |target: &World| &target.$prefix));)*
            $(pending.$privacy = Some(($privacy.into_capture(), |target: &World| &target.$privacy));)*
            $(pending.$suffix = Some(($suffix.into_capture(), |target: &World| &target.$suffix));)*
            pending.extras = Some((dataspace_catalog, external_event_buf));
        });
        pending
    }};
}

fn finish_world_capture<R>(finish: impl FnOnce() -> R) -> R {
    finish()
}

pub(in crate::state) fn try_detach_journals<Admission, E>(
    self,
    admit: impl FnOnce(&Self) -> Result<Admission, E>,
) -> Result<DetachedWorld<Admission>, CaptureError<E>> {
    self.capture_mode().map_err(widen_error)?;
    let admission = admit(&self).map_err(CaptureError::Admission)?;
    let mut pending = self.capture_slot();
    pending.capture().map_err(widen_error)?;
    Ok(pending.into_journals(admission))
}

pub(crate) struct SetBlockCapture<'set, Admission> {
    phase: CapturePhase<'set, Admission>,
    started: bool,
    // Last: retained payloads precede the original release notifications.
    cleanup: SetCaptureCleanup,
}

fn drop(&mut self) {
    for cleanup in &mut self.0 {
        drop(cleanup.take());
    }
}

enum CapturePhase<'set, Admission> {
    Empty,
    Attached(SetBlock<'set>),
    Capturing(CapturingSet<'set, Admission>),
    Captured(DetachedSet<Admission>),
}

macro_rules! capture_fields {
    ($($field:ident: ($key:ty, $value:ty)),+ $(,)?) => {
        struct CapturingSet<'set, Admission> {
            $($field: Option<mv::storage::BlockCaptureSlot<'set, $key, $value, ()>>,)+
            admission: Option<Admission>,
        }

        impl<'set, Admission> CapturingSet<'set, Admission> {
            fn new(original: SetBlock<'set>, admission: Admission) -> Self {
                // Only infallible, inert owner moves occur across this extraction.
                let SetBlockFields { $($field,)+ } = original.into_fields();
                Self { $($field: Some($field.into_executing().capture_slot()),)+ admission: Some(admission) }
            }

            fn capture(&mut self) {
                $(match self.$field.as_mut().expect("original trigger capture slot")
                    .try_capture(|_| Ok::<(), core::convert::Infallible>(() )) {
                    Ok(()) => {},
                    Err(impossible) => match impossible {},
                })+
            }

            fn release(&mut self) {
                $(if let Some(field) = self.$field.as_mut() { field.release(); })+
            }

            fn finish(mut self, mode: mv::BlockMode) -> (DetachedSet<Admission>, SetCaptureCleanup) {
                // All native capture calls completed before any journal transfer.
                $(let $field = self.$field.take().expect("original trigger capture slot").into_detached();)+
                let cleanup = SetCaptureCleanup([$(Some($field.1),)+]);
                let journal = DetachedSet {
                    mode,
                    $($field: $field.0,)+
                    admission: self.admission.take().expect("original trigger admission"),
                };
                (journal, cleanup)
            }
        }

        impl<Admission> Drop for CapturingSet<'_, Admission> {
            fn drop(&mut self) { self.release(); }
        }
    };
}

pub(crate) fn capture_slot<Admission>(self) -> SetBlockCapture<'set, Admission> {
    SetBlockCapture {
        phase: CapturePhase::Attached(self),
        started: false,
        cleanup: SetCaptureCleanup::default(),
    }
}

pub(crate) fn try_capture<E>(
    &mut self,
    admit: impl FnOnce(&SetBlock<'set>) -> Result<Admission, E>,
) -> Result<(), DetachError<E>> {
    assert!(!self.started, "original trigger capture is one-shot");
    self.started = true;
    let CapturePhase::Attached(original) = &self.phase else {
        panic!("original attached trigger capture");
    };
    let mode = original.capture_mode().map_err(|error| match error {
        DetachError::InconsistentMode {
            field,
            expected,
            actual,
        } => DetachError::InconsistentMode {
            field,
            expected,
            actual,
        },
        DetachError::Admission(impossible) => match impossible {},
    })?;
    let admission = admit(original).map_err(DetachError::Admission)?;
    let CapturePhase::Attached(original) =
        std::mem::replace(&mut self.phase, CapturePhase::Empty)
    else {
        unreachable!("original checked trigger block");
    };
    self.phase = CapturePhase::Capturing(CapturingSet::new(original, admission));
    let CapturePhase::Capturing(pending) = &mut self.phase else {
        unreachable!()
    };
    pending.capture();
    let CapturePhase::Capturing(pending) =
        std::mem::replace(&mut self.phase, CapturePhase::Empty)
    else {
        unreachable!("original completed trigger capture");
    };
    let (journal, cleanup) = pending.finish(mode);
    self.phase = CapturePhase::Captured(journal);
    self.cleanup = cleanup;
    Ok(())
}

pub(crate) fn release(&mut self) {
    self.started = true;
    match &mut self.phase {
        CapturePhase::Attached(original) => original.release_writers(),
        CapturePhase::Capturing(pending) => pending.release(),
        CapturePhase::Captured(_) | CapturePhase::Empty => {}
    }
}

pub(crate) fn into_detached(mut self) -> (DetachedSet<Admission>, SetCaptureCleanup) {
    match std::mem::replace(&mut self.phase, CapturePhase::Empty) {
        CapturePhase::Captured(journal) => (journal, std::mem::take(&mut self.cleanup)),
        original => {
            self.phase = original;
            panic!("original trigger capture did not complete");
        }
    }
}

pub(crate) fn try_detach<Admission, E>(
    self,
    admit: impl FnOnce(&Self) -> Result<Admission, E>,
) -> Result<DetachedSet<Admission>, DetachError<E>> {
    let mut pending = self.capture_slot();
    pending.try_capture(admit)?;
    let (journal, cleanup) = pending.into_detached();
    drop(cleanup);
    Ok(journal)
}

