        parts.state.release_writers();
    }
}

macro_rules! runtime_capture_fields {
    ($($field:ident: $value:ty),+ $(,)?) => {
        struct AttachedRuntime<'state> {
            $($field: Option<CellBlock<'state, $value>>,)+
        }

        impl<'state> AttachedRuntime<'state> {
            fn inputs(&self) -> RuntimeJournalInputs<'_, 'state> {
                RuntimeJournalInputs {
                    $($field: self.$field.as_ref().expect("original runtime block"),)+
                }
            }

            fn release(&mut self) {
                $(if let Some(field) = self.$field.as_mut() { field.release_writers(); })+
            }

            fn into_slots(mut self) -> CapturingRuntime<'state> {
                // Inert moves only: every original remains in one of the two
                // aggregates until the complete set has transferred.
                CapturingRuntime {
                    $($field: Some(self.$field.take().expect("original runtime block").capture_slot()),)+
                }
            }
        }

        impl Drop for AttachedRuntime<'_> {
            fn drop(&mut self) { self.release(); }
        }

        struct CapturingRuntime<'state> {
            $($field: Option<mv::cell::BlockCaptureSlot<'state, $value, ()>>,)+
        }

        impl CapturingRuntime<'_> {
            fn capture(&mut self) {
                $(match self.$field.as_mut().expect("original runtime capture slot")
                    .try_capture(|_| Ok::<(), core::convert::Infallible>(())) {
                    Ok(()) => {},
                    Err(impossible) => match impossible {},
                })+
            }

            fn release(&mut self) {
                $(if let Some(field) = self.$field.as_mut() { field.release(); })+
            }

            fn into_journals<Admission>(self, admission: Admission) -> RuntimeJournals<Admission> {
                let admission = admission;
                let mut pending = self;
                $(let $field = pending.$field.take().expect("original runtime capture slot").into_detached();)+
                let cleanup = [$($field.1,)+];
                let journals = RuntimeJournals {
                    $($field: $field.0,)+
                    admission,
                };
                drop(cleanup);
                journals
            }
        }

        impl Drop for CapturingRuntime<'_> {
            fn drop(&mut self) { self.release(); }
        }

        impl<'state, Admission> RuntimeCapture<'state, Admission> {
            /// Install all original cells without admission, allocation or release.
            pub(in crate::state::carrier_preparation::journals) fn new(
                $($field: CellBlock<'state, $value>,)+
            ) -> Self {
                Self {
                    phase: RuntimePhase::Attached(AttachedRuntime { $($field: Some($field),)+ }),
                    started: false,
                    complete: false,
                    admission: None,
                }
            }
        }
    };
}

pub(in crate::state::carrier_preparation::journals) struct RuntimeCapture<'state, Admission> {
    phase: RuntimePhase<'state>,
    started: bool,
    complete: bool,
    // Last: original payloads and notifications precede resource refund.
    admission: Option<Admission>,
}

pub(in crate::state::carrier_preparation::journals) fn try_capture<E>(
    &mut self,
    admit: impl FnOnce(RuntimeJournalInputs<'_, 'state>) -> Result<Admission, E>,
) -> Result<(), E> {
    assert!(!self.started, "original runtime capture is one-shot");
    self.started = true;
    let RuntimePhase::Attached(original) = &self.phase else {
        panic!("original attached runtime capture");
    };
    self.admission = Some(admit(original.inputs())?);
    // Only inert moves occur before the caller owns the complete slots.
    let RuntimePhase::Attached(original) =
        std::mem::replace(&mut self.phase, RuntimePhase::Empty)
    else {
        unreachable!("original checked runtime capture");
    };
    self.phase = RuntimePhase::Capturing(original.into_slots());
    let RuntimePhase::Capturing(pending) = &mut self.phase else {
        unreachable!("original runtime capture slots");
    };
    pending.capture();
    self.complete = true;
    Ok(())
}

pub(in crate::state::carrier_preparation::journals) fn release(&mut self) {
    self.started = true;
    self.complete = false;
    match &mut self.phase {
        RuntimePhase::Empty => {}
        RuntimePhase::Attached(original) => original.release(),
        RuntimePhase::Capturing(pending) => pending.release(),
    }
}

pub(in crate::state::carrier_preparation::journals) fn into_journals(
    mut self,
) -> RuntimeJournals<Admission> {
    assert!(self.complete, "original runtime capture did not complete");
    let admission = self.admission.take().expect("original runtime admission");
    let RuntimePhase::Capturing(pending) =
        std::mem::replace(&mut self.phase, RuntimePhase::Empty)
    else {
        unreachable!("original completed runtime capture");
    };
    pending.into_journals(admission)
}

pub(super) fn capture<'state, E>(
    canonical_runtime: CellBlock<'state, SnapshotNexusRuntime>,
    commit_topology: CellBlock<'state, Vec<PeerId>>,
    prev_commit_topology: CellBlock<'state, Vec<PeerId>>,
    lane_consensus_contexts: CellBlock<'state, LaneConsensusContextsV1>,
    admit: impl FnOnce(RuntimeJournalInputs<'_, 'state>) -> Result<Admission, E>,
) -> Result<Self, E> {
    let mut pending = RuntimeCapture::new(
        canonical_runtime,
        commit_topology,
        prev_commit_topology,
        lane_consensus_contexts,
    );
    pending.try_capture(admit)?;
    Ok(pending.into_journals())
}

pub(super) fn new(
    world: WorldCapture,
    runtime: RuntimeCapture<'state, ()>,
    transactions: storage_transactions::TransactionsCaptureSlot<'state>,
    block_hashes: BlockHashesBlock<'state>,
) -> Self {
    Self {
        world: Some(world),
        runtime: Some(runtime),
        transactions: Some(transactions),
        block_hashes: Some(block_hashes),
        complete: false,
    }
}

pub(super) fn try_capture(&mut self) -> Result<(), StateCaptureError> {
    self.world
        .as_mut()
        .expect("original World capture")
        .capture()?;
    match self
        .runtime
        .as_mut()
        .expect("original runtime capture")
        .try_capture(|_| Ok::<(), std::convert::Infallible>(()))
    {
        Ok(()) => {}
        Err(impossible) => match impossible {},
    }
    self.transactions
        .as_mut()
        .expect("original membership capture")
        .try_capture()?;
    self.complete = true;
    Ok(())
}

fn release(&mut self) {
    self.complete = false;
    if let Some(world) = self.world.as_mut() {
        world.release();
    }
    if let Some(runtime) = self.runtime.as_mut() {
        runtime.release();
    }
    if let Some(transactions) = self.transactions.as_mut() {
        transactions.release();
    }
}

pub(in crate::state::storage_transactions) struct MembershipWriter<'storage> {
    phase: Option<MembershipWriterPhase<'storage>>,
    pub(super) history: Option<history_slot::Slot<'storage>>,
}

pub(crate) struct TransactionsCaptureSlot<'storage> {
    pub(super) phase: MembershipCapturePhase<'storage>,
    attempted: bool,
    released: bool,
    // Last: the original staged payloads precede the successful capture's
    // deferred notification. All physical siblings must already be free.
    cleanup: Option<MembershipRelease>,
}

pub(in crate::state::storage_transactions) fn new(
    guard: OriginalMembershipGuard<'storage>,
    history: Option<history_slot::Slot<'storage>>,
) -> Self {
    Self {
        phase: Some(MembershipWriterPhase::Attached(guard)),
        history,
    }
}

pub(in crate::state::storage_transactions) fn identity(&self) -> &Identity {
    match self.phase.as_ref() {
        Some(MembershipWriterPhase::Attached(guard)) => guard,
        _ => panic!("original membership writer was terminally released"),
    }
}

pub(super) fn identity_mut(&mut self) -> &mut Identity {
    match self.phase.as_mut() {
        Some(MembershipWriterPhase::Attached(guard)) => guard,
        _ => panic!("original membership writer was terminally released"),
    }
}

fn release(&mut self) {
    if let Some(history) = self.history.as_mut() {
        history.release();
    }
    match self.phase.take() {
        Some(MembershipWriterPhase::Attached(guard)) => {
            // Native unlock does not invoke the original callback.
            let ((), release) = guard.release_deferred(drop);
            self.phase = Some(MembershipWriterPhase::Released(release));
        }
        other => self.phase = other,
    }
}

pub(super) fn into_release(mut self) -> MembershipRelease {
    self.take_release()
}

pub(crate) fn try_prepare(&mut self) -> Result<(), TransactionsBlockError> {
    assert!(
        !self.attempted && !self.released,
        "membership capture is one-shot"
    );
    self.attempted = true;
    let MembershipCapturePhase::Attached(block) = &mut self.phase else {
        panic!("original attached membership capture");
    };
    let publication = block.admit_publication()?;
    let next_identity = block
        ._guard
        .history
        .as_mut()
        .expect("original history")
        .next_identity();
    // All fallible work precedes extraction. Only original-owner moves
    // occur until the prepared owner is stored back in the caller slot.
    let MembershipCapturePhase::Attached(block) =
        std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty)
    else {
        unreachable!("original checked membership block");
    };
    self.phase = MembershipCapturePhase::Prepared(PreparedTransactionsBlock::new(
        block,
        publication,
        next_identity,
    ));
    Ok(())
}

pub(crate) fn try_capture(&mut self) -> Result<(), TransactionsBlockError> {
    assert!(!self.released, "membership capture was terminally released");
    if matches!(&self.phase, MembershipCapturePhase::Attached(_)) {
        self.try_prepare()?;
    }
    // This assertion also excludes an explicitly released prepared block
    // before taking it out of caller custody.
    match &self.phase {
        MembershipCapturePhase::Prepared(prepared) => {
            prepared.assert_unpublished();
            prepared.block._guard.identity();
        }
        _ => panic!("original prepared membership capture"),
    }
    let MembershipCapturePhase::Prepared(prepared) =
        std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty)
    else {
        unreachable!("original checked membership preparation");
    };
    // Existing detach kernel has no callback, user Drop, semantic
    // refusal or allocation after the prepared owner is extracted.
    let (journal, release) = prepared.detach_retaining();
    self.phase = MembershipCapturePhase::Captured(journal);
    self.cleanup = Some(release);
    Ok(())
}

pub(crate) fn release(&mut self) {
    self.released = true;
    let block = match &mut self.phase {
        MembershipCapturePhase::Attached(block) => Some(block),
        MembershipCapturePhase::Prepared(prepared)
        | MembershipCapturePhase::Published(prepared) => Some(&mut prepared.block),
        MembershipCapturePhase::Captured(_) | MembershipCapturePhase::Empty => None,
    };
    if let Some(block) = block {
        block.release_writers();
        if self.cleanup.is_none() {
            self.cleanup = Some(block._guard.take_release());
        }
    }
}

pub(super) fn into_prepared(mut self) -> PreparedTransactionsBlock<'storage> {
    assert!(!self.released, "membership capture was terminally released");
    match &self.phase {
        MembershipCapturePhase::Prepared(prepared) => {
            prepared.assert_unpublished();
            prepared.block._guard.identity();
        }
        _ => panic!("original membership preparation did not complete"),
    }
    match std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty) {
        MembershipCapturePhase::Prepared(prepared) => prepared,
        _ => unreachable!("original checked membership preparation"),
    }
}

pub(crate) fn into_detached(mut self) -> (DetachedTransactionsBlock, MembershipRelease) {
    assert!(!self.released, "membership capture was terminally released");
    match std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty) {
        MembershipCapturePhase::Captured(journal) => (
            journal,
            self.cleanup
                .take()
                .expect("original membership capture release"),
        ),
        original => {
            self.phase = original;
            panic!("original membership capture did not complete");
        }
    }
}

pub(crate) fn capture_slot(self) -> TransactionsCaptureSlot<'storage> {
    TransactionsCaptureSlot {
        phase: MembershipCapturePhase::Attached(self),
        attempted: false,
        released: false,
        cleanup: None,
    }
}

macro_rules! runtime_cells {
    ($($field:ident: $value:ty),+ $(,)?) => {
        struct PendingCells<'state> {
            $($field: Option<mv::cell::BlockAcquisitionSlot<'state, $value>>,)+
        }

        struct AcquiredCells<'state> {
            $($field: Option<CellBlock<'state, $value>>,)+
        }

        enum CellPhase<'state> {
            Empty,
            Pending(PendingCells<'state>),
            Acquired(AcquiredCells<'state>),
        }

        impl<'state> CellPhase<'state> {
            fn new(state: &'state State) -> Self {
                Self::Pending(PendingCells {
                    $($field: Some(state.$field.block_acquisition()),)+
                })
            }

            fn initialize(&mut self, mode: BlockMode) {
                let Self::Pending(pending) = self else {
                    panic!("original pending State Cells");
                };
                $(pending.$field.as_mut().expect("original State Cell slot").initialize(mode);)+
                // All native/user work completed while the enclosing State owner
                // retained these slots. These transfers only move checked originals.
                let Self::Pending(mut pending) = std::mem::replace(self, Self::Empty) else {
                    unreachable!("original initialized State Cell slots");
                };
                *self = Self::Acquired(AcquiredCells {
                    $($field: Some(pending.$field.take().expect("original State Cell slot").into_block()),)+
                });
            }

            fn release(&mut self) {
                match self {
                    Self::Empty => {},
                    Self::Pending(pending) => {
                        $(if let Some(field) = pending.$field.as_mut() { field.release(); })+
                    }
                    Self::Acquired(acquired) => {
                        $(if let Some(field) = acquired.$field.as_mut() { field.release_writers(); })+
                    }
                }
            }
        }

        /// Exact completed originals; consuming these fields ends joint custody.
        pub(in crate::state) struct AcquiredRuntimeBlockFields<'state> {
            pub(in crate::state) world: WorldBlock<'state>,
            pub(in crate::state) transactions: TransactionsBlock<'state>,
            $(pub(in crate::state) $field: CellBlock<'state, $value>,)+
            pub(in crate::state) projection: CanonicalRuntimeProjection,
            pub(in crate::state) sccp_registry: Arc<ValidatedSccpRegistryV1>,
            pub(in crate::state) block_hashes: BlockHashesBlock<'state>,
            pub(in crate::state) da_rewind_releases: Option<da_hydration::DaRewindReleases<'state>>,
        }

        impl AcquiredRuntimeBlockFields<'_> {
            fn release(&mut self) {
                self.world.release_writers();
                self.transactions.release_writers();
                $(self.$field.release_writers();)+
            }
        }

        impl<'state> RuntimeBlockAcquisition<'state> {
            pub(super) fn finish(
                &mut self,
                projection: &mut Option<CanonicalRuntimeProjection>,
                sccp_registry: &mut Option<Arc<ValidatedSccpRegistryV1>>,
            ) -> AcquiredRuntimeBlock<'state> {
                // Borrow the caller's pending owner and metadata. A by-value
                // receiver adds another complete World temporary to the native
                // acquisition frame, even before the final handoff is reached.
                let original = self;
                assert!(original.complete, "original State acquisition did not complete");
                let CellPhase::Acquired(cells) = &original.cells else {
                    unreachable!("original acquired State Cells");
                };
                assert!(original.world.is_some() && original.transactions.is_some());
                assert!(original.block_hashes.is_some());
                $(assert!(cells.$field.is_some());)+
                assert!(projection.is_some() && sccp_registry.is_some());
                // All checks precede any extraction. A second finish remains
                // terminal, and the outlined closure borrows every original.
                original.complete = false;
                finish_runtime_acquisition(|| {
                    let CellPhase::Acquired(cells) = &mut original.cells else {
                        unreachable!("original acquired State Cells");
                    };
                    AcquiredRuntimeBlock {
                        target: original.target,
                        fields: Some(AcquiredRuntimeBlockFields {
                            world: original.world.take().expect("original State World"),
                            transactions: original.transactions.take().expect("original State membership"),
                            $($field: cells.$field.take().expect("original State Cell"),)+
                            projection: projection.take().expect("original prepared runtime projection"),
                            sccp_registry: sccp_registry.take().expect("original prepared SCCP registry"),
                            block_hashes: original.block_hashes.take().expect("original funded hash successor"),
                            da_rewind_releases: None,
                        }),
                    }
                })
            }
        }
    };
}

pub(in crate::state) struct AcquiredRuntimeBlock<'state> {
    target: &'state State,
    fields: Option<AcquiredRuntimeBlockFields<'state>>,
}

pub(super) fn new(
    target: &'state State,
    block_hashes: BlockHashesBlock<'state>,
    membership: storage_transactions::PreparedMembershipStart,
) -> Self {
    Self {
        world: None,
        transactions: None,
        cells: CellPhase::new(target),
        block_hashes: Some(block_hashes),
        membership: Some(membership),
        target,
        started: false,
        complete: false,
    }
}

pub(super) fn initialize(
    &mut self,
    replacement: bool,
) -> Result<(), storage_transactions::MembershipAdmissionError> {
    assert!(!self.started, "original State acquisition is one-shot");
    self.started = true;
    self.world = Some(if replacement {
        self.target.world.block_and_revert()
    } else {
        self.target.world.block()
    });
    self.transactions = Some(
        self.target
            .transactions
            .attach_prepared(&mut self.membership)?,
    );
    self.cells.initialize(if replacement {
        BlockMode::Replace
    } else {
        BlockMode::Ordinary
    });
    self.complete = true;
    Ok(())
}

pub(super) fn world(&self) -> &WorldBlock<'state> {
    self.world.as_ref().expect("original acquired World")
}

pub(super) fn world_mut(&mut self) -> &mut WorldBlock<'state> {
    self.world.as_mut().expect("original acquired World")
}

pub(super) fn canonical_runtime(&self) -> &CellBlock<'state, SnapshotNexusRuntime> {
    let CellPhase::Acquired(cells) = &self.cells else {
        panic!("original acquired runtime Cell");
    };
    cells
        .canonical_runtime
        .as_ref()
        .expect("original canonical runtime")
}

fn release(&mut self) {
    self.complete = false;
    if let Some(world) = self.world.as_mut() {
        world.release_writers();
    }
    if let Some(transactions) = self.transactions.as_mut() {
        transactions.release_writers();
    }
    self.cells.release();
}

pub(in crate::state) fn fields(&self) -> &AcquiredRuntimeBlockFields<'state> {
    self.fields
        .as_ref()
        .expect("original acquired State fields")
}

pub(in crate::state) fn into_fields(mut self) -> AcquiredRuntimeBlockFields<'state> {
    self.fields.take().expect("original acquired State fields")
}

fn drop(&mut self) {
    if let Some(fields) = self.fields.as_mut() {
        fields.release();
    }
}

fn finish_runtime_acquisition<'state>(
    finish: impl FnOnce() -> AcquiredRuntimeBlock<'state>,
) -> AcquiredRuntimeBlock<'state> {
    finish()
}

pub(super) fn construct_acquired_block<'state, R>(
    &'state self,
    acquired: canonical_runtime::AcquiredRuntimeBlock<'state>,
    curr_block: BlockHeader,
    finish: impl FnOnce(StateBlock<'state>) -> R,
) -> R {
    // Initialized metadata is destroyed after the original acquisition on
    // preparation unwind. No additional metadata box/collection is needed.
    let mut finish = Some(finish);
    let mut gas_limit_per_block;
    let mut privacy_budget_in_block;
    let mut runtime_policy;
    let mut pipeline_ivm_prepared_cache;
    let mut query_ledger_time_ms;
    let mut soracloud_runtime;
    let mut accounts_snapshot_cache;
    let mut pipeline;
    let mut oracle;
    let mut crypto;
    let mut lane_compliance;
    let mut fraud_monitoring;
    let mut zk;
    let mut gov;
    let mut content;
    let mut settlement;
    let mut kagemusha_v1_runtime_verifier;
    let mut settlement_engine;
    let mut chain_id;
    let mut settlement_accumulator;
    let mut fastpq_transcripts;
    let mut fastpq_entry_dataspaces;
    let mut fastpq_source_captures;
    let mut axt_envelopes;
    let mut axt_next_handle_counters;
    let mut axt_authorization_transitioned;
    let mut batch_transfer_outcomes;
    let mut verified_lane_relay_records;
    let mut touched_lanes;
    let mut merge_carrier_entrypoints;
    let mut staged_queue_plan_admissions;
    let mut pending_nexus_fee_receipt_source_ids;
    #[cfg(feature = "telemetry")]
    let mut pending_parliament_telemetry_events;
    let mut pending_public_lane_slash_observability;
    let mut sccp_verifier_work_in_block;
    #[cfg(feature = "zk-preverify")]
    let mut zk_dedup;
    let mut original = Some(acquired);
    let acquired = original
        .as_ref()
        .expect("original acquired State block")
        .fields();
    gas_limit_per_block = Some(gas_limit_from_parameters(acquired.world.parameters()));
    privacy_budget_in_block = Some(
        crate::privacy::PrivacyBlockBudgetV1::new(
            acquired.world.privacy_consensus_policy.get().current_limits,
        )
        .expect("persisted privacy consensus policy was validated before block construction"),
    );
    runtime_policy = Some(canonical_runtime::CapturedRuntimePolicy::capture(
        &acquired.projection,
        &self.zk,
        self.lane_compliance.read().clone(),
    ));
    pipeline_ivm_prepared_cache = Some(self.pipeline_ivm_prepared_cache.read().clone());
    query_ledger_time_ms = Some(Some(
        u64::try_from(curr_block.creation_time().as_millis()).unwrap_or(u64::MAX),
    ));
    soracloud_runtime = Some(self.soracloud_runtime());
    accounts_snapshot_cache = Some(SyncOnceCell::new());
    pipeline = Some(self.pipeline.clone());
    oracle = Some(self.oracle.clone());
    crypto = Some(self.crypto());
    lane_compliance = Some(
        runtime_policy
            .as_ref()
            .expect("prepared runtime policy")
            .compliance
            .clone(),
    );
    fraud_monitoring = Some(self.fraud_monitoring.clone());
    zk = Some(self.zk.clone());
    gov = Some(self.gov.clone());
    content = Some(self.content.clone());
    settlement = Some(self.settlement.clone());
    kagemusha_v1_runtime_verifier = Some(Arc::clone(&self.kagemusha_v1_runtime_verifier));
    settlement_engine = Some(self.settlement_engine.clone());
    chain_id = Some(self.chain_id.clone());
    settlement_accumulator = Some(crate::settlement::SettlementAccumulator::default());
    fastpq_transcripts = Some(BTreeMap::new());
    fastpq_entry_dataspaces = Some(BTreeMap::new());
    fastpq_source_captures = Some(crate::fastpq::FastpqSourceCaptureAccumulator::default());
    axt_envelopes = Some(Vec::new());
    axt_next_handle_counters = Some(BTreeMap::new());
    axt_authorization_transitioned = Some(BTreeSet::new());
    batch_transfer_outcomes = Some(BTreeMap::new());
    verified_lane_relay_records = Some(Vec::new());
    touched_lanes = Some(BTreeSet::new());
    merge_carrier_entrypoints = Some(HashSet::new());
    staged_queue_plan_admissions = Some(Vec::new());
    pending_nexus_fee_receipt_source_ids = Some(BTreeSet::new());
    #[cfg(feature = "telemetry")]
    {
        pending_parliament_telemetry_events = Some(Vec::new());
    }
    pending_public_lane_slash_observability = Some(Vec::new());
    sccp_verifier_work_in_block = Some(SccpVerifierWorkV1::default());
    #[cfg(feature = "zk-preverify")]
    {
        zk_dedup = Some(Default::default());
    }
    // Every take below is checked while the joint owner is still armed.
    // The finishing closure borrows each Option, including metadata and the
    // caller continuation, rather than moving cleanup into its environment.
    assert!(original.is_some() && finish.is_some());
    assert!(
        gas_limit_per_block.is_some()
            && privacy_budget_in_block.is_some()
            && runtime_policy.is_some()
    );
    assert!(pipeline_ivm_prepared_cache.is_some());
    assert!(query_ledger_time_ms.is_some());
    assert!(soracloud_runtime.is_some());
    assert!(accounts_snapshot_cache.is_some());
    assert!(pipeline.is_some());
    assert!(oracle.is_some());
    assert!(crypto.is_some());
    assert!(lane_compliance.is_some());
    assert!(fraud_monitoring.is_some());
    assert!(zk.is_some());
    assert!(gov.is_some());
    assert!(content.is_some());
    assert!(settlement.is_some());
    assert!(kagemusha_v1_runtime_verifier.is_some());
    assert!(settlement_engine.is_some());
    assert!(chain_id.is_some());
    assert!(settlement_accumulator.is_some());
    assert!(fastpq_transcripts.is_some());
    assert!(fastpq_entry_dataspaces.is_some());
    assert!(fastpq_source_captures.is_some());
    assert!(axt_envelopes.is_some());
    assert!(axt_next_handle_counters.is_some());
    assert!(axt_authorization_transitioned.is_some());
    assert!(batch_transfer_outcomes.is_some());
    assert!(verified_lane_relay_records.is_some());
    assert!(touched_lanes.is_some());
    assert!(merge_carrier_entrypoints.is_some());
    assert!(staged_queue_plan_admissions.is_some());
    assert!(pending_nexus_fee_receipt_source_ids.is_some());
    #[cfg(feature = "telemetry")]
    assert!(pending_parliament_telemetry_events.is_some());
    assert!(pending_public_lane_slash_observability.is_some());
    assert!(sccp_verifier_work_in_block.is_some());
    #[cfg(feature = "zk-preverify")]
    assert!(zk_dedup.is_some());
    // No World-sized owner is copied into a closure payload. Its only
    // arbitrary caller operation receives an already armed StateBlock.
    finish_state_block_construction(|| {
        let canonical_runtime::AcquiredRuntimeBlockFields {
            world,
            transactions,
            commit_topology,
            prev_commit_topology,
            lane_consensus_contexts,
            canonical_runtime,
            projection,
            sccp_registry,
            block_hashes,
            da_rewind_releases,
        } = original
            .take()
            .expect("original acquired State block")
            .into_fields();
        let block = StateBlock::from_fields(StateBlockFields {
            state_ref: self,
            read_releases: StateViewReleases::new(self),
            da_rewind_releases,
            canonical_runtime: block_field::BlockField::new(canonical_runtime),
            block_hashes: block_hash_field::BlockHashField::new(block_hashes),
            world,
            merge_ledger: &self.merge_ledger,
            transactions: storage_transactions::TransactionsBlockField::new(transactions),
            commit_topology: block_field::BlockField::new(commit_topology),
            prev_commit_topology: block_field::BlockField::new(prev_commit_topology),
            lane_consensus_contexts: block_field::BlockField::new(lane_consensus_contexts),
            lane_consensus_contexts_seal: None,
            ivm: &self.ivm,
            pipeline_ivm_prepared_cache: pipeline_ivm_prepared_cache
                .take()
                .expect("prepared State input"),
            kura: &self.kura,
            query_handle: &self.query_handle,
            query_ledger_time_ms: query_ledger_time_ms.take().expect("prepared State input"),
            soracloud_runtime: soracloud_runtime.take().expect("prepared State input"),
            accounts_snapshot_cache: accounts_snapshot_cache
                .take()
                .expect("prepared State input"),
            pipeline: pipeline.take().expect("prepared State input"),
            oracle: oracle.take().expect("prepared State input"),
            crypto: crypto.take().expect("prepared State input"),
            nexus: projection.nexus,
            lane_incarnations: projection.incarnations,
            lane_incarnation_lineage: projection.lineage,
            lane_incarnation_activation_heights: projection.activation_heights,
