fn deref_mut(&mut self) -> &mut Self::Target {
    self.fields.as_mut().expect("original executing State")
}

fn from_fields(fields: StateBlockFields<'state>) -> Self {
    Self {
        fields: Some(fields),
    }
}

fn into_fields(mut self) -> StateBlockFields<'state> {
    self.fields.take().expect("original executing State")
}

fn release_writers(&mut self) {
    if let Some(fields) = self.fields.as_mut() {
        fields.world.release_writers();
        fields.canonical_runtime.release_writers();
        fields.commit_topology.release_writers();
        fields.prev_commit_topology.release_writers();
        fields.lane_consensus_contexts.release_writers();
        fields.transactions.release_writers();
        fields.block_hashes.release_writers();
    }
}

pub struct LinCowCellCommitSlot<'a, T, R, U, Charge = Untracked> {
    phase: Option<LinCowCellCommitPhase<'a, T, R, U, Charge>>,
    ready: bool,
}

enum LinCowCellCommitPhase<'a, T, R, U, Charge> {
    Writer(LinCowCellWriteTxn<'a, T, R, U, Charge>),
    Prepared(LinCowCellPreparedCommit<'a, T, R, U, Charge>),
}

pub fn commit_slot(self) -> LinCowCellCommitSlot<'a, T, R, U, Charge> {
    LinCowCellCommitSlot {
        phase: Some(LinCowCellCommitPhase::Writer(self)),
        ready: false,
    }
}

pub fn prepare_commit(self) -> LinCowCellPreparedCommit<'a, T, R, U, Charge> {
    let mut slot = self.commit_slot();
    slot.prepare();
    slot.into_prepared()
}

pub fn try_prepare_commit(
    self,
) -> Result<LinCowCellPreparedCommit<'a, T, R, U, Charge>, (Self, OwnedWriteError)> {
    let mut slot = self.commit_slot();
    if let Err(error) = slot.try_prepare() {
        let (writer, release) = slot.abort_retaining();
        debug_assert!(release.is_none(), "failed acquisition owned no reader");
        return Err((writer, error));
    }
    Ok(slot.into_prepared())
}

pub fn prepare(&mut self) {
    let Some(LinCowCellCommitPhase::Writer(writer)) = self.phase.as_ref() else {
        panic!("original writer prepares once");
    };
    let active = if writer.guard.is_retained() {
        writer.caller.lock_active_retained()
    } else {
        writer.caller.lock_active()
    };
    self.install_active(active);
    self.validate();
}

pub fn try_prepare(&mut self) -> Result<(), OwnedWriteError> {
    let Some(LinCowCellCommitPhase::Writer(writer)) = self.phase.as_ref() else {
        panic!("original writer prepares once");
    };
    let active = if writer.guard.is_retained() {
        writer.caller.try_lock_active_retained()?
    } else {
        writer.caller.try_lock_active()?
    };
    self.install_active(active);
    self.validate();
    Ok(())
}

fn install_active(&mut self, active: ActiveGuard<'a, R, Charge>) {
    let Some(LinCowCellCommitPhase::Writer(LinCowCellWriteTxn {
        caller,
        guard,
        work,
        next,
        base,
    })) = self.phase.take()
    else {
        unreachable!("borrowed original writer checked before acquisition");
    };
    // Only inert moves occur between taking the writer and installing it.
    // All assertions and cursor validation happen after caller custody resumes.
    self.phase = Some(LinCowCellCommitPhase::Prepared(LinCowCellPreparedCommit {
        caller,
        guard,
        active,
        work,
        next,
        base,
    }));
}

fn validate(&mut self) {
    let Some(LinCowCellCommitPhase::Prepared(prepared)) = self.phase.as_mut() else {
        unreachable!("original reader and writer installed before validation");
    };
    assert!(Shared::ptr_eq(&prepared.base, &prepared.guard.current));
    assert!(Shared::ptr_eq(&prepared.base, &prepared.active));
    assert!(prepared.base.pin.get().is_none());
    let original = Shared::get_mut(&mut prepared.work).expect("original cursor must be unique");
    prepared
        .guard
        .data
        .validate_commit(original, &prepared.base.data);
    self.ready = true;
}

pub fn into_prepared(mut self) -> LinCowCellPreparedCommit<'a, T, R, U, Charge> {
    assert!(self.ready, "original preparation must complete");
    let Some(LinCowCellCommitPhase::Prepared(prepared)) = self.phase.take() else {
        unreachable!("ready preparation retains original physical guards");
    };
    prepared
}

pub fn abort_retaining(
    mut self,
) -> (
    LinCowCellWriteTxn<'a, T, R, U, Charge>,
    Option<crate::release::DeferredRelease>,
) {
    match self.phase.take().expect("original commit slot") {
        LinCowCellCommitPhase::Writer(writer) => (writer, None),
        LinCowCellCommitPhase::Prepared(prepared) => {
            let (writer, release) = prepared.abort_retaining();
            (writer, Some(release))
        }
    }
}

pub fn commit_slot(self) -> EbrCellCommitSlot<'a, T, Charge> {
    EbrCellCommitSlot {
        writer: Some(self),
        ready: false,
    }
}

pub fn prepare_commit(self) -> EbrCellPreparedCommit<'a, T, Charge> {
    let mut slot = self.commit_slot();
    slot.prepare();
    slot.into_prepared()
}

fn validate_commit(&self) {
    assert!(self.data.is_some(), "original unpublished allocation");
    // SAFETY: this writer exclusively prevents replacement of active. Its
    // borrowed cell cannot be destroyed, and active is never null in a live
    // cell. No protected payload reference escapes this ownership phase.
    let active = self
        .caller
        .active
        .load(Acquire, unsafe { epoch::unprotected() });
    assert!(!active.is_null(), "original initialized generation");
}

pub fn prepare(&mut self) {
    assert!(!self.ready, "original EBR writer prepares once");
    self.writer
        .as_ref()
        .expect("original EBR writer")
        .validate_commit();
    self.ready = true;
}

pub fn into_prepared(mut self) -> EbrCellPreparedCommit<'a, T, Charge> {
    assert!(self.ready, "original preparation must complete");
    EbrCellPreparedCommit {
        writer: self.writer.take().expect("original EBR writer"),
    }
}

pub fn abort(mut self) -> EbrCellWriteTxn<'a, T, Charge> {
    self.writer.take().expect("original EBR writer")
}

pub fn commit_slot(self) -> BptreeMapCommitSlot<'a, K, V, M> {
    BptreeMapCommitSlot {
        inner: self.inner.commit_slot(),
    }
}

pub fn prepare_commit(self) -> BptreeMapPreparedCommit<'a, K, V, M> {
    let mut slot = self.commit_slot();
    slot.prepare();
    slot.into_prepared()
}

pub fn try_prepare_commit(
    self,
) -> Result<BptreeMapPreparedCommit<'a, K, V, M>, (Self, OwnedWriteError)> {
    let mut slot = self.commit_slot();
    if let Err(error) = slot.try_prepare() {
        let (writer, release) = slot.abort_retaining();
        debug_assert!(release.is_none(), "failed acquisition owned no reader");
        return Err((writer, error));
    }
    Ok(slot.into_prepared())
}

pub fn prepare(&mut self) {
    self.inner.as_ref().assert_operable();
    self.inner.prepare();
}

pub fn try_prepare(&mut self) -> Result<(), OwnedWriteError> {
    self.inner.as_ref().assert_operable();
    self.inner.try_prepare()
}

pub fn into_prepared(self) -> BptreeMapPreparedCommit<'a, K, V, M> {
    BptreeMapPreparedCommit {
        inner: self.inner.into_prepared(),
    }
}

pub fn abort_retaining(
    self,
) -> (
    BptreeMapWriteTxn<'a, K, V, M>,
    Option<crate::release::DeferredRelease>,
) {
    let (inner, release) = self.inner.abort_retaining();
    (BptreeMapWriteTxn { inner }, release)
}

pub(crate) fn prepare_current_in<'a>(
    &self,
    publication: &'a Publication,
    slot: &mut Option<PreparedIdentity<'a>>,
) {
    assert!(slot.is_none(), "original identity prepares once");
    *slot = Some(PreparedIdentity {
        version: publication.lock_version(),
    });
    let held = slot.as_ref().expect("original identity retained by caller");
    assert!(
        Shared::ptr_eq(&self.owner, &publication.owner),
        "original publication owner"
    );
    assert!(
        Shared::ptr_eq(&self.version, &held.version),
        "original publication predecessor"
    );
}

pub(crate) fn publish_retaining<Published, Retirement>(
    mut self,
    next: NextPublication,
    publish: impl FnOnce() -> Published,
    release: impl FnOnce(Published) -> Retirement,
) -> (Retirement, IdentityRetirement) {
    let published = publish();
    let version = std::mem::replace(&mut **self.version, next.0);
    let retirement = release(published);
    let ((), released) = self.version.release_deferred(drop);
    (
        retirement,
        IdentityRetirement {
            _version: Some(version),
            _release: released,
        },
    )
}

pub(crate) fn abort(self) -> IdentityRetirement {
    let ((), release) = self.version.release_deferred(drop);
    IdentityRetirement {
        _version: None,
        _release: release,
    }
}

enum CellStage<'a, V: Value, C: Send + Sync + 'static> {
    Held(ReleaseGuard<'a, EbrCellCommitSlot<'a, V, C>>),
    Released {
        _owner: EbrCellOwned<V, C>,
        _release: DeferredRelease,
    },
}

fn new(writer: CellWriter<'a, V, C>) -> Self {
    Self::Held(writer.map_preserving_release(|writer| writer.commit_slot()))
}

fn prepare(&mut self) {
    let Self::Held(slot) = self else {
        panic!("original cell was released")
    };
    slot.prepare();
}

fn is_prepared(&self) -> bool {
    matches!(self, Self::Held(slot) if slot.is_prepared())
}

fn into_held(self) -> ReleaseGuard<'a, EbrCellCommitSlot<'a, V, C>> {
    match self {
        Self::Held(slot) => slot,
        Self::Released { .. } => panic!("terminal release grants no publication"),
    }
}

fn abort(self) -> (EbrCellOwned<V, C>, DeferredRelease) {
    self.into_held()
        .release_deferred(|slot| slot.abort().detach())
}

fn release(phase: &mut Option<Self>) {
    if !matches!(phase, Some(Self::Held(_))) {
        return;
    }
    let (owner, release) = phase.take().expect("original held cell").abort();
    *phase = Some(Self::Released {
        _owner: owner,
        _release: release,
    });
}

pub(super) fn new(
    revert: CellWriter<'a, Option<V>, C>,
    blocks: CellWriter<'a, V, C>,
    probe: Option<IdentityRetirement>,
) -> Self {
    Self {
        revert: Some(CellStage::new(revert)),
        blocks: Some(CellStage::new(blocks)),
        identity: None,
        probe,
        refused_identity: None,
        complete: false,
        started: false,
        released: false,
    }
}

pub(super) fn prepare<E>(
    &mut self,
    target: &'a Cell<V, C>,
    predecessor: &CapturedPublication,
    dirty: bool,
) -> Result<(), PublicationPreparationError<E>> {
    assert!(
        !self.started && !self.released,
        "original pair prepares once"
    );
    self.started = true;
    self.revert.as_mut().expect("original undo").prepare();
    if dirty {
        self.blocks.as_mut().expect("original current").prepare();
    }
    match predecessor.try_prepare_current(&target.publication) {
        Ok(identity) => self.identity = Some(identity),
        Err((error, retirement)) => {
            self.refused_identity = retirement;
            return Err(error);
        }
    }
    self.complete = true;
    Ok(())
}

pub(super) fn prepare_attached(
    &mut self,
    publication: &'a Publication,
    predecessor: &CapturedPublication,
    dirty: bool,
) {
    assert!(
        !self.started && !self.released,
        "original pair prepares once"
    );
    self.started = true;
    self.revert.as_mut().expect("original undo").prepare();
    if dirty {
        self.blocks.as_mut().expect("original current").prepare();
    }
    predecessor.prepare_current_in(publication, &mut self.identity);
    self.complete = true;
}

pub(super) fn release(&mut self) {
    if self.released {
        return;
    }
    CellStage::release(&mut self.blocks);
    CellStage::release(&mut self.revert);
    if let Some(identity) = self.identity.take() {
        debug_assert!(self.refused_identity.is_none());
        self.refused_identity = Some(identity.abort());
    }
    self.complete = false;
    self.released = true;
}

pub(super) fn abort<I>(
    mut self,
    installation: I,
) -> (
    EbrCellOwned<V, C>,
    EbrCellOwned<Option<V>, C>,
    PublicationCleanup<I>,
) {
    assert!(!self.released, "terminal release grants no journal");
    let (blocks, blocks_release) = self.blocks.take().expect("original current").abort();
    let (revert, revert_release) = self.revert.take().expect("original undo").abort();
    let identity = self
        .identity
        .take()
        .map(PreparedIdentity::abort)
        .or(self.refused_identity.take());
    (
        blocks,
        revert,
        PublicationCleanup {
            _readers: [None, None],
            _writers: [Some(blocks_release), Some(revert_release)],
            writer_batches: [None, None],
            identities: [self.probe.take(), identity],
            installation: Some(installation),
        },
    )
}

pub(super) fn publish<A, I>(
    mut self,
    next: NextPublication,
    admission: A,
    installation: I,
) -> PublishedPublication<V, A, I, C> {
    assert!(
        self.complete && !self.released,
        "original pair preparation must complete"
    );
    let blocks_prepared = self
        .blocks
        .as_ref()
        .expect("original current")
        .is_prepared();
    assert!(self.revert.as_ref().expect("original undo").is_prepared());
    let blocks = self.blocks.take().expect("original current").into_held();
    let revert = self.revert.take().expect("original undo").into_held();
    let identity = self.identity.take().expect("original identity prepared");
    let ((blocks, revert, unchanged, blocks_release, revert_release), identity) = identity
        .publish_retaining(
            next,
            || {
                let (blocks, unchanged) = if blocks_prepared {
                    (
                        Some(
                            blocks
                                .map_preserving_release(|slot| slot.into_prepared().publish()),
                        ),
                        None,
                    )
                } else {
                    (None, Some(blocks))
                };
                (
                    blocks,
                    revert.map_preserving_release(|slot| slot.into_prepared().publish()),
                    unchanged,
                )
            },
            |(blocks, revert, unchanged)| {
                let (blocks, unchanged, blocks_release) = match (blocks, unchanged) {
                    (Some(blocks), None) => {
                        let (retirement, release) = blocks.release_deferred(|p| p.release());
                        (Some(retirement), None, release)
                    }
                    (None, Some(unchanged)) => {
                        let (owner, release) =
                            unchanged.release_deferred(|slot| slot.abort().detach());
                        (None, Some(owner), release)
                    }
                    _ => unreachable!("one original current owner"),
                };
                let (revert, revert_release) = revert.release_deferred(|p| p.release());
                (blocks, revert, unchanged, blocks_release, revert_release)
            },
        );
    PublishedPublication {
        _blocks: blocks,
        _revert: revert,
        _unchanged: unchanged,
        _blocks_release: blocks_release,
        _revert_release: revert_release,
        _identity: identity,
        _probe: self.probe.take(),
        _admission: admission,
        _installation: installation,
    }
}

enum MapStage<'a, K: Key, V: Value, M: MapMode + NodeCloning<K, V>> {
    Held(ReleaseGuard<'a, BptreeMapCommitSlot<'a, K, V, M>>),
    Released {
        _owner: BptreeMapAbandonment<K, V, M>,
        _releases: MapReleases,
    },
}

fn new(writer: ReleaseGuard<'a, BptreeMapWriteTxn<'a, K, V, M>>) -> Self {
    Self::Held(writer.map_preserving_release(|writer| writer.commit_slot()))
}

fn prepare(&mut self) -> Result<(), OwnedWriteError> {
    let Self::Held(slot) = self else {
        panic!("original map was released")
    };
    slot.try_prepare()
}

fn is_prepared(&self) -> bool {
    matches!(self, Self::Held(slot) if slot.is_prepared())
}

fn into_held(self) -> ReleaseGuard<'a, BptreeMapCommitSlot<'a, K, V, M>> {
    match self {
        Self::Held(slot) => slot,
        Self::Released { .. } => panic!("terminal release grants no publication"),
    }
}

fn abort(self) -> (BptreeMapOwned<K, V, M>, MapReleases) {
    let ((owner, reader), writer) = self.into_held().release_deferred(|slot| {
        let (writer, reader) = slot.abort_retaining();
        (writer.detach(), reader)
    });
    (
        owner,
        MapReleases {
            _reader: reader,
            _writer: writer,
        },
    )
}

fn release(phase: &mut Option<Self>) {
    if !matches!(phase, Some(Self::Held(_))) {
        return;
    }
    let ((owner, reader), writer) = phase
        .take()
        .expect("original held map")
        .into_held()
        .release_deferred(|slot| {
            let (writer, reader) = slot.abort_retaining();
            // A failed private cursor is cleanup custody, never a journal.
            (writer.abort_retaining(), reader)
        });
    *phase = Some(Self::Released {
        _owner: owner,
        _releases: MapReleases {
            _reader: reader,
            _writer: writer,
        },
    });
}

pub(super) fn new(
    writers: StorageWriters<'a, K, V, M>,
    probe: Option<IdentityRetirement>,
) -> Self {
    let target = writers.target;
    Self::from_original(target, writers.into_original(), probe)
}

pub(super) fn prepare<E>(
    &mut self,
    predecessor: &CapturedPublication,
    dirty: bool,
) -> Result<(), PublicationPreparationError<E>> {
    fn refusal<E>(
        error: OwnedWriteError,
        wait: crate::ReleaseWait,
    ) -> PublicationPreparationError<E> {
        match error {
            OwnedWriteError::Busy => {
                PublicationPreparationError::after_failed_acquisition(wait)
            }
            OwnedWriteError::Poisoned => PublicationPreparationError::Poisoned,
            OwnedWriteError::Changed => PublicationPreparationError::Changed,
        }
    }
    assert!(
        !self.started && !self.released,
        "original pair prepares once"
    );
    self.started = true;
    let wait = self.target.revert.observe_reader_release();
    self.revert
        .as_mut()
        .expect("original undo")
        .prepare()
        .map_err(|error| refusal(error, wait))?;
    if dirty {
        let wait = self.target.blocks.observe_reader_release();
        self.blocks
            .as_mut()
            .expect("original current")
            .prepare()
            .map_err(|error| refusal(error, wait))?;
    }
    match predecessor.try_prepare_current(&self.target.publication) {
        Ok(identity) => self.identity = Some(identity),
        Err((error, retirement)) => {
            self.refused_identity = retirement;
            return Err(error);
        }
    }
    self.complete = true;
    Ok(())
}

pub(super) fn prepare_attached(&mut self, predecessor: &CapturedPublication, dirty: bool) {
    assert!(
        !self.started && !self.released,
        "original pair prepares once"
    );
    self.started = true;
    self.revert
        .as_mut()
        .expect("original undo")
        .prepare_blocking();
    if dirty {
        self.blocks
            .as_mut()
            .expect("original current")
            .prepare_blocking();
    }
    predecessor.prepare_current_in(&self.target.publication, &mut self.identity);
    self.complete = true;
}

pub(super) fn release(&mut self) {
    if self.released {
        return;
    }
    MapStage::release(&mut self.blocks);
    MapStage::release(&mut self.revert);
    if let Some(identity) = self.identity.take() {
        debug_assert!(self.refused_identity.is_none());
        self.refused_identity = Some(identity.abort());
    }
    self.complete = false;
    self.released = true;
}

pub(super) fn abort<I>(
    mut self,
    installation: I,
) -> (
    BptreeMapOwned<K, V, M>,
    BptreeMapOwned<K, Option<V>, M>,
    PublicationCleanup<I>,
) {
    assert!(!self.released, "terminal release grants no journal");
    let (blocks, block_releases) = self.blocks.take().expect("original current").abort();
    let (revert, revert_releases) = self.revert.take().expect("original undo").abort();
    let identity = self
        .identity
        .take()
        .map(PreparedIdentity::abort)
        .or(self.refused_identity.take());
    // All raw locks have released, including identity. Their original
    // signals remain owned until the enclosing aggregate has unlocked.
    (
        blocks,
        revert,
        PublicationCleanup {
            _readers: [block_releases._reader, revert_releases._reader],
            _writers: [Some(block_releases._writer), Some(revert_releases._writer)],
            writer_batches: [None, None],
            identities: [self.probe.take(), identity],
            installation: Some(installation),
        },
    )
}

pub(super) fn publish(mut self, next: NextPublication) -> PublicationRetirement<K, V, M> {
    assert!(
        self.complete && !self.released,
        "original pair preparation must complete"
    );
    let blocks_prepared = self
        .blocks
        .as_ref()
        .expect("original current")
        .is_prepared();
    assert!(self.revert.as_ref().expect("original undo").is_prepared());
    let blocks = self.blocks.take().expect("original current").into_held();
    let revert = self.revert.take().expect("original undo").into_held();
    let identity = self.identity.take().expect("original prepared identity");
    let ((blocks, revert, unchanged, blocks_release, revert_release), identity) = identity
        .publish_retaining(
            next,
            || {
                let (blocks, unchanged) = if blocks_prepared {
                    (
                        Some(
                            blocks
                                .map_preserving_release(|slot| slot.into_prepared().publish()),
                        ),
                        None,
                    )
                } else {
                    (None, Some(blocks))
                };
                let revert =
                    revert.map_preserving_release(|slot| slot.into_prepared().publish());
                (blocks, revert, unchanged)
            },
            |(blocks, revert, unchanged)| {
                let (blocks, unchanged, blocks_release) = match (blocks, unchanged) {
                    (Some(blocks), None) => {
                        let (retirement, release) = blocks.release_deferred(|p| p.release());
                        (Some(retirement), None, release)
                    }
                    (None, Some(unchanged)) => {
                        let (owner, release) = unchanged.release_deferred(|slot| {
                            let (writer, reader) = slot.abort_retaining();
                            debug_assert!(
                                reader.is_none(),
                                "unchanged writer was not prepared"
                            );
                            writer.detach()
                        });
                        (None, Some(owner), release)
                    }
                    _ => unreachable!("one original current owner"),
                };
                let (revert, revert_release) = revert.release_deferred(|p| p.release());
                (blocks, revert, unchanged, blocks_release, revert_release)
            },
        );
    PublicationRetirement {
        _blocks: blocks,
        _revert: revert,
        _unchanged: unchanged,
        _blocks_release: blocks_release,
        _revert_release: revert_release,
        _identity: identity,
        _probe: self.probe.take(),
    }
}

fn prepare_blocking(&mut self) {
    let Self::Held(slot) = self else {
        panic!("original map was released")
    };
    slot.prepare();
}

pub(super) fn from_original(
    target: &'a Storage<K, V, M>,
    original: OriginalWriters<'a, K, V, M>,
    probe: Option<IdentityRetirement>,
) -> Self {
    let OriginalWriters { revert, blocks } = original;
    Self {
        revert: Some(MapStage::new(revert)),
        blocks: Some(MapStage::new(blocks)),
        identity: None,
        probe,
        refused_identity: None,
        complete: false,
        started: false,
        released: false,
        target,
    }
}

pub(super) fn prepare_publication(
    &mut self,
    publication: &'a Publication,
    predecessor: &CapturedPublication,
    dirty: bool,
) {
    // Check the complete original phase before allocating the one identity
    // that ordinary Cell::commit already requires. No owner is taken yet.
    self.as_ref();
    let next = NextPublication::new();
    let Some(CellWriterState::Attached(OriginalCellWriters { revert, blocks })) =
        self.state.take()
    else {
        unreachable!("original attached pair checked above");
    };
    self.state = Some(CellWriterState::Preparing {
        writers: PreparedCellWriters::new(revert, blocks, None),
        next,
    });
    let Some(CellWriterState::Preparing { writers, .. }) = self.state.as_mut() else {
        unreachable!("original publication phase installed before preparation");
    };
    writers.prepare_attached(publication, predecessor, dirty);
}

pub(super) fn publish_prepared(&mut self) {
    assert!(
        matches!(&self.state, Some(CellWriterState::Preparing { writers, .. }) if writers.is_prepared()),
        "original pair preparation must complete"
    );
    let Some(CellWriterState::Preparing { writers, next }) = self.state.take() else {
        unreachable!("checked original publication phase");
    };
    self.state = Some(CellWriterState::Published {
        _retirement: writers.publish(next, (), ()),
    });
}

fn prepare_publication(&mut self, predecessor: &CapturedPublication, dirty: bool) {
    self.as_ref();
    let Some(StorageWriterState::Attached(original)) = self.state.take() else {
        unreachable!("original attached pair checked above");
    };
    self.state = Some(StorageWriterState::Preparing(
        PreparedStorageWriters::from_original(self.target, original, None),
    ));
    let Some(StorageWriterState::Preparing(writers)) = self.state.as_mut() else {
        unreachable!("original publication phase installed before preparation");
    };
    writers.prepare_attached(predecessor, dirty);
}

fn publish_prepared(&mut self, next: &mut Option<NextPublication>) {
    assert!(
        matches!(&self.state, Some(StorageWriterState::Preparing(writers)) if writers.is_prepared()),
        "original pair preparation must complete"
    );
    assert!(
        next.is_some(),
        "original successor identity retained until publication"
    );
    let Some(StorageWriterState::Preparing(writers)) = self.state.take() else {
        unreachable!("checked original publication phase");
    };
    let next = next.take().expect("checked original successor identity");
    self.state = Some(StorageWriterState::Published {
        _retirement: writers.publish(next),
    });
}

pub(super) fn prepare_attached_publication(&mut self) {
    self.assert_operable();
    self.writers
        .prepare_publication(&self.predecessor, self.dirty);
}

pub(super) fn publish_attached_prepared(&mut self) {
    self.writers.publish_prepared(&mut self.next);
}

pub(super) fn publish(mut self) {
    self.prepare_attached_publication();
    self.publish_attached_prepared();
}

pub(super) fn prepare_attached_publication(&mut self) {
    self.writers
        .prepare_publication(self.publication, &self.predecessor, self.dirty);
}

pub struct BlockPublicationSlot<'a, V: Value, C: Send + Sync + 'static = Untracked> {
    block: Block<'a, V, C>,
}

pub fn publication_slot(self) -> BlockPublicationSlot<'a, V, C> {
    BlockPublicationSlot { block: self }
}

pub struct BlockPublicationSlot<'a, K: Key, V: Value, M: StorageMode<K, V> = Untracked> {
    block: Block<'a, K, V, M>,
}

pub fn publication_slot(self) -> BlockPublicationSlot<'a, K, V, M> {
    BlockPublicationSlot { block: self }
}

pub fn try_from_snapshot_admitted<M: StorageMode<K, V>>(
    snapshot: &super::snapshot::Snapshot<'_, K, V, M>,
    budget: AllocationBudget,
) -> Result<Self, AdmittedStorageError> {
    budget.with_deferred_refund_notifications(|_| {
        let restored = Self::try_new_admitted(budget.clone())?;
        let AdmittedWriters { mut writers, next } = restored.open_admitted_writers()?;
        let OriginalWriters { revert, blocks } = writers.as_mut();
        for (key, value) in snapshot.current().iter() {
            insert_copy(blocks, key, value, &budget)?;
        }
        for (key, value) in snapshot.revert_map().iter() {
            insert_copy(revert, key, value, &budget)?;
        }
        let predecessor = restored.publication.capture();
        writers.prepare_publication(&predecessor, true);
        let mut next = Some(next);
        writers.publish_prepared(&mut next);
        drop(writers);
        Ok(restored)
    })
}

fn new(
    block: TransactionsBlock<'storage>,
    publication: MembershipPublication,
    next_identity: Identity,
) -> Self {
    Self {
        block,
        publication,
        next_identity,
        retired_tip: None,
        publication_started: false,
        published: false,
    }
}

fn assert_unpublished(&self) {
    assert!(
        !self.publication_started && !self.published,
        "membership publication was already attempted"
    );
}

fn publish_in_place(&mut self) {
    self.assert_unpublished();
    assert!(
        self.is_physically_prepared(),
        "original physical membership preparation must precede publication"
    );
    self.block._guard.identity();
    self.publication_started = true;
    if !matches!(&self.publication, MembershipPublication::Repeated) {
        let next = self
            .block
            ._guard
            .history
            .as_ref()
            .expect("original history")
            .next_sequence();
        self.block
            .publication_sequence
            .store(next - 1, Ordering::Release);
        self.block
            ._guard
            .history
            .as_mut()
            .expect("original history")
            .publish();
        let current = match &self.publication {
            MembershipPublication::Replace { current }
            | MembershipPublication::Advance { current, .. } => current,
            MembershipPublication::Repeated => unreachable!(),
        };
        self.retired_tip = self.block.latest_block_ref.swap(Some(current.clone()));
        self.block
            .publication_sequence
            .store(next, Ordering::Release);
    }
    if !matches!(&self.publication, MembershipPublication::Repeated) {
        // Install the exact pre-admitted identity and retain its exact
        // predecessor in the same field. No identity is reconstructed.
        std::mem::swap(self.block._guard.identity_mut(), &mut self.next_identity);
    }
    self.block.release_writers();
    self.published = true;
}

fn into_retirement(self) -> TransactionsPublicationRetirement {
    assert!(
        self.published,
        "original membership publication must complete"
    );
    let Self {
        block,
        publication,
        next_identity,
        retired_tip,
        publication_started: _,
        published: _,
    } = self;
    let TransactionsBlock {
        current_block,
        _guard,
        ..
    } = block;
    let release = _guard.into_release();
    TransactionsPublicationRetirement {
        _tip: retired_tip,
        _staged: current_block,
        _identity: next_identity,
        _publication: publication,
        _release: release,
    }
}

fn take_release(&mut self) -> MembershipRelease {
    self.release();
    MembershipRelease {
        _history: self.history.as_mut().map(|history| history.cleanup()),
        _writer: self.take_writer_release(),
    }
}

pub(crate) fn publish_prepared(&mut self) {
    assert!(!self.released, "membership capture was terminally released");
    let MembershipCapturePhase::Prepared(prepared) = &mut self.phase else {
        panic!("original prepared membership publication");
    };
    prepared.publish_in_place();
    self.cleanup = Some(prepared.block._guard.take_release());
    // No fallible work occurs during this inert successful phase transfer.
    let MembershipCapturePhase::Prepared(prepared) =
        std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty)
    else {
        unreachable!("original completed membership publication");
    };
    self.phase = MembershipCapturePhase::Published(prepared);
}

fn executing(&self) -> &TransactionsBlock<'storage> {
    assert!(
        !self.attempted && !self.released,
        "membership execution authority ended"
    );
    match &self.phase {
        MembershipCapturePhase::Attached(block) => block,
        _ => panic!("original executing membership"),
    }
}

fn executing_mut(&mut self) -> &mut TransactionsBlock<'storage> {
    assert!(
        !self.attempted && !self.released,
        "membership execution authority ended"
    );
    match &mut self.phase {
        MembershipCapturePhase::Attached(block) => block,
        _ => panic!("original executing membership"),
    }
}

fn into_executing(mut self) -> TransactionsBlock<'storage> {
    self.executing();
    match std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty) {
        MembershipCapturePhase::Attached(block) => block,
        _ => unreachable!("checked original executing membership"),
    }
}

pub struct TransactionsBlockField<'storage> {
    pub(super) slot: TransactionsCaptureSlot<'storage>,
}

pub(crate) fn new(block: TransactionsBlock<'storage>) -> Self {
    Self {
        slot: block.capture_slot(),
    }
}

pub(crate) fn try_prepare_publication(&mut self) -> Result<(), TransactionsBlockError> {
    self.slot.try_prepare()
}

pub(crate) fn into_capture(self) -> TransactionsCaptureSlot<'storage> {
    self.slot.executing();
    self.slot
}

pub(crate) fn new(block: B) -> Self {
    Self {
        phase: Some(Phase::Executing(block)),
        released: false,
    }
}

pub(crate) fn into_executing(mut self) -> B {
    assert!(!self.released, "field was terminally released");
    assert!(
        matches!(self.phase, Some(Phase::Executing(_))),
        "field already entered publication"
    );
    match self.phase.take().expect("original field") {
        Phase::Executing(block) => block,
        Phase::Publishing(_) => unreachable!("checked original execution phase"),
    }
}

pub(crate) fn prepare_publication(&mut self) {
    assert!(!self.released, "field was terminally released");
    assert!(
        matches!(self.phase, Some(Phase::Executing(_))),
        "field publication is one-shot"
    );
    let Some(Phase::Executing(block)) = self.phase.take() else {
        unreachable!("checked original execution phase")
    };
    // Only an inert original-owner move occurs outside caller custody.
    self.phase = Some(Phase::Publishing(block.into_publication()));
    let Some(Phase::Publishing(slot)) = self.phase.as_mut() else {
        unreachable!("original publication phase")
    };
    slot.prepare_publication();
}

pub(crate) fn publish_prepared(&mut self) {
    assert!(!self.released, "field was terminally released");
    let Some(Phase::Publishing(slot)) = self.phase.as_mut() else {
        panic!("original field was not prepared")
    };
    slot.publish_prepared();
}

fn deref(&self) -> &B {
    assert!(!self.released, "field was terminally released");
    match self.phase.as_ref() {
        Some(Phase::Executing(block)) => block,
        _ => panic!("publication field has no execution authority"),
    }
}

fn deref_mut(&mut self) -> &mut B {
    assert!(!self.released, "field was terminally released");
    match self.phase.as_mut() {
        Some(Phase::Executing(block)) => block,
        _ => panic!("publication field has no execution authority"),
    }
}

fn release_writers(&mut self) {
    self.released = true;
    match self.phase.as_mut() {
        Some(Phase::Executing(block)) => block.release_writers(),
        Some(Phase::Publishing(slot)) => slot.release_writers(),
        None => {}
    }
}

fn json_serialize_to(
    &self,
    out: &mut dyn json::JsonWriteSink,
) -> Result<(), json::BoundedJsonError> {
    self.deref().json_serialize_to(out)
}

pub(crate) fn assert_executing(&self) {
    assert_eq!(*self, Self::Executing, "aggregate no longer executes");
}

pub(crate) fn begin_preparation(&mut self) {
    self.assert_executing();
    *self = Self::Preparing;
}

pub(crate) fn finish_preparation(&mut self) {
    assert_eq!(*self, Self::Preparing);
    *self = Self::Prepared;
}

pub(crate) fn begin_publication(&mut self) {
    assert_eq!(
        *self,
        Self::Prepared,
        "all original fields must prepare before any publishes"
    );
    *self = Self::Publishing;
}

pub(crate) fn finish_publication(&mut self) {
    assert_eq!(*self, Self::Publishing);
    *self = Self::Published;
}

enum Phase<'a> {
    Executing(BlockHashesBlock<'a>),
    Acquired(Acquired<'a>),
    Preparing(Preparing<'a>),
    Published(Published<'a>),
    Abandoned {
        _work: Abandoned,
        _reader: Option<DeferredRelease>,
        _writer: DeferredRelease,
    },
    Rejected {
        _work: BlockHashWork,
        _writer: DeferredRelease,
    },
    Retired {
        _work: Retired,
        _writer: DeferredRelease,
    },
}

pub(crate) fn new(block: BlockHashesBlock<'a>) -> Self {
    Self {
        target: block.inner,
        phase: Some(Phase::Executing(block)),
        height: 0,
        attempted: false,
        released: false,
    }
}

pub(crate) fn into_executing(mut self) -> BlockHashesBlock<'a> {
    self.executing();
    match self.phase.take() {
        Some(Phase::Executing(block)) => block,
        _ => unreachable!("checked original hash execution"),
    }
}

fn executing(&self) -> &BlockHashesBlock<'a> {
    assert!(
        !self.attempted && !self.released,
        "hash execution authority ended"
    );
    match self.phase.as_ref() {
        Some(Phase::Executing(block)) => block,
        _ => unreachable!("original hash execution phase"),
    }
}

pub(crate) fn try_prepare_publication(
    &mut self,
) -> Result<(), mv::PublicationPreparationError<std::convert::Infallible>> {
    self.executing();
    self.attempted = true;
    let Some(Phase::Executing(block)) = self.phase.as_ref() else {
        unreachable!()
    };
    if block.reserved_tip.is_some() {
        return Err(mv::PublicationPreparationError::Changed);
    }
    let Some(map) = self.target.map() else {
        return Err(mv::PublicationPreparationError::Changed);
    };
    // This validates cursor operability before its original owner is moved.
    // No edit occurs between this check and native acquisition.
    self.height = block.len();
    // No advisory reader acquisition: exact family/base validation happens
    // under the original writer, then reader custody stays in this slot.
    let Some(Phase::Executing(block)) = self.phase.take() else {
        unreachable!()
    };
    let BlockHashesBlock {
        inner,
        work,
        mode,
        visible_len,
        reserved_tip,
        fixture_edits,
    } = block;
    let wait = self.target.released.observe();
    let acquired = match map.try_acquire_owned(work) {
        Ok(acquired) => self.target.released.poisoning_guard(acquired),
        Err((work, error)) => {
            self.phase = Some(Phase::Executing(BlockHashesBlock {
                inner,
                work,
                mode,
                visible_len,
                reserved_tip,
                fixture_edits,
            }));
            return Err(Self::refusal(error, wait));
        }
    };
    // Install the actual acquired writer before inspecting predecessor state.
    self.phase = Some(Phase::Acquired(acquired));
    let Some(Phase::Acquired(acquired)) = self.phase.take() else {
        unreachable!()
    };
    // Native validation checks only poison and pointer identity, then makes
    // inert moves. It neither allocates nor invokes cursor/user code.
    let writer = match acquired.try_map_preserving_release(|a| a.validate()) {
        Ok(writer) => writer,
        Err((acquired, error)) => {
            self.phase = Some(Phase::Acquired(acquired));
            return Err(Self::refusal(error, wait));
        }
    };
    self.phase = Some(Phase::Preparing(
        writer.map_preserving_release(|w| w.commit_slot()),
    ));
    let Some(Phase::Preparing(slot)) = self.phase.as_mut() else {
        unreachable!()
    };
    let wait = map.observe_reader_release();
    // Reader acquisition and cursor validation can unwind. Their exact
    // originals stay in this field throughout that borrowed operation.
    slot.try_prepare()
        .map_err(|error| Self::refusal(error, wait))
}

fn refusal(
    error: OwnedWriteError,
    wait: concread::release::ReleaseWait,
) -> mv::PublicationPreparationError<std::convert::Infallible> {
    match error {
        OwnedWriteError::Changed => mv::PublicationPreparationError::Changed,
        OwnedWriteError::Poisoned => mv::PublicationPreparationError::Poisoned,
        OwnedWriteError::Busy => {
            mv::PublicationPreparationError::after_failed_acquisition(wait)
        }
    }
}

pub(crate) fn publish_prepared(&mut self) {
    assert!(!self.released, "hash field was terminally released");
    assert!(
        matches!(self.phase.as_ref(), Some(Phase::Preparing(slot)) if slot.is_prepared()),
        "original hash preparation must complete"
    );
    let Some(Phase::Preparing(slot)) = self.phase.take() else {
        unreachable!()
    };
    // Checked native publication moves the existing prepaid shell; no
    // allocation, callback, fallible work or payload destruction occurs.
    self.phase = Some(Phase::Published(
        slot.map_preserving_release(|s| s.into_prepared().publish()),
    ));
    self.target
        .committed_height
        .store(self.height, Ordering::Release);
    // Live post-publication cache work may read this map. Unlock now while
    // retaining every original retirement and notification in this field.
    mv::BlockRetirement::release_writers(self);
}

fn deref_mut(&mut self) -> &mut Self::Target {
    self.executing();
    match self.phase.as_mut() {
        Some(Phase::Executing(block)) => block,
        _ => unreachable!(),
    }
}

fn release_writers(&mut self) {
    self.released = true;
    self.phase = match self.phase.take() {
        Some(Phase::Acquired(acquired)) => {
            let (work, writer) = acquired.release_deferred(|a| a.abort());
            Some(Phase::Rejected {
                _work: work,
                _writer: writer,
            })
        }
        Some(Phase::Preparing(slot)) => {
            let ((work, reader), writer) = slot.release_deferred(|s| {
                let (writer, reader) = s.abort_retaining();
                (writer.abort_retaining(), reader)
            });
            Some(Phase::Abandoned {
                _work: work,
                _reader: reader,
                _writer: writer,
            })
        }
        Some(Phase::Published(published)) => {
            let (work, writer) = published.release_deferred(|p| p.release());
            Some(Phase::Retired {
                _work: work,
                _writer: writer,
            })
        }
        other => other,
    };
}

pub(crate) struct DeferredPublicationFence<'state, T> {
    mutex: &'state PublicationMutex<T>,
    releases: concread::release::DeferredReleaseBatch,
}

pub(crate) struct DeferredPublicationGuard<'fence, 'state, T> {
    guard: Option<PublicationGuard<'state, T>>,
    releases: &'fence mut concread::release::DeferredReleaseBatch,
}

pub(crate) fn lock(&mut self) -> DeferredPublicationGuard<'_, 'state, T> {
    DeferredPublicationGuard {
        guard: Some(self.mutex.lock()),
        releases: &mut self.releases,
    }
}

fn drop(&mut self) {
    if let Some(guard) = self.guard.take() {
        // Both fields are private and created together by defer_notifications.
        // The source cannot change between acquisition and physical release.
        assert!(
            guard.try_release_into(self.releases).is_ok(),
            "original fence release source"
        );
    }
}

pub(crate) fn defer_notifications(&self) -> DeferredPublicationFence<'_, T> {
    DeferredPublicationFence {
        mutex: self,
        releases: self.deferred_releases(),
    }
}

pub fn commit(mut self) {
    self.prepare_publication();
    self.publish_prepared();
}

pub fn commit_world_overlay_for_testing(self) -> Result<(), TransactionsBlockError> {
    let mut publication_notice = self.state_ref.state_view_publication();
    let mut commit_fence = self.state_ref.state_commit_lock.defer_notifications();
    let mut write_fence = self.state_write_lock.defer_notifications();
    let mut this = self;
    if this.transactions.has_staged_block()
        || this.block_hashes.has_pending()
        || this.commit_topology.is_dirty()
        || this.prev_commit_topology.is_dirty()
        || this.pending_da_commitments.is_some()
        || this.pending_da_pin_intents.is_some()
        || this.pending_autoscale_lifecycle.is_some()
        || this.autoscale_sample_history_dirty
        || this.canonical_runtime.is_dirty()
        || this.staged_merge_entry.is_some()
        || this.native_lane_stage.is_some()
        || !this.staged_queue_plan_admissions.is_empty()
        || this.canonical_wsv_merge_commit_authorization.is_some()
        || this
            .canonical_carrier_commit_metadata_authorization
            .is_some()
        || !this.pending_nexus_fee_receipt_source_ids.is_empty()
        || !this.verified_lane_relay_records.is_empty()
    {
        return Err(TransactionsBlockError::MergeAdmission);
    }
    this.finalize_axt_asset_incarnations()
        .map_err(|_| TransactionsBlockError::AxtAssetIncarnation)?;
    this.finalize_axt_policy_transition_ratchets()
        .map_err(|_| TransactionsBlockError::AxtCounterRatchet)?;
    let current_axt_slot =
        current_axt_slot_from_block(&this._curr_block, this.nexus.axt.slot_length_ms);
    this.prune_axt_replay_ledger(
        current_axt_slot,
        this.nexus.axt.replay_retention_slots.get(),
    );
    let state_ref = this.state_ref;
    let sccp_registry = Arc::clone(&this.sccp_registry);
    let _state_commit_lock = commit_fence.lock();
    let _state_write_lock = write_fence.lock();
    this.world.prepare_publication();
    let _view_generation = publication_notice.begin();
    this.world.publish_prepared();
    state_ref.install_sccp_registry_cache(sccp_registry);
    Ok(())
}

