enum Phase<'a> {
    Original(DetachedBlockHashes),
    Acquired(Acquired<'a>),
    Preparing(Preparing<'a>),
    Abandoned { _work: Abandoned },
}

fn original(&self) -> &DetachedBlockHashes {
    match self.phase.as_ref() {
        Some(Phase::Original(original)) => original,
        _ => panic!("original retained hash phase"),
    }
}

fn refuse<E>(
    &mut self,
    error: mv::PublicationPreparationError<E>,
) -> Result<(), mv::PublicationPreparationError<E>> {
    self.retryable = true;
    Err(error)
}

fn restore(&self, work: BlockHashWork) -> DetachedBlockHashes {
    DetachedBlockHashes {
        work,
        mode: self.mode,
        visible_len: self.visible_len,
        reserved_tip: self.reserved_tip,
    }
}

pub(crate) fn recover_original(&mut self) -> DetachedBlockHashes {
    assert!(
        self.retryable && !self.released,
        "failed/unwound hash is not retry authority"
    );
    self.released = true;
    self.complete = false;
    match self.phase.take().expect("original retained hash") {
        Phase::Original(original) => original,
        Phase::Acquired(acquired) => {
            let (work, release) = acquired.release_deferred(|a| a.abort());
            self.writer_release = Some(release);
            self.restore(work)
        }
        Phase::Preparing(slot) => {
            let ((work, reader), writer) = slot.release_deferred(|slot| {
                let (writer, reader) = slot.abort_retaining();
                (writer.detach(), reader)
            });
            self.reader_release = reader;
            self.writer_release = Some(writer);
            self.restore(work)
        }
        Phase::Abandoned { .. } => unreachable!("terminal cleanup is never a journal"),
    }
}

pub(crate) fn take_prepared(&mut self) -> PreparedBlockHashes<'a, I> {
    assert!(
        self.complete && !self.released,
        "complete original hash preparation"
    );
    let Some(Phase::Preparing(slot)) = self.phase.take() else {
        unreachable!()
    };
    self.complete = false;
    self.released = true;
    PreparedBlockHashes {
        owner: NativeLaneStateOwner(self.target.map().expect("original map").family()),
        prepared: slot.map_preserving_release(|slot| slot.into_prepared()),
        mode: self.mode,
        visible_len: self.visible_len,
        height: self.height,
        committed_height: &self.target.committed_height,
        installation: self.installation.take().expect("original installation"),
        preflight_release: self.preflight_release.take(),
    }
}

pub(crate) fn release_writers(&mut self) {
    self.released = true;
    self.retryable = false;
    self.complete = false;
    self.phase = match self.phase.take() {
        Some(Phase::Acquired(acquired)) => {
            let (work, release) = acquired.release_deferred(|a| a.abort());
            self.writer_release = Some(release);
            Some(Phase::Original(self.restore(work)))
        }
        Some(Phase::Preparing(slot)) => {
            let ((work, reader), writer) = slot.release_deferred(|slot| {
                let (writer, reader) = slot.abort_retaining();
                (writer.abort_retaining(), reader)
            });
            self.reader_release = reader;
            self.writer_release = Some(writer);
            Some(Phase::Abandoned { _work: work })
        }
        phase => phase,
    };
}

pub(super) fn new(
    original: DetachedCarrierComponents,
    target: &'target State,
    fences: CarrierFences<'target>,
) -> Self {
    let DetachedCarrierComponents {
        world,
        runtime,
        transactions,
        block_hashes,
    } = original;
    Self {
        world: Some(world.publication_slot(&target.world, None)),
        runtime: Some(runtime.publication_slot(target)),
        transactions: Some(transactions.publication_slot(&target.transactions)),
        block_hashes: RetainedHashSlot::new(block_hashes, &target.block_hashes),
        effect_locks: Some(crate::state::effect_publication::StateEffectLocks::new(
            target,
        )),
        fences: Some(fences),
        attempted: false,
        retryable: true,
        complete: false,
        released: false,
        retired_fences: None,
    }
}

pub(super) fn try_prepare(&mut self) -> Result<(), CarrierPhysicalPreparationError> {
    assert!(
        !self.attempted && !self.released,
        "carrier preparation is one-shot"
    );
    self.attempted = true;
    self.retryable = false;
    let result = self.prepare_inner();
    self.retryable = true;
    self.complete = result.is_ok();
    result
}

fn release_fences(&mut self) {
    if let Some(fences) = self.fences.take() {
        let CarrierFences {
            _state: state,
            _queue: queue,
            _kura: kura,
        } = fences;
        self.retired_fences = Some(ReleasedCarrierFences {
            _state: state.release_deferred(),
            _queue: queue.map(CarrierQueueRetirement::release_deferred),
            _kura: kura.release_deferred(),
        });
    }
}

pub(super) fn recover_original(&mut self) -> DetachedCarrierComponents {
    assert!(
        self.retryable && !self.released,
        "unwound or released carrier grants no retry authority"
    );
    self.complete = false;
    self.released = true;
    // Normal recovery moves the original journals and retains every release
    // in the installed slots. It invokes no callback or new admission.
    let original = DetachedCarrierComponents {
        world: self
            .world
            .as_mut()
            .expect("original World slot")
            .recover_original(),
        runtime: self
            .runtime
            .as_mut()
            .expect("original runtime slot")
            .recover_original(),
        transactions: self
            .transactions
            .as_mut()
            .expect("original membership slot")
            .recover_original(),
        block_hashes: self.block_hashes.recover_original(),
    };
    self.effect_locks
        .as_mut()
        .expect("original effect locks")
        .release_writers();
    self.release_fences();
    original
}

pub(super) fn into_prepared(mut self) -> AcquiredCarrierComponents<'target> {
    assert!(
        self.complete && !self.released,
        "complete original carrier preparation"
    );
    self.released = true;
    AcquiredCarrierComponents {
        original: Some(AcquiredCarrierParticipants {
            world: self
                .world
                .take()
                .expect("complete original World")
                .into_prepared(),
            runtime: self
                .runtime
                .take()
                .expect("complete original runtime")
                .into_prepared(),
            transactions: self
                .transactions
                .take()
                .expect("complete original membership")
                .into_prepared(),
            block_hashes: self.block_hashes.take_prepared(),
            effect_locks: self.effect_locks.take().expect("prepared effect locks"),
            _fences: self.fences.take().expect("original carrier fences"),
        }),
    }
}

fn drop(&mut self) {
    if let Some(world) = self.world.as_mut() {
        world.release_writers();
    }
    if let Some(runtime) = self.runtime.as_mut() {
        runtime.release_writers();
    }
    if let Some(transactions) = self.transactions.as_mut() {
        transactions.release_writers();
    }
    self.block_hashes.release_writers();
    if let Some(indexes) = self.effect_locks.as_mut() {
        indexes.release_writers();
    }
    self.release_fences();
    // Automatic payload, admission and callback destruction starts only
    // after every original participant and enclosing fence is physically free.
}

pub fn try_matches_current_retaining(
    &self,
    target: &LinCowCell<T, R, U, Charge>,
) -> Result<(bool, Option<crate::release::DeferredRelease>), OwnedWriteError> {
    if !Shared::ptr_eq(&self.root, &target.write) {
        return Ok((false, None));
    }
    let active = target.try_lock_active()?;
    let matches = Shared::ptr_eq(&self.base, &active);
    let ((), release) = active.release_deferred(drop);
    Ok((matches, Some(release)))
}

pub fn try_matches_current(
    &self,
    target: &LinCowCell<T, R, U, Charge>,
) -> Result<bool, OwnedWriteError> {
    let (matches, release) = self.try_matches_current_retaining(target)?;
    drop(release);
    Ok(matches)
}

pub fn try_matches_current_retaining(
    &self,
    target: &BptreeMap<K, V, M>,
) -> Result<(bool, Option<crate::release::DeferredRelease>), OwnedWriteError> {
    self.inner.try_matches_current_retaining(&target.inner)
}

fn original(&self) -> &DetachedTransactionsBlock {
    match self.phase.as_ref() {
        Some(Phase::Original(original)) => original,
        _ => panic!("original detached membership phase"),
    }
}

fn refuse<E>(
    &mut self,
    error: PublicationPreparationError<E>,
) -> Result<(), PublicationPreparationError<E>> {
    self.retryable = true;
    Err(error)
}

pub(crate) fn try_prepare<E>(
    &mut self,
    admit: impl FnOnce(&DetachedTransactionsBlock, &TransactionsStorage) -> Result<Installation, E>,
) -> Result<(), PublicationPreparationError<E>> {
    assert!(
        !self.attempted && !self.released,
        "detached membership preparation is one-shot"
    );
    self.attempted = true;
    // A caught admission panic never grants retry authority.
    self.retryable = false;
    let target = self.target;
    let wait = target.released.observe();
    let Some(guard) = target.write_lock.try_lock() else {
        return self.refuse(PublicationPreparationError::after_failed_acquisition(wait));
    };
    self.writer = Some(MembershipWriter::new(target.released.guard(guard), None));
    let current = Identity::ptr_eq(
        self.writer
            .as_ref()
            .expect("original observation writer")
            .identity(),
        &self.original().predecessor_identity,
    );
    // Unlock without notifying. Keep the actual event before admission can
    // run arbitrary code, refuse, or unwind through the enclosing owner.
    self.preflight_release = Some(
        self.writer
            .take()
            .expect("original observation writer")
            .into_writer_release(),
    );
    if !current {
        return self.refuse(PublicationPreparationError::Changed);
    }
    let installation = match admit(self.original(), target) {
        Ok(installation) => installation,
        Err(error) => return self.refuse(PublicationPreparationError::Admission(error)),
    };
    self.installation = Some(installation);
    let wait = target.released.observe();
    let Some(guard) = target.write_lock.try_lock() else {
        return self.refuse(PublicationPreparationError::after_failed_acquisition(wait));
    };
    // Install the actual final acquisition before checking its predecessor.
    self.writer = Some(MembershipWriter::new(target.released.guard(guard), None));
    if !Identity::ptr_eq(
        self.writer
            .as_ref()
            .expect("original publication writer")
            .identity(),
        &self.original().predecessor_identity,
    ) {
        return self.refuse(PublicationPreparationError::Changed);
    }
    // All checks precede extraction. These moves reuse the admitted action,
    // immutable payload and next identity; no new admission or allocation.
    let Some(Phase::Original(original)) = self.phase.take() else {
        unreachable!("checked original membership phase");
    };
    let DetachedTransactionsBlock {
        predecessor_identity: _,
        predecessor: _,
        history,
        current,
        revert,
        publication,
        next_identity,
    } = original;
    let baseline = target
        .blocks
        .read_predecessor(history.baseline.as_ref().expect("original history cut"))
        .expect("checked original history family");
    self.writer
        .as_mut()
        .expect("original membership writer")
        .history = Some(history_slot::Slot::new(target, history));
    self.phase = Some(Phase::Prepared(PreparedTransactionsBlock::new(
        TransactionsBlock {
            latest_block_ref: &target.latest_block,
            budget_ref: &target.budget,
            blocks_ref: &target.blocks,
            baseline,
            publication_sequence: &target.publication_sequence,
            _guard: self
                .writer
                .take()
                .expect("checked original publication writer"),
            revert,
            current_block: Some(current),
        },
        publication,
        next_identity,
    )));
    // The complete original block is back in the caller-owned phase before
    // the native tree acquires any physical publication lock.
    let Some(Phase::Prepared(prepared)) = self.phase.as_mut() else {
        unreachable!()
    };
    if !matches!(&prepared.publication, MembershipPublication::Repeated) {
        if let Err(error) = prepared
            .block
            ._guard
            .history
            .as_mut()
            .expect("original history")
            .prepare()
        {
            let refusal = match error {
                MembershipAdmissionError::Busy(wait) => PublicationPreparationError::Busy(wait),
                MembershipAdmissionError::Changed(_) => PublicationPreparationError::Changed,
                MembershipAdmissionError::Poisoned => PublicationPreparationError::Poisoned,
                _ => unreachable!("native reattachment performs no allocation admission"),
            };
            return self.refuse(refusal);
        }
    }
    self.complete = true;
    self.retryable = true;
    Ok(())
}

pub(crate) fn recover_original(&mut self) -> DetachedTransactionsBlock {
    assert!(
        self.retryable && !self.released,
        "unwound or released membership is not retry authority"
    );
    if let Some(Phase::Prepared(prepared)) = self.phase.as_ref() {
        prepared.assert_unpublished();
    }
    self.released = true;
    self.complete = false;
    if let Some(writer) = self.writer.take() {
        self.writer_release = Some(writer.into_release());
    }
    match self.phase.take().expect("original membership journal") {
        Phase::Original(original) => original,
        Phase::Prepared(prepared) => {
            let (original, release) = prepared.detach_retaining();
            self.writer_release = Some(release);
            original
        }
    }
}

pub(crate) fn release_writers(&mut self) {
    self.released = true;
    self.retryable = false;
    self.complete = false;
    if let Some(writer) = self.writer.take() {
        self.writer_release = Some(writer.into_release());
    }
    if let Some(Phase::Prepared(prepared)) = self.phase.as_mut() {
        prepared.block.release_writers();
    }
}

pub(crate) fn into_prepared(
    mut self,
) -> PreparedDetachedTransactionsBlock<'storage, Installation> {
    assert!(
        self.complete && !self.released,
        "complete original membership preparation"
    );
    let Some(Phase::Prepared(prepared)) = self.phase.take() else {
        unreachable!("checked prepared membership phase");
    };
    self.released = true;
    PreparedDetachedTransactionsBlock {
        prepared,
        installation: self.installation.take().expect("original installation"),
        preflight_release: self.preflight_release.take(),
    }
}

pub(super) fn into_cleanup(mut self) -> AbortedTransactions<Installation> {
    assert!(
        self.released && self.phase.is_none(),
        "original membership was recovered"
    );
    AbortedTransactions {
        _installation: self.installation.take(),
        _preflight_release: self.preflight_release.take(),
        _release: self.writer_release.take(),
    }
}

pub(crate) struct PreparedDetachedTransactionsBlock<'storage, Installation> {
    prepared: PreparedTransactionsBlock<'storage>,
    installation: Installation,
    preflight_release: Option<concread::release::DeferredRelease>,
}

pub(crate) fn abort(
    self,
) -> (DetachedTransactionsBlock, AbortedTransactions<Installation>) {
    let Self {
        prepared,
        installation,
        preflight_release,
    } = self;
    let (journal, release) = prepared.detach_retaining();
    (
        journal,
        AbortedTransactions {
            _release: Some(release),
            _installation: Some(installation),
            _preflight_release: preflight_release,
        },
    )
}

pub fn publication_slot<'target, Installation>(
    self,
    target: &'target Cell<V, Charge>,
) -> DetachedPublicationSlot<'target, V, Admission, Installation, Charge> {
    DetachedPublicationSlot::new(self, target)
}

pub fn try_prepare_publication<'target, Installation, E>(
    self,
    target: &'target Cell<V, Charge>,
    admit: impl FnOnce(&Self, &Cell<V, Charge>) -> Result<Installation, E>,
) -> PublicationPreparationResult<
    PreparedPublication<'target, V, Admission, Installation, Charge>,
    Self,
    E,
    Installation,
> {
    let mut slot = self.publication_slot(target);
    match slot.try_prepare(admit) {
        Ok(()) => Ok(slot.into_prepared()),
        Err(error) => {
            let original = slot.recover_original();
            Err((original, error, slot.into_cleanup()))
        }
    }
}

pub fn publication_slot<'target, Installation>(
    self,
    target: &'target Storage<K, V>,
) -> DetachedPublicationSlot<'target, K, V, Admission, Installation> {
    DetachedPublicationSlot {
        inner: DetachedPublicationSlotInner::new(self, target),
    }
}

fn prepare_publication<'target, Installation, E>(
    self,
    target: &'target Storage<K, V, M>,
    admit: impl FnOnce(&Self, &Storage<K, V, M>) -> Result<Installation, E>,
) -> PublicationPreparationResult<
    PreparedPublication<'target, K, V, Admission, Installation, M>,
    Self,
    E,
    Installation,
> {
    let mut slot = DetachedPublicationSlotInner::new(self, target);
    match slot.try_prepare(admit) {
        Ok(()) => Ok(slot.into_prepared()),
        Err(error) => {
            let original = slot.recover_original();
            Err((original, error, slot.into_cleanup()))
        }
    }
}

enum Role<'a, V: Value, C: Send + Sync + 'static> {
    Owned(EbrCellOwned<V, C>),
    Acquired(
        ReleaseGuard<'a, EbrCellWriterAcquisition<'a, V, C>>,
        EbrCellOwned<V, C>,
    ),
    Writer(CellWriter<'a, V, C>),
    Empty,
}

enum Phase<'a, V: Value, A, I, C: Send + Sync + 'static> {
    Original(Detached<V, A, C>),
    Acquiring {
        revert: Role<'a, Option<V>, C>,
        blocks: Role<'a, V, C>,
        metadata: DetachedMetadata<A>,
    },
    Prepared(PreparedPublication<'a, V, A, I, C>),
    Empty,
}

fn acquire<E>(
    &mut self,
    target: &'a EbrCell<V, C>,
    released: &'a ReleaseNotification,
    batch: &mut DeferredReleaseBatch,
) -> Result<(), PublicationPreparationError<E>> {
    assert!(
        matches!(self, Self::Owned(_)),
        "original unattached generation"
    );
    let wait = released.observe();
    let Some(raw) = target.try_acquire_writer() else {
        return Err(PublicationPreparationError::after_failed_acquisition(wait));
    };
    let Self::Owned(owned) = std::mem::replace(self, Self::Empty) else {
        unreachable!()
    };
    *self = Self::Acquired(released.poisoning_guard(raw), owned);
    let Self::Acquired(raw, _) = self else {
        unreachable!()
    };
    if raw.is_poisoned() {
        return Err(PublicationPreparationError::Poisoned);
    }
    // Native attach performs poison checking and inert moves only. The raw
    // owner is already installed before the check; no clone or callback runs.
    let Self::Acquired(raw, owned) = std::mem::replace(self, Self::Empty) else {
        unreachable!()
    };
    match raw
        .try_map_preserving_release_into(
            batch,
            |raw| raw.try_write_owned(owned),
            || target.is_poisoned(),
        )
        .unwrap_or_else(|_| unreachable!("original cell acquisition release source"))
    {
        Ok(writer) => {
            *self = Self::Writer(writer);
            Ok(())
        }
        Err((raw, owned)) => {
            *self = Self::Acquired(raw, owned);
            Err(PublicationPreparationError::Poisoned)
        }
    }
}

fn release(&mut self, target: &EbrCell<V, C>, batch: &mut DeferredReleaseBatch) {
    let owned = match std::mem::replace(self, Self::Empty) {
        Self::Acquired(raw, owned) => {
            raw.try_release_into_observed(batch, drop, || target.is_poisoned())
                .unwrap_or_else(|_| unreachable!("original acquisition release source"));
            owned
        }
        Self::Writer(writer) => writer
            .try_release_into_observed(batch, |writer| writer.detach(), || target.is_poisoned())
            .unwrap_or_else(|_| unreachable!("original writer release source")),
        other => {
            *self = other;
            return;
        }
    };
    *self = Self::Owned(owned);
}

fn into_owned(
    mut self,
    target: &EbrCell<V, C>,
    batch: &mut DeferredReleaseBatch,
) -> EbrCellOwned<V, C> {
    self.release(target, batch);
    let Self::Owned(owned) = self else {
        panic!("original detached generation")
    };
    owned
}

fn into_writer(self) -> CellWriter<'a, V, C> {
    let Self::Writer(writer) = self else {
        panic!("original acquired generation")
    };
    writer
}

pub(super) fn new(original: Detached<V, A, C>, target: &'a Cell<V, C>) -> Self {
    let mut cleanup = PublicationCleanup::empty();
    cleanup.writer_batches = [
        Some(target.blocks_released.deferred_batch()),
        Some(target.revert_released.deferred_batch()),
    ];
    Self {
        target,
        phase: Phase::Original(original),
        attempted: false,
        complete: false,
        retryable: true,
        released: false,
        cleanup,
    }
}

pub fn try_prepare<E>(
    &mut self,
    admit: impl FnOnce(&Detached<V, A, C>, &Cell<V, C>) -> Result<I, E>,
) -> Result<(), PublicationPreparationError<E>> {
    assert!(
        !self.attempted && !self.released,
        "original preparation is one-shot"
    );
    self.attempted = true;
    self.retryable = false;
    let result = self.prepare_inner(admit);
    // This is intentionally after the callee: unwind cannot grant retry.
    self.retryable = true;
    self.complete = result.is_ok();
    result
}

fn prepare_inner<E>(
    &mut self,
    admit: impl FnOnce(&Detached<V, A, C>, &Cell<V, C>) -> Result<I, E>,
) -> Result<(), PublicationPreparationError<E>> {
    let Phase::Original(original) = &self.phase else {
        panic!("original journal before preparation")
    };
    let (checked, probe) = original
        .metadata
        .predecessor
        .try_check_current(&self.target.publication);
    self.cleanup.identities[0] = probe;
    checked?;
    self.cleanup.installation =
        Some(admit(original, self.target).map_err(PublicationPreparationError::Admission)?);
    let Phase::Original(Detached {
        revert,
        blocks,
        metadata,
    }) = std::mem::replace(&mut self.phase, Phase::Empty)
    else {
        unreachable!()
    };
    self.phase = Phase::Acquiring {
        revert: Role::Owned(revert),
        blocks: Role::Owned(blocks),
        metadata,
    };
    let Phase::Acquiring { revert, blocks, .. } = &mut self.phase else {
        unreachable!()
    };
    revert.acquire(
        &self.target.revert,
        &self.target.revert_released,
        self.cleanup.writer_batches[1]
            .as_mut()
            .expect("original undo release"),
    )?;
    blocks.acquire(
        &self.target.blocks,
        &self.target.blocks_released,
        self.cleanup.writer_batches[0]
            .as_mut()
            .expect("original current release"),
    )?;
    let Phase::Acquiring {
        revert,
        blocks,
        metadata,
    } = std::mem::replace(&mut self.phase, Phase::Empty)
    else {
        unreachable!()
    };
    self.phase = Phase::Prepared(PreparedPublication {
        writers: PreparedCellWriters::new(
            revert.into_writer(),
            blocks.into_writer(),
            self.cleanup.identities[0].take(),
        ),
        metadata,
        installation: self
            .cleanup
            .installation
            .take()
            .expect("original installation"),
    });
    let Phase::Prepared(prepared) = &mut self.phase else {
        unreachable!()
    };
    prepared.writers.prepare(
        self.target,
        &prepared.metadata.predecessor,
        prepared.metadata.dirty,
    )
}

pub fn release_writers(&mut self) {
    if self.released {
        return;
    }
    self.released = true;
    self.retryable = false;
    self.complete = false;
    match &mut self.phase {
        Phase::Acquiring { revert, blocks, .. } => {
            blocks.release(
                &self.target.blocks,
                self.cleanup.writer_batches[0]
                    .as_mut()
                    .expect("original current release"),
            );
            revert.release(
                &self.target.revert,
                self.cleanup.writer_batches[1]
                    .as_mut()
                    .expect("original undo release"),
            );
        }
        Phase::Prepared(prepared) => prepared.writers.release(),
        _ => {}
    }
}

pub fn recover_original(&mut self) -> Detached<V, A, C> {
    assert!(
        self.retryable && !self.released,
        "unwound/released preparation grants no journal"
    );
    self.released = true;
    self.complete = false;
    match std::mem::replace(&mut self.phase, Phase::Empty) {
        Phase::Original(original) => original,
        Phase::Acquiring {
            revert,
            blocks,
            metadata,
        } => Detached {
            blocks: blocks.into_owned(
                &self.target.blocks,
                self.cleanup.writer_batches[0]
                    .as_mut()
                    .expect("original current release"),
            ),
            revert: revert.into_owned(
                &self.target.revert,
                self.cleanup.writer_batches[1]
                    .as_mut()
                    .expect("original undo release"),
            ),
            metadata,
        },
        Phase::Prepared(prepared) => {
            let (original, cleanup) = prepared.abort();
            self.cleanup = cleanup; // only inactive partial-acquisition batches remain here
            original
        }
        Phase::Empty => panic!("original journal already transferred"),
    }
}

pub fn into_prepared(mut self) -> PreparedPublication<'a, V, A, I, C> {
    assert!(
        self.complete && !self.released,
        "complete original pair required"
    );
    self.released = true;
    let Phase::Prepared(prepared) = std::mem::replace(&mut self.phase, Phase::Empty) else {
        unreachable!()
    };
    prepared
}

pub fn into_cleanup(mut self) -> PublicationCleanup<I> {
    assert!(
        self.retryable && self.released && matches!(self.phase, Phase::Empty),
        "original journal must first be recovered"
    );
    std::mem::replace(&mut self.cleanup, PublicationCleanup::empty())
}

enum Role<'a, K: Key, V: Value, M: MapMode + NodeCloning<K, V>> {
    Owned(BptreeMapOwned<K, V, M>),
    Acquired(ReleaseGuard<'a, BptreeMapOwnedAcquisition<'a, K, V, M>>),
    Writer(ReleaseGuard<'a, BptreeMapWriteTxn<'a, K, V, M>>),
    Abandoned {
        _original: BptreeMapAbandonment<K, V, M>,
    },
    Empty,
}

enum Phase<'a, K: Key, V: Value, A, I, M: StorageMode<K, V>> {
    Original(Detached<K, V, A, M>),
    Acquiring {
        revert: Role<'a, K, Option<V>, M>,
        blocks: Role<'a, K, V, M>,
        metadata: DetachedMetadata<A>,
    },
    Prepared(PreparedPublication<'a, K, V, A, I, M>),
    Empty,
}

fn acquire<E>(
    &mut self,
    target: &'a BptreeMap<K, V, M>,
    released: &'a ReleaseNotification,
    batch: &mut DeferredReleaseBatch,
) -> Result<(), PublicationPreparationError<E>> {
    assert!(matches!(self, Self::Owned(_)), "original unattached map");
    let wait = released.observe();
    let Self::Owned(owned) = std::mem::replace(self, Self::Empty) else {
        unreachable!()
    };
    // Root comparison and native mutex acquisition contain no user callback,
    // payload destruction or allocation. Refusal returns the exact owner.
    let acquired = match target.try_acquire_owned(owned) {
        Ok(acquired) => released.poisoning_guard(acquired),
        Err((owned, error)) => {
            *self = Self::Owned(owned);
            return Err(refusal(error, wait));
        }
    };
    *self = Self::Acquired(acquired);
    let Self::Acquired(acquired) = std::mem::replace(self, Self::Empty) else {
        unreachable!()
    };
    // Original phase is installed before native poison/base validation; the
    // same-source batch also owns any actual transition-unwind notification.
    let result = acquired
        .try_map_preserving_release_into(
            batch,
            |acquired| acquired.validate(),
            || target.is_poisoned(),
        )
        .unwrap_or_else(|_| unreachable!("original map acquisition release source"));
    match result {
        Ok(writer) => {
            *self = Self::Writer(writer);
            Ok(())
        }
        Err((acquired, error)) => {
            *self = Self::Acquired(acquired);
            Err(refusal(error, wait))
        }
    }
}

fn release(&mut self, target: &BptreeMap<K, V, M>, batch: &mut DeferredReleaseBatch) {
    *self = match std::mem::replace(self, Self::Empty) {
        Self::Acquired(acquired) => Self::Owned(
            acquired
                .try_release_into_observed(batch, |a| a.abort(), || target.is_poisoned())
                .unwrap_or_else(|_| unreachable!("original acquired map release source")),
        ),
        Self::Writer(writer) => Self::Abandoned {
            _original: writer
                .try_release_into_observed(
                    batch,
                    |w| w.abort_retaining(),
                    || target.is_poisoned(),
                )
                .unwrap_or_else(|_| unreachable!("original map writer release source")),
        },
        other => other,
    };
}

fn into_owned(
    self,
    target: &BptreeMap<K, V, M>,
    batch: &mut DeferredReleaseBatch,
) -> BptreeMapOwned<K, V, M> {
    match self {
        Self::Owned(original) => original,
        Self::Acquired(acquired) => acquired
            .try_release_into_observed(batch, |a| a.abort(), || target.is_poisoned())
            .unwrap_or_else(|_| unreachable!("original acquired map release source")),
        Self::Writer(writer) => writer
            .try_release_into_observed(batch, |w| w.detach(), || target.is_poisoned())
            .unwrap_or_else(|_| unreachable!("original map writer release source")),
        _ => panic!("terminal map abandonment is not a journal"),
    }
}

fn into_writer(self) -> ReleaseGuard<'a, BptreeMapWriteTxn<'a, K, V, M>> {
    let Self::Writer(writer) = self else {
        panic!("original acquired map")
    };
    writer
}

pub(super) fn new(original: Detached<K, V, A, M>, target: &'a Storage<K, V, M>) -> Self {
    let mut cleanup = PublicationCleanup::empty();
    cleanup.writer_batches = [
        Some(target.blocks_released.deferred_batch()),
        Some(target.revert_released.deferred_batch()),
    ];
    Self {
        target,
        phase: Phase::Original(original),
        attempted: false,
        complete: false,
        retryable: true,
        released: false,
        cleanup,
    }
}

pub(super) fn try_prepare<E>(
    &mut self,
    admit: impl FnOnce(&Detached<K, V, A, M>, &Storage<K, V, M>) -> Result<I, E>,
) -> Result<(), PublicationPreparationError<E>> {
    assert!(
        !self.attempted && !self.released,
        "original preparation is one-shot"
    );
    self.attempted = true;
    self.retryable = false;
    let result = self.prepare_inner(admit);
    self.retryable = true; // a caught callee panic never reaches this assignment
    self.complete = result.is_ok();
    result
}

fn prepare_inner<E>(
    &mut self,
    admit: impl FnOnce(&Detached<K, V, A, M>, &Storage<K, V, M>) -> Result<I, E>,
) -> Result<(), PublicationPreparationError<E>> {
    let Phase::Original(original) = &self.phase else {
        panic!("original journal before preparation")
    };
    let (checked, probe) = original
        .metadata
        .predecessor
        .try_check_current(&self.target.publication);
    self.cleanup.identities[0] = probe;
    checked?;
    self.cleanup.installation =
        Some(admit(original, self.target).map_err(PublicationPreparationError::Admission)?);
    let Phase::Original(Detached {
        revert,
        blocks,
        metadata,
    }) = std::mem::replace(&mut self.phase, Phase::Empty)
    else {
        unreachable!()
    };
    self.phase = Phase::Acquiring {
        revert: Role::Owned(revert),
        blocks: Role::Owned(blocks),
        metadata,
    };
    let Phase::Acquiring { revert, blocks, .. } = &mut self.phase else {
        unreachable!()
    };
    revert.acquire(
        &self.target.revert,
        &self.target.revert_released,
        self.cleanup.writer_batches[1]
            .as_mut()
            .expect("original undo release"),
    )?;
    blocks.acquire(
        &self.target.blocks,
        &self.target.blocks_released,
        self.cleanup.writer_batches[0]
            .as_mut()
            .expect("original current release"),
    )?;
    let Phase::Acquiring {
        revert,
        blocks,
        metadata,
    } = std::mem::replace(&mut self.phase, Phase::Empty)
    else {
        unreachable!()
    };
    self.phase = Phase::Prepared(PreparedPublication {
        writers: PreparedStorageWriters::new(
            StorageWriters::new(self.target, revert.into_writer(), blocks.into_writer()),
            self.cleanup.identities[0].take(),
        ),
        metadata,
        installation: self
            .cleanup
            .installation
            .take()
            .expect("original installation"),
    });
    let Phase::Prepared(prepared) = &mut self.phase else {
        unreachable!()
    };
    prepared
        .writers
        .prepare(&prepared.metadata.predecessor, prepared.metadata.dirty)
}

pub(super) fn release_writers(&mut self) {
    if self.released {
        return;
    }
    self.released = true;
    self.retryable = false;
    self.complete = false;
    match &mut self.phase {
        Phase::Acquiring { revert, blocks, .. } => {
            blocks.release(
                &self.target.blocks,
                self.cleanup.writer_batches[0]
                    .as_mut()
                    .expect("original current release"),
            );
            revert.release(
                &self.target.revert,
                self.cleanup.writer_batches[1]
                    .as_mut()
                    .expect("original undo release"),
            );
        }
        Phase::Prepared(prepared) => prepared.writers.release(),
        _ => {}
    }
}

pub(super) fn recover_original(&mut self) -> Detached<K, V, A, M> {
    assert!(
        self.retryable && !self.released,
        "unwound/released preparation grants no journal"
    );
    self.released = true;
    self.complete = false;
    match std::mem::replace(&mut self.phase, Phase::Empty) {
        Phase::Original(original) => original,
        Phase::Acquiring {
            revert,
            blocks,
            metadata,
        } => Detached {
            blocks: blocks.into_owned(
                &self.target.blocks,
                self.cleanup.writer_batches[0]
                    .as_mut()
                    .expect("original current release"),
            ),
            revert: revert.into_owned(
                &self.target.revert,
                self.cleanup.writer_batches[1]
                    .as_mut()
                    .expect("original undo release"),
            ),
            metadata,
        },
        Phase::Prepared(prepared) => {
            let (original, cleanup) = prepared.abort();
            self.cleanup = cleanup;
            original
        }
        Phase::Empty => panic!("original journal already transferred"),
    }
}

pub(super) fn into_prepared(mut self) -> PreparedPublication<'a, K, V, A, I, M> {
    assert!(
        self.complete && !self.released,
        "complete original pair required"
    );
    self.released = true;
    let Phase::Prepared(prepared) = std::mem::replace(&mut self.phase, Phase::Empty) else {
        unreachable!()
    };
    prepared
}

pub(super) fn into_cleanup(mut self) -> PublicationCleanup<I> {
    assert!(
        self.retryable && self.released && matches!(self.phase, Phase::Empty),
        "original journal must first be recovered"
    );
    std::mem::replace(&mut self.cleanup, PublicationCleanup::empty())
}

pub struct DetachedPublicationSlot<'a, K: Key, V: Value, A, I> {
    pub(super) inner: DetachedPublicationSlotInner<'a, K, V, A, I, Untracked>,
}

pub fn try_prepare<E>(
    &mut self,
    admit: impl FnOnce(&Detached<K, V, A>, &Storage<K, V>) -> Result<I, E>,
) -> Result<(), PublicationPreparationError<E>> {
    self.inner.try_prepare(admit)
}

pub fn recover_original(&mut self) -> Detached<K, V, A> {
    self.inner.recover_original()
}

pub fn into_prepared(self) -> PreparedPublication<'a, K, V, A, I> {
    self.inner.into_prepared()
}

pub fn try_prepare(&mut self) -> Result<(), PublicationPreparationError<AdmittedStorageError>> {
    self.inner.try_prepare(|_, _| Ok(()))
}

pub fn recover_original(&mut self) -> Detached<K, V, Admission, Prepaid<P>> {
    self.inner.recover_original()
}

pub fn into_prepared(self) -> AdmittedPreparedPublication<'scope, 'target, K, V, Admission, P> {
    AdmittedPreparedPublication {
        inner: self.inner.into_prepared(),
        _scope: self.scope,
    }
}

fn into_cleanup(self) -> AdmittedAbortedPublication<'scope> {
    AdmittedAbortedPublication {
        _inner: self.inner.into_cleanup(),
        _scope: self.scope,
    }
}

pub fn try_publication_slot<'scope, 'target>(
    self,
    scope: &'scope AllocationScope<'scope>,
    target: &'target Storage<K, V, Prepaid<P>>,
) -> Result<
    AdmittedDetachedPublicationSlot<'scope, 'target, K, V, Admission, P>,
    (Self, PublicationPreparationError<AdmittedStorageError>),
> {
    if !scope.belongs_to(
        target
            .allocation
            .as_ref()
            .expect("admitted Storage original pool"),
    ) {
        return Err((
            self,
            PublicationPreparationError::Admission(AdmittedStorageError::ScopeIdentity),
        ));
    }
    Ok(AdmittedDetachedPublicationSlot {
        inner: DetachedPublicationSlotInner::new(self, target),
        scope,
    })
}

pub fn try_prepare_admitted<'scope, 'target>(
    self,
    scope: &'scope AllocationScope<'scope>,
    target: &'target Storage<K, V, Prepaid<P>>,
) -> Result<
    AdmittedPreparedPublication<'scope, 'target, K, V, Admission, P>,
    (
        Self,
        PublicationPreparationError<AdmittedStorageError>,
        AdmittedAbortedPublication<'scope>,
    ),
> {
    let mut slot = self
        .try_publication_slot(scope, target)
        .map_err(|(original, error)| {
            (
                original,
                error,
                AdmittedAbortedPublication {
                    _inner: PublicationCleanup::empty(),
                    _scope: scope,
                },
            )
        })?;
    match slot.try_prepare() {
        Ok(()) => Ok(slot.into_prepared()),
        Err(error) => {
            let original = slot.recover_original();
            Err((original, error, slot.into_cleanup()))
        }
    }
}

macro_rules! define_runtime_publication_components {
    ($($field:ident: ($($ty:ty),+)),+ $(,)?) => {
        struct AcquiredRuntimeJournals<'target, Admission, Installation> {

            $($field: PreparedPublication<'target, $($ty,)+ (), ()>,)+
            admission: Admission,
            installation: Installation,
        }
        struct RuntimePublicationComponents<'target, Admission> {

            $($field: mv::cell::DetachedPublicationSlot<'target, $($ty,)+ (), ()>,)+
            // Retain the original reservation after every component's cleanup.
            admission: Option<Admission>,
        }
        impl<'target, Admission> RuntimePublicationComponents<'target, Admission> {
            fn new(original: RuntimeJournals<Admission>, target: &'target State) -> Self {
                let RuntimeJournals {  $($field,)+ admission } = original;
                // Every move below is inert: no readiness probe, admission or payload clone.
                Self {  $($field: $field.publication_slot(&target.$field),)+ admission: Some(admission) }
            }
            fn try_prepare<E>(&mut self) -> Result<(), RuntimePublicationError<E>> {
                $(self.$field.try_prepare(|_, _| Ok::<_, Infallible>(()))
                    .map_err(|cause| RuntimePublicationError::Component { field: stringify!($field), cause })?;)+
                Ok(())
            }
            fn release_writers(&mut self) { $(self.$field.release_writers();)+ }
            fn recover_original(&mut self) -> RuntimeJournals<Admission> {
                // Each lower method unlocks and returns its original journal; actual cleanup stays in its slot.
                RuntimeJournals {  $($field: self.$field.recover_original(),)+
                    admission: self.admission.take().expect("original capture admission"), }
            }
            fn into_prepared<Installation>(self, installation: Installation) -> PreparedRuntimeJournals<'target, Admission, Installation> {
                PreparedRuntimeJournals { original: Some(AcquiredRuntimeJournals {
                    $($field: self.$field.into_prepared(),)+
                    admission: self.admission.expect("original capture admission"), installation,
                }) }
            }
            fn into_cleanup(self) -> [Option<mv::PublicationCleanup<()>>; 4] {
                assert!(self.admission.is_none(), "original journals must first be recovered");
                [$(Some(self.$field.into_cleanup()),)+]
            }
        }
    };
}

