) -> Result<
    PreparedRuntimeJournals<'target, Admission, Installation>,
    (
        Self,
        RuntimePublicationError<E>,
        AbortedRuntimeJournals<Installation>,
    ),
> {
    let mut slot = self.publication_slot(target);
    match slot.try_prepare(admit) {
