pub(in crate::state) fn abort(
    self,
) -> (
    DetachedWorld<Admission>,
    AbortedWorld<'target, Installation>,
) {
    let installation;
    let admission;
    let Self {
        mode,
        mut fields,
        mut retry,
        dataspace_catalog,
        external_event_buf,
        admission: retained_admission,
        installation: retained_installation,
    } = self;
    installation = retained_installation;
    admission = retained_admission;
    fields.recover_all();
    retry.extend(fields.iter_mut().map(|field| field.abort()));
    let retirement = AbortedWorld {
        _fields: fields,
        _installation: Some(installation),
    };
    (
        DetachedWorld {
            mode,
            fields: retry,
            dataspace_catalog,
            external_event_buf,
            admission,
        },
        retirement,
    )
}

pub(in crate::state) fn publish(
    self,
) -> (
    DataSpaceCatalog,
    Vec<EventBox>,
    WorldRetirement<'target>,
    Admission,
    Installation,
) {
    let installation;
    let admission;
    let Self {
        mode: _,
        mut fields,
        retry,
        dataspace_catalog,
        external_event_buf,
        admission: retained_admission,
        installation: retained_installation,
    } = self;
    installation = retained_installation;
    admission = retained_admission;
    for field in fields.iter_mut() {
        field.publish();
    }
    let retirement = WorldRetirement {
        _fields: fields.into_inner(),
        _retry: retry,
    };
    (
        dataspace_catalog,
        external_event_buf,
        retirement,
        admission,
        installation,
    )
}

