}

macro_rules! define_indexes {
    ($($field:ident: $ty:ty,)*) => {
        /// Original target locks; constructing the slot acquires nothing.
        pub(in crate::state) struct StateEffectLocks<'state> {
            target: &'state State,
            $(pub(in crate::state) $field: Option<PublicationRwLockWriteGuard<'state, $ty>> ,)*
            pub(in crate::state) sccp_registry_cache: Option<PublicationGuard<'state, SccpRegistryCache>>,
            retired: [concread::release::DeferredReleaseBatch; 12],
            attempted: bool,
            complete: bool,
            retired_manifests: Option<LaneManifestRegistryHandle>,
            retired_privacy: Option<LanePrivacyRegistryHandle>,
            retired_sccp: Option<Arc<ValidatedSccpRegistryV1>>,
        }

        impl<'state> StateEffectLocks<'state> {
            /// Install an inert slot before any sibling starts preparation.
            pub(in crate::state) fn new(target: &'state State) -> Self {
                Self {
                    target,
                    $($field: None,)*
                    sccp_registry_cache: None,
                    retired: [$(target.$field.deferred_releases(),)* target.sccp_registry_cache.deferred_releases()],
                    attempted: false,
                    complete: false,
                    retired_manifests: None,
                    retired_privacy: None,
                    retired_sccp: None,
                }
            }

            /// Retain each acquired original guard before probing its successor.
            /// The returned waiter belongs to the actual reader/writer blocker.
            pub(in crate::state) fn try_prepare(&mut self) -> Result<(), (&'static str, concread::release::ReleaseWait)> {
                assert!(!self.attempted, "effect lock preparation is one-shot");
                self.attempted = true;
                self.prepare_inner()
            }

            fn prepare_inner(&mut self) -> Result<(), (&'static str, concread::release::ReleaseWait)> {
                $(self.$field = Some(self.target.$field.try_write_or_wait()
                    .map_err(|wait| (stringify!($field), wait))?);)*
                self.sccp_registry_cache = Some(self.target.sccp_registry_cache.try_lock_or_wait()
                    .map_err(|wait| ("sccp_registry_cache", wait))?);
                self.complete = true;
                Ok(())
            }

            /// Complete the existing synchronous commit contract before visibility.
            /// Never block while retaining an acquired index prefix: release that
            /// prefix, wait by acquiring only the actual blocking lock, then retry
            /// the full original inventory. Notification cleanup stays retained.
            /// TODO: retire synchronous commit with the funded retained Apply owner.
            pub(in crate::state) fn prepare_blocking(&mut self) {
                assert!(!self.attempted, "effect lock preparation is one-shot");
                self.attempted = true;
                while let Err((field, _wait)) = self.prepare_inner() {
                    self.release_writers();
                    let names = [$(stringify!($field),)* "sccp_registry_cache"];
                    let index = names.iter().position(|name| *name == field).expect("original effect index");
                    match field {
                        $(stringify!($field) => assert!(self.target.$field.write().try_release_into(&mut self.retired[index]).is_ok(), "original effect wait source"),)*
                        "sccp_registry_cache" => assert!(self.target.sccp_registry_cache.lock().try_release_into(&mut self.retired[index]).is_ok(), "original SCCP wait source"),
                        _ => unreachable!("only original effect locks can refuse"),
                    }
                }
            }

            /// Release only physical guards. Every original notification and
            /// displaced registry allocation remains in this owner afterward.
            pub(in crate::state) fn release_writers(&mut self) {
                self.complete = false;
                let mut slots = self.retired.iter_mut();
                $(let retired = slots.next().expect("effect release slot");
                if let Some(guard) = self.$field.take() {
                    assert!(guard.try_release_into(retired).is_ok(), "original effect release source");
                })*
                if let Some(guard) = self.sccp_registry_cache.take() {
                    assert!(guard.try_release_into(slots.next().expect("SCCP release slot")).is_ok(), "original SCCP release source");
                }
            }

            /// Retain the real short preflight read until the enclosing State
            /// cleanup ends, including if validation unwinds. The later writer
            /// coalesces into this same original source batch.
            pub(in crate::state) fn with_merge_admission<R>(&mut self, inspect: impl FnOnce(&MergeAdmissionState) -> R) -> R {
                let names = [$(stringify!($field),)*];
                let index = names.iter().position(|name| *name == "merge_admission").expect("original merge index");
                let read = DeferredIndexRead {
                    guard: Some(self.target.merge_admission.read()),
                    releases: &mut self.retired[index],
                };
                inspect(&read)
            }

            /// Original guards remain owned through the exact registry swap.
            pub(in crate::state) fn install_registries(&mut self, manifests: LaneManifestRegistryHandle, privacy: LanePrivacyRegistryHandle) {
                assert!(self.complete && self.retired_manifests.is_none() && self.retired_privacy.is_none(), "one complete registry publication");
                self.retired_manifests = Some(std::mem::replace(&mut **self.lane_manifests.as_mut().expect("prepared manifests"), manifests));
                self.retired_privacy = Some(std::mem::replace(&mut **self.lane_privacy_registry.as_mut().expect("prepared privacy"), privacy));
            }

            /// Retain the displaced SCCP allocation through all physical fences.
            pub(in crate::state) fn install_sccp(&mut self, registry: Arc<ValidatedSccpRegistryV1>) {
                assert!(self.complete && self.retired_sccp.is_none(), "one complete SCCP publication");
                self.retired_sccp = Some(std::mem::replace(&mut self.sccp_registry_cache.as_mut().expect("prepared SCCP").registry, registry));
            }
        }

        impl Drop for StateEffectLocks<'_> {
            fn drop(&mut self) {
                self.release_writers();
            }
        }
    };
}

pub(in crate::state) fn physical_scope(&mut self) -> EffectLockScope<'_, 'state> {
    EffectLockScope(self)
}

struct DeferredIndexRead<'scope, 'state, T> {
    guard: Option<crate::publication_rwlock::PublicationRwLockReadGuard<'state, T>>,
    releases: &'scope mut concread::release::DeferredReleaseBatch,
}

fn drop(&mut self) {
    if let Some(guard) = self.guard.take() {
        assert!(
            guard.try_release_into(self.releases).is_ok(),
            "original short index release source"
        );
    }
}

pub(super) struct DaCommitmentPostPublication {
    lane_config: Option<iroha_config::parameters::actual::LaneConfig>,
    snapshot: Option<DaShardCursorJournal>,
    captured: bool,
}

pub(super) fn publish(
    self,
    state: &State,
    indexes: &mut effect_publication::StateEffectLocks<'_>,
    _publication: &StateViewGenerationWriteGuard<'_>,
    persist_cursor_journal: bool,
) -> DaCommitmentPostPublication {
    let Self {
        pending,
        lane_config,
        active,
        query_visible,
        identity_visible,
        confidential,
    } = self;
    let height = pending.block_height;
    indexes
        .da_commitments
        .as_mut()
        .expect("prepared DA commitments")
        .insert_bundle_with_visibility_filter(
            height,
            pending.bundle,
            |record| identity_visible.contains(&DaCommitmentKey::from_record(record)),
            |record| query_visible.contains(&DaCommitmentKey::from_record(record)),
        );
    let cursor_result = state.advance_da_shard_cursors_into(
        indexes
            .da_shard_cursors
            .as_mut()
            .expect("prepared DA shard cursors"),
        &lane_config,
        height,
        &active,
    );
    let persist = match cursor_result {
        Ok(()) => persist_cursor_journal,
        Err(error) => {
            warn!(
                ?error,
                height, "failed to advance DA shard cursor index during block commit"
            );
            false
        }
    };
    if let Err(error) = state.advance_da_receipt_cursors_into(
        indexes
            .da_receipt_cursors
            .as_mut()
            .expect("prepared DA receipt cursors"),
        height,
        &active,
    ) {
        warn!(
            ?error,
            height, "failed to advance DA receipt cursor index during block commit"
        );
    }
    {
        let store = indexes
            .da_confidential_compute
            .as_mut()
            .expect("prepared confidential compute");
        for (record, location, policy) in confidential {
            store.insert(&record, location, &policy);
        }
    }
    DaCommitmentPostPublication {
        lane_config: persist.then_some(lane_config),
        snapshot: None,
        captured: false,
    }
}

pub(super) fn capture_snapshot(&mut self, state: &State, cursors: &DaShardCursorIndex) {
    assert!(!self.captured, "original DA cursor snapshot captured once");
    self.captured = true;
    let Some(lane_config) = self.lane_config.as_ref() else {
        return;
    };
    let path = state.da_shard_cursor_journal_path();
    if !path.as_os_str().is_empty() {
        self.snapshot = Some(DaShardCursorJournal::from_index(
            lane_config,
            cursors,
            &path,
        ));
    }
}

pub(super) fn publish(self, state: &State) {
    assert!(
        self.captured,
        "original DA cursor snapshot precedes release"
    );
    let Some(snapshot) = self.snapshot else {
        return;
    };
    state.da_shard_cursor_persistor.schedule(snapshot);
}

pub(super) fn publish(
    self,
    state: &State,
    indexes: &mut effect_publication::StateEffectLocks<'_>,
    _publication: &StateViewGenerationWriteGuard<'_>,
    publish_process_runtime: bool,
) -> LaneLifecyclePostPublication {
    indexes.install_registries(self.manifests, self.privacy);
    if !self.lanes_to_reset.is_empty() {
        indexes
            .merge_admission
            .as_mut()
            .expect("prepared merge admission")
            .prune_lane_progress(&self.lanes_to_reset);
        indexes
            .lane_relays
            .as_mut()
            .expect("prepared relays")
            .prune_lanes(&self.lanes_to_reset);
        indexes
            .da_commitments
            .as_mut()
            .expect("prepared commitments")
            .prune_lanes(&self.lanes_to_reset);
        indexes
            .da_confidential_compute
            .as_mut()
            .expect("prepared confidential compute")
            .prune_lanes(&self.lanes_to_reset);
        indexes
            .da_pin_intents
            .as_mut()
            .expect("prepared pins")
            .prune_lanes(&self.lanes_to_reset);
        indexes
            .da_receipt_cursors
            .as_mut()
            .expect("prepared receipt cursors")
            .prune_lanes(&self.lanes_to_reset);
        indexes
            .da_shard_cursors
            .as_mut()
            .expect("prepared shard cursors")
            .prune_lanes(&self.lanes_to_reset);
    }
    if publish_process_runtime {
        state.publish_lane_scoped_runtime_reset(&self.lanes_to_reset);
    }
    let records_reset = !self.active_reset_lanes.is_empty() && self.transition_height != 0;
    if records_reset {
        indexes
            .da_shard_cursors
            .as_mut()
            .expect("prepared shard cursors")
            .mark_lanes_canonically_reset(&self.active_reset_lanes, self.transition_height);
    }
    let persist_cursor_journal = publish_process_runtime
        && (records_reset
            || (!self.lanes_to_reset.is_empty()
                && indexes
                    .da_indexes_hydrated
                    .as_ref()
                    .expect("prepared hydration status")
                    .is_some()));
    LaneLifecyclePostPublication {
        lane_config: self.lane_config,
        persist_cursor_journal,
        snapshot: None,
        captured: false,
        transition: self.transition,
        transition_height: self.transition_height,
        #[cfg(feature = "telemetry")]
        nexus: self.nexus,
    }
}

pub(super) fn capture_snapshot(&mut self, state: &State, cursors: &DaShardCursorIndex) {
    assert!(
        !self.captured,
        "original lifecycle cursor snapshot captured once"
    );
    self.captured = true;
    if self.persist_cursor_journal {
        let path = state.da_shard_cursor_journal_path();
        if !path.as_os_str().is_empty() {
            self.snapshot = Some(DaShardCursorJournal::from_index(
                &self.lane_config,
                cursors,
                &path,
            ));
        }
    }
}

pub(super) fn publish(self, state: &State) {
    assert!(
        self.captured,
        "original lifecycle cursor snapshot precedes release"
    );
    #[cfg(not(feature = "telemetry"))]
    let _ = state;
    if let Some(snapshot) = self.snapshot {
        if let Err(err) = snapshot.persist() {
            warn!(?err, "failed to persist DA shard cursor journal");
        }
    }
    // Preserve existing lifecycle telemetry and log behavior even for replay
    // prevalidation; only cursor/process publication was suppressed before.
    #[cfg(feature = "telemetry")]
    {
        state
            .telemetry
            .set_nexus_catalogs(&self.nexus.lane_catalog, &self.nexus.dataspace_catalog);
        if let Some(event) = state.telemetry.record_nexus_config_diff(&self.nexus) {
            match norito::json::to_string(&event) {
                Ok(payload) => {
                    iroha_logger::telemetry!(msg = "nexus.config.diff", event = payload);
                }
                Err(err) => {
                    iroha_logger::error!(
                        ?err,
                        "failed to serialize autoscale nexus config diff event for telemetry log"
                    );
                }
            }
        }
    }
    self.transition.log(self.transition_height);
}

pub(in crate::state) fn publish(self, state: &State, cache: &mut DaPinStore) {
    state.publish_prepared_da_pins(self.da_pins, cache);
}

pub(crate) struct DeferredPublicationRwLock<'lock, T> {
    lock: &'lock PublicationRwLock<T>,
    releases: DeferredReleaseBatch,
}

pub(crate) fn defer_notifications(&self) -> DeferredPublicationRwLock<'_, T> {
    DeferredPublicationRwLock {
        lock: self,
        releases: self.deferred_releases(),
    }
}

pub(crate) fn read(&mut self) -> DeferredReadGuard<'_, 'lock, T> {
    DeferredReadGuard {
        guard: Some(self.lock.read()),
        releases: &mut self.releases,
    }
}

pub(crate) fn write(&mut self) -> DeferredWriteGuard<'_, 'lock, T> {
    DeferredWriteGuard {
        guard: Some(self.lock.write()),
        releases: &mut self.releases,
    }
}

macro_rules! deferred_guard {
    ($name:ident, $original:ident) => {
        /// Physically unlocks on Drop; the original notification stays outside.
        pub(crate) struct $name<'scope, 'lock, T> {
            guard: Option<$original<'lock, T>>,
            releases: &'scope mut DeferredReleaseBatch,
        }

        impl<T> std::ops::Deref for $name<'_, '_, T> {
            type Target = T;
            fn deref(&self) -> &T {
                self.guard
                    .as_deref()
                    .expect("original deferred index guard")
            }
        }

        impl<T> Drop for $name<'_, '_, T> {
            fn drop(&mut self) {
                if let Some(guard) = self.guard.take() {
                    assert!(
                        guard.try_release_into(self.releases).is_ok(),
                        "original deferred index source"
                    );
                }
            }
        }
    };
}

fn new(state: &'state State) -> Self {
    Self {
        commitments: state.da_commitments.defer_notifications(),
        confidential_compute: state.da_confidential_compute.defer_notifications(),
        receipt_cursors: state.da_receipt_cursors.defer_notifications(),
        shard_cursors: state.da_shard_cursors.defer_notifications(),
        pin_intents: state.da_pin_intents.defer_notifications(),
        hydrated: state.da_indexes_hydrated.defer_notifications(),
    }
}

fn publish_hydrated_da_indexes(
    &self,
    hydrated: HydratedDaIndexes,
    releases: &mut DaHydrationReleases<'_>,
) {
    let HydratedDaIndexes {
        commitments,
        confidential_compute,
        receipt_cursors,
        shard_cursors,
        pin_intents,
    } = hydrated;
    // Keep this acquisition order aligned with snapshot/test readers that hold more than
    // one DA guard. No published field changes until all five write guards are owned.
    let mut published_commitments = releases.commitments.write();
    let mut published_confidential_compute = releases.confidential_compute.write();
    let mut published_receipt_cursors = releases.receipt_cursors.write();
    let mut published_shard_cursors = releases.shard_cursors.write();
    let mut published_pin_intents = releases.pin_intents.write();
    *published_commitments = commitments;
    *published_confidential_compute = confidential_compute;
    *published_receipt_cursors = receipt_cursors;
    *published_shard_cursors = shard_cursors;
    *published_pin_intents = pin_intents;
}

fn persist_hydrated_da_shard_cursor_journal(&self, releases: &mut DaHydrationReleases<'_>) {
    let path = self.da_shard_cursor_journal_path();
    if path.as_os_str().is_empty() {
        return;
    }
    let lane_config = self.nexus_ownership_projection().lane_config.clone();
    let snapshot =
        DaShardCursorJournal::from_index(&lane_config, &releases.shard_cursors.read(), &path);
    if let Err(err) = snapshot.persist() {
        warn!(?err, path = %path.display(), "failed to persist DA shard cursor journal");
    }
}

fn ensure_da_indexes_hydrated_with_journal_publication(
    &self,
    persist_journal: bool,
) -> Result<(), DaIndexHydrationError> {
    {
        let guard = self.da_indexes_hydrated.read();
        if let Some(result) = guard.as_ref() {
            return *result;
        }
    }
    let mut releases = DaHydrationReleases::new(self);
    let mut write_fence = self.state_write_lock.defer_notifications();
    let _hydration_guard = self.da_index_hydration_fence.lock();
    if let Some(result) = releases.hydrated.read().as_ref() {
        return *result;
    }
    let _state_write_guard = write_fence.lock();
    let result = self.build_da_indexes_from_kura(None).map(|mut hydrated| {
        hydrated.pin_intents = self.da_pin_cache_from_world();
        self.publish_hydrated_da_indexes(hydrated, &mut releases);
        if persist_journal {
            self.persist_hydrated_da_shard_cursor_journal(&mut releases);
        }
    });
    if let Err(err) = &result {
        warn!(?err, "failed to hydrate DA indexes from Kura");
    }
    *releases.hydrated.write() = Some(result);
    result
}

pub(crate) fn rewind_da_indexes_to_height(
    &self,
    target_height: u64,
) -> Result<(), DaIndexHydrationError> {
    let mut releases = DaRewindReleases::new(self);
    self.rewind_da_indexes_to_height_with_releases(target_height, &mut releases)
}

pub fn next_relays_with_merge_material(
    &self,
    previous_snapshots: &BTreeMap<(LaneId, DataSpaceId, Hash), MergeLaneSnapshot>,
) -> Vec<LaneRelayEnvelope> {
    let mut next = BTreeMap::new();
    for envelope in self.entries.values() {
        if !envelope.has_merge_admission_material() {
            continue;
        }
        let key = (
            envelope.lane_id,
            envelope.dataspace_id,
            envelope.lane_incarnation,
        );
        let Some(expected_height) = expected_next_merge_lane_height(
            previous_snapshots,
            envelope.lane_id,
            envelope.dataspace_id,
            envelope.lane_incarnation,
        ) else {
            continue;
        };
        if envelope.block_height == expected_height {
            next.insert(key, envelope);
        }
    }
    next.into_values().cloned().collect()
}

fn merge_entry_candidates_from_lane_relays_with_view(
    &self,
    global_view: Option<u64>,
) -> Vec<crate::merge::MergeLedgerCandidate> {
    if self.ensure_merge_history_available().is_err() {
        return Vec::new();
    }
    self.hydrate_verified_lane_relay_records_from_contract_state();
    let consensus = self.merge_consensus_snapshot();
    let lifecycle = &consensus.lifecycle;
    let nexus = lifecycle.nexus.clone();
    let admission = &consensus.admission;
    let next_epoch = admission.expected_epoch();
    let previous_view = admission.previous_view();
    let Some(carrier_parent_hash) = consensus.latest_block_hash else {
        return Vec::new();
    };
    let Some(carrier_height) = consensus.committed_height.checked_add(1) else {
        return Vec::new();
    };
    let previous_snapshots = &admission.latest_lane_snapshots;
    let Ok((lane_catalog_hash, merge_lane_bindings, lane_authority_catalog)) =
        self.merge_active_lane_authority_snapshot(carrier_height)
    else {
        iroha_logger::error!(
            "cannot synthesize merge entry from incomplete lane authority state"
        );
        return Vec::new();
    };
    let lifecycle_incarnations = merge_lane_bindings
        .iter()
        .map(
            |entry| iroha_data_model::nexus::LaneLifecycleIncarnationEntry {
                lane_id: entry.lane_id,
                incarnation: entry.incarnation,
            },
        )
        .collect::<Vec<_>>();
    let incarnation_root = iroha_data_model::nexus::LaneLifecycleParameterV1::incarnation_root(
        &lifecycle_incarnations,
    );
    let activation_root = crate::merge::merge_activation_root(&merge_lane_bindings);
    // This relay-only helper carries independently certified settlement
    // snapshots. Autonomous execution candidates are constructed by
    // `build_merge_execution_candidate` and compete in the same global
    // merge round.
    let mut lane_snapshots = Vec::new();
    let mut max_view = global_view.unwrap_or(previous_view);
    // Retain candidate bytes, not a relay guard, while validation opens
    // World/Kura readers. Direct publication holds World reader guards
    // before acquiring the relay writer, so the opposite order can deadlock.
    let relay_candidates = self
        .lane_relays
        .read()
        .next_relays_with_merge_material(previous_snapshots);
    {
        for latest_admissible in relay_candidates {
            #[cfg(test)]
            tests::relay_candidate_snapshot_tests::before_validation();
            if self
                .verify_lane_relay_fastpq_record(&latest_admissible)
                .is_err()
            {
                continue;
            }
            let relay_proposal_height = latest_admissible.block_header.height().get();
            if !lifecycle.lane_route_and_incarnation_matches(
                latest_admissible.lane_id,
                latest_admissible.dataspace_id,
                relay_proposal_height,
                latest_admissible.lane_incarnation,
            ) {
                continue;
            }
            if validate_merge_snapshot_against_nexus(
                &nexus,
                latest_admissible.lane_id,
                latest_admissible.dataspace_id,
                latest_admissible.block_header.height().get(),
            )
            .is_err()
            {
                continue;
            }
            let key = (
                latest_admissible.lane_id,
                latest_admissible.dataspace_id,
                latest_admissible.lane_incarnation,
            );
            if previous_snapshots.get(&key).is_some_and(|previous| {
                previous.lane_block_height >= latest_admissible.block_height
            }) {
                continue;
            }
            let merge_hint_root = match latest_admissible.merge_hint_root() {
                Ok(root) => root,
                Err(err) => {
                    iroha_logger::warn!(
                        lane_id = %latest_admissible.lane_id,
                        dataspace_id = %latest_admissible.dataspace_id,
                        height = latest_admissible.block_height,
                        error_kind = err.as_label(),
                        error = %err,
                        "skipping merge entry synthesis for relay without merge hint root"
                    );
                    continue;
                }
            };
            let selected_snapshot = MergeLaneSnapshot {
                lane_id: latest_admissible.lane_id,
                lane_incarnation: latest_admissible.lane_incarnation,
                incarnation_activation_height: lifecycle
                    .activation_heights
                    .get(&latest_admissible.lane_id)
                    .copied()
                    .and_then(|height| height.checked_add(1))
                    .unwrap_or(u64::MAX),
                proposal_height: latest_admissible.block_header.height().get(),
                dataspace_id: latest_admissible.dataspace_id,
                lane_block_height: latest_admissible.block_height,
                tip_hash: latest_admissible.block_header.hash(),
                merge_hint_root,
                settlement_commitment: latest_admissible.settlement_commitment.clone(),
                settlement_hash: latest_admissible.settlement_hash,
                relay_envelope: Some(latest_admissible.clone()),
            };
            if global_view.is_none() {
                let snapshot_view = latest_admissible.block_header.view_change_index();
                max_view = max_view.max(snapshot_view);
            }
            lane_snapshots.push(selected_snapshot);
        }
    }
    if lane_snapshots.is_empty() {
        return Vec::new();
    }
    lane_snapshots
        .sort_by_key(|snapshot| (snapshot.lane_id.as_u32(), snapshot.dataspace_id.as_u64()));
    let merge_hint_roots: Vec<Hash> = lane_snapshots
        .iter()
        .map(|snapshot| snapshot.merge_hint_root)
        .collect();
    let global_state_root = crate::merge::reduce_merge_hint_roots(&merge_hint_roots);
    vec![crate::merge::MergeLedgerCandidate {
        version: crate::merge::MergeLedgerCandidate::VERSION,
        epoch_id: next_epoch,
        view: max_view,
        carrier_height,
        carrier_parent_hash,
        lane_catalog_hash,
        active_lanes: merge_lane_bindings,
        lane_authority_catalog,
        incarnation_root,
        activation_root,
        lane_snapshots,
        execution_batch: None,
        lane_drain_certificates: Vec::new(),
        global_state_root,
    }]
}

pub(super) fn persist_lane_lifecycle_cursor_journal(
    &self,
    releases: &mut LaneLifecycleReleases<'_>,
