pub(crate) fn install_lane_manifests_if_consensus_compatible(
    &self,
    manifests: &LaneManifestRegistryHandle,
) -> bool {
    let privacy = Arc::new(LanePrivacyRegistry::from_manifest_registry(manifests));
    let manifests = Arc::clone(manifests);
    let mut publication_notice = self.state_view_publication();
    let mut releases = LaneLifecycleReleases::new(self);
    let mut state_write_release = self.state_write_lock.defer_notifications();
    let _state_write_lock = state_write_release.lock();
    let publication = publication_notice.begin();
    if !manifests.is_bound_to_catalog(&self.nexus_ownership_projection().lane_catalog) {
        return false;
    }
    {
        let current = releases.manifests.read();
        if current.consensus_policy_digest() != manifests.consensus_policy_digest()
            || current.baseline_consensus_policy_digest()
                != manifests.baseline_consensus_policy_digest()
        {
            return false;
        }
    }
    self.install_prepared_lane_manifests_in_publication(manifests, privacy, &publication, &mut releases);
    true
}

fn lane_consensus_lifecycle_snapshot(&self) -> LaneConsensusLifecycleSnapshot {
    let mut cursors = self.da_shard_cursors.defer_notifications();
    self.lane_consensus_lifecycle_snapshot_with_cursors(&mut cursors)
}

fn lane_consensus_lifecycle_snapshot_with_cursors(
    &self,
    cursors: &mut crate::publication_rwlock::DeferredPublicationRwLock<'_, DaShardCursorIndex>,
) -> LaneConsensusLifecycleSnapshot {
    loop {
        let generation_before = self.state_view_generation();
        if generation_before % 2 != 0 {
            std::thread::yield_now();
            continue;
        }
        let nexus = self.nexus_snapshot();
        let incarnations = self.lane_incarnations_snapshot();
        let activation_heights = self.lane_incarnation_activation_heights_snapshot();
        let mut reset_heights = cursors.read().canonical_reset_heights().clone();
        for (lane_id, activation_height) in &activation_heights {
            if *activation_height == 0 {
                continue;
            }
            reset_heights
                .entry(*lane_id)
                .and_modify(|height| *height = (*height).max(*activation_height))
                .or_insert(*activation_height);
        }
        let generation_after = self.state_view_generation();
        if is_stable_state_view_generation(generation_before, generation_after) {
            return LaneConsensusLifecycleSnapshot {
                nexus,
                incarnations,
                activation_heights,
                reset_heights,
            };
        }
        std::thread::yield_now();
    }
}

fn publish_prevalidated_lane_relay(
    &self,
    envelope: &LaneRelayEnvelope,
    relay_proposal_height: u64,
) -> core::result::Result<LaneRelayInsert, LaneRelayError> {
    // Serialize the final authenticated lifecycle recheck and cache
    // insertion with geometry archive/removal, catalog publication, and
    // lane-scoped cache pruning. If admission wins this fence, retirement
    // observes the relay as a drain blocker. If retirement wins, this
    // post-fence snapshot rejects the retired incarnation. Raw/unvalidated
    // cache noise never crosses this fence and therefore cannot veto
    // Byzantine-tolerant retirement.
    let mut relay_releases = self.lane_relays.defer_notifications();
    let mut cursor_releases = self.da_shard_cursors.defer_notifications();
    let lifecycle_guard = self.lane_lifecycle_lock.lock();
    let current_lifecycle =
        self.lane_consensus_lifecycle_snapshot_with_cursors(&mut cursor_releases);
    let current_incarnation = current_lifecycle
        .incarnations
        .get(&envelope.lane_id)
        .copied()
        .ok_or(LaneRelayError::UnknownLane(envelope.lane_id))?;
    if current_incarnation != envelope.lane_incarnation {
        return Err(LaneRelayError::LaneIncarnationMismatch {
            lane: envelope.lane_id,
            expected: current_incarnation,
            actual: envelope.lane_incarnation,
        });
    }
    if !current_lifecycle.lane_route_and_incarnation_matches(
        envelope.lane_id,
        envelope.dataspace_id,
        relay_proposal_height,
        envelope.lane_incarnation,
    ) {
        return Err(LaneRelayError::StaleLaneIncarnation {
            lane: envelope.lane_id,
            reset_height: current_lifecycle
                .reset_heights
                .get(&envelope.lane_id)
                .copied()
                .unwrap_or(relay_proposal_height),
            relay_height: relay_proposal_height,
        });
    }
    let inserted = {
        let mut guard = relay_releases.write();
        guard.insert(envelope.clone())?
    };
    if matches!(
        inserted,
        LaneRelayInsert::Inserted | LaneRelayInsert::Replaced
    ) {
        // Retirement prunes both caches under this fence. Publishing status
        // after unlocking could resurrect an already retired incarnation.
        crate::sumeragi::status::push_lane_relay_envelope(envelope.clone());
    }
    drop(lifecycle_guard);
    #[cfg(feature = "telemetry")]
    if matches!(
        inserted,
        LaneRelayInsert::Inserted | LaneRelayInsert::Replaced
    ) {
        let head_height = u64::try_from(self.block_hashes.view().len()).unwrap_or(0);
        self.telemetry.record_lane_relay_finality(
            envelope.lane_id,
            envelope.dataspace_id,
            relay_proposal_height,
            head_height,
            envelope.rbc_bytes_total,
        );
    }
    Ok(inserted)
}

fn record_da_lane_reset_watermarks(
    &self,
    lanes_to_reset: &BTreeSet<LaneId>,
    reset_height: u64,
    releases: &mut LaneLifecycleReleases<'_>,
) {
    if lanes_to_reset.is_empty() || reset_height == 0 {
        return;
    }
    {
        let mut cursors = releases.shard_cursors.write();
        cursors.mark_lanes_canonically_reset(lanes_to_reset, reset_height);
    }
    self.persist_lane_lifecycle_cursor_journal(releases);
}

fn prune_merge_admission_lane_progress(
    &self,
    lanes_to_prune: &BTreeSet<LaneId>,
    releases: &mut LaneLifecycleReleases<'_>,
) {
    releases
        .merge_admission
        .write()
        .prune_lane_progress(lanes_to_prune);
}

fn reset_lane_scoped_runtime_state(
    &self,
    lanes_to_reset: &BTreeSet<LaneId>,
    publish_process_runtime: bool,
    releases: &mut LaneLifecycleReleases<'_>,
) {
    if lanes_to_reset.is_empty() {
        return;
    }
    self.reset_lane_scoped_runtime_indexes(lanes_to_reset, releases);
    if publish_process_runtime {
        self.publish_lane_scoped_runtime_reset(lanes_to_reset);
        if releases.hydrated.read().is_some() {
            self.persist_lane_lifecycle_cursor_journal(releases);
        }
    }
}

fn reset_lane_scoped_runtime_indexes(
    &self,
    lanes_to_reset: &BTreeSet<LaneId>,
    releases: &mut LaneLifecycleReleases<'_>,
) {
    if lanes_to_reset.is_empty() {
        return;
    }
    self.prune_merge_admission_lane_progress(lanes_to_reset, releases);
    releases.relays.write().prune_lanes(lanes_to_reset);
    releases.commitments.write().prune_lanes(lanes_to_reset);
    releases
        .confidential_compute
        .write()
        .prune_lanes(lanes_to_reset);
    releases.pin_intents.write().prune_lanes(lanes_to_reset);
    releases.receipt_cursors.write().prune_lanes(lanes_to_reset);
    {
        let mut cursors = releases.shard_cursors.write();
        cursors.prune_lanes(lanes_to_reset);
    }
}

fn install_prepared_lane_manifests_in_publication(
    &self,
    manifests: LaneManifestRegistryHandle,
    privacy: LanePrivacyRegistryHandle,
    _publication: &StateViewGenerationWriteGuard<'_>,
    releases: &mut LaneLifecycleReleases<'_>,
) {
    {
        let mut guard = releases.manifests.write();
        *guard = manifests;
        #[cfg(test)]
        lifecycle_index_publication::after_manifest_write_for_test();
    }
    let mut privacy_guard = releases.privacy.write();
    *privacy_guard = privacy;
}

fn set_nexus_with_configured_lane_catalog(
    &mut self,
    mut nexus: iroha_config::parameters::actual::Nexus,
    configured_lane_catalog: LaneCatalog,
    configured_baseline: Option<Hash>,
) -> Result<(), LaneLifecycleError> {
    let mut releases = LaneLifecycleReleases::new(self);
    iroha_data_model::merge::validate_merge_lane_authority_geometry(
        &nexus.lane_catalog,
        &nexus.dataspace_catalog,
    )?;
    nexus.configured_lane_catalog = configured_lane_catalog;
    let previous_nexus = self.nexus_snapshot().clone();
    let dataspace_ids: BTreeSet<_> = nexus
        .dataspace_catalog
        .entries()
        .iter()
        .map(|entry| entry.id)
        .collect();
    let dataspace_aliases: BTreeSet<_> = nexus
        .dataspace_catalog
        .entries()
        .iter()
        .map(|entry| entry.alias.clone())
        .collect();
    let dataspace_ids_by_alias: BTreeMap<_, _> = nexus
        .dataspace_catalog
        .entries()
        .iter()
        .map(|entry| (entry.alias.clone(), entry.id))
        .collect();
    // This must precede lane-geometry publication, catalog replacement, and stale-token
    // pruning. A failed retirement therefore leaves both the binding and its authority path
    // intact so the owner can clear it and retry.
    self.ensure_retired_dataspace_aliases_have_no_asset_definition_bindings(
        &previous_nexus.dataspace_catalog,
        &dataspace_aliases,
    )?;
    let active_lane_ids: BTreeSet<_> = nexus
        .lane_catalog
        .lanes()
        .iter()
        .map(|lane| lane.id)
        .collect();
    if !nexus_fee_asset_selector_is_xor(&nexus.fees.fee_asset_id) {
        return Err(LaneLifecycleError::NexusFeeAssetIdInvalid);
    }
    if nexus.fees.fee_sink_account_id.trim().is_empty() {
        return Err(LaneLifecycleError::NexusFeeSinkAccountEmpty);
    }
    if nexus.relay_worker.enabled
        && nexus.fees.settlement_mode != NexusFeeSettlementMode::LaneRelayBurn
    {
        return Err(LaneLifecycleError::RelayWorkerFeeConfig);
    }
    if nexus.lane_relay_emergency.multisig_threshold
        > nexus.lane_relay_emergency.multisig_members
    {
        return Err(LaneLifecycleError::LaneRelayEmergencyThreshold);
    }
    for dataspace_id in nexus.dataspace_fee_sponsor_program_ids.keys() {
        if !dataspace_ids.contains(dataspace_id) {
            return Err(
                LaneLifecycleError::DataspaceFeeSponsorProgramUnknownDataspace(*dataspace_id),
            );
        }
    }
    ensure_autoscale_runtime_lane_bounds(&nexus.autoscale)?;
    ensure_autoscale_default_lane_is_base(&nexus)?;
    if nexus.autoscale.enabled {
        ensure_autoscale_base_profile_supported(&nexus, None, None)?;
    }
    let current_block_height = self.block_hashes.view().len() as u64;
    let protected_autoscale_lanes: BTreeMap<LaneId, iroha_data_model::nexus::LaneConfig> = self
        .nexus_snapshot()
        .lane_catalog
        .lanes()
        .iter()
        .filter(|lane| lane_claims_autoscale_managed(lane))
        .map(|lane| (lane.id, lane.clone()))
        .collect();
    for (lane_id, protected_lane) in &protected_autoscale_lanes {
        let candidate = nexus
            .lane_catalog
            .lanes()
            .iter()
            .find(|lane| lane.id == *lane_id);
        if !candidate.is_some_and(|lane| lane == protected_lane) {
            return Err(LaneLifecycleError::ReservedAutoscaleManagedLane(*lane_id));
        }
    }
    for lane in nexus.lane_catalog.lanes() {
        if !dataspace_ids.contains(&lane.dataspace_id) {
            return Err(LaneLifecycleError::UnknownDataspace(lane.dataspace_id));
        }
        let is_preserved_autoscale_lane = protected_autoscale_lanes
            .get(&lane.id)
            .is_some_and(|protected_lane| protected_lane == lane);
        if lane_claims_autoscale_managed(lane) && !is_preserved_autoscale_lane {
            return Err(LaneLifecycleError::ReservedAutoscaleManagedLane(lane.id));
        }
        if lane_claims_autoscale_managed(lane) {
            ensure_autoscale_managed_lane_owned_by_nexus(lane, &nexus)?;
            let committee = decode_autoscale_lane_committee(lane).ok().flatten().ok_or(
                LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: lane.id,
                    reason: "autoscale committee metadata is missing or malformed",
                },
            )?;
            validate_autoscale_lane_committee_pops(&committee).map_err(|reason| {
                LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: lane.id,
                    reason,
                }
            })?;
            ensure_autoscale_managed_lane_created_height_not_future(
                lane,
                current_block_height,
            )?;
            ensure_autoscale_lane_drain_close_not_future(lane, current_block_height)?;
        } else {
            ensure_manual_lane_has_no_reserved_autoscale_metadata(lane)?;
            ensure_manual_lane_outside_autoscale_elastic_range(lane.id, &nexus)?;
        }
    }
    validate_nexus_routing_policy(
        &nexus.routing_policy,
        &nexus.lane_catalog,
        &nexus.dataspace_catalog,
    )?;
    nexus.lane_config =
        iroha_config::parameters::actual::LaneConfig::from_catalog(&nexus.lane_catalog);
    let configured_fee_asset_id = nexus.fees.fee_asset_id.clone();
    crate::sns::ensure_default_namespace_policies_match_configured(
        &self.world.view(),
        &configured_fee_asset_id,
    )
    .map_err(|error| {
        LaneLifecycleError::Storage(format!(
            "Nexus fee configuration does not match current SNS namespace policies: {error}"
        ))
    })?;
    let previous_lane_config = previous_nexus.lane_config.clone();
    let previous_lane_incarnations = self.lane_incarnations_snapshot();
    let previous_lane_incarnation_lineage = self.lane_incarnation_lineage_snapshot();
    let previous_lane_incarnation_activation_heights =
        self.lane_incarnation_activation_heights_snapshot();
    validate_lane_incarnation_lineage(
        &previous_nexus.lane_catalog,
        &previous_lane_incarnations,
        &previous_lane_incarnation_activation_heights,
        &previous_lane_incarnation_lineage,
    )?;
    let static_incarnations = derive_static_lane_incarnations(&nexus.lane_catalog);
    let updated_catalog_hash = merge_lane_consensus_catalog_hash(&nexus.lane_catalog);
    let mut updated_lane_incarnations = BTreeMap::new();
    let mut updated_lane_incarnation_activation_heights = BTreeMap::new();
    let mut updated_lane_incarnation_lineage = previous_lane_incarnation_lineage.clone();
    for lane in nexus.lane_catalog.lanes() {
        let unchanged = previous_nexus
            .lane_catalog
            .lanes()
            .iter()
            .find(|previous| previous.id == lane.id)
            .is_some_and(|previous| lane_consensus_identity_matches(previous, lane));
        let (generation, incarnation, activation_height) = if unchanged {
            let incarnation = previous_lane_incarnations
                .get(&lane.id)
                .copied()
                .ok_or_else(|| {
                    LaneLifecycleError::LaneIncarnationState(format!(
                        "unchanged lane {} is missing its active incarnation",
                        lane.id
                    ))
                })?;
            let activation_height = previous_lane_incarnation_activation_heights
                .get(&lane.id)
                .copied()
                .ok_or_else(|| {
                    LaneLifecycleError::LaneIncarnationState(format!(
                        "unchanged lane {} is missing its activation height",
                        lane.id
                    ))
                })?;
            let generation = previous_lane_incarnation_lineage
                .get(&lane.id)
                .ok_or_else(|| {
                    LaneLifecycleError::LaneIncarnationState(format!(
                        "unchanged lane {} is missing its retained lineage",
                        lane.id
                    ))
                })?
                .generation;
            (generation, incarnation, activation_height)
        } else if let Some(prior) = previous_lane_incarnation_lineage.get(&lane.id).copied() {
            let generation = prior.generation.checked_add(1).ok_or_else(|| {
                LaneLifecycleError::LaneIncarnationState(format!(
                    "lane {} incarnation generation overflow",
                    lane.id
                ))
            })?;
            let incarnation = derive_config_lane_incarnation(
                &self.network_id,
                &previous_nexus.lane_catalog,
                current_block_height,
                lane,
                prior,
                generation,
                updated_catalog_hash,
            );
            (generation, incarnation, current_block_height)
        } else {
            (0, static_incarnations[&lane.id], current_block_height)
        };
        updated_lane_incarnations.insert(lane.id, incarnation);
        updated_lane_incarnation_activation_heights.insert(lane.id, activation_height);
        updated_lane_incarnation_lineage.insert(
            lane.id,
            LaneIncarnationLineage {
                generation,
                incarnation,
                activation_height,
            },
        );
    }
    for lane in nexus.lane_catalog.lanes() {
        if let Some(drain_state) =
            decode_autoscale_lane_drain_state(lane).map_err(|reason| {
                LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: lane.id,
                    reason,
                }
            })?
            && !autoscale_lane_drain_state_matches_context(
                lane,
                &drain_state,
                &self.network_id,
                updated_lane_incarnations[&lane.id],
            )
        {
            return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
                lane: lane.id,
                reason: "autoscale drain state is bound to another network or incarnation",
            });
        }
    }
    validate_lane_incarnation_lineage(
        &nexus.lane_catalog,
        &updated_lane_incarnations,
        &updated_lane_incarnation_activation_heights,
        &updated_lane_incarnation_lineage,
    )?;
    let mut lanes_to_reset =
        lanes_requiring_state_reset(&previous_lane_config, &nexus.lane_config);
    lanes_to_reset.extend(lanes_requiring_consensus_reset(
        &previous_nexus.lane_catalog,
        &nexus.lane_catalog,
    ));
    let geometry_replaced_lane_ids = lanes_to_reset
        .iter()
        .copied()
        .filter(|lane_id| {
            previous_lane_config.entry(*lane_id).is_some()
                && nexus.lane_config.entry(*lane_id).is_some()
        })
        .collect::<BTreeSet<_>>();
    {
        let world = self.world.view();
        ensure_live_shared_dataspace_staking_owner_is_not_reset(
            &world,
            &previous_nexus,
            &nexus,
            &lanes_to_reset,
            current_block_height,
        )?;
    }
    if self.kura.emergency_fast_startup_enabled() {
        warn!(
            "emergency Fast startup skipped lane-geometry publication and backend reconciliation"
        );
    } else {
        self.apply_lane_geometry_updates(
            &previous_lane_config,
            &nexus.lane_config,
            &previous_lane_incarnations,
            &updated_lane_incarnations,
            &previous_lane_incarnation_activation_heights,
            &updated_lane_incarnation_activation_heights,
            &previous_lane_incarnation_lineage,
            &updated_lane_incarnation_lineage,
            &geometry_replaced_lane_ids,
            current_block_height,
            &mut releases,
        )?;
        if let Err(failure) = self.mark_lane_geometry_catalog_published(
            &nexus.lane_config,
            &updated_lane_incarnations,
            &updated_lane_incarnation_activation_heights,
            &updated_lane_incarnation_lineage,
            configured_baseline,
        ) {
            let LaneGeometryCatalogPublicationFailure {
                error,
                rollback_safe,
            } = failure;
            if !rollback_safe {
                return Err(error);
            }
            self.rollback_lane_geometry_updates(
                &previous_lane_config,
                &nexus.lane_config,
                &previous_lane_incarnations,
                &previous_lane_incarnation_activation_heights,
                &previous_lane_incarnation_lineage,
                &geometry_replaced_lane_ids,
                current_block_height,
                &mut releases,
            )
            .map_err(|rollback| {
                LaneLifecycleError::Storage(format!(
                    "{error}; lane geometry rollback also failed: {rollback}"
                ))
            })?;
            return Err(error);
        }
    }
    let active_reset_lanes = Self::active_reset_lanes(&lanes_to_reset, &nexus.lane_config);
    let reset_height = self.block_hashes.view().len() as u64;
    let autoscale_history_cap = autoscale_sample_history_cap(&nexus.autoscale);
    let mut samples = self.autoscale_sample_history_snapshot();
    trim_autoscale_sample_history(&mut samples, autoscale_history_cap);
    self.install_canonical_runtime_projection(
        &nexus,
        &updated_lane_incarnation_lineage,
        &samples,
    )?;
    *self.nexus.write() = nexus;
    self.reset_lane_scoped_runtime_state(&lanes_to_reset, true, &mut releases);
    self.record_da_lane_reset_watermarks(&active_reset_lanes, reset_height, &mut releases);
    drop(releases);
    self.prune_da_pin_intent_world_indexes_for_lanes(&lanes_to_reset);
    self.prune_public_lane_economic_state_for_lanes(&lanes_to_reset);
    self.prune_verified_lane_relay_contract_state_for_lanes(&lanes_to_reset);
    self.prune_lane_relay_emergency_validators_for_reset_or_inactive_lanes(
        &lanes_to_reset,
        &active_lane_ids,
    );
    // Drop UAID dataspace bindings that point to removed catalog entries.
    // This keeps derived UAID->dataspace/account links consistent with the
    // active dataspace catalog after runtime config updates.
    let stale_uaids: Vec<UniversalAccountId> = self
        .world
        .uaid_dataspaces
        .view()
        .iter()
        .filter_map(|(uaid, bindings)| {
            bindings
                .iter()
                .any(|(dataspace_id, _)| !dataspace_ids.contains(dataspace_id))
                .then_some(*uaid)
        })
        .collect();
    if !stale_uaids.is_empty() {
        let mut tx = self.world.uaid_dataspaces.block();
        for uaid in stale_uaids {
            let Some(mut bindings) = tx.get(&uaid).cloned() else {
                continue;
            };
            if !bindings.retain_dataspaces(&dataspace_ids) {
                continue;
            }
            if bindings.is_empty() {
                tx.remove(uaid);
            } else {
                tx.insert(uaid, bindings);
            }
        }
        tx.commit();
    }
    // Drop Space Directory manifest entries targeting removed dataspaces so
    // stale manifest records cannot rehydrate removed dataspace bindings.
    let stale_manifest_uaids: Vec<UniversalAccountId> = self
        .world
        .space_directory_manifests
        .view()
        .iter()
        .filter_map(|(uaid, manifests)| {
            manifests
                .iter()
                .any(|(dataspace_id, _)| !dataspace_ids.contains(dataspace_id))
                .then_some(*uaid)
        })
        .collect();
    if !stale_manifest_uaids.is_empty() {
        let mut tx = self.world.space_directory_manifests.block();
        for uaid in stale_manifest_uaids {
            let Some(mut manifests) = tx.get(&uaid).cloned() else {
                continue;
            };
            let stale_dataspaces: Vec<DataSpaceId> = manifests
                .iter()
                .filter_map(|(dataspace_id, _)| {
                    (!dataspace_ids.contains(dataspace_id)).then_some(*dataspace_id)
                })
                .collect();
            for dataspace_id in stale_dataspaces {
                manifests.remove(&dataspace_id);
            }
            if manifests.is_empty() {
                tx.remove(uaid);
            } else {
                tx.insert(uaid, manifests);
            }
        }
        tx.commit();
    }
    // Drop account-scope directory entries targeting removed dataspaces so routed
    // account-read scope cannot retain stale dataspace references after catalog updates.
    let stale_account_scope_accounts: Vec<AccountId> = self
        .world
        .account_scope_directory
        .view()
        .iter()
        .filter_map(|(account_id, entry)| {
            entry
                .iter()
                .any(|(dataspace_id, _)| !dataspace_ids.contains(dataspace_id))
                .then_some(account_id.clone())
        })
        .collect();
    if !stale_account_scope_accounts.is_empty() {
        let mut tx = self.world.account_scope_directory.block();
        for account_id in stale_account_scope_accounts {
            let Some(mut entry) = tx.get(&account_id).cloned() else {
                continue;
            };
            if !entry.retain_dataspaces(&dataspace_ids) {
                continue;
            }
            if entry.is_empty() {
                tx.remove(account_id);
            } else {
                tx.insert(account_id, entry);
            }
        }
        tx.commit();
        self.world.rebuild_account_scope_accounts_index();
    }
    // Drop AXT policy entries targeting removed dataspaces so runtime policy
    // caches cannot retain stale dataspace references across nexus updates.
    let stale_axt_policies: Vec<DataSpaceId> = self
        .world
        .axt_policies
        .view()
        .iter()
        .filter_map(|(dataspace_id, _)| {
            (!dataspace_ids.contains(dataspace_id)).then_some(*dataspace_id)
        })
        .collect();
    if !stale_axt_policies.is_empty() {
        let mut tx = self.world.axt_policies.block();
        for dataspace_id in stale_axt_policies {
            tx.remove(dataspace_id);
        }
        tx.commit();
    }
    // Drop account/role permissions targeting removed dataspaces so
    // permission payload references do not outlive catalog entries.
    let is_stale_account_alias_scope =
        |scope: &iroha_executor_data_model::permission::account::AccountAliasPermissionScope| {
            match scope {
                iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Domain(
                    domain,
                ) => !dataspace_aliases.contains(domain.dataspace().as_ref()),
                iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Dataspace(
                    dataspace,
                ) => !dataspace_ids.contains(dataspace),
                iroha_executor_data_model::permission::account::AccountAliasPermissionScope::Alias(
                    alias,
                ) => {
                    !dataspace_ids.contains(&alias.dataspace_id)
                        || !dataspace_aliases
                            .contains(alias.canonical_name.dataspace.as_ref())
                }
            }
        };
    let is_stale_asset_definition_alias_scope = |scope: &iroha_executor_data_model::permission::asset_definition::AssetDefinitionAliasPermissionScope| {
            match scope {
                iroha_executor_data_model::permission::asset_definition::AssetDefinitionAliasPermissionScope::Domain(
                    domain,
                ) => !dataspace_aliases.contains(domain.dataspace().as_ref()),
                iroha_executor_data_model::permission::asset_definition::AssetDefinitionAliasPermissionScope::Dataspace(
                    dataspace,
                ) => !dataspace_ids.contains(dataspace),
                iroha_executor_data_model::permission::asset_definition::AssetDefinitionAliasPermissionScope::Alias(
                    alias,
                ) => dataspace_ids_by_alias
                    .get(alias.canonical_name.dataspace_segment())
                    .copied()
                    != Some(alias.dataspace_id),
            }
        };
    let is_stale_dataspace_permission = |permission: &Permission| {
        if let Ok(permission) =
            iroha_executor_data_model::permission::query::CanReadRestrictedDataspace::try_from(
                permission,
            )
        {
            return !dataspace_ids.contains(&permission.dataspace);
        }
        if let Ok(permission) = iroha_executor_data_model::permission::asset::CanSetAssetTransferDailyLimit::try_from(permission) {
            return !dataspace_ids.contains(&permission.account_dataspace);
        }
        if let Ok(permission) =
            iroha_executor_data_model::permission::account::CanResolveAccountAlias::try_from(
                permission,
            )
        {
            return is_stale_account_alias_scope(&permission.scope);
        }
        if let Ok(permission) = iroha_executor_data_model::permission::account::CanDelegateAccountAliasResolution::try_from(permission) {
            return is_stale_account_alias_scope(&permission.scope);
        }
        if let Ok(permission) =
            iroha_executor_data_model::permission::account::CanManageAccountAlias::try_from(
                permission,
            )
        {
            return is_stale_account_alias_scope(&permission.scope);
        }
        if let Ok(permission) = iroha_executor_data_model::permission::asset_definition::CanManageAssetDefinitionAlias::try_from(permission)
        {
            return is_stale_asset_definition_alias_scope(&permission.scope);
        }
        if let Ok(permission) =
            iroha_executor_data_model::permission::nexus::CanPublishSpaceDirectoryManifest::try_from(
                permission,
            )
        {
            return !dataspace_ids.contains(&permission.dataspace);
        }
        if let Ok(permission) = iroha_executor_data_model::permission::nexus::CanPublishSpaceDirectoryManifestForUaid::try_from(
            permission,
        ) {
            return !dataspace_ids.contains(&permission.dataspace);
        }
        if let Ok(permission) = iroha_executor_data_model::permission::nexus::CanPublishSpaceDirectoryManifestForAccountDomain::try_from(
            permission,
        ) {
            return !dataspace_ids.contains(&permission.dataspace)
                || dataspace_ids_by_alias
                    .get(permission.domain.dataspace().as_ref())
                    .is_none_or(|dataspace| *dataspace != permission.dataspace);
        }
        false
    };
    let stale_permission_holders: Vec<AccountId> = self
        .world
        .account_permissions
        .view()
        .iter()
        .filter_map(|(holder, permissions)| {
            permissions
                .iter()
                .any(is_stale_dataspace_permission)
                .then_some(holder.clone())
        })
        .collect();
    if !stale_permission_holders.is_empty() {
        let mut tx = self.world.account_permissions.block();
        for holder in stale_permission_holders {
            let remove_entry = if let Some(permissions) = tx.get_mut(&holder) {
                permissions.retain(|permission| !is_stale_dataspace_permission(permission));
                permissions.is_empty()
            } else {
                false
            };
            if remove_entry {
                tx.remove(holder);
            }
        }
        tx.commit();
    }
    let stale_roles: Vec<RoleId> = self
        .world
        .roles
        .view()
        .iter()
        .filter_map(|(role_id, role)| {
            role.permissions()
                .any(is_stale_dataspace_permission)
                .then_some(role_id.clone())
        })
        .collect();
    if !stale_roles.is_empty() {
        let mut tx = self.world.roles.block();
        for role_id in stale_roles {
            if let Some(role) = tx.get_mut(&role_id) {
                role.permissions
                    .retain(|permission| !is_stale_dataspace_permission(permission));
                role.permission_epochs
                    .retain(|permission, _| role.permissions.contains(permission));
            }
        }
        tx.commit();
    }
    self.nexus_storage_budget_last_check_height
        .store(0, Ordering::Relaxed);
    let _ = self.refresh_axt_policies_from_directory();
    #[cfg(feature = "telemetry")]
    {
        let nexus = self.nexus_snapshot();
        self.telemetry
            .set_nexus_catalogs(&nexus.lane_catalog, &nexus.dataspace_catalog);
        if let Some(event) = self.telemetry.record_nexus_config_diff(&nexus) {
            match norito::json::to_string(&event) {
                Ok(payload) => {
                    iroha_logger::telemetry!(msg = "nexus.config.diff", event = payload);
                }
                Err(err) => {
                    iroha_logger::error!(
                        ?err,
                        "failed to serialize nexus config diff event for telemetry log"
                    );
                }
            }
        }
    }
    Ok(())
}

fn apply_lane_lifecycle_with_options(
    &self,
    plan: &iroha_data_model::nexus::LaneLifecyclePlan,
    refresh_axt_policies: bool,
    allow_autoscale_managed_changes: bool,
) -> core::result::Result<(), LaneLifecycleError> {
    const STATE_VIEW_LOCK_THRESHOLD: Duration = Duration::from_millis(10);
    let mut publication_notice = self.state_view_publication();
    let mut releases = LaneLifecycleReleases::new(self);
    let mut commit_release = self.state_commit_lock.defer_notifications();
    let mut lifecycle_release = self.lane_lifecycle_lock.defer_notifications();
    let mut write_release = self.state_write_lock.defer_notifications();
    let (lanes_to_reset, active_lane_ids) = {
        // A prebuilt StateBlock owns these MV writers before it takes the
        // commit fence. Wait for that original owner before taking State
        // fences, then consume this replacement inside the same visibility
        // boundary. It must not survive into the World cleanup below.
        let runtime = self.acquire_canonical_runtime_replacement();
        let _state_commit_lock = commit_release.lock();
        let _lifecycle_lock = lifecycle_release.lock();
        let current_block_height = self.block_hashes.view().len() as u64;
        let mut effective_plan = plan.clone();
        if allow_autoscale_managed_changes && !effective_plan.additions.is_empty() {
            for addition in &effective_plan.additions {
                if !lane_uses_reserved_autoscale_metadata(addition) {
                    return Err(LaneLifecycleError::AutoscaleAddUnmanagedLane(addition.id));
                }
                ensure_autoscale_managed_lane_shape(addition)?;
            }
            let proposal_height = current_block_height.checked_add(1).ok_or(
                LaneLifecycleError::AutoscaleProposalHeightOverflow(
                    effective_plan.additions[0].id,
                ),
            )?;
            let nexus = self.nexus_snapshot().clone();
            let manifests = releases.manifests.read().clone();
            let world = self.world.view();
            for addition in &mut effective_plan.additions {
                #[cfg(test)]
                if self.commit_topology_snapshot().is_empty()
                    && matches!(decode_autoscale_lane_committee(addition), Ok(Some(_)))
                {
                    // Most state unit tests install geometry without a live
                    // consensus actor. Their fixture lane already carries a
                    // fully validated deterministic pin.
                    let committee = decode_autoscale_lane_committee(addition)
                        .expect("checked synthetic pin decoding")
                        .expect("checked synthetic pin presence");
                    validate_autoscale_lane_committee_pops(&committee).map_err(|reason| {
                        LaneLifecycleError::InvalidAutoscaleManagedLane {
                            lane: addition.id,
                            reason,
                        }
                    })?;
                    continue;
                }
                State::pin_new_autoscale_lane_committee_from_sources(
                    &world,
                    &self.network_id,
                    manifests.as_ref(),
                    &nexus,
                    addition,
                    proposal_height,
                )?;
            }
        }
        let plan = &effective_plan;
        let previous_lane_incarnations = self.lane_incarnations_snapshot();
        let previous_lane_incarnation_lineage = self.lane_incarnation_lineage_snapshot();
        let previous_lane_incarnation_activation_heights =
            self.lane_incarnation_activation_heights_snapshot();
        let committing_header_hash =
            synthetic_lane_lifecycle_header_hash(&self.network_id, current_block_height, plan);
        let compliance_engine = self.lane_compliance.read().clone();
        let (lifecycle_update, updated_lane_manifests) = {
            let nexus = self.nexus_snapshot();
            ensure_lane_lifecycle_compliance_ready(&nexus, compliance_engine.as_deref(), plan)?;
            let lifecycle_update = prepare_lane_lifecycle_update(
                &nexus,
                &previous_lane_incarnations,
                &previous_lane_incarnation_lineage,
                &previous_lane_incarnation_activation_heights,
                &self.network_id,
                committing_header_hash,
                plan,
                current_block_height,
                allow_autoscale_managed_changes,
            )?;
            let world = self.world.view();
            let mut prospective_nexus = nexus.clone();
            prospective_nexus.lane_catalog = lifecycle_update.updated_catalog.clone();
            prospective_nexus.lane_config = lifecycle_update.updated_lane_config.clone();
            ensure_live_shared_dataspace_staking_owner_is_not_reset(
                &world,
                &nexus,
                &prospective_nexus,
                &lifecycle_update.lanes_to_reset,
                current_block_height,
            )?;
            let updated_lane_manifests = rebind_lane_manifests_for_lifecycle(
                releases.manifests.read().as_ref(),
                &lifecycle_update.updated_catalog,
                &nexus.governance,
            )?;
            (lifecycle_update, updated_lane_manifests)
        };
        let updated_lane_privacy = Arc::new(LanePrivacyRegistry::from_manifest_registry(
            &updated_lane_manifests,
        ));
        let active_reset_lanes = Self::active_reset_lanes(
            &lifecycle_update.lanes_to_reset,
            &lifecycle_update.updated_lane_config,
        );
        let reset_height = current_block_height;
        self.apply_lane_geometry_updates(
            &lifecycle_update.previous_lane_config,
            &lifecycle_update.updated_lane_config,
            &lifecycle_update.previous_lane_incarnations,
            &lifecycle_update.updated_lane_incarnations,
            &lifecycle_update.previous_lane_incarnation_activation_heights,
            &lifecycle_update.updated_lane_incarnation_activation_heights,
            &lifecycle_update.previous_lane_incarnation_lineage,
            &lifecycle_update.updated_lane_incarnation_lineage,
            &lifecycle_update.replaced_lane_ids,
            current_block_height,
            &mut releases,
        )?;
        if let Err(failure) = self.mark_lane_geometry_catalog_published(
            &lifecycle_update.updated_lane_config,
            &lifecycle_update.updated_lane_incarnations,
            &lifecycle_update.updated_lane_incarnation_activation_heights,
            &lifecycle_update.updated_lane_incarnation_lineage,
            None,
        ) {
            let LaneGeometryCatalogPublicationFailure {
                error,
                rollback_safe,
            } = failure;
            if !rollback_safe {
                return Err(error);
            }
            self.rollback_lane_geometry_updates(
                &lifecycle_update.previous_lane_config,
                &lifecycle_update.updated_lane_config,
                &lifecycle_update.previous_lane_incarnations,
                &lifecycle_update.previous_lane_incarnation_activation_heights,
                &lifecycle_update.previous_lane_incarnation_lineage,
                &lifecycle_update.replaced_lane_ids,
                current_block_height,
                &mut releases,
            )
            .map_err(|rollback| {
                LaneLifecycleError::Storage(format!(
                    "{error}; lane geometry rollback also failed: {rollback}"
                ))
            })?;
            return Err(error);
        }
        let lanes_to_reset = lifecycle_update.lanes_to_reset.clone();
        let active_lane_ids: BTreeSet<_> = lifecycle_update
            .updated_catalog
            .lanes()
            .iter()
            .map(|lane| lane.id)
            .collect();
        {
            let state_write_lock_wait_start = Instant::now();
            let _state_write_lock = write_release.lock();
            let state_write_lock_wait = state_write_lock_wait_start.elapsed();
            let state_write_lock_hold_start = Instant::now();
            let _view_generation = publication_notice.begin();
            {
                let mut nexus = self.nexus_ownership_projection();
                nexus.lane_catalog = lifecycle_update.updated_catalog;
                nexus.lane_config = lifecycle_update.updated_lane_config;
                Self::install_canonical_runtime_projection_with_owner(
                    runtime,
                    &nexus,
                    &lifecycle_update.updated_lane_incarnation_lineage,
                    &self.autoscale_sample_history_snapshot(),
                )?;
            }
            self.install_prepared_lane_manifests_in_publication(
                updated_lane_manifests,
                updated_lane_privacy,
                &_view_generation,
                &mut releases,
            );
            if !lanes_to_reset.is_empty() {
                self.reset_lane_scoped_runtime_state(&lanes_to_reset, true, &mut releases);
                self.record_da_lane_reset_watermarks(
                    &active_reset_lanes,
                    reset_height,
                    &mut releases,
                );
            }
            let state_write_lock_hold = state_write_lock_hold_start.elapsed();
            if state_write_lock_wait >= STATE_VIEW_LOCK_THRESHOLD
                || state_write_lock_hold >= STATE_VIEW_LOCK_THRESHOLD
            {
                debug!(
                    state_write_lock_wait_us = state_write_lock_wait.as_micros(),
                    state_write_lock_hold_us = state_write_lock_hold.as_micros(),
                    "state write lock held (lane lifecycle)"
                );
            }
        }
        (lanes_to_reset, active_lane_ids)
    };
    if !lanes_to_reset.is_empty() {
        self.prune_da_pin_intent_world_indexes_for_lanes(&lanes_to_reset);
        self.prune_public_lane_economic_state_for_lanes(&lanes_to_reset);
        self.prune_verified_lane_relay_contract_state_for_lanes(&lanes_to_reset);
    }
    self.prune_lane_relay_emergency_validators_for_reset_or_inactive_lanes(
        &lanes_to_reset,
        &active_lane_ids,
    );
    if refresh_axt_policies {
        let _ = self.refresh_axt_policies_from_directory();
    }
    #[cfg(feature = "telemetry")]
    {
        let nexus = self.nexus_snapshot();
        self.telemetry
            .set_nexus_catalogs(&nexus.lane_catalog, &nexus.dataspace_catalog);
        if let Some(event) = self.telemetry.record_nexus_config_diff(&nexus) {
            match norito::json::to_string(&event) {
                Ok(payload) => {
                    iroha_logger::telemetry!(msg = "nexus.config.diff", event = payload);
                }
                Err(err) => {
                    iroha_logger::error!(
                        ?err,
                        "failed to serialize nexus config diff event for telemetry log"
                    );
                }
            }
        }
    }
    Ok(())
}

fn apply_committed_autoscale_lane_geometry(
    &self,
    pending: &PendingAutoscaleLaneLifecycle,
    block_height: u64,
    block_header_hash: HashOf<BlockHeader>,
    staged_merge_entry: Option<&MergeLedgerEntry>,
    releases: &mut LaneLifecycleReleases<'_>,
) -> Result<(), LaneLifecycleError> {
    self.preflight_committed_autoscale_lane_geometry(
        pending,
        block_height,
        block_header_hash,
        staged_merge_entry,
        releases,
    )?;
    let update = &pending.catalog_update;
    if !pending.transition.requires_geometry() {
        return Ok(());
    }
    let certified_frontiers = match &pending.transition {
        PendingAutoscaleTransition::ScaleIn { lane, .. } => {
            let previous_lane = update
                .previous_catalog
                .lanes()
                .iter()
                .find(|candidate| candidate.id == *lane)
                .ok_or(LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason: "certified retirement lane is absent from the previous catalog",
                })?;
            let incarnation = update.previous_lane_incarnations.get(lane).copied().ok_or(
                LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason: "certified retirement lane has no previous incarnation",
                },
            )?;
            let commitment = decode_autoscale_lane_drain_state(previous_lane)
                .map_err(|reason| LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason,
                })?
                .and_then(|state| state.commitment)
                .ok_or(LaneLifecycleError::UnsafeRetirement {
                    lane: *lane,
                    reason: "certified retirement has no committed drain frontier",
                })?;
            BTreeMap::from([(
                (*lane, previous_lane.dataspace_id, incarnation),
                commitment.frontier,
            )])
        }
        _ => BTreeMap::new(),
    };
    self.apply_lane_geometry_updates_with_certified_drain_frontiers(
        &update.previous_lane_config,
        &update.updated_lane_config,
        &update.previous_lane_incarnations,
        &update.updated_lane_incarnations,
        &update.previous_lane_incarnation_activation_heights,
        &update.updated_lane_incarnation_activation_heights,
        &update.previous_lane_incarnation_lineage,
        &update.updated_lane_incarnation_lineage,
        &update.replaced_lane_ids,
        &certified_frontiers,
        block_height,
        releases,
    )?;
    if let Err(failure) = self.mark_lane_geometry_catalog_published(
        &update.updated_lane_config,
        &update.updated_lane_incarnations,
        &update.updated_lane_incarnation_activation_heights,
        &update.updated_lane_incarnation_lineage,
        None,
    ) {
        let LaneGeometryCatalogPublicationFailure {
            error,
            rollback_safe,
        } = failure;
        if !rollback_safe {
            return Err(error);
        }
        self.rollback_lane_geometry_updates(
            &update.previous_lane_config,
            &update.updated_lane_config,
            &update.previous_lane_incarnations,
            &update.previous_lane_incarnation_activation_heights,
            &update.previous_lane_incarnation_lineage,
            &update.replaced_lane_ids,
            block_height,
            releases,
        )
        .map_err(|rollback| {
            LaneLifecycleError::Storage(format!(
                "{error}; lane geometry rollback also failed: {rollback}"
            ))
        })?;
        return Err(error);
    }
    Ok(())
}

fn preflight_committed_autoscale_lane_geometry(
    &self,
    pending: &PendingAutoscaleLaneLifecycle,
    block_height: u64,
    block_header_hash: HashOf<BlockHeader>,
    staged_merge_entry: Option<&MergeLedgerEntry>,
    releases: &mut LaneLifecycleReleases<'_>,
) -> Result<(), LaneLifecycleError> {
    let update = &pending.catalog_update;
    self.validate_committed_autoscale_lane_lifecycle(
        pending,
        block_height,
        block_header_hash,
        staged_merge_entry,
        releases,
    )?;
    let diff = lane_topology_diff(
        &update.previous_lane_config,
        &update.updated_lane_config,
        &update.replaced_lane_ids,
    );
    self.preflight_lane_geometry_updates(
        &update.previous_lane_config,
        &update.updated_lane_config,
        &diff,
    )
}

fn validate_committed_autoscale_lane_lifecycle(
    &self,
    pending: &PendingAutoscaleLaneLifecycle,
    block_height: u64,
    block_header_hash: HashOf<BlockHeader>,
    staged_merge_entry: Option<&MergeLedgerEntry>,
    releases: &mut LaneLifecycleReleases<'_>,
) -> Result<(), LaneLifecycleError> {
    let update = &pending.catalog_update;
    let nexus = self.nexus_snapshot();
    if pending.transition_height != block_height {
        return Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
            transition: pending.transition.name(),
            reason: "transition_height must match the committing block height",
        });
    }
    let lane_incarnations = self.lane_incarnations_snapshot();
    let lane_incarnation_lineage = self.lane_incarnation_lineage_snapshot();
    let lane_incarnation_activation_heights =
        self.lane_incarnation_activation_heights_snapshot();
    if nexus.lane_catalog != update.previous_catalog
        || nexus.dataspace_catalog != update.previous_dataspace_catalog
        || nexus.routing_policy != update.previous_routing_policy
        || nexus.autoscale != update.previous_autoscale
        || !lane_config_entries_match(&nexus.lane_config, &update.previous_lane_config)
        || lane_incarnations != update.previous_lane_incarnations
        || lane_incarnation_lineage != update.previous_lane_incarnation_lineage
        || lane_incarnation_activation_heights
            != update.previous_lane_incarnation_activation_heights
    {
        return Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
            transition: pending.transition.name(),
            reason: "staged autoscale lifecycle no longer matches committed nexus state",
        });
    }
    let allow_autoscale_managed_changes =
        pending.transition != PendingAutoscaleTransition::Manual;
    let actual_incarnation_root =
        lane_lifecycle_incarnation_root(&nexus.lane_catalog, &lane_incarnations)?;
    if pending.expected_incarnation_root != actual_incarnation_root {
        return Err(LaneLifecycleError::StaleIncarnationRoot {
            expected: pending.expected_incarnation_root,
            actual: actual_incarnation_root,
        });
    }
    let compliance_engine = self.lane_compliance.read().clone();
    ensure_lane_lifecycle_compliance_ready(
        &nexus,
        compliance_engine.as_deref(),
        &pending.plan,
    )?;
    if matches!(
        &pending.transition,
        PendingAutoscaleTransition::DrainIntent { .. }
            | PendingAutoscaleTransition::DrainCommitment { .. }
    ) {
        return self.validate_committed_autoscale_drain_metadata_update(
            &nexus,
            &lane_incarnations,
            &lane_incarnation_activation_heights,
            pending,
            block_height,
            releases,
        );
    }
    let mut prospective_nexus = nexus.clone();
    if let Some(runtime) = &pending.runtime_catalog {
        if pending.transition != PendingAutoscaleTransition::Manual {
            return Err(runtime_catalog_invalid(
                "only signed manual transitions may add runtime catalog authority",
            ));
        }
        prospective_nexus.dataspace_catalog = runtime_catalog_transition_dataspaces(
            &nexus,
            releases.manifests.read().as_ref(),
            &self.world.view(),
            runtime,
            &pending.plan,
        )?;
    }
    let derivation_header_hash = if let Some(batch) = staged_merge_entry
        .filter(|_| pending.runtime_catalog.is_some())
        .and_then(|entry| entry.execution_batch.as_ref())
    {
        let entry = staged_merge_entry.expect("the exact execution batch has its owning entry");
        if !crate::merge::merge_execution_batch_commitments_match(batch) {
            return Err(runtime_catalog_invalid(
                "catalog effect has invalid certified execution batch commitments",
            ));
        }
        if batch.application_block_header.height().get() != block_height
            || entry.merge_qc.carrier_height != block_height
            || batch.application_block_header.prev_block_hash()
                != Some(entry.merge_qc.carrier_parent_hash)
            || batch.application_block_header.view_change_index() != entry.merge_qc.view
        {
            return Err(runtime_catalog_invalid(
                "catalog effect differs from its certified application header",
            ));
        }
        // State admission and final commit bind this batch to the exact carrier. Its
        // application header predates the carrier roots and owns incarnation derivation.
        batch.application_block_header.hash()
    } else {
        block_header_hash
    };
    let mut expected_update = prepare_lane_lifecycle_update(
        &prospective_nexus,
        &lane_incarnations,
        &lane_incarnation_lineage,
        &lane_incarnation_activation_heights,
        &self.network_id,
        derivation_header_hash,
        &pending.plan,
        pending.transition_height,
        allow_autoscale_managed_changes,
    )?;
    ensure_runtime_catalog_lanes_preserved(
        &self.world.view(),
        &nexus.lane_catalog,
        &expected_update.updated_catalog,
    )?;
    expected_update.previous_dataspace_catalog = nexus.dataspace_catalog.clone();
    expected_update.updated_dataspace_catalog = prospective_nexus.dataspace_catalog.clone();
    let committed_lane_manifests = if let Some(runtime) = &pending.runtime_catalog {
        Arc::new(
            releases
                .manifests
                .read()
                .with_runtime_additions(
                    &runtime.manifests,
                    &expected_update.updated_catalog,
                    &prospective_nexus.dataspace_catalog,
                    &nexus.governance,
                )
                .map_err(runtime_catalog_invalid)?,
        )
    } else {
        rebind_lane_manifests_for_lifecycle(
            releases.manifests.read().as_ref(),
            &expected_update.updated_catalog,
            &nexus.governance,
        )?
    };
    if committed_lane_manifests.consensus_policy_digest()
        != pending.updated_lane_manifests.consensus_policy_digest()
    {
        return Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
            transition: pending.transition.name(),
            reason: "installed lane manifest policy changed after lifecycle staging",
        });
    }
    pending
        .updated_lane_manifests
        .validate_active_coverage_for_catalog(&expected_update.updated_catalog)
        .map_err(|err| LaneLifecycleError::ManifestPolicyUnavailable {
            lane: err.lane,
            reason: err.message(),
        })?;
    if expected_update.updated_catalog != update.updated_catalog
        || expected_update.updated_dataspace_catalog != update.updated_dataspace_catalog
        || !lane_config_entries_match(
            &expected_update.updated_lane_config,
            &update.updated_lane_config,
        )
        || expected_update.lanes_to_reset != update.lanes_to_reset
        || expected_update.replaced_lane_ids != update.replaced_lane_ids
        || expected_update.updated_lane_incarnations != update.updated_lane_incarnations
        || expected_update.updated_lane_incarnation_lineage
            != update.updated_lane_incarnation_lineage
        || expected_update.updated_lane_incarnation_activation_heights
            != update.updated_lane_incarnation_activation_heights
    {
        return Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
            transition: pending.transition.name(),
            reason: "staged lifecycle update must exactly match the signed plan",
        });
    }
    if allow_autoscale_managed_changes {
        for addition in &pending.plan.additions {
            ensure_autoscale_managed_lane_created_height_is_current(
                addition,
                pending.transition_height,
            )?;
        }
        ensure_autoscale_transition_matches_plan(&pending.plan, &pending.transition)?;
        ensure_autoscale_transition_capacity_matches_nexus(&nexus, &pending.transition)?;
    }
    if let PendingAutoscaleTransition::ScaleIn { lane, .. } = &pending.transition {
        let previous_lane = update
            .previous_catalog
            .lanes()
            .iter()
            .find(|candidate| candidate.id == *lane)
            .ok_or(LaneLifecycleError::InvalidAutoscaleManagedLane {
                lane: *lane,
                reason: "scale-in lane is absent from the previous catalog",
            })?;
        let drain_state = decode_autoscale_lane_drain_state(previous_lane)
            .map_err(|reason| LaneLifecycleError::InvalidAutoscaleManagedLane {
                lane: *lane,
                reason,
            })?
            .ok_or(LaneLifecycleError::UnsafeRetirement {
                lane: *lane,
                reason: "it has no committed drain intent",
            })?;
        let commitment =
            drain_state
                .commitment
                .ok_or(LaneLifecycleError::UnsafeRetirement {
                    lane: *lane,
                    reason: "its drain certificate is not globally committed",
                })?;
        let incarnation = update.previous_lane_incarnations.get(lane).copied().ok_or(
            LaneLifecycleError::InvalidAutoscaleManagedLane {
                lane: *lane,
                reason: "scale-in lane has no committed incarnation",
            },
        )?;
        if !autoscale_lane_drain_state_matches_context(
            previous_lane,
            &drain_state,
            &self.network_id,
            incarnation,
        ) || commitment.carrier_height >= block_height
        {
            return Err(LaneLifecycleError::UnsafeRetirement {
                lane: *lane,
                reason: "its drain commitment is stale or not from an earlier carrier",
            });
        }
        let frontier = Self::evidence_aware_lane_drain_frontier_from_world(
            &self.world.view(),
            &self.kura,
            *lane,
            previous_lane.dataspace_id,
            incarnation,
        )
        .map_err(LaneLifecycleError::DrainObservation)?;
        if frontier != commitment.frontier
            || self
                .lane_has_drain_blocking_evidence_with_releases(
                    *lane,
                    previous_lane.dataspace_id,
                    incarnation,
                    releases,
                )
                .map_err(LaneLifecycleError::DrainObservation)?
        {
            return Err(LaneLifecycleError::UnsafeRetirement {
                lane: *lane,
                reason: "its committed drain frontier or durable evidence differs from replicated state",
            });
        }
    }
    for lane in &pending.plan.retire {
        let dataspace_id = update
            .previous_catalog
            .lanes()
            .iter()
            .find(|entry| entry.id == *lane)
            .map_or(update.previous_routing_policy.default_dataspace, |entry| {
                entry.dataspace_id
            });
        if let Some((expected_height, latest_unmerged_height)) = self
            .unmerged_merge_admissible_relay_progress_with_releases(
                *lane,
                dataspace_id,
                releases,
            )
            && !staged_merge_entry.is_some_and(|entry| {
                entry.lane_snapshots.iter().any(|snapshot| {
                    snapshot.lane_id == *lane
                        && snapshot.dataspace_id == dataspace_id
                        && snapshot.lane_block_height == latest_unmerged_height
                        && snapshot.lane_block_height >= expected_height
                })
            })
        {
            warn!(
                lane = lane.as_u32(),
                dataspace = dataspace_id.as_u64(),
                expected_height,
                latest_unmerged_height,
                "rejecting staged lane retirement because the candidate has unmerged relay progress"
            );
            return Err(LaneLifecycleError::UnsafeRetirement {
                lane: *lane,
                reason: "it has unmerged relay progress",
            });
        }
        if let Some(lane_block_height) = self
            .unapplied_certified_lane_block_height_with_lifecycle(
                *lane,
                dataspace_id,
                &self.lane_consensus_lifecycle_snapshot_with_cursors(
                    &mut releases.shard_cursors,
                ),
            )
            .map_err(|error| LaneLifecycleError::Storage(error.to_string()))?
        {
            warn!(
                lane = lane.as_u32(),
                dataspace = dataspace_id.as_u64(),
                lane_block_height,
                "rejecting staged lane retirement because the candidate has unapplied certified lane-block progress"
            );
            return Err(LaneLifecycleError::UnsafeRetirement {
                lane: *lane,
                reason: "it has unapplied certified lane-block progress",
            });
        }
    }
    for lane in update.updated_catalog.lanes() {
        if prospective_nexus
            .dataspace_catalog
            .by_id(lane.dataspace_id)
            .is_none()
        {
            return Err(LaneLifecycleError::UnknownDataspace(lane.dataspace_id));
        }
    }
    ensure_catalog_autoscale_lanes_consistent(
        &nexus,
        &update.updated_catalog,
        pending.transition_height,
        &BTreeSet::new(),
    )?;
    validate_nexus_routing_policy(
        &nexus.routing_policy,
        &update.updated_catalog,
        &prospective_nexus.dataspace_catalog,
    )
}

pub(crate) fn record_globally_committed_merge_entry(
    &self,
    entry: &MergeLedgerEntry,
    publication_mode: MergeLedgerPublicationMode,
) -> Result<(Arc<MergeLedgerEntry>, Option<PipelineEventBox>), MergeLedgerCommitError> {
    self.ensure_merge_history_available()?;
    let entry_hash = entry.canonical_hash();
    let carrier = self
        .kura
        .merge_carrier_for_entry(entry_hash)?
        .ok_or_else(|| {
            MergeLedgerCommitError::Persistence(crate::kura::Error::MergeCarrierConflict(
                format!("globally committed entry {entry_hash} has no durable carrier"),
            ))
        })?;
    let durable = self
        .kura
        .merge_entry_for_carrier(carrier.block_height, carrier.block_hash)?
        .ok_or_else(|| {
            MergeLedgerCommitError::Persistence(crate::kura::Error::MergeCarrierConflict(
                format!(
                    "carrier {} has no durable full merge entry",
                    carrier.block_height
                ),
            ))
        })?;
    if durable != *entry {
        return Err(MergeLedgerCommitError::Persistence(
            crate::kura::Error::MergeCarrierConflict(
                "durable carrier entry differs from the committed State entry".to_owned(),
            ),
        ));
    }
    // Cache retry callbacks may inspect State again. Keep the original
    // admission release outside both the visibility interval and its fence.
    let mut admission_releases = self.merge_admission.defer_notifications();
    let mut publication_notice = self.state_view_publication();
    let _state_write_lock = self.state_write_lock.lock();
    let committed_carrier_hash = usize::try_from(carrier.block_height)
        .ok()
        .and_then(|height| height.checked_sub(1))
        .and_then(|index| self.block_hashes.view().get(index).copied());
    if committed_carrier_hash != Some(carrier.block_hash) {
        return Err(MergeLedgerCommitError::ExecutionStatePublication(format!(
            "merge carrier {} is durable in Kura but absent from committed State history",
            carrier.block_height
        )));
    }
    let mut admission = admission_releases.write();
    let _view_generation = publication_notice.begin();
    if let Some(latest) = admission.latest_entry() {
        if latest.epoch_id == entry.epoch_id {
            if latest != entry {
                return Err(MergeLedgerCommitError::Persistence(
                    crate::kura::Error::MergeCarrierConflict(format!(
                        "merge admission epoch {} conflicts with its durable carrier",
                        entry.epoch_id
                    )),
                ));
            }
            drop(admission);
            if let Some(existing) = self
                .merge_ledger
                .snapshot()
                .into_iter()
                .find(|candidate| candidate.epoch_id == entry.epoch_id)
            {
                return Ok((existing, None));
            }
            let stored = self.merge_ledger.push(entry.clone());
            let event = publication_mode.emits_live_event().then(|| {
                PipelineEventBox::from(MergeLedgerEvent {
                    entry: stored.as_ref().clone(),
                })
            });
            return Ok((stored, event));
        }
    }
    admission.validate_next(entry)?;
    admission.record(entry);
    drop(admission);
    let stored = self.merge_ledger.push(entry.clone());
    let event = publication_mode.emits_live_event().then(|| {
        PipelineEventBox::from(MergeLedgerEvent {
            entry: stored.as_ref().clone(),
        })
    });
    Ok((stored, event))
}

fn certified_lane_block_persistence_authority(
    &self,
    proposal: &iroha_data_model::block::consensus::LaneBlockProposalV1,
    cursors: &mut crate::publication_rwlock::DeferredPublicationRwLock<'_, DaShardCursorIndex>,
) -> core::result::Result<CertifiedLaneBlockPersistenceAuthority, &'static str> {
    let descriptor = &proposal.descriptor;
    let lifecycle = self.lane_consensus_lifecycle_snapshot_with_cursors(cursors);
    if !lifecycle.lane_route_and_incarnation_matches(
        descriptor.lane_id,
        descriptor.dataspace_id,
        descriptor.proposal_height,
        descriptor.lane_incarnation,
    ) {
        return Err("certified lane block proposal is outside the committed lane lifecycle");
    }
    let authority = lifecycle
        .certified_lane_block_persistence_authority(descriptor.lane_id, descriptor.dataspace_id)
        .ok_or("certified lane block lane has no committed incarnation")?;
    authority
        .authorizes_proposal(proposal)
        .then_some(authority)
        .ok_or("certified lane block proposal is not visible after the canonical reset")
}

pub(crate) fn persist_committed_lane_block_session_lifecycle_bound(
    &self,
    session: &crate::lane_consensus::CommittedLaneBlockSession,
    signer_pops: &BTreeMap<PublicKey, Vec<u8>>,
) -> core::result::Result<(), String> {
    // Every production lifecycle publisher takes this same lock before it
    // opens an odd state-view generation.  Holding it across authority
    // derivation and Kura publication prevents a copied reset watermark
    // from outliving the committed lifecycle which authorized it.
    let mut cursor_releases = self.da_shard_cursors.defer_notifications();
    let _state_write_lock = self.state_write_lock.lock();
    let generation = self.state_view_generation();
    if generation % 2 != 0 {
        return Err(
            "cannot persist a lane certificate during an active State publication".to_owned(),
        );
    }
    let authority = self
        .certified_lane_block_persistence_authority(&session.proposal, &mut cursor_releases)
        .map_err(str::to_owned)?;
    self.kura
        .persist_committed_lane_block_session_with_authority(session, signer_pops, &authority)
        .map_err(|error| error.to_string())?;
    if self.state_view_generation() != generation {
        return Err(
            "State lifecycle generation changed under lane certificate persistence lock"
                .to_owned(),
        );
    }
    Ok(())
}

pub(crate) fn latest_certified_lane_block_frontier_sessions_snapshot_cached(
    &self,
) -> Vec<crate::lane_consensus::CommittedLaneBlockSession> {
    // Serialize the complete read-only multi-route projection with
    // lifecycle publication so route authority cannot change mid-snapshot.
    let mut cursor_releases = self.da_shard_cursors.defer_notifications();
    let _state_write_lock = self.state_write_lock.lock();
    let lifecycle = self.lane_consensus_lifecycle_snapshot_with_cursors(&mut cursor_releases);
    let mut sessions = Self::lane_block_artifact_routes(&lifecycle.nexus)
        .into_iter()
        .filter_map(|(lane_id, dataspace_id)| {
            let authority =
                lifecycle.certified_lane_block_persistence_authority(lane_id, dataspace_id)?;
            let (artifact, _) = self
                .kura
                .preflight_latest_certified_lane_block_frontier_with_authority(
                    lane_id, &authority,
                )
                .ok()??;
            let descriptor = &artifact.proposal.descriptor;
            (descriptor.dataspace_id == dataspace_id
                && lifecycle.lane_route_and_incarnation_matches(
                    lane_id,
                    dataspace_id,
                    descriptor.proposal_height,
                    descriptor.lane_incarnation,
                ))
            .then_some(crate::lane_consensus::CommittedLaneBlockSession {
                proposal: artifact.proposal,
                prepare_qc: artifact.prepare_qc,
                commit_qc: artifact.commit_qc,
            })
        })
        .collect::<Vec<_>>();
    sessions.sort_by_key(|session| {
        let descriptor = &session.proposal.descriptor;
        (
            descriptor.lane_id,
            descriptor.dataspace_id,
            descriptor.proposal_height,
            descriptor.lane_block_height,
            descriptor.lane_block_view,
        )
    });
    sessions
}

pub(crate) fn lane_application_certified_repair_snapshot_cached(
    &self,
    capacity: usize,
) -> Result<LaneApplicationCertifiedRepairSnapshot, MergeLedgerCommitError> {
    if capacity == 0 {
        return Err(MergeLedgerCommitError::ExecutionMarkerConflict(
            "ordinary lane receipt startup repair has zero capacity".to_owned(),
        ));
    }
    let mut cursor_releases = self.da_shard_cursors.defer_notifications();
    let _state_write_lock = self.state_write_lock.lock();
    let lifecycle = self.lane_consensus_lifecycle_snapshot_with_cursors(&mut cursor_releases);
    let routes = Self::lane_block_artifact_routes(&lifecycle.nexus);
    if routes.len() > capacity {
        return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(
            "ordinary lane receipt startup repair has {} active routes; capacity is {capacity}",
            routes.len()
        )));
    }
    let mut frontiers = Vec::new();
    let mut pair_repairs = Vec::new();
    for (lane_id, dataspace_id) in routes {
        let authority = lifecycle
            .certified_lane_block_persistence_authority(lane_id, dataspace_id)
            .ok_or_else(|| {
                MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                    "ordinary certified lane {} has no committed incarnation",
                    lane_id.as_u32()
                ))
            })?;
        let Some((artifact, pair_repair_required)) = self
            .kura
            .preflight_latest_certified_lane_block_frontier_with_authority(lane_id, &authority)
            .map_err(|error| {
                MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                    "ordinary certified lane {} read-only frontier preflight failed: {error}",
                    lane_id.as_u32()
                ))
            })?
        else {
            continue;
        };
        let descriptor = &artifact.proposal.descriptor;
        if descriptor.dataspace_id != dataspace_id
            || !lifecycle.lane_route_and_incarnation_matches(
                lane_id,
                dataspace_id,
                descriptor.proposal_height,
                descriptor.lane_incarnation,
            )
        {
            return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                "ordinary certified lane {} frontier is outside its active route",
                lane_id.as_u32()
            )));
        }
        if pair_repair_required {
            pair_repairs.push(artifact.clone());
        }
        if let Some(session) = Self::ordinary_application_receipt_repair_session(artifact) {
            frontiers.push(session);
        }
    }
    let mut earliest = Vec::new();
    let mut traversed_total = 0_usize;
    for mut session in frontiers {
        if self.certified_lane_block_session_is_applied_or_snapshot_anchored(&session)? {
            continue;
        }
        let mut traversed = 0_usize;
        loop {
            let descriptor = &session.proposal.descriptor;
            if descriptor.lane_block_height == 0
                || !lifecycle.lane_route_and_incarnation_matches(
                    descriptor.lane_id,
                    descriptor.dataspace_id,
                    descriptor.proposal_height,
                    descriptor.lane_incarnation,
                )
                || (descriptor.previous_lane_block_height == 0)
                    != descriptor.previous_lane_block_descriptor_hash.is_none()
                || (descriptor.lane_block_height == 1)
                    != (descriptor.previous_lane_block_height == 0)
                || (descriptor.lane_block_height > 1
                    && descriptor.previous_lane_block_height.checked_add(1)
                        != Some(descriptor.lane_block_height))
            {
                return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                    "ordinary certified lane route {} contains a stale, ABA, or non-contiguous descriptor",
                    descriptor.lane_id.as_u32()
                )));
            }
            if self.certified_lane_block_predecessor_is_applied_or_snapshot_anchored(
                &session.proposal,
            )? {
                break;
            }
            traversed = traversed.saturating_add(1);
            traversed_total = traversed_total.saturating_add(1);
            if traversed > capacity || traversed_total > capacity {
                return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                    "ordinary certified lane route {} predecessor walk exceeds startup capacity {capacity}",
                    descriptor.lane_id.as_u32()
                )));
            }
            let previous_height = descriptor.previous_lane_block_height;
            let previous_hash =
                descriptor
                    .previous_lane_block_descriptor_hash
                    .ok_or_else(|| {
                        MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                            "ordinary certified lane route {} lost its predecessor descriptor",
                            descriptor.lane_id.as_u32()
                        ))
                    })?;
            let previous = self
                .kura
                .read_certified_lane_block_artifact_read_only(
                    descriptor.lane_id,
                    previous_height,
                )
                .map_err(|error| {
                    MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                        "ordinary certified lane {} predecessor read-only lookup failed: {error}",
                        descriptor.lane_id.as_u32()
                    ))
                })?
                .ok_or_else(|| {
                    MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                        "ordinary certified lane route {} is missing predecessor height {previous_height}",
                        descriptor.lane_id.as_u32()
                    ))
                })?;
            let previous_descriptor = &previous.proposal.descriptor;
            if previous_descriptor.lane_id != descriptor.lane_id
                || previous_descriptor.dataspace_id != descriptor.dataspace_id
                || previous_descriptor.lane_incarnation != descriptor.lane_incarnation
                || previous_descriptor.lane_block_height != previous_height
                || previous_descriptor.descriptor_hash != previous_hash
                || previous_descriptor.proposal_height >= descriptor.proposal_height
                || !lifecycle.lane_route_and_incarnation_matches(
                    previous_descriptor.lane_id,
                    previous_descriptor.dataspace_id,
                    previous_descriptor.proposal_height,
                    previous_descriptor.lane_incarnation,
                )
            {
                return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                    "ordinary certified lane route {} predecessor is conflicting or stale",
                    descriptor.lane_id.as_u32()
                )));
            }
            let route_lane_id = descriptor.lane_id;
            session = crate::lane_consensus::CommittedLaneBlockSession {
                proposal: previous.proposal,
                prepare_qc: previous.prepare_qc,
                commit_qc: previous.commit_qc,
            };
            if self.certified_lane_block_session_is_applied_or_snapshot_anchored(&session)? {
                return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                    "ordinary certified lane route {} selected an already-applied predecessor",
                    route_lane_id.as_u32()
                )));
            }
        }
        earliest.push(session);
    }
    earliest.sort_by_key(|session| {
        let descriptor = &session.proposal.descriptor;
        (
            descriptor.lane_id,
            descriptor.dataspace_id,
            descriptor.lane_incarnation,
            descriptor.lane_block_height,
            descriptor.lane_block_view,
        )
    });
    pair_repairs.sort_by_key(|artifact| {
        let descriptor = &artifact.proposal.descriptor;
        (
            descriptor.lane_id,
            descriptor.dataspace_id,
            descriptor.lane_incarnation,
            descriptor.lane_block_height,
            descriptor.lane_block_view,
        )
    });
    Ok(LaneApplicationCertifiedRepairSnapshot {
        pair_repairs,
        earliest_unapplied: earliest,
    })
}

fn merge_consensus_snapshot_inner(
    &self,
    entry: Option<&MergeLedgerEntry>,
) -> Result<MergeConsensusSnapshot, MergeLedgerCommitError> {
    let mut releases = LaneLifecycleReleases::new(self);
    self.merge_consensus_snapshot_inner_with_releases(entry, &mut releases)
}

fn merge_consensus_snapshot_inner_with_releases(
    &self,
    entry: Option<&MergeLedgerEntry>,
    releases: &mut LaneLifecycleReleases<'_>,
) -> Result<MergeConsensusSnapshot, MergeLedgerCommitError> {
    loop {
        let generation_before = self.state_view_generation();
        if generation_before % 2 != 0 {
            std::thread::yield_now();
            continue;
        }
        let (committed_height, latest_block_hash) = {
            let block_hashes = self.block_hashes.view_retaining(&mut releases.hashes);
            (
                u64::try_from(block_hashes.len()).unwrap_or(u64::MAX),
                block_hashes.last().copied(),
            )
        };
        let nexus = self.nexus_snapshot();
        let incarnations = self.lane_incarnations_snapshot();
        let activation_heights = self.lane_incarnation_activation_heights_snapshot();
        let mut reset_heights = releases
            .shard_cursors
            .read()
            .canonical_reset_heights()
            .clone();
        for (lane_id, activation_height) in &activation_heights {
            if *activation_height == 0 {
                continue;
            }
            reset_heights
                .entry(*lane_id)
                .and_modify(|height| *height = (*height).max(*activation_height))
                .or_insert(*activation_height);
        }
        let (admission, admission_validation) = {
            let admission = releases.merge_admission.read();
            let validation = entry.map(|entry| admission.validate_next(entry));
            (admission.snapshot(), validation)
        };
        let generation_after = self.state_view_generation();
        if is_stable_state_view_generation(generation_before, generation_after) {
            if let Some(validation) = admission_validation {
                validation?;
            }
            return Ok(MergeConsensusSnapshot {
                generation: generation_after,
                lifecycle: LaneConsensusLifecycleSnapshot {
                    nexus,
                    incarnations,
                    activation_heights,
                    reset_heights,
                },
                admission,
                committed_height,
                latest_block_hash,
            });
        }
        std::thread::yield_now();
    }
}

fn unmerged_merge_admissible_relay_progress_with_releases(
    &self,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    releases: &mut LaneLifecycleReleases<'_>,
) -> Option<(u64, u64)> {
    if self.ensure_merge_history_available().is_err() {
        return None;
    }
    let consensus = self
        .merge_consensus_snapshot_inner_with_releases(None, releases)
        .expect("merge snapshot without entry validation cannot fail");
    let lifecycle = &consensus.lifecycle;
    let lane_incarnation = lifecycle.incarnations.get(&lane_id).copied()?;
    let expected_height = expected_next_merge_lane_height(
        &consensus.admission.latest_lane_snapshots,
        lane_id,
        dataspace_id,
        lane_incarnation,
    )?;
    let relays = releases.relays.read().snapshot();
    let latest_unmerged_height = relays
        .into_iter()
        .filter(|relay| {
            let proposal_height = relay.block_header.height().get();
            relay.lane_id == lane_id
                && relay.dataspace_id == dataspace_id
                && relay.has_merge_admission_material()
                && self.verify_lane_relay_fastpq_record(relay).is_ok()
                && relay.lane_incarnation == lane_incarnation
                && lifecycle.lane_route_and_incarnation_matches(
                    lane_id,
                    dataspace_id,
                    proposal_height,
                    lane_incarnation,
                )
        })
        .map(|relay| relay.block_height)
        .filter(|height| *height >= expected_height)
        .max()?;
    Some((expected_height, latest_unmerged_height))
}

pub(crate) fn lane_has_drain_blocking_evidence(
    &self,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    lane_incarnation: Hash,
) -> Result<bool, MergeLedgerCommitError> {
    let mut releases = LaneLifecycleReleases::new(self);
    self.lane_has_drain_blocking_evidence_with_releases(
        lane_id,
        dataspace_id,
        lane_incarnation,
        &mut releases,
    )
}

fn pending_queue_plan_admission_blocks_lane_drain_with_releases(
    &self,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    lane_incarnation: Hash,
    releases: &mut LaneLifecycleReleases<'_>,
) -> Result<bool, MergeLedgerCommitError> {
    let pending = self
        .kura
        .pending_queue_plan_admission_certificates_bounded(
            self.kura.pending_queue_plan_admission_capacity(),
        )?;
    let carrier_height = u64::try_from(self.committed_height())
        .ok()
        .and_then(|height| height.checked_add(1))
        .ok_or_else(|| {
            MergeLedgerCommitError::ExecutionMarkerConflict(
                "lane drain observation carrier height overflow".to_owned(),
            )
        })?;
    for (_, bytes) in pending {
        let admission = self.authenticate_pending_queue_plan_admission(&bytes)?;
        let disposition = {
            let state_view = self.view_with_index_releases(releases);
            Self::classify_pending_queue_plan_admission_in_view(
                &state_view,
                &admission,
                carrier_height,
            )?
        };
        if matches!(
            disposition,
            PendingQueuePlanAdmissionDisposition::ExactPending
                | PendingQueuePlanAdmissionDisposition::Applied
                | PendingQueuePlanAdmissionDisposition::DefinitiveConflict
                | PendingQueuePlanAdmissionDisposition::Stale
        ) {
            continue;
        }
        if admission
            .certificate
            .binding
            .admission_context
            .route_incarnations
            .iter()
            .any(|bound| {
                bound.leg.route.lane_id == lane_id
                    && bound.leg.route.dataspace_id == dataspace_id
                    && bound.lane_incarnation == lane_incarnation
            })
        {
            return Ok(true);
        }
    }
    Ok(false)
}

fn view_with_index_releases(&self, releases: &mut LaneLifecycleReleases<'_>) -> StateView<'_> {
    loop {
        if let Some(view) = self
            .try_view_once_with_index_releases(
                &mut releases.header,
                &mut releases.manifests,
                &mut releases.sccp,
                &mut releases.hashes,
                &mut releases.membership,
            )
            .expect("persisted canonical runtime projection must be valid")
        {
            return view;
        }
        self.note_view_generation_contention(core::panic::Location::caller());
        std::thread::yield_now();
    }
}

fn try_view_once_with_index_releases(
    &self,
    header: &mut crate::publication_rwlock::DeferredPublicationRwLock<'_, Option<BlockHeader>>,
    manifests: &mut crate::publication_rwlock::DeferredPublicationRwLock<
        '_,
        LaneManifestRegistryHandle,
    >,
    sccp: &mut crate::publication_lock::DeferredPublicationFence<'_, SccpRegistryCache>,
    hashes: &mut Option<concread::release::DeferredReleaseBatch>,
    membership: &mut concread::release::DeferredReleaseBatch,
) -> Result<Option<StateView<'_>>, LaneLifecycleError> {
    const STATE_VIEW_LOG_THRESHOLD: Duration = Duration::from_millis(10);
    let caller = core::panic::Location::caller();
    let total_start = Instant::now();
    {
        let generation_before = self.state_view_generation();
        if generation_before % 2 != 0 {
            return Ok(None);
        }
        let block_hashes_start = Instant::now();
        let block_hashes = self.block_hashes.view_retaining(hashes);
        let block_hashes_wait = block_hashes_start.elapsed();
        let latest_hash = block_hashes.last().copied();
        let cached_header = header.read().clone();
        let query_ledger_time_ms =
            self.latest_block_creation_time_ms_from_header(latest_hash, cached_header.as_ref());
        let nexus_start = Instant::now();
        let canonical_runtime = self.canonical_runtime.view();
        let canonical_runtime_predecessor = self.canonical_runtime.predecessor_view();
        let nexus_wait = nexus_start.elapsed();
        let world_start = Instant::now();
        let mut world = self.world.view();
        let baseline = manifests.read().clone();
        let projection = self.project_canonical_runtime_with_manifests(
            canonical_runtime.get(),
            &world,
            &baseline,
        );
        let world_wait = world_start.elapsed();
        let transactions_start = Instant::now();
        let transactions = self
            .transactions
            .view_retaining(membership)
            .expect("original membership reader source must be healthy");
        let transactions_wait = transactions_start.elapsed();
        let commit_topology_start = Instant::now();
        let commit_topology = self.commit_topology.view();
        let commit_topology_wait = commit_topology_start.elapsed();
        let prev_commit_topology_start = Instant::now();
        let prev_commit_topology = self.prev_commit_topology.view();
        let lane_consensus_contexts = self.lane_consensus_contexts.view().get().clone();
        let prev_commit_topology_wait = prev_commit_topology_start.elapsed();
        let sccp_registry = Self::sccp_registry_snapshot_from_cache(
            world.sccp_registry.get(),
            &mut sccp.lock(),
        );
        let generation_after = self.state_view_generation();
        if !is_stable_state_view_generation(generation_before, generation_after) {
            drop(prev_commit_topology);
            drop(commit_topology);
            drop(transactions);
            drop(world);
            return Ok(None);
        }
        let projection = projection?;
        let canonical_runtime::CanonicalRuntimeProjection {
            nexus,
            incarnations: lane_incarnations,
            activation_heights: lane_incarnation_activation_heights,
            lineage: lane_incarnation_lineage,
            samples: _,
            manifests: lane_manifests,
            privacy: _,
        } = projection;
        world.dataspace_catalog = nexus.dataspace_catalog.clone();
        let total_wait = total_start.elapsed();
        let (mut max_component, mut max_wait) = ("block_hashes", block_hashes_wait);
        if world_wait > max_wait {
            max_component = "world";
            max_wait = world_wait;
        }
        if transactions_wait > max_wait {
            max_component = "transactions";
            max_wait = transactions_wait;
        }
        if commit_topology_wait > max_wait {
            max_component = "commit_topology";
            max_wait = commit_topology_wait;
        }
        if prev_commit_topology_wait > max_wait {
            max_component = "prev_commit_topology";
            max_wait = prev_commit_topology_wait;
        }
        if nexus_wait > max_wait {
            max_component = "nexus";
            max_wait = nexus_wait;
        }
        if max_wait >= STATE_VIEW_LOG_THRESHOLD {
            debug!(
                caller = %caller,
                max_component,
                max_wait_us = max_wait.as_micros(),
                total_wait_us = total_wait.as_micros(),
                block_hashes_wait_us = block_hashes_wait.as_micros(),
                world_wait_us = world_wait.as_micros(),
                transactions_wait_us = transactions_wait.as_micros(),
                commit_topology_wait_us = commit_topology_wait.as_micros(),
                prev_commit_topology_wait_us = prev_commit_topology_wait.as_micros(),
                nexus_wait_us = nexus_wait.as_micros(),
                state_view_generation = generation_after,
                "state view acquisition slow or retried"
            );
        }
        return Ok(Some(StateView {
            canonical_runtime,
            canonical_runtime_predecessor,
            world,
            block_hashes,
            merge_ledger: &self.merge_ledger,
            transactions,
            commit_topology,
            prev_commit_topology,
            lane_consensus_contexts,
            ivm: &self.ivm,
            pipeline_ivm_prepared_cache: self.pipeline_ivm_prepared_cache.read().clone(),
            da_receipt_cursors: &self.da_receipt_cursors,
            da_shard_cursors: &self.da_shard_cursors,
            kura: &self.kura,
            query_handle: &self.query_handle,
            query_ledger_time_ms,
            accounts_snapshot_cache: SyncOnceCell::new(),
            #[cfg(feature = "telemetry")]
            telemetry: &self.telemetry,
            pipeline: self.pipeline.clone(),
            oracle: self.oracle.clone(),
            crypto: self.crypto(),
            nexus,
            lane_incarnations,
            lane_incarnation_lineage,
            lane_incarnation_activation_heights,
            lane_manifests,
            fraud_monitoring: self.fraud_monitoring.clone(),
            zk: self.zk.clone(),
            sccp_registry,
            gov: self.gov.clone(),
            content: self.content.clone(),
            settlement: self.settlement.clone(),
            kagemusha_v1_runtime_verifier: Arc::clone(&self.kagemusha_v1_runtime_verifier),
            settlement_engine: self.settlement_engine.clone(),
            chain_id: self.chain_id.clone(),
            network_id: self.network_id,
            created_at: Instant::now(),
        }));
    }
}

pub fn latest_block_creation_time_ms_fast(&self) -> Option<u64> {
    let latest_hash = self.latest_block_hash_fast();
    let cached_header = self.latest_block_header.read().clone();
    self.latest_block_creation_time_ms_from_header(latest_hash, cached_header.as_ref())
}

fn latest_block_creation_time_ms_from_header(
    &self,
    latest_hash: Option<HashOf<BlockHeader>>,
    cached_header: Option<&BlockHeader>,
) -> Option<u64> {
    let cached = cached_header
        .filter(|header| Some(header.hash()) == latest_hash)
        .map(|header| u64::try_from(header.creation_time().as_millis()).unwrap_or(u64::MAX));
    cached.or_else(|| {
        let anchor = self
            .authenticated_snapshot_v2_bootstrap
            .as_ref()?
            .context
            .snapshot_bootstrap
            .as_ref()?;
        (Some(anchor.snapshot_block_hash) == latest_hash)
            .then_some(anchor.snapshot_block_creation_time_ms)
    })
}

fn sccp_registry_snapshot_from_world(
    &self,
    wire: &SccpOnChainRegistryV1,
) -> Arc<ValidatedSccpRegistryV1> {
    let mut cache = self.sccp_registry_cache.lock();
    Self::sccp_registry_snapshot_from_cache(wire, &mut cache)
}

fn sccp_registry_snapshot_from_cache(
    wire: &SccpOnChainRegistryV1,
    cache: &mut SccpRegistryCache,
) -> Arc<ValidatedSccpRegistryV1> {
    if cache.matches(wire) {
        return Arc::clone(&cache.registry);
    }
    let registry = ValidatedSccpRegistryV1::try_from_wire(wire.clone()).unwrap_or_else(
        |error| {
            panic!(
                "consensus SCCP registry invariant violated after admission or snapshot validation: {error}"
            )
        },
    );
    cache.registry = Arc::clone(&registry);
    registry
}

fn native_amx_participant_application_snapshot_with_lifecycle(
    &self,
    lifecycle: &LaneConsensusLifecycleSnapshot,
) -> Result<NativeAmxParticipantApplicationSnapshot, MergeLedgerCommitError> {
    use crate::kura::NativeAmxParticipantApplicationObservation;

    let world = self.world.view();
    let mut snapshot = NativeAmxParticipantApplicationSnapshot::default();
    for lane in lifecycle.nexus.lane_catalog.lanes() {
        let incarnation = lifecycle
            .incarnations
            .get(&lane.id)
            .copied()
            .ok_or_else(|| {
                MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                    "active Native AMX participant route {} has no incarnation",
                    lane.id.as_u32(),
                ))
            })?;
        // Read before marker filtering: a valid pending carrier may be
        // durable before its replicated frontier is visible in this State.
        let history = self
            .kura
            .consensus_storage_read(
                self.kura
                    .read_native_amx_participant_application_history(lane.id),
            )
            .map_err(MergeLedgerCommitError::Persistence)?;
        let marker = Self::canonical_native_amx_participant_frontier_from_world(
            &world,
            lane.id,
            lane.dataspace_id,
            incarnation,
        )?;
        if let Some(marker) = marker {
            if !lifecycle.lane_route_and_incarnation_matches(
                lane.id,
                lane.dataspace_id,
                marker.application_block_height,
                incarnation,
            ) {
                return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                    "Native AMX participant frontier for lane {} is stale at application height {}",
                    lane.id.as_u32(),
                    marker.application_block_height,
                )));
            }
        }
        if let Some(marker) = marker {
            Self::validate_native_amx_participant_shared_frontier(&world, &marker)?;
        }
        let route = (lane.id, lane.dataspace_id);
        for (height, observation) in history.entries() {
            let (
                observed_lane,
                observed_dataspace,
                observed_incarnation,
                application_height,
                marker_matches,
            ) = match observation {
                NativeAmxParticipantApplicationObservation::Applied(receipt)
                | NativeAmxParticipantApplicationObservation::PendingTipMetadata(receipt)
                | NativeAmxParticipantApplicationObservation::PendingManifestRepair(receipt) => {
                    let descriptor = &receipt.participant_proposal.descriptor;
                    (
                        descriptor.lane_id,
                        descriptor.dataspace_id,
                        descriptor.lane_incarnation,
                        receipt.application_block_height,
                        marker.is_none_or(|marker| {
                            marker.lane_block_height != height
                                || Self::native_amx_participant_receipt_matches_frontier(
                                    receipt, marker,
                                )
                        }),
                    )
                }
                NativeAmxParticipantApplicationObservation::PendingReceiptRepair(manifest) => {
                    let leaf = &manifest.leaf;
                    (leaf.lane_id, leaf.dataspace_id, leaf.lane_incarnation,
                        leaf.application_block_height, marker.is_none_or(|marker| {
                            marker.lane_block_height != height
                                || crate::kura::Kura::native_amx_manifest_leaf_matches_frontier_marker(leaf, &marker)
                        }))
                }
            };
            if observed_lane != lane.id
                || observed_dataspace != lane.dataspace_id
                || observed_incarnation != incarnation
                || !lifecycle.lane_route_and_incarnation_matches(
                    observed_lane,
                    observed_dataspace,
                    application_height,
                    observed_incarnation,
                )
            {
                return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                    "Native AMX durable history for lane {} disagrees with the active State route at height {height}",
                    lane.id.as_u32(),
                )));
            }
            if !marker_matches {
                return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                    "Native AMX durable evidence conflicts with its replicated frontier for lane {} height {height}",
                    lane.id.as_u32(),
                )));
            }
            if !matches!(
                observation,
                NativeAmxParticipantApplicationObservation::Applied(_)
            ) || marker.is_none_or(|marker| height > marker.lane_block_height)
            {
                snapshot
                    .blocked
                    .entry(route)
                    .and_modify(|blocked| *blocked = (*blocked).max(height))
                    .or_insert(height);
            } else {
                snapshot.applied_slots.insert((
                    lane.id,
                    lane.dataspace_id,
                    incarnation,
                    height,
                ));
            }
        }
        let Some(marker) = marker else {
            continue;
        };
        if matches!(
            history.get(marker.lane_block_height),
            Some(NativeAmxParticipantApplicationObservation::Applied(_))
        ) {
            snapshot.applied.push(marker);
        } else {
            snapshot.repair.push(marker);
            snapshot
                .blocked
                .entry(route)
                .and_modify(|blocked| *blocked = (*blocked).max(marker.lane_block_height))
                .or_insert(marker.lane_block_height);
        }
    }
    Ok(snapshot)
}

