fn unapplied_certified_lane_block_height_with_lifecycle(
    &self,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    lifecycle: &LaneConsensusLifecycleSnapshot,
) -> Result<Option<u64>, MergeLedgerCommitError> {
    let Some(artifact) = self
        .kura
        .latest_certified_lane_block_artifact_matching(lane_id, |artifact| {
            let descriptor = &artifact.proposal.descriptor;
            descriptor.dataspace_id == dataspace_id
                && lifecycle.lane_route_and_incarnation_matches(
                    lane_id,
                    dataspace_id,
                    descriptor.proposal_height,
                    descriptor.lane_incarnation,
                )
        })
        .map_err(|error| {
            MergeLedgerCommitError::ExecutionMarkerConflict(format!(
                "certified lane retirement frontier read failed: {error}"
            ))
        })?
    else {
        return Ok(None);
    };
    let height = artifact.proposal.descriptor.lane_block_height;
    Ok(
        (!self.certified_lane_block_artifact_is_applied_or_snapshot_anchored(&artifact)?)
            .then_some(height),
    )
}

fn resume_lane_geometry_publication(
    &self,
    request: &crate::kura::ReplayGeometryBindingRequest<'_>,
    replaced: &BTreeSet<LaneId>,
    certified: &BTreeMap<(LaneId, DataSpaceId, Hash), LaneDrainFrontierV1>,
    mut startup: Option<&mut crate::kura::StartupReplayGeometryTransition>,
    mut releases: Option<&mut LaneLifecycleReleases<'_>>,
) -> Result<(), LaneLifecycleError> {
    let publish_cursors = releases.is_some();
    let mut slot = self.geometry_publication.lock();
    if let Some(original) = slot.as_ref() {
        let startup_matches = match (&original.startup_owner, startup.as_deref()) {
            (None, None) => true,
            (Some(owner), Some(transition)) => {
                Arc::ptr_eq(owner, &transition.original_owner_identity())
            }
            _ => false,
        };
        if original.publish_cursors != publish_cursors
            || !lane_config_entries_match(&original.previous, request.previous)
            || !lane_config_entries_match(&original.current, request.updated)
            || original.previous_incarnations != *request.previous_incarnations
            || original.current_incarnations != *request.updated_incarnations
            || original.previous_activation_heights != *request.previous_activation_heights
            || original.current_activation_heights != *request.updated_activation_heights
            || original.previous_lineage_root != request.previous_lineage_root
            || original.current_lineage_root != request.updated_lineage_root
            || original.transition_height != request.transition_height
            || original.replaced != *replaced
            || original.certified != *certified
            || !startup_matches
            || original
                .raw
                .as_ref()
                .is_some_and(|raw| !raw.matches_request(request, replaced, certified))
        {
            return Err(LaneLifecycleError::Storage(
                "another exact lane geometry operation is already retained".to_owned(),
            ));
        }
    } else {
        if startup.is_some() && !certified.is_empty() {
            return Err(LaneLifecycleError::Storage(
                "startup replay cannot replace live certified drain ownership".to_owned(),
            ));
        }
        *slot = Some(LaneGeometryPublication {
            raw: None,
            tiered: None,
            certified: certified.clone(),
            startup_owner: startup
                .as_deref()
                .map(|transition| transition.original_owner_identity()),
            startup_attached: false,
            previous: request.previous.clone(),
            current: request.updated.clone(),
            previous_incarnations: request.previous_incarnations.clone(),
            current_incarnations: request.updated_incarnations.clone(),
            previous_activation_heights: request.previous_activation_heights.clone(),
            current_activation_heights: request.updated_activation_heights.clone(),
            previous_lineage_root: request.previous_lineage_root,
            current_lineage_root: request.updated_lineage_root,
            replaced: replaced.clone(),
            transition_height: request.transition_height,
            cursors_updated: false,
            publish_cursors,
        });
    }
    let original = slot.as_mut().ok_or_else(|| {
        LaneLifecycleError::Storage("lane geometry operation was not installed".to_owned())
    })?;
    if original.tiered.is_none() {
        let diff = lane_topology_diff(request.previous, request.updated, replaced);
        original.tiered = Some(
            self.tiered_backend
                .lock()
                .prepare_lane_geometry_attempt(
                    request.previous,
                    request.updated,
                    &diff.replacements,
                    &diff.relabelled,
                )
                .map_err(|error| {
                    LaneLifecycleError::Storage(format!("tiered preparation: {error:#}"))
                })?,
        );
    }
    if original.raw.is_none() {
        let lease = self
            .kura
            .try_publication_lease()
            .map_err(geometry_lease_error)?;
        original.raw = Some(
            lease
                .begin_raw_geometry_attempt(request, replaced, certified)
                .map_err(LaneLifecycleError::GeometryStorage)?,
        );
    }
    let raw = original.raw.as_mut().ok_or_else(|| {
        LaneLifecycleError::Storage("missing retained raw geometry owner".to_owned())
    })?;
    if !original.startup_attached {
        if let Some(startup) = startup.as_deref_mut() {
            raw.attach_startup_transition(startup)
                .map_err(LaneLifecycleError::GeometryStorage)?;
        }
        original.startup_attached = true;
    }
    // Catalog retry must not send an already chosen publication direction
    // through apply again. Its completed tiered plan is retained too.
    if !matches!(
        raw.phase(),
        crate::kura::RawGeometryPhase::PublishingCatalog
            | crate::kura::RawGeometryPhase::CatalogPublished
    ) {
        let lease = self
            .kura
            .try_publication_lease()
            .map_err(geometry_lease_error)?;
        raw.resume_under(&lease)
            .map_err(LaneLifecycleError::GeometryStorage)?;
    }
    original
        .tiered
        .as_mut()
        .ok_or_else(|| {
            LaneLifecycleError::Storage("missing retained tiered geometry owner".to_owned())
        })?
        .resume(&mut self.tiered_backend.lock())
        .map_err(|error| {
            LaneLifecycleError::Storage(format!("retained tiered geometry: {error:#}"))
        })?;
    if !original.cursors_updated {
        if let Some(releases) = releases.as_mut() {
            releases.shard_cursors.write().sync_mapping(request.updated);
            let should_persist = releases.hydrated.read().is_some();
            original.cursors_updated = true;
            if should_persist {
                self.persist_lane_lifecycle_cursor_journal(releases);
            }
        } else {
            // Replay geometry has no authority to publish live cursor indexes.
            original.cursors_updated = true;
        }
    }
    Ok(())
}

fn rollback_owned_lane_geometry(
    &self,
    previous: &LaneConfig,
    current: &LaneConfig,
    incarnations: &BTreeMap<LaneId, Hash>,
    activation_heights: &BTreeMap<LaneId, u64>,
    lineage_root: Hash,
    replaced: &BTreeSet<LaneId>,
    transition_height: u64,
    releases: &mut LaneLifecycleReleases<'_>,
) -> Result<(), LaneLifecycleError> {
    let mut slot = self.geometry_publication.lock();
    let original = slot.as_mut().ok_or_else(|| {
        LaneLifecycleError::Storage(
            "rollback requires the original retained geometry operation".to_owned(),
        )
    })?;
    if !lane_config_entries_match(&original.previous, previous)
        || !lane_config_entries_match(&original.current, current)
        || original.previous_incarnations != *incarnations
        || original.previous_activation_heights != *activation_heights
        || original.previous_lineage_root != lineage_root
        || original.replaced != *replaced
        || original.transition_height != transition_height
        || original.startup_owner.is_some()
    {
        return Err(LaneLifecycleError::Storage(
            "rollback differs from its original geometry owner".to_owned(),
        ));
    }
    if let Some(error) = original.raw.as_ref().and_then(|raw| raw.recovery_refusal()) {
        return Err(LaneLifecycleError::GeometryStorage(error));
    }
    // Finish a pending apply write before choosing reversal; the raw owner
    // refuses to switch direction while that exact write remains unsettled.
    if original.raw.as_ref().is_some_and(|raw| {
        raw.has_pending_journal_write()
            && raw.phase() != crate::kura::RawGeometryPhase::RollingBack
    }) {
        return Err(LaneLifecycleError::Storage(
            "original geometry write must finish before rollback".to_owned(),
        ));
    }
    if let Some(tiered) = original.tiered.as_mut() {
        tiered
            .rollback(&mut self.tiered_backend.lock())
            .map_err(|error| {
                LaneLifecycleError::Storage(format!("retained tiered rollback: {error:#}"))
            })?;
    }
    if let Some(raw) = original.raw.as_mut() {
        let lease = self
            .kura
            .try_publication_lease()
            .map_err(geometry_lease_error)?;
        raw.rollback_under(&lease)
            .map_err(LaneLifecycleError::GeometryStorage)?;
    }
    if original.publish_cursors {
        releases.shard_cursors.write().sync_mapping(previous);
    }
    *slot = None;
    if releases.hydrated.read().is_some() {
        self.persist_lane_lifecycle_cursor_journal(releases);
    }
    Ok(())
}

pub(super) fn project_canonical_runtime(
    &self,
    record: &SnapshotNexusRuntime,
    world: &impl WorldReadOnly,
) -> Result<CanonicalRuntimeProjection, LaneLifecycleError> {
    let baseline = self.lane_manifests.read().clone();
    self.project_canonical_runtime_with_manifests(record, world, &baseline)
}

pub(super) fn project_canonical_runtime_with_manifests(
    &self,
    record: &SnapshotNexusRuntime,
    world: &impl WorldReadOnly,
    baseline: &LaneManifestRegistryHandle,
) -> Result<CanonicalRuntimeProjection, LaneLifecycleError> {
    let catalog = runtime_catalog_from_world(world)?;
    let nexus = record.nexus_projection_with_catalog(&self.nexus.read(), catalog.as_ref())?;
    if let Some(catalog) = &catalog
        && catalog.baseline_manifests_hash
            != Hash::prehashed(baseline.baseline_consensus_policy_digest())
    {
        return Err(runtime_catalog_invalid(
            "manifest baseline differs from canonical World catalog",
        ));
    }
    let manifests = if let Some(catalog) = &catalog {
        Arc::new(
            baseline
                .with_runtime_additions(
                    &catalog.manifests,
                    &nexus.lane_catalog,
                    &nexus.dataspace_catalog,
                    &nexus.governance,
                )
                .map_err(runtime_catalog_invalid)?,
        )
    } else {
        rebind_lane_manifests_for_lifecycle(
            baseline.as_ref(),
            &nexus.lane_catalog,
            &nexus.governance,
        )?
    };
    let incarnations = record.active_incarnations()?;
    let activation_heights = record.active_activation_heights()?;
    let lineage = record.lineage_projection();
    validate_lane_incarnation_lineage(
        &nexus.lane_catalog,
        &incarnations,
        &activation_heights,
        &lineage,
    )?;
    let privacy = Arc::new(LanePrivacyRegistry::from_manifest_registry(
        manifests.as_ref(),
    ));
    Ok(CanonicalRuntimeProjection {
        nexus,
        incarnations,
        activation_heights,
        lineage,
        samples: record.autoscale_sample_history.iter().copied().collect(),
        manifests,
        privacy,
    })
}

if !matches!(
    observation,
    NativeAmxParticipantApplicationObservation::Applied(_)
) || marker.is_none_or(|marker| height > marker.lane_block_height)
{
    snapshot
        .blocked
        .entry(route)
        .and_modify(|blocked| *blocked = (*blocked).max(height))
        .or_insert(height);
} else {
    snapshot.applied_slots.insert((
        lane.id,
        lane.dataspace_id,
        incarnation,
        height,
    ));
}

if matches!(
    history.get(marker.lane_block_height),
    Some(NativeAmxParticipantApplicationObservation::Applied(_))
) {
    snapshot.applied.push(marker);
} else {
    snapshot.repair.push(marker);
    snapshot
        .blocked
        .entry(route)
        .and_modify(|blocked| *blocked = (*blocked).max(marker.lane_block_height))
        .or_insert(marker.lane_block_height);
}

fn deref(&self) -> &T {
    self.guard
        .as_deref()
        .expect("original deferred physical guard")
}

fn deref_mut(&mut self) -> &mut T {
    self.guard
        .as_deref_mut()
        .expect("original deferred physical guard")
}

pub(super) struct DaRewindReleases<'state> {
    indexes: DaHydrationReleases<'state>,
    write_fence: crate::publication_lock::DeferredPublicationFence<'state, ()>,
}

pub(super) fn new(state: &'state State) -> Self {
    Self {
        indexes: DaHydrationReleases::new(state),
        write_fence: state.state_write_lock.defer_notifications(),
    }
}

pub(super) fn rewind_da_indexes_to_height_with_releases(
    &self,
    target_height: u64,
    releases: &mut DaRewindReleases<'_>,
) -> Result<(), DaIndexHydrationError> {
    let DaRewindReleases {
        indexes: releases,
        write_fence,
    } = releases;
    let _hydration_guard = self.da_index_hydration_fence.lock();
    // Make concurrent accessors join this fenced rebuild instead of observing the
    // previous cached success while the committed projection is being rewound.
    *releases.hydrated.write() = None;
    let _state_write_guard = write_fence.lock();
    let result = self
        .build_da_indexes_from_kura(Some(target_height))
        .map(|hydrated| {
            self.publish_hydrated_da_indexes(hydrated, releases);
            self.persist_hydrated_da_shard_cursor_journal(releases);
        });
    if let Err(err) = &result {
        warn!(?err, target_height, "failed to rewind DA indexes from Kura");
    }
    *releases.hydrated.write() = Some(result);
    result
}

pub(in crate::state) fn rewind_da_indexes_to_height(
    &mut self,
    target_height: u64,
) -> Result<(), da_hydration::DaIndexHydrationError> {
    let fields = self
        .fields
        .as_mut()
        .expect("original acquired State fields");
    let releases = fields
        .da_rewind_releases
        .get_or_insert_with(|| da_hydration::DaRewindReleases::new(self.target));
    self.target
        .rewind_da_indexes_to_height_with_releases(target_height, releases)
}

fn validate_committed_autoscale_drain_metadata_update(
    &self,
    nexus: &iroha_config::parameters::actual::Nexus,
    lane_incarnations: &BTreeMap<LaneId, Hash>,
    lane_incarnation_activation_heights: &BTreeMap<LaneId, u64>,
    pending: &PendingAutoscaleLaneLifecycle,
    block_height: u64,
    releases: &mut LaneLifecycleReleases<'_>,
) -> Result<(), LaneLifecycleError> {
    let update = &pending.catalog_update;
    if !pending.plan.additions.is_empty()
        || !pending.plan.retire.is_empty()
        || pending.runtime_catalog.is_some()
        || update.updated_dataspace_catalog != nexus.dataspace_catalog
    {
        return Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
            transition: pending.transition.name(),
            reason: "drain metadata transitions must not change lane geometry",
        });
    }
    let (lane_id, expected_state) = match &pending.transition {
        PendingAutoscaleTransition::DrainIntent { lane, intent, .. } => {
            if intent.close_global_height != block_height {
                return Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
                    transition: pending.transition.name(),
                    reason: "drain intent close height must equal its committing block",
                });
            }
            let previous_lane = nexus
                .lane_catalog
                .lanes()
                .iter()
                .find(|candidate| candidate.id == *lane)
                .ok_or(LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason: "drain intent lane is absent from committed state",
                })?;
            if decode_autoscale_lane_drain_state(previous_lane)
                .map_err(|reason| LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason,
                })?
                .is_some()
            {
                return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason: "drain intent cannot replace an existing irreversible drain state",
                });
            }
            (
                *lane,
                LaneDrainStateV1 {
                    version: 1,
                    intent: intent.clone(),
                    commitment: None,
                },
            )
        }
        PendingAutoscaleTransition::DrainCommitment { lane, commitment } => {
            let previous_lane = nexus
                .lane_catalog
                .lanes()
                .iter()
                .find(|candidate| candidate.id == *lane)
                .ok_or(LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason: "drain commitment lane is absent from committed state",
                })?;
            let previous = decode_autoscale_lane_drain_state(previous_lane)
                .map_err(|reason| LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason,
                })?
                .ok_or(LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason: "drain commitment has no committed intent",
                })?;
            if previous.commitment.is_some()
                || commitment.carrier_height != block_height
                || block_height <= previous.intent.close_global_height
            {
                return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason: "drain commitment is repeated or has an invalid carrier height",
                });
            }
            let frontier = Self::evidence_aware_lane_drain_frontier_from_world(
                &self.world.view(),
                &self.kura,
                previous.intent.lane_id,
                previous.intent.dataspace_id,
                previous.intent.lane_incarnation,
            )
            .map_err(|err| LaneLifecycleError::Storage(err.to_string()))?;
            if frontier != commitment.frontier {
                return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
                    lane: *lane,
                    reason: "drain commitment does not match the replicated final frontier",
                });
            }
            (
                *lane,
                LaneDrainStateV1 {
                    version: 1,
                    intent: previous.intent,
                    commitment: Some(*commitment),
                },
            )
        }
        _ => {
            return Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
                transition: pending.transition.name(),
                reason: "expected a drain metadata transition",
            });
        }
    };
    crate::lane_consensus::validate_lane_drain_intent(&expected_state.intent).map_err(
        |_| LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane_id,
            reason: "drain transition intent is invalid",
        },
    )?;
    let previous_lane = nexus
        .lane_catalog
        .lanes()
        .iter()
        .find(|candidate| candidate.id == lane_id)
        .expect("validated drain transition lane must exist");
    let incarnation = lane_incarnations.get(&lane_id).copied().ok_or(
        LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane_id,
            reason: "drain transition lane has no committed incarnation",
        },
    )?;
    if !autoscale_lane_drain_state_matches_context(
        previous_lane,
        &expected_state,
        &self.network_id,
        incarnation,
    ) {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane_id,
            reason: "drain transition does not match chain or incarnation",
        });
    }
    let expected_catalog =
        autoscale_catalog_with_lane_drain_state(nexus, lane_id, &expected_state)?;
    let expected_lane_config =
        iroha_config::parameters::actual::LaneConfig::from_catalog(&expected_catalog);
    if update.updated_catalog != expected_catalog
        || !lane_config_entries_match(&update.updated_lane_config, &expected_lane_config)
        || !lane_config_entries_match(&update.previous_lane_config, &expected_lane_config)
        || update.updated_lane_incarnations != *lane_incarnations
        || update.previous_lane_incarnations != *lane_incarnations
        || update.updated_lane_incarnation_activation_heights
            != *lane_incarnation_activation_heights
        || update.previous_lane_incarnation_activation_heights
            != *lane_incarnation_activation_heights
        || !update.lanes_to_reset.is_empty()
        || !update.replaced_lane_ids.is_empty()
    {
        return Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
            transition: pending.transition.name(),
            reason: "staged drain metadata update changed geometry or incarnation state",
        });
    }
    ensure_autoscale_transition_matches_plan(&pending.plan, &pending.transition)?;
    ensure_autoscale_transition_capacity_matches_nexus(nexus, &pending.transition)?;
    let committed_lane_manifests = rebind_lane_manifests_for_lifecycle(
        releases.manifests.read().as_ref(),
        &expected_catalog,
        &nexus.governance,
    )?;
    if committed_lane_manifests.consensus_policy_digest()
        != pending.updated_lane_manifests.consensus_policy_digest()
    {
        return Err(LaneLifecycleError::Storage(
            "installed lane manifest policy changed after drain staging".to_owned(),
        ));
    }
    pending
        .updated_lane_manifests
        .validate_active_coverage_for_catalog(&expected_catalog)
        .map_err(|err| LaneLifecycleError::ManifestPolicyUnavailable {
            lane: err.lane,
            reason: err.message(),
        })?;
    ensure_catalog_autoscale_lanes_consistent(
        nexus,
        &expected_catalog,
        block_height,
        &BTreeSet::new(),
    )?;
    validate_nexus_routing_policy(
        &nexus.routing_policy,
        &expected_catalog,
        &nexus.dataspace_catalog,
    )
}

fn require_native_amx_completed_repair_receipt_at_target_locked(
    &self,
    entry: &impl LaneArtifactStorageView,
    receipt: &NativeAmxParticipantApplicationReceiptArtifact,
    recovery: Option<(
        &NativeAmxPublicationIndexRecord,
        &NativeAmxParticipantApplicationManifestArtifactV1,
    )>,
) -> Result<()> {
    let descriptor = &receipt.participant_proposal.descriptor;
    self.require_active_lane_artifact(entry, descriptor)?;
    let namespace = self.native_amx_evidence_namespace_for_entry(entry)?;
    self.require_native_amx_evidence_prune_intent_absent_locked(&namespace)?;
    let inventory = self.inventory_native_amx_evidence_files_locked(&namespace, true)?;
    self.require_native_amx_completed_repair_receipt_with_inventory_locked(
        entry, receipt, recovery, &namespace, &inventory,
    )
}

fn require_native_amx_completed_repair_receipt_with_inventory_locked(
    &self,
    entry: &impl LaneArtifactStorageView,
    receipt: &NativeAmxParticipantApplicationReceiptArtifact,
    recovery: Option<(
        &NativeAmxPublicationIndexRecord,
        &NativeAmxParticipantApplicationManifestArtifactV1,
    )>,
    namespace: &BoundProgressNamespace,
    inventory: &NativeAmxEvidenceInventory,
) -> Result<()> {
    let descriptor = &receipt.participant_proposal.descriptor;
    let file = inventory.receipts.get(&descriptor.lane_block_height)
        .ok_or_else(|| Error::PruneIntentConflict("Native unfinished publication lacks its exact pending index and retained receipt".to_owned()))?;
    if self.decode_native_amx_receipt_file_locked(entry, &namespace, file)? != *receipt {
        return Err(Error::PruneIntentConflict(
            "Native completed repair lacks exact stable receipt custody".to_owned(),
        ));
    }
    if !inventory.temporaries.is_empty() {
        let Some((record, manifest)) = recovery else {
            return Err(Error::PruneIntentConflict(
                "Native new completed repair cannot adopt unowned publication temporaries"
                    .to_owned(),
            ));
        };
        record
            .validate()
            .map_err(|message| Error::PruneIntentConflict(message.to_owned()))?;
        if record.origin != NativeAmxPublicationIndexOriginV1::CompletedRepair
            || record.carrier.height != manifest.leaf.application_block_height
            || record.carrier.block_hash != manifest.leaf.application_block_hash
            || record.carrier.executed_wire_hash != manifest.leaf.executed_block_wire_hash
            || HashOf::new(manifest) != receipt.manifest_artifact_hash
            || manifest.finality_artifact_hash != receipt.finality_artifact_hash
            || !Self::native_amx_participant_receipt_matches_manifest_leaf(
                receipt,
                &manifest.leaf,
            )
        {
            return Err(Error::PruneIntentConflict(
                "Native repair temporary lacks its exact retained index and artifact join"
                    .to_owned(),
            ));
        }
        for temporary in inventory.temporaries.values() {
            let expected = match temporary.kind {
                NativeAmxEvidenceKind::Manifest => manifest.encode_framed()?,
                NativeAmxEvidenceKind::Receipt => receipt.encode_framed()?,
            };
            // Inventory binds canonical filename, route and physical identity;
            // this read rechecks that same object, not a path-only replacement.
            if temporary.participant_height != descriptor.lane_block_height
                || self.read_native_amx_evidence_file_bytes_locked(&namespace, temporary)?
                    != expected
            {
                return Err(Error::PruneIntentConflict(
                    "Native repair temporary differs from its exact authenticated canonical artifact".to_owned(),
                ));
            }
        }
    }
    let latest_path = Self::native_amx_participant_receipt_latest_index_path_for_entry(
        entry,
        &self.store_root,
    );
    self.require_native_amx_latest_index_temp_absent_locked(&namespace)?;
    let latest = self.decode_bound_native_amx_participant_receipt_latest_index_locked(
        entry,
        &latest_path,
        &namespace,
    )?;
    if latest
        != Some(NativeAmxParticipantReceiptLatestIndexV2::from_receipt(
            receipt,
        ))
    {
        return Err(Error::PruneIntentConflict(
            "Native completed repair lacks its exact published receipt pointer".to_owned(),
        ));
    }
    Ok(())
}

fn authenticate_native_amx_completed_repair_on_startup(
    &self,
    block: &SignedBlock,
    merge: Option<&MergeLedgerEntry>,
    record: &NativeAmxPublicationIndexRecord,
) -> Result<()> {
    if record.origin != NativeAmxPublicationIndexOriginV1::CompletedRepair {
        return Err(Error::PruneIntentConflict(
            "Native completed repair requires its original repair locator".to_owned(),
        ));
    }
    let artifacts = self
        .native_amx_indexed_publication_artifacts_under_prune_and_canonical_guards(
            block, merge, record,
        )?;
    let _geometry = self.lane_geometry_lock.lock();
    let _sidecar = self.sidecar_lock.lock();
    for (manifest, receipt) in artifacts {
        if !self.native_amx_publication_wsv_join_is_complete_locked(&manifest, &receipt)? {
            return Err(Error::PruneIntentConflict(
                "Native completed repair startup lost its finalized WSV join".to_owned(),
            ));
        }
        let target = self.native_amx_reservation_physical_target_from_journal(
            &receipt.participant_proposal.descriptor,
        )?;
        // An independently authenticated later completed pointer is an
        // existing terminal proof, not authority to republish old evidence.
        if self
            .native_amx_route_publication_capacity_at_target_locked(
                &target, &manifest, &receipt,
            )?
            .is_some()
        {
            self.require_native_amx_completed_repair_receipt_at_target_locked(
                &target,
                &receipt,
                Some((record, &manifest)),
            )?;
        }
        self.require_native_amx_reservation_physical_target(&target)?;
    }
    Ok(())
}

fn inventory_native_amx_evidence_with_indexed_prefix_locked(
    &self,
    namespace: &BoundProgressNamespace,
    allow_transient: bool,
    indexed_prefix: Option<&NativeAmxEvidenceFile>,
) -> Result<NativeAmxEvidenceInventory> {
    if !Self::progress_mutation_namespace_unchanged(namespace) {
        return Err(Self::invalid_lane_artifact_error(
            namespace.data_path.clone(),
            "Native AMX evidence namespace changed before inventory",
        ));
    }
    let directory = namespace.data_path.parent().ok_or_else(|| {
        Self::invalid_lane_artifact_error(
            namespace.data_path.clone(),
            "Native AMX evidence namespace has no directory",
        )
    })?;
    let mut inventory = NativeAmxEvidenceInventory::default();
    let entries = std::fs::read_dir(directory)
        .map_err(|error| Error::IO(error, directory.to_path_buf()))?;
    for entry in entries {
        let entry = entry.map_err(|error| Error::IO(error, directory.to_path_buf()))?;
        let path = entry.path();
        let Some((kind, participant_height, temporary)) =
            Self::parse_native_amx_evidence_path(&path)?
        else {
            continue;
        };
        let metadata = Self::regular_sidecar_metadata_for(&self.store_root, &path, directory)?
            .ok_or_else(|| {
                Self::invalid_lane_artifact_error(
                    path.clone(),
                    "Native AMX evidence disappeared during bounded inventory",
                )
            })?;
        let len = metadata.file.len();
        let owned_prefix = indexed_prefix.is_some_and(|candidate| {
            allow_transient
                && temporary
                && candidate.kind == kind
                && candidate.path == path
                && candidate.participant_height == participant_height
                && Self::stable_sidecar_metadata_unchanged(&candidate.metadata, &metadata)
        });
        if (len == 0 && !owned_prefix)
            || len > STRICT_INIT_MAX_BLOCK_BYTES
            || len > self.native_amx_participant_evidence_file_bytes()
        {
            return Err(Self::invalid_lane_artifact_error(
                path,
                format!(
                    "{} has an empty or oversized standalone payload for the shared stable budget",
                    kind.label()
                ),
            ));
        }
        let file = NativeAmxEvidenceFile {
            kind,
            participant_height,
            path: path.clone(),
            metadata,
        };
        if temporary {
            if inventory.temporaries.insert(kind, file).is_some() {
                return Err(Self::invalid_lane_artifact_error(
                    directory.to_path_buf(),
                    format!(
                        "{} retains more than one publication temporary",
                        kind.label()
                    ),
                ));
            }
            continue;
        }
        let (stable, aggregate) = match kind {
            NativeAmxEvidenceKind::Manifest => (
                &mut inventory.manifests,
                &mut inventory.manifest_stable_bytes,
            ),
            NativeAmxEvidenceKind::Receipt => {
                (&mut inventory.receipts, &mut inventory.receipt_stable_bytes)
            }
        };
        if stable.insert(participant_height, file).is_some() {
            return Err(Self::invalid_lane_artifact_error(
                path,
                format!(
                    "{} repeats participant height {participant_height}",
                    kind.label()
                ),
            ));
        }
        *aggregate = aggregate.checked_add(len).ok_or_else(|| {
            Self::invalid_lane_artifact_error(
                directory.to_path_buf(),
                format!("{} aggregate byte count overflowed", kind.label()),
            )
        })?;
    }
    let stable_entry_limit = self
        .native_amx_participant_evidence_retention()
        .get()
        .checked_add(usize::from(allow_transient))
        .ok_or_else(|| {
            Self::invalid_lane_artifact_error(
                directory.to_path_buf(),
                "Native AMX evidence entry bound overflowed",
            )
        })?;
    let aggregate_limit = if allow_transient {
        self.native_amx_participant_evidence_startup_bytes()?
    } else {
        self.native_amx_participant_evidence_file_bytes()
    };
    for kind in [
        NativeAmxEvidenceKind::Manifest,
        NativeAmxEvidenceKind::Receipt,
    ] {
        let temporary_count = usize::from(
            inventory
                .temporary(kind)
                .is_some_and(|file| file.kind == kind),
        );
        if inventory
            .stable(kind)
            .len()
            .checked_add(temporary_count)
            .is_none_or(|count| count > stable_entry_limit)
        {
            return Err(Self::invalid_lane_artifact_error(
                directory.to_path_buf(),
                format!("{} exceeds its retained record bound", kind.label()),
            ));
        }
    }
    if Self::native_amx_evidence_total_payload_bytes(&inventory)
        .is_none_or(|bytes| bytes > aggregate_limit)
    {
        return Err(Self::invalid_lane_artifact_error(
            directory.to_path_buf(),
            "Native AMX manifests, receipts, and temporaries exceed their shared aggregate byte bound",
        ));
    }
    if !allow_transient && !inventory.temporaries.is_empty() {
        return Err(Self::invalid_lane_artifact_error(
            directory.to_path_buf(),
            "Native AMX evidence retains an unresolved publication temporary",
        ));
    }
    for file in inventory
        .manifests
        .values()
        .chain(inventory.receipts.values())
        .chain(inventory.temporaries.values())
    {
        let current =
            Self::regular_sidecar_metadata_for(&self.store_root, &file.path, directory)?
                .ok_or_else(|| {
                    Self::invalid_lane_artifact_error(
                        file.path.clone(),
                        "Native AMX evidence disappeared after bounded inventory",
                    )
                })?;
        if !Self::stable_sidecar_metadata_unchanged(&file.metadata, &current) {
            return Err(Self::invalid_lane_artifact_error(
                file.path.clone(),
                "Native AMX evidence changed during bounded inventory",
            ));
        }
    }
    if !Self::progress_mutation_namespace_unchanged(namespace) {
        return Err(Self::invalid_lane_artifact_error(
            directory.to_path_buf(),
            "Native AMX evidence namespace changed during inventory",
        ));
    }
    Ok(inventory)
}

fn native_amx_indexed_publication_artifacts_under_prune_and_canonical_guards(
    &self,
    block: &SignedBlock,
    merge: Option<&MergeLedgerEntry>,
    record: &NativeAmxPublicationIndexRecord,
) -> Result<
    Vec<(
        NativeAmxParticipantApplicationManifestArtifactV1,
        NativeAmxParticipantApplicationReceiptArtifact,
    )>,
> {
    let carrier = Self::native_amx_publication_carrier(block)?;
    record
        .validate()
        .map_err(|message| Error::PruneIntentConflict(message.to_owned()))?;
    if record.carrier != carrier
        || record.merge_entry_hash != merge.map(MergeLedgerEntry::canonical_hash)
    {
        return Err(Error::PruneIntentConflict(
            "Native indexed publication startup differs from its retained index".to_owned(),
        ));
    }
    let height = NonZeroUsize::new(usize::try_from(carrier.height)?).ok_or_else(|| {
        Error::PruneIntentConflict(
            "Native indexed publication has zero startup height".to_owned(),
        )
    })?;
    let selected = self
        .read_block_body_under_prune_and_canonical_guards(height)?
        .ok_or_else(|| {
            Error::PruneIntentConflict(
                "Native indexed publication startup lacks its authenticated canonical body"
                    .to_owned(),
            )
        })?;
    if Self::native_amx_publication_carrier(&selected)? != carrier {
        return Err(Error::PruneIntentConflict(
            "Native indexed publication startup changed canonical executed wire".to_owned(),
        ));
    }
    let (_, finality, _) = self
        .v2_finality_artifact_with_archive_under_prune_and_canonical_guards(carrier.height)?
        .ok_or(Error::MissingV2FinalityArtifact {
            height: carrier.height,
        })?;
    let manifest = crate::sumeragi::exec::NativeAmxApplicationManifestV1::from_result_bearing_block_and_merge_entry(block, merge)
        .map_err(|error| Error::PruneIntentConflict(format!("Native indexed publication startup manifest: {error}")))?;
    let artifacts =
        native_amx_participant_application_artifacts(&manifest, HashOf::new(&finality))
            .filter(|artifacts| !artifacts.is_empty())
            .ok_or_else(|| {
                Error::PruneIntentConflict(
                    "Native indexed publication startup has no exact artifact plan".to_owned(),
                )
            })?;
    Ok(artifacts)
}

struct NativeAmxIndexedPublicationPrefix {
    target: lane_geometry::NativeAmxReservationPhysicalTarget,
    namespace: BoundProgressNamespace,
    file: NativeAmxIndexedPrefixFile,
}

fn recover_native_amx_indexed_publication_prefixes_under_publication_guard(
    &self,
    block: &SignedBlock,
) -> Result<()> {
    let _canonical = self.canonical_chain_lock.lock();
    self.recover_native_amx_indexed_publication_prefixes_under_prune_and_canonical_guards(
        &[Self::native_amx_publication_carrier(block)?],
        NativeAmxPrefixRecoveryScope::Indexed,
    )
}

fn recover_native_amx_indexed_publication_prefixes_under_prune_and_canonical_guards(
    &self,
    carriers: &[NativeAmxPublicationCarrier],
    scope: NativeAmxPrefixRecoveryScope,
) -> Result<()> {
    let index = Self::read_native_amx_publication_index_for_store(&self.store_root)?;
    let selected_marker = {
        let mut store = self.block_store.lock();
        let count = store.read_exact_durable_index_count()?;
        store.commit_marker_for_count(count)?
    };
    let mut authenticated = Vec::new();
    for carrier in carriers.iter().copied().collect::<BTreeSet<_>>() {
        let Some(record) = index.records.get(&carrier) else {
            continue;
        };
        let height = NonZeroUsize::new(usize::try_from(carrier.height)?).ok_or_else(|| {
            Error::PruneIntentConflict(
                "Native indexed prefix has zero carrier height".to_owned(),
            )
        })?;
        let block = self
            .get_block_without_merge_sidecar(height)
            .ok_or_else(|| {
                Error::PruneIntentConflict(
                    "Native indexed prefix lost its canonical carrier".to_owned(),
                )
            })?;
        if record.classify_resolved_carrier(
            &selected_marker,
            Some(Self::native_amx_publication_carrier(&block)?),
        )? != NativeAmxPublicationIndexResolution::Committed
        {
            return Err(Error::PruneIntentConflict(
                "Native indexed prefix lacks committed selected-wire authority".to_owned(),
            ));
        }
        let merge =
            self.native_amx_capacity_merge_entry_under_prune_and_canonical_guards(&block)?;
        if record.merge_entry_hash != merge.as_ref().map(MergeLedgerEntry::canonical_hash) {
            return Err(Error::PruneIntentConflict(
                "Native indexed prefix changed its original merge association".to_owned(),
            ));
        }
        if record.origin == NativeAmxPublicationIndexOriginV1::CanonicalWrite
            && !self
                .native_amx_indexed_publication_has_temporary_under_prune_and_canonical_guards(
                    &block,
                    merge.as_ref(),
                )?
        {
            // No derived writer ran: preserve the legitimate pre-finality cut.
            continue;
        }
        let artifacts = self
            .native_amx_indexed_publication_artifacts_under_prune_and_canonical_guards(
                &block,
                merge.as_ref(),
                record,
            )?;
        authenticated.push((record, artifacts));
    }
    if authenticated.is_empty() && scope == NativeAmxPrefixRecoveryScope::Indexed {
        return Ok(());
    }
    let indexed_routes = authenticated
        .iter()
        .flat_map(|(_, artifacts)| {
            artifacts.iter().map(|(_, receipt)| {
                let descriptor = &receipt.participant_proposal.descriptor;
                (descriptor.lane_id, descriptor.lane_incarnation)
            })
        })
        .collect::<BTreeSet<_>>();
    let _geometry = self.lane_geometry_lock.lock();
    let _sidecar = self.sidecar_lock.lock();
    let mut prefixes = Vec::new();
    for (record, artifacts) in authenticated {
        for (manifest, receipt) in artifacts {
            if record.origin == NativeAmxPublicationIndexOriginV1::CompletedRepair
                && !self
                    .native_amx_publication_wsv_join_is_complete_locked(&manifest, &receipt)?
            {
                return Err(Error::PruneIntentConflict(
                    "Native completed-repair prefix lacks its finalized WSV join".to_owned(),
                ));
            }
            if !self.native_amx_participant_application_manifest_matches_available_finality_under_prune_and_canonical_guards(&manifest) {
                return Err(Error::PruneIntentConflict("Native indexed prefix differs from authenticated finality".to_owned()));
            }
            let manifest_bytes = manifest.encode_framed()?;
            let receipt_bytes = receipt.encode_framed()?;
            if !self.native_amx_participant_evidence_pair_fits_stable_bytes(
                manifest_bytes.len(),
                receipt_bytes.len(),
            ) {
                return Err(Error::PruneIntentConflict(
                    "Native indexed prefix exceeds the authenticated pair byte bound"
                        .to_owned(),
                ));
            }
            let descriptor = &receipt.participant_proposal.descriptor;
            let target =
                self.native_amx_reservation_physical_target_from_journal(descriptor)?;
            let namespace = self.native_amx_evidence_namespace_for_entry(&target)?;
            self.require_active_lane_artifact(&target, descriptor)?;
            self.require_native_amx_evidence_prune_intent_absent_locked(&namespace)?;
            let manifest_path = Self::native_amx_application_manifest_path_for_entry(
                &target,
                &self.store_root,
                descriptor.lane_block_height,
            );
            let receipt_path = Self::native_amx_participant_receipt_path_for_entry(
                &target,
                &self.store_root,
                descriptor.lane_block_height,
            );
            let latest_path = Self::native_amx_participant_receipt_latest_index_path_for_entry(
                &target,
                &self.store_root,
            );
            let latest_temp = latest_path
                .parent()
                .expect("bound latest directory")
                .join(NATIVE_AMX_PARTICIPANT_RECEIPTS_LATEST_INDEX_TEMP_FILE);
            let latest_bytes = norito::encode_canonical(
                &NativeAmxParticipantReceiptLatestIndexV2::from_receipt(&receipt),
            )?;
            let mut route_prefix = None;
            for (component, stable, path, expected) in [
                (
                    NativeAmxPublicationComponent::Manifest,
                    &manifest_path,
                    manifest_path.with_extension("norito.tmp"),
                    manifest_bytes.as_slice(),
                ),
                (
                    NativeAmxPublicationComponent::Receipt,
                    &receipt_path,
                    receipt_path.with_extension("norito.tmp"),
                    receipt_bytes.as_slice(),
                ),
                (
                    NativeAmxPublicationComponent::Latest,
                    &latest_path,
                    latest_temp,
                    latest_bytes.as_slice(),
                ),
            ] {
                if let Some(prefix) = self.open_native_amx_indexed_publication_prefix_locked(
                    &namespace, component, stable, &path, expected,
                )? {
                    if route_prefix.replace(prefix).is_some() {
                        return Err(Error::PruneIntentConflict(
                            "Native indexed route has ambiguous simultaneous partial writes"
                                .to_owned(),
                        ));
                    }
                }
            }
            let evidence_prefix = route_prefix.as_ref().and_then(|prefix| {
                let kind = match prefix.component {
                    NativeAmxPublicationComponent::Manifest => NativeAmxEvidenceKind::Manifest,
                    NativeAmxPublicationComponent::Receipt => NativeAmxEvidenceKind::Receipt,
                    NativeAmxPublicationComponent::Latest => return None,
                };
                Some(NativeAmxEvidenceFile {
                    kind,
                    participant_height: descriptor.lane_block_height,
                    path: prefix.path.clone(),
                    metadata: prefix.metadata.clone(),
                })
            });
            let mut inventory = self.inventory_native_amx_evidence_with_indexed_prefix_locked(
                &namespace,
                true,
                evidence_prefix.as_ref(),
            )?;
            // Bounds include the original prefix bytes before the strictly
            // authenticated incomplete object is omitted from decode planning.
            if let Some(temporary) = &evidence_prefix {
                let removed = inventory.temporaries.remove(&temporary.kind);
                if !removed.as_ref().is_some_and(|file| {
                    file.path == temporary.path
                        && Self::stable_sidecar_metadata_unchanged(
                            &file.metadata,
                            &temporary.metadata,
                        )
                }) {
                    return Err(Error::PruneIntentConflict(
                        "Native indexed prefix differs from its bounded inventory".to_owned(),
                    ));
                }
            }
            let latest_prefix = route_prefix
                .as_ref()
                .filter(|prefix| prefix.component == NativeAmxPublicationComponent::Latest);
            // Use the original incoming-pair validator for every route. It
            // checks complete/wrong temporaries and all retained continuity.
            if record.origin == NativeAmxPublicationIndexOriginV1::CanonicalWrite
                || route_prefix.is_some()
            {
                self.preflight_native_amx_incoming_artifacts_locked(
                    &target, &namespace, &inventory, &manifest, &receipt,
                )?;
            }
            if self
                .native_amx_route_publication_capacity_with_inventory_locked(
                    &target,
                    &manifest,
                    &receipt,
                    Some((&namespace, &inventory)),
                    latest_prefix,
                )?
                .is_some()
            {
                if record.origin == NativeAmxPublicationIndexOriginV1::CompletedRepair {
                    self.require_native_amx_completed_repair_receipt_with_inventory_locked(
                        &target,
                        &receipt,
                        Some((record, &manifest)),
                        &namespace,
                        &inventory,
                    )?;
                }
            } else if route_prefix.is_some() {
                return Err(Error::PruneIntentConflict(
                    "Native indexed prefix cannot rewrite a later published frontier"
                        .to_owned(),
                ));
            }
            self.require_native_amx_reservation_physical_target(&target)?;
            if let Some(file) = route_prefix {
                prefixes.push(NativeAmxIndexedPublicationPrefix {
                    target,
                    namespace,
                    file,
                });
            }
        }
    }
    if scope == NativeAmxPrefixRecoveryScope::Startup {
        self.collect_native_amx_completed_pair_latest_prefixes_locked(
            &index,
            &indexed_routes,
            &mut prefixes,
        )?;
    }
    // All authorities and routes passed without mutation. Retain exact file
    // and directory objects through both this pass and every durable unlink.
    for prefix in &mut prefixes {
        self.require_native_amx_reservation_physical_target(&prefix.target)?;
        self.verify_bound_open_regular_file_exact_bytes_locked(
            &prefix.namespace,
            &prefix.file.path,
            &mut prefix.file.opened,
            &prefix.file.metadata,
            &prefix.file.prefix,
            prefix.file.prefix.len(),
            "Native indexed publication prefix",
        )?;
    }
    if prefixes.is_empty() {
        return Ok(());
    }
    self.durable_mutation_authorized()?;
    let resources = self.begin_total_disk_usage_mutation().with_resource_paths(
        prefixes
            .iter()
            .map(|prefix| prefix.file.path.clone())
            .collect(),
    );
    for prefix in &mut prefixes {
        self.verify_bound_open_regular_file_exact_bytes_after_namespace_mutation_locked(
            &prefix.namespace,
            &prefix.file.path,
            &mut prefix.file.opened,
            &prefix.file.metadata,
            &prefix.file.prefix,
            prefix.file.prefix.len(),
            "Native indexed publication prefix",
        )?;
        Self::remove_bound_progress_file_if_matches(
            &prefix.namespace,
            &prefix.file.path,
            &prefix.file.opened,
            &prefix.file.metadata,
        )
        .map_err(|error| Error::IO(error, prefix.file.path.clone()))?;
        self.sync_native_amx_evidence_namespace(
            &prefix.namespace,
            "Native indexed prefix removal",
        )?;
        self.require_native_amx_reservation_physical_target(&prefix.target)?;
    }
    resources.finish_resources_before_disk_rescan();
    Ok(())
}

fn open_native_amx_indexed_publication_prefix_locked(
    &self,
    namespace: &BoundProgressNamespace,
    component: NativeAmxPublicationComponent,
    stable: &Path,
    path: &Path,
    expected: &[u8],
) -> Result<Option<NativeAmxIndexedPrefixFile>> {
    let directory = path.parent().ok_or_else(|| {
        Error::PruneIntentConflict("Native indexed prefix has no parent".to_owned())
    })?;
    let Some(metadata) = Self::regular_sidecar_metadata_for(&self.store_root, path, directory)?
    else {
        return Ok(None);
    };
    let len = usize::try_from(metadata.file.len())?;
    if len >= expected.len() {
        return Ok(None);
    }
    let limit = if component == NativeAmxPublicationComponent::Latest {
        u64::try_from(NATIVE_AMX_PARTICIPANT_RECEIPTS_LATEST_INDEX_MAX_BYTES)?
    } else {
        self.native_amx_participant_evidence_file_bytes()
    };
    if metadata.file.len() > STRICT_INIT_MAX_BLOCK_BYTES
        || metadata.file.len() > limit
        || (component != NativeAmxPublicationComponent::Latest
            && Self::regular_sidecar_metadata_for(&self.store_root, stable, directory)?
                .is_some())
    {
        return Err(Self::invalid_lane_artifact_error(
            path.to_path_buf(),
            "Native indexed prefix is oversized or overlaps a stable pair file",
        ));
    }
    let mut opened = Self::open_bound_progress_file(namespace, path, &metadata)?;
    let mut prefix = Vec::new();
    prefix.try_reserve_exact(len)?;
    prefix.resize(len, 0);
    opened
        .read_exact(&mut prefix)
        .map_err(|error| Error::IO(error, path.to_path_buf()))?;
    if !expected.starts_with(&prefix) {
        return Err(Self::invalid_lane_artifact_error(
            path.to_path_buf(),
            "Native indexed temporary is not an exact canonical prefix",
        ));
    }
    self.verify_bound_open_regular_file_exact_bytes_locked(
        namespace,
        path,
        &mut opened,
        &metadata,
        &prefix,
        len,
        "Native indexed publication prefix",
    )?;
    Ok(Some(NativeAmxIndexedPrefixFile {
        component,
        path: path.to_path_buf(),
        metadata,
        opened,
        prefix,
    }))
}

fn native_amx_indexed_publication_has_temporary_under_prune_and_canonical_guards(
    &self,
    block: &SignedBlock,
    merge: Option<&MergeLedgerEntry>,
) -> Result<bool> {
    let manifest = crate::sumeragi::exec::NativeAmxApplicationManifestV1::from_result_bearing_block_and_merge_entry(block, merge)
        .map_err(|error| Error::PruneIntentConflict(format!("Native indexed prefix discovery manifest: {error}")))?;
    let artifacts = native_amx_participant_application_artifacts(
        &manifest,
        native_amx_participant_application_finality_placeholder_hash(),
    )
    .ok_or_else(|| {
        Error::PruneIntentConflict(
            "Native indexed prefix discovery lacks an artifact plan".to_owned(),
        )
    })?;
    let _geometry = self.lane_geometry_lock.lock();
    let _sidecar = self.sidecar_lock.lock();
    for (_, receipt) in artifacts {
        let descriptor = &receipt.participant_proposal.descriptor;
        let target = self.native_amx_reservation_physical_target_from_journal(descriptor)?;
        let manifest_path = Self::native_amx_application_manifest_path_for_entry(
            &target,
            &self.store_root,
            descriptor.lane_block_height,
        );
        let receipt_path = Self::native_amx_participant_receipt_path_for_entry(
            &target,
            &self.store_root,
            descriptor.lane_block_height,
        );
        if self.bound_progress_sidecar_directory_is_absent(&manifest_path, &receipt_path)? {
            continue;
        }
        let directory = manifest_path.parent().ok_or_else(|| {
            Error::PruneIntentConflict("Native indexed prefix path has no parent".to_owned())
        })?;
        for path in [
            manifest_path.with_extension("norito.tmp"),
            receipt_path.with_extension("norito.tmp"),
            directory.join(NATIVE_AMX_PARTICIPANT_RECEIPTS_LATEST_INDEX_TEMP_FILE),
        ] {
            if Self::regular_sidecar_metadata_for(&self.store_root, &path, directory)?.is_some()
            {
                self.require_native_amx_reservation_physical_target(&target)?;
                return Ok(true);
            }
        }
        self.require_native_amx_reservation_physical_target(&target)?;
    }
    Ok(false)
}

fn require_native_amx_indexed_latest_prefix_locked(
    &self,
    entry: &impl LaneArtifactStorageView,
    namespace: &BoundProgressNamespace,
    inventory: &NativeAmxEvidenceInventory,
    manifest: &NativeAmxParticipantApplicationManifestArtifactV1,
    receipt: &NativeAmxParticipantApplicationReceiptArtifact,
    prefix: &NativeAmxIndexedPrefixFile,
) -> Result<()> {
    let expected_path = namespace
        .data_path
        .parent()
        .expect("bound Native directory")
        .join(NATIVE_AMX_PARTICIPANT_RECEIPTS_LATEST_INDEX_TEMP_FILE);
    let height = receipt.participant_proposal.descriptor.lane_block_height;
    if prefix.component != NativeAmxPublicationComponent::Latest
        || prefix.path != expected_path
        || !inventory.temporaries.is_empty()
    {
        return Err(Error::PruneIntentConflict(
            "Native latest prefix ambiguously overlaps another publication phase".to_owned(),
        ));
    }
    self.require_native_amx_evidence_prune_intent_absent_locked(namespace)?;
    let retained_manifest = inventory.manifests.get(&height).ok_or_else(|| {
        Error::PruneIntentConflict("Native latest prefix lacks its stable manifest".to_owned())
    })?;
    let retained_receipt = inventory.receipts.get(&height).ok_or_else(|| {
        Error::PruneIntentConflict("Native latest prefix lacks its stable receipt".to_owned())
    })?;
    if self.decode_native_amx_manifest_file_locked(entry, namespace, retained_manifest)?
        != *manifest
        || self.decode_native_amx_receipt_file_locked(entry, namespace, retained_receipt)?
            != *receipt
    {
        return Err(Error::PruneIntentConflict(
            "Native latest prefix differs from its exact stable pair".to_owned(),
        ));
    }
    Ok(())
}

fn consume_native_amx_startup_stable_components_locked(
    &self,
    entry: &impl LaneArtifactStorageView,
    namespace: &BoundProgressNamespace,
    manifest: &NativeAmxParticipantApplicationManifestArtifactV1,
    receipt: &NativeAmxParticipantApplicationReceiptArtifact,
) -> Result<()> {
    let descriptor = &receipt.participant_proposal.descriptor;
    let carrier = NativeAmxPublicationCarrier {
        height: receipt.application_block_height,
        block_hash: receipt.application_block_hash,
        executed_wire_hash: receipt.executed_block_wire_hash,
    };
    let route = NativeAmxPublicationRoute {
        lane_id: descriptor.lane_id,
        dataspace_id: descriptor.dataspace_id,
        incarnation: descriptor.lane_incarnation,
    };
    let Some(original_index) = self
        .native_amx_publication_capacity_reservations
        .lock()
        .get(&carrier)
        .filter(|owner| owner.routes.contains_key(&route))
        .map(|owner| owner.index_record.clone())
    else {
        return Ok(());
    };
    let index = Self::read_native_amx_publication_index_for_store(&self.store_root)?;
    if let Some(original) = original_index.as_ref() {
        original
            .validate()
            .map_err(|message| Error::PruneIntentConflict(message.to_owned()))?;
        if index.records.get(&carrier) != Some(original) {
            return Err(Error::PruneIntentConflict(
                "Native startup component allocation lost or changed its original index"
                    .to_owned(),
            ));
        }
    } else if index.records.contains_key(&carrier) {
        return Err(Error::PruneIntentConflict(
            "Native startup maintenance acquired a foreign publication index".to_owned(),
        ));
    }
    let latest_path = Self::native_amx_participant_receipt_latest_index_path_for_entry(
        entry,
        &self.store_root,
    );
    let expected = NativeAmxParticipantReceiptLatestIndexV2::from_receipt(receipt);
    if self.decode_bound_native_amx_participant_receipt_latest_index_locked(
        entry,
        &latest_path,
        namespace,
    )? != Some(expected)
    {
        return Ok(()); // A later authoritative frontier is not this route's publication.
    }
    let height = descriptor.lane_block_height;
    let inventory = self.inventory_native_amx_evidence_files_locked(namespace, true)?;
    let manifest_file = inventory.manifests.get(&height).ok_or_else(|| {
        Error::PruneIntentConflict("Native startup component lost stable manifest".to_owned())
    })?;
    let receipt_file = inventory.receipts.get(&height).ok_or_else(|| {
        Error::PruneIntentConflict("Native startup component lost stable receipt".to_owned())
    })?;
    if self.decode_native_amx_manifest_file_locked(entry, namespace, manifest_file)?
        != *manifest
        || self.decode_native_amx_receipt_file_locked(entry, namespace, receipt_file)?
            != *receipt
        || !expected.matches_manifest(manifest)
    {
        return Err(Error::PruneIntentConflict(
            "Native startup component readback differs from original pair".to_owned(),
        ));
    }
    // Completed-pair maintenance was admitted without a pending index.
    // Reauthenticate that same finalized WSV authority before consuming its
    // original component allocation; missing indexed ownership never falls
    // through to this branch.
    if original_index.is_none()
        && (!self.native_amx_participant_application_receipt_matches_manifest_and_available_evidence_under_prune_canonical_and_sidecar_guards(receipt, manifest)
            || !self.native_amx_publication_wsv_join_is_complete_locked(manifest, receipt)?)
    {
        return Err(Error::PruneIntentConflict(
            "Native startup maintenance lost its completed-pair authority".to_owned(),
        ));
    }
    for (component, bytes) in [
        (
            NativeAmxPublicationComponent::Manifest,
            manifest.encode_framed()?.len(),
        ),
        (
            NativeAmxPublicationComponent::Receipt,
            receipt.encode_framed()?.len(),
        ),
        (
            NativeAmxPublicationComponent::Latest,
            norito::encode_canonical(&expected)?.len(),
        ),
    ] {
        self.consume_native_amx_publication_component_after_durable_publication(
            receipt, component, bytes,
        )?;
    }
    Ok(())
}

fn collect_native_amx_completed_pair_latest_prefixes_locked(
    &self,
    index: &NativeAmxPublicationIndexInventory,
    indexed_routes: &BTreeSet<(LaneId, Hash)>,
    prefixes: &mut Vec<NativeAmxIndexedPublicationPrefix>,
) -> Result<()> {
    for location in self.native_amx_evidence_physical_locations_from_journal()? {
        if indexed_routes.contains(&(location.lane_id(), location.incarnation())) {
            continue;
        }
        let directory = Self::lane_artifact_dir(location.blocks_path());
        let latest_path = directory.join(NATIVE_AMX_PARTICIPANT_RECEIPTS_LATEST_INDEX_FILE);
        let latest_temp =
            directory.join(NATIVE_AMX_PARTICIPANT_RECEIPTS_LATEST_INDEX_TEMP_FILE);
        if Self::regular_sidecar_metadata_for(&self.store_root, &latest_temp, &directory)?
            .is_none()
        {
            continue;
        }
        self.require_native_amx_evidence_physical_location(&location)?;
        let manifest_path = directory.join(Self::native_amx_evidence_file_name(
            NativeAmxEvidenceKind::Manifest,
            1,
        ));
        let receipt_path = directory.join(Self::native_amx_evidence_file_name(
            NativeAmxEvidenceKind::Receipt,
            1,
        ));
        let namespace = self.open_bound_progress_namespace(&manifest_path, &receipt_path)?;
        let inventory = self.inventory_native_amx_evidence_files_locked(&namespace, true)?;
        if !inventory.temporaries.is_empty() {
            return Err(Error::PruneIntentConflict(
                "Native maintenance latest prefix overlaps unindexed pair publication"
                    .to_owned(),
            ));
        }
        let height = inventory
            .manifests
            .keys()
            .chain(inventory.receipts.keys())
            .copied()
            .max()
            .ok_or_else(|| {
                Error::PruneIntentConflict(
                    "Native maintenance latest prefix lacks its stable pair".to_owned(),
                )
            })?;
        let manifest_file = inventory.manifests.get(&height).ok_or_else(|| {
            Error::PruneIntentConflict(
                "Native maintenance latest prefix lacks its highest stable manifest".to_owned(),
            )
        })?;
        let receipt_file = inventory.receipts.get(&height).ok_or_else(|| {
            Error::PruneIntentConflict(
                "Native maintenance latest prefix lacks its highest stable receipt".to_owned(),
            )
        })?;
        let receipt_bytes =
            self.read_native_amx_evidence_file_bytes_locked(&namespace, receipt_file)?;
        let observed =
            norito::decode_canonical::<NativeAmxParticipantApplicationReceiptArtifact>(
                &receipt_bytes,
            )
            .map_err(|error| {
                Self::invalid_lane_artifact_error(
                    receipt_file.path.clone(),
                    format!(
                        "Native maintenance receipt discovery failed exact decode: {error}"
                    ),
                )
            })?;
        let target = self.native_amx_reservation_physical_target_from_location(
            &location,
            observed.participant_proposal.descriptor.dataspace_id,
        )?;
        let manifest =
            self.decode_native_amx_manifest_file_locked(&target, &namespace, manifest_file)?;
        let receipt =
            self.decode_native_amx_receipt_file_locked(&target, &namespace, receipt_file)?;
        let carrier = NativeAmxPublicationCarrier {
            height: receipt.application_block_height,
            block_hash: receipt.application_block_hash,
            executed_wire_hash: receipt.executed_block_wire_hash,
        };
        if index.records.contains_key(&carrier) {
            return Err(Error::PruneIntentConflict(
                "Native maintenance latest prefix cannot borrow indexed publication authority"
                    .to_owned(),
            ));
        }
        self.ensure_durable_block_at_height(carrier.height, carrier.block_hash)?;
        if !self.native_amx_participant_application_receipt_matches_manifest_and_available_evidence_under_prune_canonical_and_sidecar_guards(&receipt, &manifest)
            || !self.native_amx_publication_wsv_join_is_complete_locked(&manifest, &receipt)?
        {
            return Err(Error::PruneIntentConflict(
                "Native maintenance latest prefix lacks completed-pair authority".to_owned(),
            ));
        }
        let expected = norito::encode_canonical(
            &NativeAmxParticipantReceiptLatestIndexV2::from_receipt(&receipt),
        )?;
        let prefix = self.open_native_amx_indexed_publication_prefix_locked(
            &namespace,
            NativeAmxPublicationComponent::Latest,
            &latest_path,
            &latest_temp,
            &expected,
        )?;
        self.preflight_native_amx_incoming_artifacts_locked(
            &target, &namespace, &inventory, &manifest, &receipt,
        )?;
        let Some((_, capacity)) = self
            .native_amx_route_publication_capacity_with_inventory_locked(
                &target,
                &manifest,
                &receipt,
                Some((&namespace, &inventory)),
                prefix.as_ref(),
            )?
        else {
            return Err(Error::PruneIntentConflict(
                "Native maintenance latest prefix cannot rewrite a later frontier".to_owned(),
            ));
        };
        if capacity
            .outstanding_components
            .iter()
            .any(|component| *component != NativeAmxPublicationComponent::Latest)
        {
            return Err(Error::PruneIntentConflict(
                "Native maintenance latest prefix cannot authorize missing pair publication"
                    .to_owned(),
            ));
        }
        self.require_native_amx_reservation_physical_target(&target)?;
        if let Some(file) = prefix {
            prefixes.push(NativeAmxIndexedPublicationPrefix {
                target,
                namespace,
                file,
            });
        }
    }
    Ok(())
}

pub(super) fn widen_untracked(error: PublicationPreparationError<Infallible>) -> Refusal {
    match error {
        PublicationPreparationError::Busy(wait) => PublicationPreparationError::Busy(wait),
        PublicationPreparationError::Poisoned => PublicationPreparationError::Poisoned,
        PublicationPreparationError::Changed => PublicationPreparationError::Changed,
        PublicationPreparationError::Admission(impossible) => match impossible {},
    }
}

pub(super) enum PrepaidSlot<'a, K: Key, V: Value, P>
where
    P: mv::storage::AdmittedStoragePolicy + ClonePlanning<K, V> + ClonePlanning<K, Option<V>>,
{
    Original(mv::storage::AdmittedDetachedPublicationSlot<'a, 'a, K, V, (), P>),
    Refused {
        journal: Option<mv::storage::Detached<K, V, (), Prepaid<P>>>,
        cause: Option<Refusal>,
    },
}

fn publication_slot<'a>(
    original: mv::storage::Detached<K, V, ()>,
    target: &'a Storage<K, V>,
    _scope: Option<&'a AllocationScope<'a>>,
) -> Self::Slot<'a> {
    original.publication_slot(target)
}

fn try_prepare(slot: &mut Self::Slot<'_>) -> Result<(), Refusal> {
    slot.try_prepare(|_, _| Ok::<_, Infallible>(()))
        .map_err(widen_untracked)
}

fn recover_original(slot: &mut Self::Slot<'_>) -> mv::storage::Detached<K, V, ()> {
    slot.recover_original()
}

fn abort<'a>(
    prepared: Self::Prepared<'a>,
) -> (mv::storage::Detached<K, V, ()>, Self::Aborted<'a>) {
    prepared.abort()
}

fn publication_slot<'a>(
    original: mv::storage::Detached<K, V, (), Self>,
    target: &'a Storage<K, V, Self>,
    scope: Option<&'a AllocationScope<'a>>,
) -> Self::Slot<'a> {
    let result = match scope {
        Some(scope) => original.try_publication_slot(scope, target),
        None => Err((
            original,
            PublicationPreparationError::Admission(AdmittedStorageError::ScopeIdentity),
        )),
    };
    match result {
        Ok(slot) => PrepaidSlot::Original(slot),
        Err((journal, cause)) => PrepaidSlot::Refused {
            journal: Some(journal),
            cause: Some(cause),
        },
    }
}

fn try_prepare(slot: &mut Self::Slot<'_>) -> Result<(), Refusal> {
    match slot {
        PrepaidSlot::Original(slot) => slot.try_prepare(),
        PrepaidSlot::Refused { cause, .. } => Err(cause
            .take()
            .expect("original field preparation is one-shot")),
    }
}

fn release_writers(slot: &mut Self::Slot<'_>) {
    if let PrepaidSlot::Original(slot) = slot {
        slot.release_writers();
    }
}

fn recover_original(slot: &mut Self::Slot<'_>) -> mv::storage::Detached<K, V, (), Self> {
    match slot {
        PrepaidSlot::Original(slot) => slot.recover_original(),
        PrepaidSlot::Refused { journal, .. } => journal.take().expect("original refused field"),
    }
}

fn into_prepared<'a>(slot: Self::Slot<'a>) -> Self::Prepared<'a> {
    let PrepaidSlot::Original(slot) = slot else {
        unreachable!("refused field cannot complete preparation")
    };
    slot.into_prepared()
}

fn abort<'a>(
    prepared: Self::Prepared<'a>,
) -> (mv::storage::Detached<K, V, (), Self>, Self::Aborted<'a>) {
    prepared.abort()
}

