pub(crate) struct PreparedTransactionsBlock<'storage> {
    block: TransactionsBlock<'storage>,
    publication: MembershipPublication,
    next_identity: Identity,
    // Fixed original-owner metadata. During publication the admitted action
    // stays in place, and every displaced allocation stays in this caller.
    retired_tip: Option<Tip>,
    publication_started: bool,
    published: bool,
}

pub(crate) fn publish(mut self) -> TransactionsPublicationRetirement {
    self.try_prepare_physical()
        .expect("fixture physical membership admission");
    self.publish_prepared()
}

pub(crate) fn observe_predecessor(
    &self,
    storage: &TransactionsStorage,
) -> MembershipPredecessorStatus {
    let Some(guard) = storage.write_lock.try_lock() else {
        return MembershipPredecessorStatus::Busy;
    };
    let guard = storage.released.guard(guard);
    if Identity::ptr_eq(&guard, &self.predecessor_identity) {
        MembershipPredecessorStatus::Current
    } else {
        MembershipPredecessorStatus::Changed
    }
}

fn block_impl(&self, replacement: bool) -> TransactionsBlock<'_> {
    let mut pending = Some(
        self.prepare_next_block(replacement)
            .expect("fixture history admission"),
    );
    self.attach_prepared(&mut pending)
        .expect("fixture original predecessor")
}

pub(crate) fn try_prepare_publication<'storage, Installation, E>(
    self,
    storage: &'storage TransactionsStorage,
    admit: impl FnOnce(&Self, &TransactionsStorage) -> Result<Installation, E>,
) -> Result<
    PreparedDetachedTransactionsBlock<'storage, Installation>,
    (
        Self,
        mv::PublicationPreparationError<E>,
        AbortedTransactions<Installation>,
    ),
> {
    let mut slot = self.publication_slot(storage);
    match slot.try_prepare(admit) {
        Ok(()) => Ok(slot.into_prepared()),
        Err(error) => {
            let original = slot.recover_original();
            Err((original, error, slot.into_cleanup()))
        }
    }
}

pub(crate) fn publish(self) -> PublishedTransactions<Installation> {
    let Self {
        prepared,
        installation,
        preflight_release,
    } = self;
    PublishedTransactions {
        _retirement: prepared.publish_prepared(),
        _installation: installation,
        _preflight_release: preflight_release,
    }
}

fn detach_retaining(self) -> (DetachedTransactionsBlock, MembershipRelease) {
    self.assert_unpublished();
    let Self {
        block,
        publication,
        next_identity,
        retired_tip: _,
        publication_started: _,
        published: _,
    } = self;
    let mut block = block;
    let history = block
        ._guard
        .history
        .as_mut()
        .expect("original history")
        .recover_detached();
    let detached = DetachedTransactionsBlock {
        history,
        predecessor_identity: block._guard.identity().clone(),
        predecessor: block.latest_block_ref.load_full(),
        current: block
            .current_block
            .as_ref()
            .expect("admitted membership")
            .clone(),
        revert: block.revert,
        publication,
        next_identity,
    };
    let TransactionsBlock {
        _guard,
        current_block,
        ..
    } = block;
    let release = _guard.into_release();
    // The detached journal owns the original staged allocation.
    drop(current_block);
    (detached, release)
}

pub(in crate::state::storage_transactions) struct MembershipWriter<'storage> {
    phase: Option<MembershipWriterPhase<'storage>>,
    pub(super) history: Option<history_slot::Slot<'storage>>,
}

pub(crate) struct TransactionsCaptureSlot<'storage> {
    pub(super) phase: MembershipCapturePhase<'storage>,
    attempted: bool,
    released: bool,
    // Last: the original staged payloads precede the successful capture's
    // deferred notification. All physical siblings must already be free.
    cleanup: Option<MembershipRelease>,
}

pub(in crate::state::storage_transactions) fn new(
    guard: OriginalMembershipGuard<'storage>,
    history: Option<history_slot::Slot<'storage>>,
) -> Self {
    Self {
        phase: Some(MembershipWriterPhase::Attached(guard)),
        history,
    }
}

pub(in crate::state::storage_transactions) fn identity(&self) -> &Identity {
    match self.phase.as_ref() {
        Some(MembershipWriterPhase::Attached(guard)) => guard,
        _ => panic!("original membership writer was terminally released"),
    }
}

pub(super) fn identity_mut(&mut self) -> &mut Identity {
    match self.phase.as_mut() {
        Some(MembershipWriterPhase::Attached(guard)) => guard,
        _ => panic!("original membership writer was terminally released"),
    }
}

fn release(&mut self) {
    if let Some(history) = self.history.as_mut() {
        history.release();
    }
    match self.phase.take() {
        Some(MembershipWriterPhase::Attached(guard)) => {
            // Native unlock does not invoke the original callback.
            let ((), release) = guard.release_deferred(drop);
            self.phase = Some(MembershipWriterPhase::Released(release));
        }
        other => self.phase = other,
    }
}

pub(super) fn into_release(mut self) -> MembershipRelease {
    self.take_release()
}

pub(crate) fn try_prepare(&mut self) -> Result<(), TransactionsBlockError> {
    assert!(
        !self.attempted && !self.released,
        "membership capture is one-shot"
    );
    self.attempted = true;
    let MembershipCapturePhase::Attached(block) = &mut self.phase else {
        panic!("original attached membership capture");
    };
    let publication = block.admit_publication()?;
    let next_identity = block
        ._guard
        .history
        .as_mut()
        .expect("original history")
        .next_identity();
    // All fallible work precedes extraction. Only original-owner moves
    // occur until the prepared owner is stored back in the caller slot.
    let MembershipCapturePhase::Attached(block) =
        std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty)
    else {
        unreachable!("original checked membership block");
    };
    self.phase = MembershipCapturePhase::Prepared(PreparedTransactionsBlock::new(
        block,
        publication,
        next_identity,
    ));
    Ok(())
}

pub(crate) fn try_capture(&mut self) -> Result<(), TransactionsBlockError> {
    assert!(!self.released, "membership capture was terminally released");
    if matches!(&self.phase, MembershipCapturePhase::Attached(_)) {
        self.try_prepare()?;
    }
    // This assertion also excludes an explicitly released prepared block
    // before taking it out of caller custody.
    match &self.phase {
        MembershipCapturePhase::Prepared(prepared) => {
            prepared.assert_unpublished();
            prepared.block._guard.identity();
        }
        _ => panic!("original prepared membership capture"),
    }
    let MembershipCapturePhase::Prepared(prepared) =
        std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty)
    else {
        unreachable!("original checked membership preparation");
    };
    // Existing detach kernel has no callback, user Drop, semantic
    // refusal or allocation after the prepared owner is extracted.
    let (journal, release) = prepared.detach_retaining();
    self.phase = MembershipCapturePhase::Captured(journal);
    self.cleanup = Some(release);
    Ok(())
}

pub(crate) fn release(&mut self) {
    self.released = true;
    let block = match &mut self.phase {
        MembershipCapturePhase::Attached(block) => Some(block),
        MembershipCapturePhase::Prepared(prepared)
        | MembershipCapturePhase::Published(prepared) => Some(&mut prepared.block),
        MembershipCapturePhase::Captured(_) | MembershipCapturePhase::Empty => None,
    };
    if let Some(block) = block {
        block.release_writers();
        if self.cleanup.is_none() {
            self.cleanup = Some(block._guard.take_release());
        }
    }
}

pub(super) fn into_prepared(mut self) -> PreparedTransactionsBlock<'storage> {
    assert!(!self.released, "membership capture was terminally released");
    match &self.phase {
        MembershipCapturePhase::Prepared(prepared) => {
            prepared.assert_unpublished();
            prepared.block._guard.identity();
        }
        _ => panic!("original membership preparation did not complete"),
    }
    match std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty) {
        MembershipCapturePhase::Prepared(prepared) => prepared,
        _ => unreachable!("original checked membership preparation"),
    }
}

pub(crate) fn into_detached(mut self) -> (DetachedTransactionsBlock, MembershipRelease) {
    assert!(!self.released, "membership capture was terminally released");
    match std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty) {
        MembershipCapturePhase::Captured(journal) => (
            journal,
            self.cleanup
                .take()
                .expect("original membership capture release"),
        ),
        original => {
            self.phase = original;
            panic!("original membership capture did not complete");
        }
    }
}

pub(crate) fn capture_slot(self) -> TransactionsCaptureSlot<'storage> {
    TransactionsCaptureSlot {
        phase: MembershipCapturePhase::Attached(self),
        attempted: false,
        released: false,
        cleanup: None,
    }
}

fn new(
    block: TransactionsBlock<'storage>,
    publication: MembershipPublication,
    next_identity: Identity,
) -> Self {
    Self {
        block,
        publication,
        next_identity,
        retired_tip: None,
        publication_started: false,
        published: false,
    }
}

fn assert_unpublished(&self) {
    assert!(
        !self.publication_started && !self.published,
        "membership publication was already attempted"
    );
}

fn publish_in_place(&mut self) {
    self.assert_unpublished();
    assert!(
        self.is_physically_prepared(),
        "original physical membership preparation must precede publication"
    );
    self.block._guard.identity();
    self.publication_started = true;
    if !matches!(&self.publication, MembershipPublication::Repeated) {
        let next = self
            .block
            ._guard
            .history
            .as_ref()
            .expect("original history")
            .next_sequence();
        self.block
            .publication_sequence
            .store(next - 1, Ordering::Release);
        self.block
            ._guard
            .history
            .as_mut()
            .expect("original history")
            .publish();
        let current = match &self.publication {
            MembershipPublication::Replace { current }
            | MembershipPublication::Advance { current, .. } => current,
            MembershipPublication::Repeated => unreachable!(),
        };
        self.retired_tip = self.block.latest_block_ref.swap(Some(current.clone()));
        self.block
            .publication_sequence
            .store(next, Ordering::Release);
    }
    if !matches!(&self.publication, MembershipPublication::Repeated) {
        // Install the exact pre-admitted identity and retain its exact
        // predecessor in the same field. No identity is reconstructed.
        std::mem::swap(self.block._guard.identity_mut(), &mut self.next_identity);
    }
    self.block.release_writers();
    self.published = true;
}

fn into_retirement(self) -> TransactionsPublicationRetirement {
    assert!(
        self.published,
        "original membership publication must complete"
    );
    let Self {
        block,
        publication,
        next_identity,
        retired_tip,
        publication_started: _,
        published: _,
    } = self;
    let TransactionsBlock {
        current_block,
        _guard,
        ..
    } = block;
    let release = _guard.into_release();
    TransactionsPublicationRetirement {
        _tip: retired_tip,
        _staged: current_block,
        _identity: next_identity,
        _publication: publication,
        _release: release,
    }
}

fn take_release(&mut self) -> MembershipRelease {
    self.release();
    MembershipRelease {
        _history: self.history.as_mut().map(|history| history.cleanup()),
        _writer: self.take_writer_release(),
    }
}

pub(crate) fn publish_prepared(&mut self) {
    assert!(!self.released, "membership capture was terminally released");
    let MembershipCapturePhase::Prepared(prepared) = &mut self.phase else {
        panic!("original prepared membership publication");
    };
    prepared.publish_in_place();
    self.cleanup = Some(prepared.block._guard.take_release());
    // No fallible work occurs during this inert successful phase transfer.
    let MembershipCapturePhase::Prepared(prepared) =
        std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty)
    else {
        unreachable!("original completed membership publication");
    };
    self.phase = MembershipCapturePhase::Published(prepared);
}

fn executing(&self) -> &TransactionsBlock<'storage> {
    assert!(
        !self.attempted && !self.released,
        "membership execution authority ended"
    );
    match &self.phase {
        MembershipCapturePhase::Attached(block) => block,
        _ => panic!("original executing membership"),
    }
}

fn executing_mut(&mut self) -> &mut TransactionsBlock<'storage> {
    assert!(
        !self.attempted && !self.released,
        "membership execution authority ended"
    );
    match &mut self.phase {
        MembershipCapturePhase::Attached(block) => block,
        _ => panic!("original executing membership"),
    }
}

fn into_executing(mut self) -> TransactionsBlock<'storage> {
    self.executing();
    match std::mem::replace(&mut self.phase, MembershipCapturePhase::Empty) {
        MembershipCapturePhase::Attached(block) => block,
        _ => unreachable!("checked original executing membership"),
    }
}

pub struct TransactionsBlockField<'storage> {
    pub(super) slot: TransactionsCaptureSlot<'storage>,
}

pub(crate) fn new(block: TransactionsBlock<'storage>) -> Self {
    Self {
        slot: block.capture_slot(),
    }
}

pub(crate) fn try_prepare_publication(&mut self) -> Result<(), TransactionsBlockError> {
    self.slot.try_prepare()
}

pub(crate) fn into_capture(self) -> TransactionsCaptureSlot<'storage> {
    self.slot.executing();
    self.slot
}

fn original(&self) -> &DetachedTransactionsBlock {
    match self.phase.as_ref() {
        Some(Phase::Original(original)) => original,
        _ => panic!("original detached membership phase"),
    }
}

fn refuse<E>(
    &mut self,
    error: PublicationPreparationError<E>,
) -> Result<(), PublicationPreparationError<E>> {
    self.retryable = true;
    Err(error)
}

pub(crate) fn try_prepare<E>(
    &mut self,
    admit: impl FnOnce(&DetachedTransactionsBlock, &TransactionsStorage) -> Result<Installation, E>,
) -> Result<(), PublicationPreparationError<E>> {
    assert!(
        !self.attempted && !self.released,
        "detached membership preparation is one-shot"
    );
    self.attempted = true;
    // A caught admission panic never grants retry authority.
    self.retryable = false;
    let target = self.target;
    let wait = target.released.observe();
    let Some(guard) = target.write_lock.try_lock() else {
        return self.refuse(PublicationPreparationError::after_failed_acquisition(wait));
    };
    self.writer = Some(MembershipWriter::new(target.released.guard(guard), None));
    let current = Identity::ptr_eq(
        self.writer
            .as_ref()
            .expect("original observation writer")
            .identity(),
        &self.original().predecessor_identity,
    );
    // Unlock without notifying. Keep the actual event before admission can
    // run arbitrary code, refuse, or unwind through the enclosing owner.
    self.preflight_release = Some(
        self.writer
            .take()
            .expect("original observation writer")
            .into_writer_release(),
    );
    if !current {
        return self.refuse(PublicationPreparationError::Changed);
    }
    let installation = match admit(self.original(), target) {
        Ok(installation) => installation,
        Err(error) => return self.refuse(PublicationPreparationError::Admission(error)),
    };
    self.installation = Some(installation);
    let wait = target.released.observe();
    let Some(guard) = target.write_lock.try_lock() else {
        return self.refuse(PublicationPreparationError::after_failed_acquisition(wait));
    };
    // Install the actual final acquisition before checking its predecessor.
    self.writer = Some(MembershipWriter::new(target.released.guard(guard), None));
    if !Identity::ptr_eq(
        self.writer
            .as_ref()
            .expect("original publication writer")
            .identity(),
        &self.original().predecessor_identity,
    ) {
        return self.refuse(PublicationPreparationError::Changed);
    }
    // All checks precede extraction. These moves reuse the admitted action,
    // immutable payload and next identity; no new admission or allocation.
    let Some(Phase::Original(original)) = self.phase.take() else {
        unreachable!("checked original membership phase");
    };
    let DetachedTransactionsBlock {
        predecessor_identity: _,
        predecessor: _,
        history,
        current,
        revert,
        publication,
        next_identity,
    } = original;
    let baseline = target
        .blocks
        .read_predecessor(history.baseline.as_ref().expect("original history cut"))
        .expect("checked original history family");
    self.writer
        .as_mut()
        .expect("original membership writer")
        .history = Some(history_slot::Slot::new(target, history));
    self.phase = Some(Phase::Prepared(PreparedTransactionsBlock::new(
        TransactionsBlock {
            latest_block_ref: &target.latest_block,
            budget_ref: &target.budget,
            blocks_ref: &target.blocks,
            baseline,
            publication_sequence: &target.publication_sequence,
            _guard: self
                .writer
                .take()
                .expect("checked original publication writer"),
            revert,
            current_block: Some(current),
        },
        publication,
        next_identity,
    )));
    // The complete original block is back in the caller-owned phase before
    // the native tree acquires any physical publication lock.
    let Some(Phase::Prepared(prepared)) = self.phase.as_mut() else {
        unreachable!()
    };
    if !matches!(&prepared.publication, MembershipPublication::Repeated) {
        if let Err(error) = prepared
            .block
            ._guard
            .history
            .as_mut()
            .expect("original history")
            .prepare()
        {
            let refusal = match error {
                MembershipAdmissionError::Busy(wait) => PublicationPreparationError::Busy(wait),
                MembershipAdmissionError::Changed(_) => PublicationPreparationError::Changed,
                MembershipAdmissionError::Poisoned => PublicationPreparationError::Poisoned,
                _ => unreachable!("native reattachment performs no allocation admission"),
            };
            return self.refuse(refusal);
        }
    }
    self.complete = true;
    self.retryable = true;
    Ok(())
}

pub(crate) fn recover_original(&mut self) -> DetachedTransactionsBlock {
    assert!(
        self.retryable && !self.released,
        "unwound or released membership is not retry authority"
    );
    if let Some(Phase::Prepared(prepared)) = self.phase.as_ref() {
        prepared.assert_unpublished();
    }
    self.released = true;
    self.complete = false;
    if let Some(writer) = self.writer.take() {
        self.writer_release = Some(writer.into_release());
    }
    match self.phase.take().expect("original membership journal") {
        Phase::Original(original) => original,
        Phase::Prepared(prepared) => {
            let (original, release) = prepared.detach_retaining();
            self.writer_release = Some(release);
            original
        }
    }
}

pub(crate) fn release_writers(&mut self) {
    self.released = true;
    self.retryable = false;
    self.complete = false;
    if let Some(writer) = self.writer.take() {
        self.writer_release = Some(writer.into_release());
    }
    if let Some(Phase::Prepared(prepared)) = self.phase.as_mut() {
        prepared.block.release_writers();
    }
}

pub(crate) fn into_prepared(
    mut self,
) -> PreparedDetachedTransactionsBlock<'storage, Installation> {
    assert!(
        self.complete && !self.released,
        "complete original membership preparation"
    );
    let Some(Phase::Prepared(prepared)) = self.phase.take() else {
        unreachable!("checked prepared membership phase");
    };
    self.released = true;
    PreparedDetachedTransactionsBlock {
        prepared,
        installation: self.installation.take().expect("original installation"),
        preflight_release: self.preflight_release.take(),
    }
}

pub(super) fn into_cleanup(mut self) -> AbortedTransactions<Installation> {
    assert!(
        self.released && self.phase.is_none(),
        "original membership was recovered"
    );
    AbortedTransactions {
        _installation: self.installation.take(),
        _preflight_release: self.preflight_release.take(),
        _release: self.writer_release.take(),
    }
}

pub(crate) struct PreparedDetachedTransactionsBlock<'storage, Installation> {
    prepared: PreparedTransactionsBlock<'storage>,
    installation: Installation,
    preflight_release: Option<concread::release::DeferredRelease>,
}

pub(crate) fn abort(
    self,
) -> (DetachedTransactionsBlock, AbortedTransactions<Installation>) {
    let Self {
        prepared,
        installation,
        preflight_release,
    } = self;
    let (journal, release) = prepared.detach_retaining();
    (
        journal,
        AbortedTransactions {
            _release: Some(release),
            _installation: Some(installation),
            _preflight_release: preflight_release,
        },
    )
}

self.next_retry = if self.cursor == 0 {
                    deadline_after(now, retransmit)
                } else {
                    now
                };

fn publish_prepared(mut self) -> TransactionsPublicationRetirement {
    self.publish_in_place();
    self.into_retirement()
}

pub(in crate::state) fn try_prepare_physical(
    &mut self,
) -> Result<(), TransactionsBlockError> {
    self.assert_unpublished();
    if !matches!(&self.publication, MembershipPublication::Repeated) {
        self.block
            ._guard
            .history
            .as_mut()
            .expect("original history")
            .prepare()
            .map_err(TransactionsBlockError::MembershipAdmission)?;
    }
    Ok(())
}

pub(super) fn into_writer_release(mut self) -> concread::release::DeferredRelease {
    assert!(self.history.is_none(), "observation-only writer");
    self.take_writer_release()
}

fn take_writer_release(&mut self) -> concread::release::DeferredRelease {
    self.release();
    match self.phase.take() {
        Some(MembershipWriterPhase::Released(release)) => release,
        _ => unreachable!("original membership release custody"),
    }
}

pub(crate) fn try_prepare_physical(&mut self) -> Result<(), TransactionsBlockError> {
    assert!(!self.released, "original membership capture is live");
    let MembershipCapturePhase::Prepared(prepared) = &mut self.phase else {
        panic!("logical original membership preparation precedes physical admission");
    };
    prepared.try_prepare_physical()
}

pub(crate) fn try_prepare_physical(&mut self) -> Result<(), TransactionsBlockError> {
    self.slot.try_prepare_physical()
}

pub(crate) fn recover_preparation(&mut self) -> history::Pending {
    let MembershipCapturePhase::Prepared(prepared) = &mut self.slot.phase else {
        panic!("original logically prepared membership");
    };
    prepared.assert_unpublished();
    let mut original = prepared
        .block
        ._guard
        .history
        .as_mut()
        .expect("original history")
        .recover();
    original.next_identity = Some(std::mem::replace(
        &mut prepared.next_identity,
        original.predecessor.clone(),
    ));
    original
}

fn advance(&mut self, storage: &TransactionsStorage) -> Result<(), MembershipAdmissionError> {
    if self.work.is_none() {
        let len = if self.replacement {
            0
        } else {
            self.latest.as_ref().map_or(0, |b| b.transactions.len())
        };
        let batch_layout = std::alloc::Layout::array::<Key>(len).map_err(|_| {
            MembershipAdmissionError::Capacity(AllocationRefusal::DemandOverflow)
        })?;
        let identity_layout = Identity::layout();
        let wait = storage.released.observe();
        let writer = storage
            .blocks
            .try_write_admitted_with_footprint(|existing, additional| {
                let required = existing
                    .bytes()
                    .checked_add(additional.bytes())
                    .and_then(|n| n.checked_add(batch_layout.size()))
                    .and_then(|n| n.checked_add(identity_layout.size().checked_mul(2)?))
                    .ok_or(MembershipAdmissionError::Capacity(
                        AllocationRefusal::DemandOverflow,
                    ))?;
                if required > storage.budget.limit_bytes() {
                    return Err(MembershipAdmissionError::Capacity(
                        AllocationRefusal::ExceedsLimit {
                            requested_bytes: required,
                            limit_bytes: storage.budget.limit_bytes(),
                        },
                    ));
                }
                // The callback precedes every cursor shell allocation. Fund
                // its exact demand with the missing original batch and next
                // identity in one pool acquisition before sorting or building
                // any of them. Already retained siblings remain owned by this
                // Pending across a later private-tree insertion refusal.
                let initial_bytes = additional
                    .bytes()
                    .checked_add(if self.batch.is_none() {
                        batch_layout.size()
                    } else {
                        0
                    })
                    .and_then(|n| {
                        n.checked_add(if self.next_identity.is_none() {
                            identity_layout.size()
                        } else {
                            0
                        })
                    })
                    .ok_or(MembershipAdmissionError::Capacity(
                        AllocationRefusal::DemandOverflow,
                    ))?;
                let mut reservation = storage
                    .budget
                    .try_reserve_bytes(initial_bytes)
                    .map_err(MembershipAdmissionError::Capacity)?;
                if self.next_identity.is_none() {
                    let charge = reservation
                        .try_split(identity_layout)
                        .expect("complete original identity layout was admitted");
                    let shell = Reserved::<IdentityState, AllocationCharge>::try_new(charge)
                        .map_err(|(_charge, error)| MembershipAdmissionError::Allocator {
                            requested_bytes: error.layout().size(),
                        })?;
                    self.next_identity = Some(shell.initialize(IdentityState::default()));
                }
                if self.batch.is_none() {
                    let charge = reservation
                        .try_split(batch_layout)
                        .expect("complete original batch layout was admitted");
                    let mut batch = ChargedBuffer::try_from_charge(len, charge).map_err(
                        |(_charge, error)| match error {
                            ChargedBufferFromChargeError::Allocator { layout } => {
                                MembershipAdmissionError::Allocator {
                                    requested_bytes: layout.size(),
                                }
                            }
                            ChargedBufferFromChargeError::DemandOverflow
                            | ChargedBufferFromChargeError::LayoutMismatch { .. } => {
                                unreachable!("checked original batch layout and charge")
                            }
                        },
                    )?;
                    if !self.replacement
                        && let Some(latest) = &self.latest
                    {
                        for key in &latest.transactions {
                            batch
                                .append(std::slice::from_ref(key))
                                .expect("exact preceding tip count");
                        }
                    }
                    batch.as_mut_slice().sort_unstable();
                    self.batch = Some(batch);
                }
                debug_assert_eq!(reservation.remaining_bytes(), additional.bytes());
                Ok(Policy(reservation))
            })
            .map_err(|error| match error {
                MapAdmissionError::Busy => MembershipAdmissionError::Busy(wait.clone()),
                MapAdmissionError::Poisoned => MembershipAdmissionError::Poisoned,
                MapAdmissionError::Changed => MembershipAdmissionError::Changed(wait.clone()),
                MapAdmissionError::Planning(e) => MembershipAdmissionError::Planning(e),
                MapAdmissionError::Refused(e) => e,
            })?;
        self.baseline = Some(writer.predecessor().retain());
        self.work = Some(writer.detach());
    }
    let batch = self.batch.as_ref().expect("original funded batch");
    let work = self.work.as_mut().expect("original successor");
    while self.next < batch.as_slice().len() {
        let key = batch.as_slice()[self.next];
        let height = self
            .latest
            .as_ref()
            .expect("nonempty promotion has a tip")
            .height;
        let wait = storage.released.observe();
        let result = work.try_insert_admitted(key, height, |d| admit(&storage.budget, d));
        if let Err((_, error)) = result {
            // Distinguish a permanently impossible original successor from
            // credits retained by other readers. This floor is diagnostic,
            // not an authorization and is computed only after refusal.
            let error = edit_error(error, wait);
            if let MembershipAdmissionError::Capacity(AllocationRefusal::Capacity {
                requested_bytes,
                ..
            }) = error
            {
                let floor = work
                    .required_allocation_floor()
                    .map_err(MembershipAdmissionError::Planning)?
                    .bytes();
                let batch_bytes = std::alloc::Layout::array::<Key>(batch.capacity())
                    .map_err(|_| {
                        MembershipAdmissionError::Capacity(AllocationRefusal::DemandOverflow)
                    })?
                    .size();
                let required = floor
                    .checked_add(batch_bytes)
                    .and_then(|n| n.checked_add(Identity::layout().size() * 2))
                    .and_then(|n| n.checked_add(requested_bytes))
                    .ok_or(MembershipAdmissionError::Capacity(
                        AllocationRefusal::DemandOverflow,
                    ))?;
                if required > storage.budget.limit_bytes() {
                    return Err(MembershipAdmissionError::Capacity(
                        AllocationRefusal::ExceedsLimit {
                            requested_bytes: required,
                            limit_bytes: storage.budget.limit_bytes(),
                        },
                    ));
                }
            }
            return Err(error);
        }
        self.next += 1;
    }
    Ok(())
}

pub(super) fn release_loan(&mut self) -> Option<concread::release::DeferredRelease> {
    if self.leased {
        self.predecessor.loaned.store(false, Ordering::Release);
        self.leased = false;
    }
    self.lease_release.take()
}

fn drop(&mut self) {
    // The actual release remains a last field, after the flag and all payloads.
    if self.leased {
        self.predecessor.loaned.store(false, Ordering::Release);
    }
}

pub(super) fn new(target: &'a TransactionsStorage, mut pending: Pending) -> Self {
    let work = pending
        .work
        .take()
        .expect("original complete private successor");
    Self {
        target,
        pending: Some(pending),
        phase: Some(Phase::Original(work)),
        prepared: false,
        reader_release: None,
        writer_release: None,
        loan_release: None,
    }
}

pub(super) fn next_sequence(&self) -> u64 {
    self.pending
        .as_ref()
        .expect("original pending metadata")
        .next_sequence
}

pub(super) fn prepare(&mut self) -> Result<(), MembershipAdmissionError> {
    assert!(!self.prepared, "original history preparation is one-shot");
    if matches!(self.phase, Some(Phase::Original(_))) {
        let Some(Phase::Original(work)) = self.phase.take() else {
            unreachable!()
        };
        let wait = self.target.released.observe();
        let acquired = match self.target.blocks.try_acquire_owned_retained(work) {
            Ok(acquired) => self.target.released.guard(acquired),
            Err((work, error)) => {
                self.phase = Some(Phase::Original(work));
                return Err(physical_error(error, wait));
            }
        };
        self.phase = Some(Phase::Acquired(acquired));
    }
    if matches!(self.phase, Some(Phase::Acquired(_))) {
        let Some(Phase::Acquired(acquired)) = self.phase.take() else {
            unreachable!()
        };
        let wait = self.target.released.observe();
        let writer = match acquired.try_map_preserving_release(|a| a.validate()) {
            Ok(writer) => writer,
            Err((acquired, error)) => {
                self.phase = Some(Phase::Acquired(acquired));
                return Err(physical_error(error, wait));
            }
        };
        self.phase = Some(Phase::Preparing(
            writer.map_preserving_release(|w| w.commit_slot()),
        ));
    }
    let wait = self.target.blocks.observe_reader_release();
    let Some(Phase::Preparing(slot)) = self.phase.as_mut() else {
        unreachable!()
    };
    slot.try_prepare()
        .map_err(|error| physical_error(error, wait))?;
    self.prepared = true;
    Ok(())
}

pub(super) fn publish(&mut self) {
    assert!(self.prepared, "original prepared membership history");
    let Some(Phase::Preparing(slot)) = self.phase.take() else {
        unreachable!()
    };
    let (retired, writer) =
        slot.release_deferred(|slot| slot.into_prepared().publish().release());
    self.writer_release = Some(writer);
    self.phase = Some(Phase::Published(retired));
    self.prepared = false;
}

pub(super) fn release(&mut self) {
    self.prepared = false;
    self.phase = match self.phase.take() {
        Some(Phase::Acquired(acquired)) => {
            let (work, writer) = acquired.release_deferred(|a| a.abort());
            self.writer_release = Some(writer);
            Some(Phase::Original(work))
        }
        Some(Phase::Preparing(slot)) => {
            let ((work, reader), writer) = slot.release_deferred(|slot| {
                let (writer, reader) = slot.abort_retaining();
                (writer.abort_retaining(), reader)
            });
            self.reader_release = reader;
            self.writer_release = Some(writer);
            Some(Phase::Abandoned(work))
        }
        phase => phase,
    };
}

pub(super) fn recover(&mut self) -> Pending {
    self.prepared = false;
    let work = match self.phase.take().expect("original tree custody") {
        Phase::Original(work) => work,
        Phase::Acquired(acquired) => {
            let (work, writer) = acquired.release_deferred(|a| a.abort());
            self.writer_release = Some(writer);
            work
        }
        Phase::Preparing(slot) => {
            let ((work, reader), writer) = slot.release_deferred(|slot| {
                let (writer, reader) = slot.abort_retaining();
                (writer.detach(), reader)
            });
            self.reader_release = reader;
            self.writer_release = Some(writer);
            work
        }
        _ => panic!("terminal history is not retry authority"),
    };
    let mut pending = self.pending.take().expect("original pending metadata");
    pending.work = Some(work);
    pending
}

pub(super) fn recover_detached(&mut self) -> Pending {
    let mut pending = self.recover();
    self.loan_release = pending.release_loan();
    pending
}

pub(super) fn cleanup(&mut self) -> Cleanup {
    self.release();
    let mut pending = self.pending.take();
    let mut abandoned = None;
    let mut retired = None;
    match self.phase.take() {
        Some(Phase::Original(work)) => {
            pending.as_mut().expect("original metadata").work = Some(work)
        }
        Some(Phase::Abandoned(work)) => abandoned = Some(work),
        Some(Phase::Published(work)) => retired = Some(work),
        None => {}
        _ => unreachable!("all physical history owners released"),
    }
    Cleanup {
        _pending: pending,
        _abandoned: abandoned,
        _retired: retired,
        _reader: self.reader_release.take(),
        _writer: self.writer_release.take(),
        _loan: self.loan_release.take(),
    }
}

pub(crate) fn prepare_next_block(
    &self,
    replacement: bool,
) -> Result<Pending, MembershipAdmissionError> {
    self.budget.with_deferred_refund_notifications(|_| {
        // This custody is declared before either lock so actual retained
        // notices also retire after both locks on unwind, not only success.
        let mut retired = None;
        let wait = self.released.observe();
        let guard = self
            .write_lock
            .try_lock()
            .ok_or_else(|| MembershipAdmissionError::Busy(wait.clone()))?;
        let guard = self.released.guard(guard);
        if guard.loaned.load(Ordering::Acquire) {
            let identity = guard.clone();
            drop(guard);
            // Observe after this read-only acquisition releases; its own
            // release must not turn an outstanding loan into a busy loop.
            let after_release = self.released.observe();
            return Err(MembershipAdmissionError::Busy(
                if identity.loaned.load(Ordering::Acquire) {
                    after_release
                } else {
                    wait
                },
            ));
        }
        let next_sequence = self
            .publication_sequence
            .load(Ordering::Relaxed)
            .checked_add(2)
            .ok_or(MembershipAdmissionError::Planning(PlanningError::Overflow))?;
        let mut pending = self.pending.lock();
        if pending.as_ref().is_some_and(|p| {
            !Identity::ptr_eq(&p.predecessor, &guard) || p.replacement != replacement
        }) {
            retired = pending.take();
        }
        let original = pending.get_or_insert_with(|| {
            Pending::new(
                guard.clone(),
                self.latest_block.load_full(),
                replacement,
                next_sequence,
                self.released.deferred_batch(),
            )
        });
        #[cfg(test)]
        tests::panic_before_advance();
        let result = original.advance(self);
        let mut ready = result
            .is_ok()
            .then(|| pending.take().expect("completed original preparation"));
        if let Some(ready) = ready.as_mut() {
            ready.predecessor.loaned.store(true, Ordering::Release);
            ready.leased = true;
        }
        drop(pending);
        if let Some(ready) = ready.as_mut() {
            ready.lease_release = Some(guard.release_deferred(drop).1);
        } else {
            drop(guard);
        }
        drop(retired);
        result?;
        Ok(ready.expect("successful original preparation"))
    })
}

pub(crate) fn retain_preparation(&self, mut original: Pending) {
    self.budget.with_deferred_refund_notifications(|_| {
        // This method is called only after the enclosing aggregate releases
        // all physical fences. No other accepted preparation may be displaced.
        let guard = self.released.guard(self.write_lock.lock());
        let mut pending = self.pending.lock();
        let current = Identity::ptr_eq(&original.predecessor, &guard);
        if current {
            assert!(
                original.leased && pending.is_none(),
                "exclusive original preparation loan"
            );
        }
        let notice = original.release_loan();
        let attachments = std::mem::replace(
            &mut original.attachment_releases,
            self.released.deferred_batch(),
        );
        let stale = if current {
            *pending = Some(original);
            None
        } else {
            Some(original)
        };
        drop(pending);
        drop(guard);
        drop(stale);
        drop(attachments);
        drop(notice);
    });
}

pub(crate) fn attach_prepared<'a>(
    &'a self,
    pending: &mut Option<history::Pending>,
) -> Result<TransactionsBlock<'a>, MembershipAdmissionError> {
    let original = pending
        .as_mut()
        .expect("original pre-World membership preparation");
    let wait = self.released.observe();
    // A foreign family cannot acquire this target's notification authority.
    let baseline = self
        .blocks
        .read_predecessor(original.baseline.as_ref().expect("original history cut"))
        .ok_or_else(|| MembershipAdmissionError::Changed(wait.clone()))?;
    let guard = self
        .write_lock
        .try_lock()
        .ok_or_else(|| MembershipAdmissionError::Busy(wait.clone()))?;
    if !Identity::ptr_eq(&guard, &original.predecessor) {
        let released = self
            .released
            .guard(guard)
            .try_release_into(&mut original.attachment_releases, drop);
        assert!(released.is_ok(), "original preparation release family");
        return Err(MembershipAdmissionError::Changed(wait));
    }
    let original = pending.take().expect("checked original preparation");
    let revert = original.replacement;
    Ok(TransactionsBlock {
        latest_block_ref: &self.latest_block,
        budget_ref: &self.budget,
        blocks_ref: &self.blocks,
        baseline,
        publication_sequence: &self.publication_sequence,
        _guard: block::MembershipWriter::new(
            self.released.guard(guard),
            Some(history_slot::Slot::new(self, original)),
        ),
        revert,
        current_block: None,
    })
}

fn from(error: StateAdmissionError) -> Self {
    match error {
        StateAdmissionError::History(e) => Self::History(e),
        StateAdmissionError::Membership(e) => Self::Membership(e),
    }
}

fn wrap<'state>(
        &'state self,
        guard: parking_lot::MutexGuard<'state, T>,
    ) -> PublicationGuard<'state, T> {
        // Advance while the actual physical mutex is held, before any caller
        // can create/rename/unlink or unwind. Saturation permanently disables
        // observation reuse instead of allowing an ABA wraparound.
        if let Some(epoch) = &self.mutation_epoch {
            let _ = epoch.fetch_update(
                std::sync::atomic::Ordering::Relaxed,
                std::sync::atomic::Ordering::Relaxed,
                |epoch| epoch.checked_add(1),
            );
        }
        self.wrap_read_only(guard)
    }

fn wrap_read_only<'state>(
        &'state self,
        guard: parking_lot::MutexGuard<'state, T>,
    ) -> PublicationGuard<'state, T> {
        let epoch = self.mutation_epoch.as_ref().and_then(|epoch| {
            let epoch = epoch.load(std::sync::atomic::Ordering::Relaxed);
            (epoch != u64::MAX).then_some(epoch)
        });
        PublicationGuard {
            mutation_epoch: epoch,
            inner: self.released.guard(PhysicalPublicationGuard {
                guard: Some(guard),
                fair: false,
            }),
        }
    }

